@app.post("/upload")
def upload_chunk():
    # Check if another upload is already in progress
    if get_upload_status():
        return jsonify({"error": "Another upload is in progress. Please wait."}), 400

    # Mark upload as started
    set_upload_status(True)
    session["upload_uuid"] = request.form["dzuuid"]
    session["upload_filename"] = secure_filename(request.form["dzfilename"])

    file = request.files["file"]
    file_uuid = request.form["dzuuid"]
    filename = f"{file_uuid[:8]}_{secure_filename(file.filename)}"
    save_path = UPLOAD_DIR / filename
    current_chunk = int(request.form["dzchunkindex"])
    total_chunks = int(request.form["dztotalchunkcount"])
    total_size = int(request.form["dztotalfilesize"])

    try:
        # Append chunk to file
        with open(save_path, "ab") as f:
            f.seek(int(request.form["dzchunkbyteoffset"]))
            f.write(file.stream.read())
    except OSError as e:
        print(f"Error writing file: {e}")
        return jsonify({"error": "Failed to save chunk"}), 500

    # Check if this was the last chunk
    if current_chunk + 1 == total_chunks:
        # Verify size matches
        if os.path.getsize(save_path) != total_size:
            return jsonify({"error": "Size mismatch. File may be corrupted."}), 500

        # Upload complete!
        session["uploaded_file"] = {
            "name": filename,
            "path": str(save_path),
            "uuid": file_uuid
        }

        # Clear upload status
        set_upload_status(False)

        return jsonify({"success": True, "message": "File uploaded successfully!"}), 200

    return jsonify({"success": True, "msg": "Chunk uploaded"}), 200


@app.get("/download")
def download_file():
    uploaded_file = session.get("uploaded_file")
    if not uploaded_file:
        return "No file has been uploaded yet.", 404

    path = Path(uploaded_file["path"])
    if not path.exists():
        return "File not found.", 404

    # Send file to browser
    return send_file(
        path,
        as_attachment=True,
        mimetype="application/octet-stream",
        download_name=uploaded_file["name"]
    )


@app.post("/start_new_upload")
def start_new_upload():
