    if get_upload_status():
        return jsonify({"error": "An upload is still in progress."}), 400

    # Reset any old state
    session.pop("uploaded_file", None)
    session.pop("upload_uuid", None)
    session.pop("upload_filename", None)

    return jsonify({"success": True, "message": "Ready for next upload."})


if __name__ == "__main__":
