import os
import shutil
import time
from flask import Flask, render_template, jsonify, request

app = Flask(__name__)

# Configuration
SOURCE_DIR = "./videos"  # Répertoire contenant les fichiers MP4
USB_MOUNT_POINT = "/media/usb"  # Clé USB montée ici

# État global de la copie
copy_progress = {
    "total": 0,
    "copied": 0,
    "status": "ready",  # 'ready', 'running', 'done'
    "error": None
}

@app.route("/")
def index():
    return render_template("index.html")

@app.route("/start_copy", methods=["POST"])
def start_copy():
    global copy_progress
    copy_progress = {
        "total": 0,
        "copied": 0,
        "status": "running",
        "error": None
    }

    # Vérifier que la clé USB est disponible
    if not os.path.exists(USB_MOUNT_POINT):
        copy_progress["error"] = f"Clé USB non détectée à {USB_MOUNT_POINT}"
        copy_progress["status"] = "done"
        return jsonify(copy_progress), 500

    # Liste tous les fichiers .mp4
    try:
        files = [f for f in os.listdir(SOURCE_DIR) if f.lower().endswith(".mp4")]
    except Exception as e:
        copy_progress["error"] = f"Erreur lecture dossier source : {e}"
        copy_progress["status"] = "done"
        return jsonify(copy_progress), 500

    if not files:
        copy_progress["status"] = "done"
        return jsonify(copy_progress)

    copy_progress["total"] = len(files)
    copy_progress["status"] = "running"

    # Copie des fichiers avec mise à jour de la progression
    for filename in files:
        src_path = os.path.join(SOURCE_DIR, filename)
        dst_path = os.path.join(USB_MOUNT_POINT, filename)

        try:
            shutil.copy2(src_path, dst_path)
            time.sleep(0.1)  # Simule un délai (facultatif, peut être supprimé)
            copy_progress["copied"] += 1
        except Exception as e:
            copy_progress["error"] = f"Échec de copie de {filename} : {e}"
            copy_progress["status"] = "done"
            break

    if copy_progress["error"] is None:
        copy_progress["status"] = "done"
    else:
        copy_progress["status"] = "done"

    return jsonify(copy_progress)

@app.route("/progress", methods=["GET"])
def progress():
    return jsonify(copy_progress)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=False)
```

