      </div>
    </div>

    <!-- Statut -->
    <div id="statusText" class="text-muted small">Prêt à copier...</div>

    <!-- Message d'erreur (si nécessaire) -->
    <div id="errorBox" class="alert alert-danger d-none mt-3"></div>
  </div>

  <!-- Script JavaScript -->
  <script>
    const statusText = document.getElementById('statusText');
    const progressBar = document.getElementById('progressBar');
    const errorBox = document.getElementById('errorBox');
    const startBtn = document.getElementById('startBtn');

    function updateProgress() {
      fetch('/progress')
        .then(response => response.json())
        .then(data => {
          // Mise à jour de l'affichage
          const percent = data.total > 0 ? Math.round((data.copied / data.total) * 100) : 0;
          progressBar.style.width = percent + '%';
          progressBar.textContent = percent + '%';

          // Gestion des états
          if (data.status === 'ready') {
            statusText.textContent = "Prêt à copier...";
            startBtn.disabled = false;
            errorBox.classList.add('d-none');
          } else if (data.status === 'running') {
            statusText.textContent = `Copie en cours... ${data.copied}/${data.total}`;
            startBtn.disabled = true;
            errorBox.classList.add('d-none');
          } else if (data.status === 'done') {
            if (data.error) {
              statusText.textContent = "Échec de la copie.";
              errorBox.classList.remove('d-none');
              errorBox.textContent = data.error;
            } else {
              statusText.textContent = "✅ Copie terminée avec succès !";
              progressBar.className = "progress-bar bg-success progress-bar-striped";
              startBtn.disabled = false;
            }
          }
        })
        .catch(err => {
          console.error("Erreur de récupération de la progression :", err);
          statusText.textContent = "Erreur réseau.";
        });
    }

    function startCopy() {
      startBtn.disabled = true;
      statusText.textContent = "Envoi de la requête...";

      fetch('/start_copy', { method: 'POST' })
        .then(() => {
          startBtn.disabled = true;
          statusText.textContent = "Copie en cours...";
          errorBox.classList.add('d-none');

          // Démarrer la mise à jour toutes les 500ms
          setInterval(updateProgress, 500);

          // Mettre le bouton actif après 3 sec si jamais finit
          setTimeout(() => {
            if (startBtn.disabled) {
              startBtn.disabled = false;
            }
          }, 10000);
        })
        .catch(err => {
          startBtn.disabled = false;
          errorBox.classList.remove('d-none');
          errorBox.textContent = "Erreur serveur : " + err.message;
          console.error("Erreur lors du lancement de la copie :", err);
        });
    }

    // Initialisation : vérification dès le chargement
    updateProgress();

    // Rédiger un message final en cas de problème
    window.addEventListener('DOMContentLoaded', () => {
      const urlParams = new URLSearchParams(window.location.search);
      if (urlParams.get('error')) {
        alert("Erreur : " + urlParams.get('error'));
      }
    });
  </script>
</body>
</html>
```

