app = Flask(__name__)
app.config['SECRET_KEY'] = 'supersecretkey'

# 存储用户会话数据
sessions = {}

# 保存章节的路径
CHUNK_DIR = "chapters"
os.makedirs(CHUNK_DIR, exist_ok=True)

# 从文本中提取关键信息
def get_user_data(session_id):
    if session_id not in sessions:
