    return sessions[session_id]

# 生成扩写内容
def expand_content(prompt, model="gpt-4-turbo"):
    try:
        response = openai.ChatCompletion.create(
            model=model,
            messages=[
                {"role": "system", "content": "你是一个专业的网络小说策划师，擅长将简略的设定扩展为详细的大纲、角色设定、情节和语言风格描述。请用清晰、有画面感的语言进行扩写。"},
                {"role": "user", "content": prompt}
            ],
            temperature=0.9,
            max_tokens=1024
        )
        return response.choices[0].message["content"]
    except Exception as e:
        return f"生成失败: {str(e)}"

# 生成小说章节
def generate_chapter_outline(novel_outline, character, plot, style, context="", model="gpt-4-turbo"):
    try:
        system_prompt = (
            "你是一位顶尖的网络小说作家，擅长创作节奏紧凑、人物鲜明、语言生动的爆款章节。"
            "根据以下设定，请写出一章约1500字左右的小说。"
            "要求：描写细节丰富，有冲突、悬念或情感爆发点；语言风格符合指定类型；包含对话和心理描写。"
            "不要输出章节标题或额外解释，直接输出正文。"
        )

        user_prompt = (
            f"【小说大纲】{novel_outline}\n"
            f"【主角人设】{character}\n"
            f"【当前情节】{plot}\n"
            f"【语言风格】{style}\n"
            f"【补充背景】{context}\n\n"
            f"请立即开始创作下一章小说正文，不要加标题，直接输出内容。"
        )

        response = openai.ChatCompletion.create(
            model=model,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt}
            ],
            temperature=0.85,
            max_tokens=2048
        )

        return response.choices[0].message["content"]

    except Exception as e:
        return f"章节生成失败: {str(e)}"

# 路由：首页
@app.route("/", methods=["GET", "POST"])
def index():
    session_id = request.cookies.get("session_id")
    if not session_id:
        session_id = str(uuid.uuid4())

    if request.method == "POST":
        action = request.form.get("action")

