            plot = data.get("plot", "")
            style = data.get("style", "")

            if not outline or not character or not plot or not style:
                return jsonify({"error": "请先完成扩写！"}), 400

            chapter_text = generate_chapter_outline(outline, character, plot, style)
            sessions[session_id]["generated_chapter"] = chapter_text
            sessions[session_id]["chapter_count"] += 1

            return jsonify({
                "status": "success",
