            new_chapter = generate_chapter_outline(outline, character, plot, style, context="根据上次反馈调整写作方向")
            sessions[session_id]["generated_chapter"] = new_chapter
            return jsonify({"status": "regenerated", "chapter": new_chapter})

        elif action == "save_chapter":
            data = get_user_data(session_id)
            text = data.get("generated_chapter", "")
            if not text:
