            filename = f"chapter_{data['chapter_count']}.txt"
            file_path = os.path.join(CHUNK_DIR, filename)
            with open(file_path, "w", encoding="utf-8") as f:
                f.write(text)

            data["saved_chapters"].append(filename)
            sessions[session_id] = data

            return jsonify({
                "success": True,
                "filename": filename,
                "download_url": f"/download/{filename}"
            })

        elif action == "get_next_plot":
            # 提供下一步剧情建议
            outline = request.form.get("outline", "")
            current_context = f"这是已经完成的章节内容：{get_user_data(session_id)['generated_chapter']}"
            suggestion = expand_content(
