        "style": session_data.get("style", ""),
        "expanded": session_data.get("expanded", "")
    }

    return render_template("index.html", **ctx)

# 下载章节
@staticmethod
@app.route("/download/<filename>")
def download(filename):
    path = os.path.join(CHUNK_DIR, filename)
    if not os.path.exists(path):
        return "文件不存在", 404
    return send_file(path, as_attachment=True)

# 告知用户需要重新生成
@app.route("/regen", methods=["POST"])
def regen():
    session_id = request.json.get("session_id")
    data = get_user_data(session_id)
    if not data:
        return jsonify({"error": "无效会话"}), 400
    chapter = generate_chapter_outline(data["outline"], data["character"], data["plot"], data["style"])
    data["generated_chapter"] = chapter
    sessions[session_id] = data
    return jsonify({"chapter": chapter})

# 前端请求：获取下一段建议
@app.route("/suggest_plot", methods=["GET"])
def suggest_plot():
    session_id = request.args.get("sid")
