# Creating a Short Image URL Sharing Website

Here's a complete solution for a website where users can upload images and get a short URL to share them.

## Backend (Node.js + Express + MongoDB)

```javascript
// server.js - Backend server using Node.js, Express, and MongoDB
const express = require('express');
const mongoose = require('mongoose');
const multer = require('multer');
const crypto = require('crypto');
const path = require('path');
const fs = require('fs');

const app = express();
const port = 3000;

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/image-sharing', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Image upload configuration
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const uploadDir = 'uploads/';
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir);
    }
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    // Generate unique filename with timestamp
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    const ext = path.extname(file.originalname);
    cb(null, file.fieldname + '-' + uniqueSuffix + ext);
  }
});

const upload = multer({ storage });

// Image model
const ImageSchema = new mongoose.Schema({
  originalName: String,
  fileName: String,
  url: String,
  createdAt: { type: Date, default: Date.now },
  shortUrl: { type: String, required: true, unique: true }
});

const Image = mongoose.model('Image', ImageSchema);

// Middleware
app.use(express.json());
app.use(express.static('public'));
app.use('/uploads', express.static('uploads'));

// Routes
app.post('/upload', upload.single('image'), async (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No file uploaded' });
    }

    // Generate short URL
    const shortUrl = generateShortId();

    // Create image record
    const image = new Image({
      originalName: req.file.originalname,
      fileName: req.file.filename,
      url: `/uploads/${req.file.filename}`,
      shortUrl: shortUrl
    });

    await image.save();

    res.json({
      message: 'Image uploaded successfully',
      shortUrl: `http://localhost:${port}/${shortUrl}`
    });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/:shortUrl', async (req, res) => {
  try {
    const shortUrl = req.params.shortUrl;
    const image = await Image.findOne({ shortUrl });

    if (!image) {
      return res.status(404).send('Image not found');
    }

    // Redirect to the image
    res.redirect(image.url);
  } catch (error) {
    console.error(error);
    res.status(500).send('Internal server error');
  }
});

// Helper function to generate short ID
function generateShortId() {
  return crypto.randomBytes(6).toString('hex').slice(0, 8); // 8-character hex string
}

// Start server
app.listen(port, () => {
  console.log(`Server running at http://localhost:${port}`);
});
```

