/*
 * =============================================================================
 * Программа для устройства на основе Ардуино Про Мини (3.3V)
 * Автор: [Ваше имя]
 * Цель: Считывать температуру с датчиков (DS18B20), состояние цифрового входа,
 *        формировать строку с данными и отправлять её через радиомодуль HC-12.
 *
 * Датчики:     Датчики температуры - тип: 1-проводной, по протоколу "OneWire"
 * Модуль:       Радиомодуль: 433/900 МГц, протокол: 802.15.4 (самый распространенный вариант)
 *               Подключается к Ардуино через сериальную шину (UART)
 *               Пины: 
 *                 - ТЕКСТ: 0 (вход) / 1 (выход)
 *                 - Подключение к пину 0 (исходящий поток данных) и пину 1 (входной поток)
 *                 ИСПОЛЬЗУЕМ: НАШИ ЗАЧЕТЫ — ПИН 0 (приём), ПИН 1 (передача)
 * 
 * ВНИМАНИЕ: Для совместимости с 3.3В (Arduino Pro Mini) — модуль должен быть на 3.3В!
 * ============================================================================= 
 */

// ============ БИБЛИОТЕКИ ============
#include <OneWire.h>     // Для работы с датчиками типа 1-Wire (DS18B20)
#include <DallasTemperature.h>   // Упрощает работу с датчиками температуры

// ============ ОПРЕДЕЛЕНИЯ ПИНОВ ============
#define ONE_WIRE_PIN    2          // Пин, к которому подключен датчик (или шина) 1-проводного интерфейса

// Пин для цифрового входа (например, светодиод, контакт, сенсор)
#define DIGITAL_INPUT_PIN  3      // Пин, где считываются 0/1 от внешнего датчика

// Вычисляем, сколько датчиков мы ожидаем (можно увеличивать, если нужно)
#define MAX_SENSOR_COUNT  4        // Максимально 4 датчика температуры

// ============ ОБЪЕКТЫ ============
OneWire oneWire(ONE_WIRE_PIN);                // Объект для управления шиной 1-проводного протокола
DallasTemperature sensors(&oneWire);          // Объект для управления датчиками температуры

// ============ ГЛОБАЛЬНЫЕ ПЕРЕМЕННЫЕ ============
char sendDataBuffer[256];           // Буфер для сбора данных перед отправкой (максимум 256 символов)
float temperatures[MAX_SENSOR_COUNT]; // Массив для хранения температур
bool digitalInputState;              // Состояние цифрового входа

// ===================== ФУНКЦИИ =====================

// Функция: Отправить данные через радиомодуль (через последовательный порт)
void sendViaRadio(const char* message) {
  Serial1.print(message);            // Отправка строки через порт, настроенный на радиомодуль
  Serial1.println();                 // Добавляем перевод строки — удобно для разделения сообщений
}

// Функция: Собрать данные в единый текстовый формат
void buildDataString() {
  int index = 0;
  char tempStr[10];

  // Очистим буфер
  sendDataBuffer[0] = '\0';

  // Формируем строку: `TEMP1=23.1;TEMP2=24.5;...;DIG=1`
  for (int i = 0; i < MAX_SENSOR_COUNT; i++) {
    // Если датчик найден, читаем температуру
    if (sensors.getDeviceCount() > i) {
      float temp = sensors.getTempCByIndex(i);
      if (temp == DEVICE_IS_UNPLUGGED || temp == DEVICE_DISCONNECTED) {
        // Если датчик не подключён — используем ошибку или знач. -100
        sprintf(tempStr, "%.1f", -100.0);
      } else {
        sprintf(tempStr, "%.1f", temp);
      }
      strcat(sendDataBuffer, "TEMP");
      strcat(sendDataBuffer, String(i + 1).c_str());  // TEMP1, TEMP2...
      strcat(sendDataBuffer, "=");
      strcat(sendDataBuffer, tempStr);
      strcat(sendDataBuffer, ";");  // Разделитель
    }
  }

  // Добавляем состояние цифрового входа
  sprintf(tempStr, "%d", digitalInputState ? 1 : 0);
  strcat(sendDataBuffer, "DIG=");
  strcat(sendDataBuffer, tempStr);
  strcat(sendDataBuffer, ";");

  // После создания полной строки — можно отправить
  sendViaRadio(sendDataBuffer);

  // Просто в лог — для отладки через монитор портов (если нужен)
  // Serial.println("Отправлено: ");
  // Serial.println(sendDataBuffer);
}

// ============ ИНИЦИАЛИЗАЦИЯ ============

void setup() {
  // ==========================================
  // Настройка последовательного порта (для отладки через компьютер/USB)
  // Используем только внутренний порт (не радиомодуль!)
  // Для отладки можно подключить через USB-точку (FTDI, CH340 и т.п.)
  // ==========================================
  Serial.begin(9600);                    // Асинхронная передача данных на 9600 бод (только для отладки!)

  // ==========================================
  // Настройка второго последовательного порта — для радиомодуля
  // Ардуино Про Мини имеет только один физический порт (RX/TX), но его можно переключить
  // Однако: стандартная библиотека `SoftwareSerial` — лучший выбор!
  // Мы будем использовать `SoftwareSerial`
  // ==========================================
  pinMode(0, INPUT);                     // RX для модуля (вход)
  pinMode(1, OUTPUT);                    // TX для модуля (выход)

  // Создаём объект для программной последовательной шины (выбор пинов может меняться!)
  SoftwareSerial radioSerial(0, 1);      // RX=0, TX=1 — обратите внимание
                                          // При использовании этого обозначения, важно: радиомодуль подключен к пину 0 (RX) и 1 (TX)

  // Активируем порт для радиомодуля
  radioSerial.begin(9600);               // Частота должна совпадать с настройками модуля

  // Инициализируем объект для чтения датчиков
  sensors.begin();                       // Инициализация датчиков температуры

  // Проверяем количество подключённых датчиков
  int deviceCount = sensors.getDeviceCount();
  Serial.print("Найдено датчиков температуры: ");
  Serial.println(deviceCount);
  if (deviceCount == 0) {
    Serial.println("⚠️ Нет ни одного датчика температуры!");
  }

  // Настройка цифрового входа
  pinMode(DIGITAL_INPUT_PIN, INPUT_PULLUP);  // Активируем внутренний резистор, чтобы при снятии сигнала было 1
  // Если датчик активируется нажатием кнопки — тогда 0 (лог. ноль), 1 — разомкнуто (по умолчанию)
  // ПРИМЕР: если датчик подключён ко входу и заземлён при срабатывании -> срабатывает на 0

  // Задержка для стабилизации системы
  delay(500);

  // Пример: отправляем тестовое сообщение
  Serial.println("✅ Ардуино запущен. Ждём синхро-данных...");
}


// ============ ОСНОВНОЙ ЦИКЛ ============

void loop() {
  // Запросим актуальные показания датчиков
  sensors.requestTemperatures();

  // Получим каждую температуру — записываем в массив
  for (int i = 0; i < MAX_SENSOR_COUNT; i++) {
    if (sensors.getDeviceCount() > i) {
      float temp = sensors.getTempCByIndex(i);
      if (temp != DEVICE_DISCONNECTED && temp != DEVICE_IS_UNPLUGGED) {
        temperatures[i] = temp;
      } else {
        temperatures[i] = -100.0;  // Индикация "нет сигнала"
      }
    }    
  }

  // Считаем состояние цифрового входа
  digitalInputState = !digitalRead(DIGITAL_INPUT_PIN);  // При наличии подтяжки вверх — срабатывание = 0
  // Если вы хотите инвертировать сигнал — просто замените на:
  // digitalInputState = digitalRead(DIGITAL_INPUT_PIN);

  // Собираем всё в одну строку
  buildDataString();

  // Периодическая отправка (раз в 5 секунд)
  delay(5000);  // Ждём 5 секунд
}
