### `frontend/script.js`

```javascript
// frontend/script.js

// DOM Elements
const recordBtn = document.getElementById('record-btn');
const stopBtn = document.getElementById('stop-btn');
const status = document.querySelector('.status');
const audioPreview = document.getElementById('audio-preview');
const result = document.getElementById('result');
const translationText = document.querySelector('.translation-text');
const emotionText = document.querySelector('.emotion-text');

const imageUpload = document.getElementById('image-upload');
const preview = document.getElementById('preview');
const bodyResult = document.getElementById('body-result');
const bodyLanguage = document.querySelector('.body-language');
const analysisEmotion = document.querySelector('.analysis-emotion');
const suggestionList = document.querySelector('.suggestion-list');

const exampleButtons = document.querySelectorAll('.example-btn');

// State
let stream = null;
let mediaRecorder = null;
let chunks = [];
let isRecording = false;

// Initialize Microphone
recordBtn.addEventListener('click', async () => {
  try {
    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    mediaRecorder = new MediaRecorder(stream);

    chunks = [];

    mediaRecorder.ondataavailable = function(event) {
      chunks.push(event.data);
    };

    mediaRecorder.onstop = function() {
      const blob = new Blob(chunks, { type: 'audio/wav' });
      const url = URL.createObjectURL(blob);
      audioPreview.src = url;
      audioPreview.style.display = 'block';
      status.textContent = 'Translating...';
      result.classList.remove('hidden');

      // Upload to backend
      uploadAudio(blob);
    };

    mediaRecorder.start();
    recordBtn.disabled = true;
    stopBtn.disabled = false;
    isRecording = true;
    status.textContent = 'Recording... 🎙️';
  } catch (err) {
    console.error('Error accessing microphone:', err);
    alert('Could not access microphone. Please allow microphone access.');
  }
});

stopBtn.addEventListener('click', () => {
  if (mediaRecorder && isRecording) {
    mediaRecorder.stop();
    stream.getTracks().forEach(track => track.stop());
    recordBtn.disabled = false;
    stopBtn.disabled = true;
    isRecording = false;
  }
});

// Upload audio to server
function uploadAudio(blob) {
  const formData = new FormData();
  formData.append('audio', blob, 'bark.wav');

  fetch('http://localhost:5000/api/translate', {
    method: 'POST',
    body: formData
  })
  .then(response => response.json())
  .then(data => {
    translationText.textContent = data.translation;
    emotionText.textContent = data.emotion;
    status.textContent = `Translated at ${data.time}`;
  })
  .catch(err => {
    console.error('Error:', err);
    status.textContent = 'Translation failed. Try again.';
  });
}

// Image upload
imageUpload.addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = () => {
    preview.src = reader.result;
    preview.classList.remove('hidden');
  };
  reader.readAsDataURL(file);

  // Send image to backend
  const formData = new FormData();
  formData.append('image', file);

  fetch('http://localhost:5000/api/analyze-body', {
    method: 'POST',
    body: formData
  })
  .then(response => response.json())
  .then(data => {
    bodyLanguage.textContent = data.body_language;
    analysisEmotion.textContent = data.emotion;
    suggestionList.innerHTML = '';
    data.suggestions.forEach(suggestion => {
      const li = document.createElement('li');
      li.textContent = suggestion;
      suggestionList.appendChild(li);
    });
    bodyResult.classList.remove('hidden');
  })
  .catch(err => {
    console.error('Error:', err);
    alert('Image analysis failed.');
  });
});

// Examples
exampleButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    const bark = btn.getAttribute('data-bark');
    status.textContent = `Analyzing: "${bark}"`;
    result.classList.remove('hidden');

    // Simulate AI delay
    setTimeout(() => {
      let translation, emotion;
      if (bark === "woof!") {
        translation = "I'm happy!";
        emotion = "Happy";
      } else if (bark === "yip!") {
        translation = "I'm excited!";
        emotion = "Excited";
      } else if (bark === "whimper") {
        translation = "I'm scared.";
        emotion = "Scared";
      } else if (bark === "growl") {
        translation = "I'm angry.";
        emotion = "Angry";
      }

      translationText.textContent = translation;
      emotionText.textContent = emotion;

      if (bark === "yip!") {
        alert("Oh, is your dog excited? That’s so cute! 🎉");
      }
    }, 1000);
  });
});

// Make sure preview is hidden initially
preview.classList.add('hidden');
result.classList.add('hidden');
bodyResult.classList.add('hidden');
