cam = ESP32CAM()

# 服务器地址（修改为你的服务器 IP）
SERVER_URL = "http://192.168.1.100:5000"  # 改成你服务器的IP

# 控制状态
current_servo1_angle = 90
current_servo2_angle = 90
motor_state = {"forward": 0, "left": 0, "right": 0, "back": 0}

def set_servo_angle(servo, angle):
    if angle < 0: angle = 0
    if angle > 180: angle = 180
    duty = int((angle / 180.0) * 1023 + 256)  # 50Hz 对应 2.5% ~ 12.5% 占空比
    servo.duty(duty)

def move_motor(forward=0, backward=0, left=0, right=0, speed=100):
    # 保持正负关系
    IN1.value(forward)
    IN2.value(backward)
    IN3.value(right)
    IN4.value(left)

    # 可以设置 PWM 调速，这里用 1023 为全速，512 为 50%
    pwm1.duty(speed)
    pwm2.duty(speed)

def send_video_stream():
    print("Starting video stream...")
    cam.start()
    while True:
        try:
            img = cam.capture()
            if img is None:
                continue

            # 将图像转换为二进制数据
            data = img
            # 发送 HTTP-MJPEG 流（简化为多部分）
            headers = {
                'Content-Type': 'multipart/x-mixed-replace; boundary=--frame',
                'Cache-Control': 'no-cache'
            }

            # 使用 urequests 发送流数据
            response = urequests.post(
                f"{SERVER_URL}/stream",
                data=data,
                headers=headers,
                stream=True  # 重要：启用流式传输
            )
            if response.status_code != 200:
                print(f"Stream error: {response.status_code}")
                response.close()
                sleep(2)
            response.close()

        except Exception as e:
            print("Stream error:", e)
            cam.stop()
            sleep(2)
            cam.start()

        gc.collect()

def receive_commands():
    global current_servo1_angle, current_servo2_angle, motor_state
    while True:
        try:
            response = urequests.get(f"{SERVER_URL}/command")
            if response.status_code == 200:
                cmd = ujson.loads(response.text)
                print("Received command:", cmd)

                # 舵机控制 - 舵机1水平
                if 'servo1' in cmd:
                    angle = cmd['servo1']
                    set_servo_angle(servo1, angle)
                    current_servo1_angle = angle

                # 舵机2俯仰
                if 'servo2' in cmd:
                    angle = cmd['servo2']
                    set_servo_angle(servo2, angle)
                    current_servo2_angle = angle

                # 电机控制
                if 'motor' in cmd:
                    m = cmd['motor']
                    if m == 'forward':
                        move_motor(forward=1, backward=0, left=0, right=0, speed=512)
                    elif m == 'back':
                        move_motor(forward=0, backward=1, left=0, right=0, speed=512)
                    elif m == 'left':
                        move_motor(forward=1, backward=0, left=0, right=1, speed=512)
                    elif m == 'right':
                        move_motor(forward=1, backward=0, left=1, right=0, speed=512)
                    elif m == 'stop':
                        move_motor(forward=0, backward=0, left=0, right=0, speed=0)

            response.close()
        except Exception as e:
            print("Recv error:", e)
        sleep(0.1)

# 主函数
def main():
    print("Connecting to WiFi...")
    # 请确保已配置 WiFi（可写死或通过 web server 配置）
    # 这里假设有 WiFi 连接（使用 micropython 的 wlan 模块）
    from network import WLAN, STA_IF
    wlan = WLAN(STA_IF)
    wlan.active(True)
    wlan.connect("YourWiFiName", "YourWiFiPassword")

    while not wlan.isconnected():
        sleep(1)
    print("Connected to WiFi:", wlan.ifconfig())

    # 启动视频流（在单独线程或协程中）
    from _thread import start_new_thread
    start_new_thread(send_video_stream, ())
    start_new_thread(receive_commands, ())

    # 主线程保持运行
    while True:
        sleep(1)

if __name__ == "__main__":
    main()
