```python
from flask import Flask, render_template, Response
from flask_socketio import SocketIO, emit
import cv2
import threading
import time
import json
import atexit

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret!'
socketio = SocketIO(app, cors_allowed_origins="*")

# 记录 ESP32-CAM 状态
esp32_status = {
    'connected': False,
    'last_seen': None,
    'servo1': 90,
    'servo2': 90,
    'motor': 'stop'
}

# 全局视频帧变量（用于网页显示）
current_frame = None
frame_lock = threading.Lock()

# 模拟视频流（也可以从 ESP32 收到流后用 requests 接收）
# 这里只提供一个演示的 MJPEG 流发送功能
def generate_frames():
    global current_frame
    while True:
        with frame_lock:
            if current_frame is not None:
                ret, buffer = cv2.imencode('.jpg', current_frame)
                frame = buffer.tobytes()
                yield (b'--frame\r\n'
                       b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n')
        time.sleep(0.1)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/video_feed')
def video_feed():
    return Response(generate_frames(),
                    mimetype='multipart/x-mixed-replace; boundary=--frame')

# WebSocket 通信
@socketio.on('connect')
def handle_connect():
    print("Client connected")
    emit('esp_status', esp32_status)

@socketio.on('command')
def handle_command(data):
    command = data.get('command', {})
    print("Received command:", command)
    # 可以广播或转发给 ESP32（这里模拟回传）
    esp32_status['servo1'] = command.get('servo1', esp32_status['servo1'])
    esp32_status['servo2'] = command.get('servo2', esp32_status['servo2'])
    esp32_status['motor'] = command.get('motor', esp32_status['motor'])

    # 转发给 ESP32（通过 HTTP POST）
    import requests
    try:
        url = "http://192.168.1.105:80"  # ESP32-CAM 的 IP
        resp = requests.post(f"{url}/command", json=command)
        print("Sent to ESP32:", resp.status_code)
    except Exception as e:
        print("Failed to send to ESP32:", e)

    emit('esp_status', esp32_status)

# 上传图片流（从 ESP32-CAM）
@app.route('/stream', methods=['POST'])
def stream():
    global current_frame
    content_type = request.headers.get('Content-Type')
    if 'mjpeg' in content_type or 'multipart/x-mixed-replace' in content_type:
        try:
            # 读取图像流（此处简化处理）
            # 实际可使用 `request.stream.read()` 保存为图片或转为 OpenCV
            data = request.stream.read()
            # 简单：使用 OpenCV 解码（实际需处理边界）
            _, buffer = cv2.imencode('.jpg', data)  # 需要正确解析
            # 临时方式，实际需要解析 MJPEG 流
            with frame_lock:
                current_frame = cv2.imdecode(buffer, cv2.IMREAD_COLOR)
            return 'OK', 200
        except Exception as e:
            print("Error processing stream:", e)
    return 'OK', 200

# 程序退出时清理
@atexit.register
def cleanup():
    print("Server shutting down...")

if __name__ == '__main__':
    socketio.run(app, host='0.0.0.0', port=5000, debug=False)
