## 🔄 3. 转账云函数（`cloudfunctions/transfer/index.js`）

```js
// cloudfunctions/transfer/index.js
const db = require('wxcloud-base').db;

exports.main = async (event, context) => {
  const { fromOpenId, toOpenId, amount } = event;

  if (!fromOpenId || !toOpenId || !amount || amount <= 0) {
    return { success: false, msg: '参数错误' };
  }

  try {
    // 1. 查找转出方
    const fromUser = await db.collection('users')
      .where({ openid: fromOpenId })
      .get();

    if (fromUser.data.length === 0) {
      return { success: false, msg: '转出账户不存在' };
    }

    const fromScore = fromUser.data[0].score;
    if (fromScore < amount) {
      return { success: false, msg: '积分不足' };
    }

    // 2. 查找接收方
    const toUser = await db.collection('users')
      .where({ openid: toOpenId })
      .get();

    if (toUser.data.length === 0) {
      return { success: false, msg: '接收账户不存在' };
    }

    // 3. 事务操作（原子性）
    const res = await db.collection('users').where({ openid: fromOpenId }).update({
      data: {
        score: fromScore - amount
      }
    });

    const res2 = await db.collection('users').where({ openid: toOpenId }).update({
      data: {
        score: toUser.data[0].score + amount
      }
    });

    if (res.stats.updated === 1 && res2.stats.updated === 1) {
      return { success: true, msg: '转账成功' };
    } 

    return { success: false, msg: '转账失败' };

  } catch (err) {
    console.error('转账失败:', err);
    return { success: false, msg: '系统错误' };
  }
};
```

