// pages/index/index.js
const app = getApp();

Page({
  data: {
    score: 0,
    otherOpenid: '',
    amount: 10,
    userInfo: {}
  },

  onLoad() {
    const openid = wx.getStorageSync('openid');
    if (!openid) {
      wx.showToast({ title: '未登录', icon: 'none' });
      wx.redirectTo({ url: '/pages/login/login' });
      return;
    }

    this.loadUserInfo(openid);
  },

  loadUserInfo(openid) {
    wx.cloud.callFunction({
      name: 'get_user_info',
      data: { openid },
      success: res => {
        if (res.result.success && res.result.userInfo) {
          const user = res.result.userInfo;
          this.setData({
            score: user.score,
            userInfo: user
          });
        }
      },
      fail: () => {
        wx.showToast({ title: '加载失败', icon: 'none' });
      }
    });
  },

  handleTransfer() {
    const { otherOpenid, amount } = this.data;
    const fromOpenid = wx.getStorageSync('openid');

    if (!otherOpenid.trim()) {
      wx.showToast({ title: '请输入目标用户', icon: 'none' });
      return;
    }

    if (isNaN(amount) || amount <= 0) {
      wx.showToast({ title: '请输入有效金额', icon: 'none' });
      return;
    }

    wx.showModal({
      title: '确认转账',
      content: `确定转账 ${amount} 积分给 ${otherOpenid}？`,
      confirmText: '转账',
      success: async res => {
        if (res.confirm) {
          wx.showLoading({ title: '正在转账...' });

          try {
            const result = await wx.cloud.callFunction({
              name: 'transfer',
              data: {
                fromOpenId: fromOpenid,
                toOpenId: otherOpenid,
                amount: parseInt(amount)
              }
            });

            if (result.result.success) {
              wx.showToast({ title: '转账成功！', icon: 'success' });
              this.loadUserInfo(fromOpenid); // 刷新数据
            } 
            else {
              wx.showToast({ title: result.result.msg, icon: 'none' });
            }
          } catch (err) {
            wx.showToast({ title: '网络错误', icon: 'none' });
          } finally {
            wx.hideLoading();
          }
        }
      }
    });
  },

  onShareAppMessage() {
    return {
      title: '快来一起赚积分吧！',
      path: '/pages/index/index'
    };
  }
});
