Вот пример программы на **C++**, которая позволяет вручную вводить **ориентированный граф** (список смежности), причём пользователь указывает количество вершин и затем по каждой паре вершин указывает, есть ли дуга из одной вершины в другую.

---

### ✅ Программа: Ввод ориентированного графа вручную

```cpp
#include <iostream>
#include <vector>
#include <iomanip>

using namespace std;

int main() {
    int n;
    cout << "Введите количество вершин в графе: ";
    cin >> n;

    // Инициализируем граф как список смежности
    vector<vector<int>> graph(n);

    cout << "\nВведите дуги графа (в формате: из вершины -> в вершину):\n";
    cout << "Для завершения ввода нажмите 'Enter' с пустой строкой.\н";

    string line;
    while (true) {
        cout << "Введите дугу (например: 0 1): ";
        getline(cin, line);

        // Если строка пустая — завершаем ввод
        if (line.empty()) {
            break;
        }

        // Пытаемся распарсить строку
        int from, to;
        stringstream ss(line);
        if (ss >> from >> to) {
            // Проверяем корректность вершин
            if (from < 0 || from >= n || to < 0 || to >= n) {
                cout << "Ошибка: вершины должны быть в диапазоне [0, " << n-1 << "].\n";
                continue;
            }
            // Добавляем дугу
            graph[from].push_back(to);
            cout << "Дуга " << from << " -> " << to << " добавлена.\н";
        } 
        else {
            cout << "Неверный формат. Введите два числа через пробел.\n";
        }
    }

    // Вывод графа
    cout << "\n--- Список смежности графа ---\n";
    for (int i = 0; i < n; ++i) {
        cout << "Вершина " << i << ": ";
        if (graph[i].empty()) {
            cout << "нет выходящих дуг";
        } 
        else {
            for (size_t j = 0; j < graph[i].size(); ++j) {
                cout << graph[i][j];
                if (j < graph[i].size() - 1) cout << ", ";
            }
        }
        cout << endl;
    }

    return 0;
}
```

---

### 🔍 Как работает:

1. Пользователь вводит количество вершин `n`.
2. Затем система начинает принимать пары `(from, to)` до тех пор, пока не будет введён пустой ввод.
3. Для каждой дуги проверяется, что вершины в допустимом диапазоне `[0, n-1]`.
4. Граф хранится в виде списка смежности (`vector<vector<int>>`).
5. В конце выводится структура графа.

---

### 📌 Пример использования:

```
Введите количество вершин в графе: 4

Введите дуги графа (в формате: из вершины -> в вершину):
Для завершения ввода нажмите 'Enter' с пустой строкой.

Введите дугу (например: 0 1): 0 1
Дуга 0 -> 1 добавлена.
Введите дугу (например: 0 1): 0 2
Дуга 0 -> 2 добавлена.
Введите дугу (например: 0 1): 1 3
Дуга 1 -> 3 добавлена.
Введите дугу (например: 0 1): 2 3
Дуга 2 -> 3 добавлена.
Введите дугу (например: 0 1): 

--- Список смежности графа ---
Вершина 0: 1, 2
Вершина 1: 3
Вершина 2: 3
Вершина 3: нет выходящих дуг
```

