#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "mjson.h"

// === Параметры ===
#define NUM_BUTTONS 6
#define NUM_RELAYS  6

// Прототип функции
void process_button_events(int button_states[], int relay_states[], const char* json_map);

// Глобальные переменные
int last_button_state[NUM_BUTTONS] = {0}; // предыдущее состояние кнопок
int current_relay_state[NUM_RELAYS] = {0}; // текущее состояние реле
```

