### 🔄 Функция обработки карты соответствий

```c
void process_button_events(int button_states[], int relay_states[], const char* json_map)
{
    // Парсим JSON
    mjson_t j;
    mjson_init(&j, json_map, strlen(json_map));

    // Обнуляем реле — чтобы не было "залипания" без действия
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_states[i] = 0;
    }

    // Читаем каждый элемент массива
    if (mjson_type(&j) != MJ_ARRAY) {
        printf("Ошибка: ожидается массив.\n");
        return;
    }

    int len = mjson_array_length(&j);
    mjson_t item;

    for (int i = 0; i < len; i++) {
        mjson_array_get(&j, i, &item);

        int button = -1;
        int relay_count = 0;
        int relays[32]; // на всякий случай, максимум 32 реле

        // Извлекаем данные из объекта
        if (mjson_object_get(&item, "button", NULL, &j) && mjson_value(&j, &button)) {
            // Находим все реле
            mjson_object_get(&item, "relay", NULL, &j);
            if (mjson_type(&j) == MJ_ARRAY) {
                relay_count = mjson_array_length(&j);
                for (int r = 0; r < relay_count; r++) {
                    mjson_array_get(&j, r, &item);
                    int val;
                    if (mjson_value(&item, &val) && val >= 0 && val < NUM_RELAYS) {
                        relays[r] = val;
                    }
                }
            }
        }

        // Если кнопка была нажата (флаг 0->1), то включаем указанные реле
        if (button >= 0 && button < NUM_BUTTONS) {
            if (button_states[button] == 1 && last_button_state[button] == 0) {
                // Эффект: сигнал нажатия (флаг переход)
                for (int r = 0; r < relay_count; r++) {
                    relay_states[relays[r]] = 1;
                }
            }
        }
    }

    // Обновляем состояние для следующей итерации
    for (int i = 0; i < NUM_BUTTONS; i++) {
        last_button_state[i] = button_states[i];
    }
}
```

