    // 3. 所有已完成的进程跳过，只有未完成的才考虑
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state == F || processes[i].state == B) {
            finish[i] = 1;
        }
    }

    // 4. 检查当前进程是否可能申请：资源是否足够？
    for (int i = 0; i < 3; i++) {
        if (req[i] > available[i]) return 0;  // 不足够
    }

    // 5. 申请资源看是否可以执行
    // 先临时分配（仅测试）
    for (int i = 0; i < 3; i++) {
        work[i] -= req[i];
    }
    finish[process_index] = 1;

    // 6. 找寻可以执行的进程（所有未完成且还能满足申请）—— 采用安全序列算法
    int found;
    int count = 1;  // 已完成的线程数量（包括刚分配的）

    while (count < MAX_PROCESSES) {
        found = 0;
        for (int i = 0; i < MAX_PROCESSES; i++) {
            if (!finish[i]) {
                int can_run = 1;
                for (int j = 0; j < 3; j++) {
                    if (processes[i].remaining[j] > work[j]) {
                        can_run = 0;
                        break;
                    }
                }
                if (can_run) {
                    // 可以执行，释放其资源
                    for (int j = 0; j < 3; j++) {
                        work[j] += processes[i].allocated[j];
                    }
                    finish[i] = 1;
                    count++;
                    found = 1;
                    break;
                }
            }
        }
        if (!found) break;
    }

    // 7. 若所有进程都完成了，则是安全状态
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (!finish[i]) return 0;
    }
    return 1;
}

