        int idx = blocked_queue[i];
        PCB *p = &processes[idx];

        // 是否还有剩余需求？
        if (p->remaining[0] == 0 && p->remaining[1] == 0 && p->remaining[2] == 0) {
            continue; // 已完成，不应在此
        }

        // 向进程发起申请请求
        int req[3];
        for (int j = 0; j < 3; j++) {
            req[j] = p->remaining[j];
        }

        if (is_safe_state(req, idx)) {
            // 分配资源
            for (int j = 0; j < 3; j++) {
                available[j] -= req[j];
                p->allocated[j] += req[j];
            }
            update_remaining(p);

            // 放入就绪队列
            add_to_ready(idx);
            p->state = W;

            // 从原阻塞队列移除
            temp_blocked[temp_count++] = idx;
            new_wake_count++;
        }
    }

    if (new_wake_count > 0) {
        printf("唤醒了 %d 个阻塞进程。\n", new_wake_count);
    }

    // 重写阻塞队列
    int j = 0;
    for (int i = 0; i < blocked_count; i++) {
        int flag = 1;
        for (int k = 0; k < temp_count; k++) {
            if (blocked_queue[i] == temp_blocked[k]) {
                flag = 0;
                break;
            }
        }
        if (flag) {
            blocked_queue[j++] = blocked_queue[i];
        }
    }
    blocked_count = j;
}

// 随机创建一个新进程（最多5个）
void create_new_process(int completed_idx) {
