    // Case 1: Circles are concentric (same center)
    if (d == 0) {
        if (r1 == r2) {
            // Same circle - infinite intersection points
            return -1;
        } else {
            // Concentric but different radii - no intersection
            return 0;
        }
    }

    // Case 2: One circle is completely inside another without touching
    if (d < fabs(r1 - r2)) {
        return 0;
    }

    // Case 3: Circles are externally tangent
    if (d == fabs(r1 - r2)) {
        return 1;
    }

    // Case 4: Circles intersect at two points
    if (d < r1 + r2) {
        return 2;
    }

    // Case 5: Circles are externally tangent or separate
    if (d == r1 + r2) {
        return 1;
    }

    // Case 6: Circles are completely separate
    if (d > r1 + r2) {
        return 0;
    }

    // Default case (should not be reached due to the conditions above)
    return -1;
}

// Function to display the result
void display_result(int intersections, double x1, double y1, double r1,
                   double x2, double y2, double r2) {
    printf("\nCircle 1: Center (%.2f, %.2f), Radius %.2f\n", x1, y1, r1);
    printf("Circle 2: Center (%.2f, %.2f), Radius %.2f\n", x2, y2, r2);

    switch (intersections) {
        case -1:
            printf("Result: Infinite intersection points (same circle)\n");
            break;
        case 0:
            printf("Result: No intersection points\n");
            break;
        case 1:
            printf("Result: One intersection point (tangent circles)\n");
            break;
        case 2:
            printf("Result: Two intersection points (intersecting circles)\n");
            break;
        default:
            printf("Result: Unknown case\n");
            break;
    }
}

int main() {
    double x1, y1, r1, x2, y2, r2;

    printf("=== Circle Intersection Calculator ===\n\n");
    printf("Enter parameters for first circle:\n");
