    scanf("%lf", &y2);
    printf("Radius of second circle: ");
    scanf("%lf", &r2);

    // Validate inputs
    if (r1 <= 0 || r2 <= 0) {
        printf("Error: Radii must be positive numbers.\n");
        return 1;
    }

    // Calculate number of intersection points
    int intersections = count_intersection_points(x1, y1, r1, x2, y2, r2);

