    double d = calculate_distance(x1, y1, x2, y2);
    printf("Distance between centers: %.4f\n", d);
    printf("Sum of radii: %.4f\n", r1 + r2);
    printf("Difference of radii: %.4f\n", fabs(r1 - r2));

    return 0;
}
