# Todo App in C

Below is a simple command-line Todo application implemented in C. This app allows you to:
- Add new tasks
- View all tasks
- Mark tasks as completed
- Delete tasks
- Save and load tasks from a file

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_TASKS 100
#define MAX_TASK_LENGTH 256
#define FILENAME "todo.txt"

// Task structure
typedef struct {
    int id;
    char description[MAX_TASK_LENGTH];
    bool completed;
} Task;

// Global variables
Task tasks[MAX_TASKS];
int taskCount = 0;

// Function declarations
void displayMenu();
void addTask();
void viewTasks();
void markCompleted();
void deleteTask();
void saveTasks();
void loadTasks();
void clearScreen();

int main() {
    // Load existing tasks from file
    loadTasks();

    int choice;

    do {
        clearScreen();
        displayMenu();
        printf("Enter your choice: ");
        scanf("%d", &choice);

        getchar(); // Consume newline

        switch (choice) {
            case 1:
                addTask();
                break;
            case 2:
                viewTasks();
                break;
            case 3:
                markCompleted();
                break;
            case 4:
                deleteTask();
                break;
            case 5:
                saveTasks();
                printf("\nTasks saved successfully!\n");
                break;
            case 0:
                printf("\nThank you for using the Todo App! Goodbye.\n");
                break;
            default:
                printf("\nInvalid choice! Please try again.\n");
                getchar(); // Wait for user input
        }

    } while (choice != 0);

    return 0;
}

void displayMenu() {
    printf("\n===== TO-DO APPLICATION =====\n");
    printf("1. Add Task\n");
    printf("2. View Tasks\n");
    printf("3. Mark Task as Completed\n");
    printf("4. Delete Task\n");
    printf("5. Save Tasks\n");
    printf("0. Exit\n");
    printf("==============================\n");
}

void clearScreen() {
#ifdef _WIN32
    system("cls");
#else
    system("clear");
#endif
}

void addTask() {
    if (taskCount >= MAX_TASKS) {
        printf("\nError: Cannot add more tasks. Maximum limit reached!\n");
        getchar();
        return;
    }

    printf("\nEnter task description: ");
    fgets(tasks[taskCount].description, MAX_TASK_LENGTH, stdin);

    // Remove newline character if present
    tasks[taskCount].description[strcspn(tasks[taskCount].description, "\n")] = '\0';

    tasks[taskCount].id = taskCount + 1;
    tasks[taskCount].completed = false;

    taskCount++;
    printf("\nTask added successfully!\n");
    getchar(); // Wait for user input
}

void viewTasks() {
    clearScreen();
    printf("\n===== TASK LIST =====\n");

    if (taskCount == 0) {
        printf("No tasks available!\n");
    } else {
        for (int i = 0; i < taskCount; i++) {
            printf("%d. [%s] %s\n", 
                   tasks[i].id, 
                   tasks[i].completed ? "X" : " ", 
                   tasks[i].description);
        }
    }

    printf("======================\n");
    getchar(); // Wait for user input
}

void markCompleted() {
    int id;
    printf("\nEnter task ID to mark as completed: ");
    scanf("%d", &id);
    getchar(); // Consume newline

    bool found = false;
    for (int i = 0; i < taskCount; i++) {
        if (tasks[i].id == id) {
            tasks[i].completed = true;
            printf("\nTask #%d marked as completed!\n", id);
            found = true;
            break;
        }
    }

    if (!found) {
        printf("\nTask with ID %d not found!\n", id);
    }

    getchar(); // Wait for user input
}

void deleteTask() {
    int id;
    printf("\nEnter task ID to delete: ");
    scanf("%d", &id);
    getchar(); // Consume newline

    bool found = false;
    for (int i = 0; i < taskCount; i++) {
        if (tasks[i].id == id) {
            // Shift remaining elements
            for (int j = i; j < taskCount - 1; j++) {
                tasks[j] = tasks[j + 1];
            }

            taskCount--;
            printf("\nTask #%d deleted successfully!\n", id);
            found = true;
            break;
        }
    }

    if (!found) {
        printf("\nTask with ID %d not found!\n", id);
    }

    getchar(); // Wait for user input
}

void saveTasks() {
    FILE *file = fopen(FILENAME, "w");
    if (file == NULL) {
        printf("\nError: Could not open file for writing!\n");
        return;
    }

    fprintf(file, "%d\n", taskCount);
    for (int i = 0; i < taskCount; i++) {
        fprintf(file, "%d|%s|%d\n", 
                tasks[i].id, 
                tasks[i].description, 
                tasks[i].completed);
    }

    fclose(file);
    printf("\nTasks saved to %s\n", FILENAME);
}

void loadTasks() {
    FILE *file = fopen(FILENAME, "r");
    if (file == NULL) {
        // File doesn't exist yet, start fresh
        taskCount = 0;
        return;
    }

    fscanf(file, "%d", &taskCount);
    getchar(); // Consume newline

    for (int i = 0; i < taskCount; i++) {
        char line[256];
        if (fgets(line, sizeof(line), file) == NULL) break;

        // Parse the line
        int id;
        char description[MAX_TASK_LENGTH];
        int completed;

        sscanf(line, "%d|%[^|]|%d", &id, description, &completed);

        tasks[i].id = id;
        strcpy(tasks[i].description, description);
        tasks[i].completed = (completed == 1);
    }

    fclose(file);
    printf("\nLoaded %d tasks from %s\n", taskCount, FILENAME);
}
```

## How to Compile and Run

1. Save the code above in a file named `todo.c`
2. Open a terminal/command prompt and navigate to the directory containing the file
3. Compile the program using:
   ```bash
   gcc todo.c -o todo
   ```
4. Run the program using:
   ```bash
   ./todo
   ```

## Features

- **Persistence**: Tasks are saved to `todo.txt` and loaded when the app starts
- **User-friendly interface**: Clear menu and instructions
- **Error handling**: Checks for overflow, invalid inputs, etc.
- **File-based storage**: Tasks are stored in a plain text file

## Usage Tips

- Press Enter after each input to confirm
- Use the menu numbers to select actions
- The `save` option will save current progress to the file
- If you close the app, your tasks will be preserved for next time

This simple todo app provides a solid foundation that you can extend with additional features like due dates, categories, or a GUI interface.

