        return;
    }

    printf("Removendo %s da fila.\n", fila[0].nomePessoa);

    // Move todos os elementos para a esquerda
    for (int i = 0; i < *qtdFila - 1; i++) {
        fila[i] = fila[i + 1];
    }
    (*qtdFila)--;

