// Function to find and count repeated numbers
void countRepetitions(int arr[], int n) {
    // We'll use a simple approach: compare each element with others
    // For efficiency, you could use a hash map, but for simplicity, we use a nested loop

    printf("Repeating numbers and their frequencies:\n");

    // We'll keep track of already printed numbers to avoid duplicates
    int *visited = (int*)calloc(n, sizeof(int));
    if (visited == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    for (int i = 0; i < n; i++) {
        if (visited[i]) continue; // Skip if already processed

        int count = 1;
        for (int j = i + 1; j < n; j++) {
            if (arr[i] == arr[j]) {
                count++;
                visited[j] = 1; // Mark as visited
            }
        }

        // Only print if the number appears more than once
        if (count > 1) {
            printf("%d appears %d times\n", arr[i], count);
        }

        // Mark current number as visited
        visited[i] = 1;
    }

    free(visited);
}

int main() {
