// 函數：求解雞兔同籠問題，使用指針傳遞結果
void chicken_rabbit(int total_heads, int total_feet, int* chicken, int* rabbit) {
    // 檢查條件是否合乎邏輯
    if (total_feet % 2 != 0 || total_feet < 2 * total_heads || total_feet > 4 * total_heads) {
        *chicken = -1;  // 表示無解
        *rabbit = -1;
        return;
    }

    // 計算兔子數量
    *rabbit = (total_feet / 2) - total_heads;
    // 雞數量
