```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 100
#define INF 32767

// 并查集结构
typedef struct {
    int parent[MAXN];
    int rank[MAXN];
} UFSet;

// 边的数据结构
typedef struct {
    int u, v, w;
} Edge;

// 快速排序比较函数
int cmp(const void *a, const void *b) {
    return ((Edge*)a)->w - ((Edge*)b)->w;
}

// 并查集初始化
void MakeSet(UFSet *uf, int n) {
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

// 找父节点 + 路径压缩
int Find(UFSet *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = Find(uf, uf->parent[x]);
    return uf->parent[x];
}

// 合并两个集合，按秩合并
int Union(UFSet *uf, int x, int y) {
    int rootX = Find(uf, x);
    int rootY = Find(uf, y);
    if (rootX == rootY) return 0; // 已在同一集合，不能合并（避免环）

    if (uf->rank[rootX] < uf->rank[rootY])
        swap(rootX, rootY);
    if (uf->rank[rootX] == uf->rank[rootY])
        uf->rank[rootX]++;
    uf->parent[rootY] = rootX;
    return 1;
}

// 打印交换宏
#define swap(a,b) do { int t = a; a = b; b = t; } while(0)

// Kruskal 算法主函数
void Kruskal(int n, int edges[][MAXN]) {
    printf("Kruskal:\n");

    Edge edgeList[MAXN * MAXN];
    int edgeCount = 0;

    // 构建边列表（无向图，只取上三角或下三角，避免重复）
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (edges[i][j] < INF) { // 有效边（非无穷）
                edgeList[edgeCount].u = i;
                edgeList[edgeCount].v = j;
                edgeList[edgeCount].w = edges[i][j];
                edgeCount++;
            }
        }
    }

    // 按权重从小到大排序
    qsort(edgeList, edgeCount, sizeof(Edge), cmp);

    // 初始化并查集
    UFSet uf;
    MakeSet(&uf, n);

    int treeEdges = 0;
    for (int i = 0; i < edgeCount && treeEdges < n - 1; i++) {
        Edge e = edgeList[i];
        if (Union(&uf, e.u, e.v)) {
            printf("(%d,%d):%d\n", e.u, e.v, e.w);
            treeEdges++;
        }
    }
}

int main() {
    int n, e;
    scanf("%d %d", &n, &e);

    int edges[MAXN][MAXN];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &edges[i][j]);
            // 原始0表示无边？不，题说0是自环，不参与；但注意：若为0且非自环则可能合法
            // 实际上根据样例：0表示自环，其余非负值表示边权
            // 而且样例中所有非0非32767都是合理边权
            // 所以我们要保留正常权重，把32767当作无效边（无穷）
            // 因此我们不需要修改0
            // 错误修正：不要再把0改为32767！
        }
    }

    // 开始运行Kruskal
    Kruskal(n, edges);

    return 0;
}
