Voici un programme **C** complet qui respecte vos spécifications :

- Il prend une chaîne de caractères en argument.
- Utilise les **sockets UDP**.
- Crée deux processus : père et fils.
- Le **processus père** envoie chaque seconde la chaîne en argument à `255.255.255.255` (broadcast) sur le port **2346**, et tous les **30 secondes**, affiche le tableau `tb`.
- Le **processus fils** écoute sur le port **2346**, et quand il reçoit un message **identique** à l’argument, il ajoute l’**adresse IP** et **port d’origine** du message dans un tableau `tb`.
- Après avoir traité un message, il reste en attente.

---

### ✅ Remarques importantes :
- Le tableau `tb` est partagé entre les deux processus (mais ici, on le montre sous forme de **tableau local au fils**, avec un accès via mémoire partagée ou communication… mais comme les processus sont créés par `fork`, on ne peut pas partager directement des données sauf avec `shm`).
- Pour simplifier, nous allons **utiliser un fichier temporaire** ou **une mémoire partagée** pour permettre la lecture du tableau par le père (car les variables locales ne sont pas partagées après `fork`).
- Ici, on utilise **mémoire partagée (shared memory)** via `shmget`/`shmat`.

---

### 📌 Prérequis
Compilez avec :
```bash
gcc -o udp_bcast_program udp_bcast_program.c -lrt
```

> Nécessite la bibliothèque `rt` pour `shmget`.

---

## ✅ Code complet (UDP Broadcast + Fork + Shared Memory)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/shm.h>
#include <errno.h>

#define PORT 2346
#define BROADCAST_ADDR "255.255.255.255"
#define BUFFER_SIZE 1024
#define SHM_KEY 12345
#define MAX_ENTRIES 50

// Structure pour stocker les adresses sources
typedef struct {
    char ip[16];
    int port;
} SourceEntry;

// Tableau partagé
typedef struct {
    SourceEntry entries[MAX_ENTRIES];
    int count;
} SharedTB;

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <chaine_a_envoyer>\n", argv[0]);
        exit(1);
    }

    char *target_string = argv[1];
    int len = strlen(target_string);

    // Création de la mémoire partagée pour le tableau tb
    int shm_id = shmget(SHM_KEY, sizeof(SharedTB), IPC_CREAT | 0666);
    if (shm_id == -1) {
        perror("shmget");
        exit(1);
    }

    SharedTB *tb = (SharedTB *)shmat(shm_id, NULL, 0);
    if (tb == (void *) -1) {
        perror("shmat");
        exit(1);
    }

    // Initialisation du tableau
    tb->count = 0;

    // Création du socket UDP pour envoi (père)
    int sock_send = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_send < 0) {
        perror("socket (send)");
        exit(1);
    }

    // Activer le broadcast
    int broadcast_enable = 1;
    if (setsockopt(sock_send, SOL_SOCKET, SO_BROADCAST, &broadcast_enable, sizeof(broadcast_enable)) < 0) {
        perror("setsockopt SO_BROADCAST");
        close(sock_send);
        exit(1);
    }

    // Configuration de la structure d'envoi
    struct sockaddr_in broadcast_addr;
    memset(&broadcast_addr, 0, sizeof(broadcast_addr));
    broadcast_addr.sin_family = AF_INET;
    broadcast_addr.sin_port = htons(PORT);
    inet_pton(AF_INET, BROADCAST_ADDR, &broadcast_addr.sin_addr);

    // Création du socket UDP pour réception (fils)
    int sock_recv = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_recv < 0) {
        perror("socket (recv)");
        shmdt(tb);
        exit(1);
    }

    // Configuration du socket réception
    struct sockaddr_in local_addr;
    memset(&local_addr, 0, sizeof(local_addr));
    local_addr.sin_family = AF_INET;
    local_addr.sin_port = htons(PORT);
    local_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sock_recv, (struct sockaddr*)&local_addr, sizeof(local_addr)) < 0) {
        perror("bind");
        close(sock_send);
        close(sock_recv);
        shmdt(tb);
        exit(1);
    }

    // Fork pour créer le processus fils
    pid_t pid = fork();

    if (pid < 0) {
        perror("fork");
        close(sock_send);
        close(sock_recv);
        shmdt(tb);
        exit(1);
    }

    // Processus fils : écouteur
    if (pid == 0) {
        printf("Fils (%d) en écoute sur le port %d...\n", getpid(), PORT);
        char buffer[BUFFER_SIZE];
        struct sockaddr_in sender_addr;
        socklen_t sender_len = sizeof(sender_addr);

        while (1) {
            int n = recvfrom(sock_recv, buffer, BUFFER_SIZE - 1, 0,
                             (struct sockaddr *)&sender_addr, &sender_len);
            if (n < 0) {
                perror("recvfrom");
                continue;
            }
            buffer[n] = '\0';

            // Comparer le message reçu avec l'argument
            if (strcmp(buffer, target_string) == 0) {
                // Ajouter l'adresse et le port dans le tableau partagé
                if (tb->count < MAX_ENTRIES) {
                    strcpy(tb->entries[tb->count].ip, inet_ntoa(sender_addr.sin_addr));
                    tb->entries[tb->count].port = ntohs(sender_addr.sin_port);
                    tb->count++;
                    printf("Fils: Message identique reçu de %s:%d, ajouté à tb.\n",
                           inet_ntoa(sender_addr.sin_addr), ntohs(sender_addr.sin_port));
                } else {
                    printf("Tableau tb plein !\n");
                }
            } else {
                printf("Fils: Message reçu (différent) : %s\n", buffer);
            }
        }
    }

    // Processus père : émetteur
    else {
        printf("Père (%d) envoi chaque seconde du message : '%s'\n", getpid(), target_string);
        int sec_count = 0;

        while (1) {
            // Envoyer chaque seconde
            if (sendto(sock_send, target_string, len, 0,
                       (struct sockaddr*)&broadcast_addr, sizeof(broadcast_addr)) < 0) {
                perror("sendto");
            } else {
                printf("Père: Message envoyé à %s:%d\n", BROADCAST_ADDR, PORT);
            }

            sleep(1);

            // Tous les 30 secondes, afficher le tableau tb
            sec_count++;
            if (sec_count % 30 == 0) {
                printf("\n--- Père : Affichage du tableau tb après %d seconds ---\n", sec_count);
                for (int i = 0; i < tb->count; i++) {
                    printf("  [%d] Source: %s:%d\n", i+1, tb->entries[i].ip, tb->entries[i].port);
                }
                printf("---------------------------------------------\n\n");
            }
        }
    }

    // On n'arrive jamais ici si tout est bien géré, mais pour la sécurité
    close(sock_send);
    close(sock_recv);
    shmdt(tb);
    shmctl(shm_id, IPC_RMID, NULL); // Supprimer la mémoire partagée

    return 0;
}
```

---

### 🔧 Comment utiliser

1. Compilez :
   ```bash
   gcc -o udp_bcast_program udp_bcast_program.c -lrt
   ```

2. Exécutez :
   ```bash
   ./udp_bcast_program "Bonjour"
   ```

3. Lorsqu’un autre appareil (ou processus) envoie `"Bonjour"` via UDP sur le port 2346, le fils détecte le message et ajoute l’envoyeur (`IP:PORT`) à `tb`.

4. Le père affiche le contenu de `tb` toutes les **30 secondes**.

---

### ⚠️ Limitations / Notes

- Le programme fonctionne sur un réseau local (le broadcast peut être bloqué par les pare-feux).
- En environnement réel, les PC peuvent ignorer les paquets de broadcast.
- Pour tester sans réseau, vous pouvez **lancer deux instances sur la même machine** et faire qu’elles s’écrivent mutuellement.

