    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

char* base64_encode(const unsigned char* data, int len) {
    int i = 0, j = 0;
    int padding = 0;
    char *result = malloc(4 * ((len + 2) / 3) + 1);
    if (!result) return NULL;

    while (i < len) {
        result[j++] = base64_chars[(data[i] >> 2) & 0x3F];
        result[j++] = base64_chars[((data[i] << 4) | (i + 1 < len ? (data[i+1] >> 4) : 0)) & 0x3F];

        padding = (i + 1 < len) ? 1 : 2;
