            return NULL;
        }

        if (i + 1 < len && encoded_data[i+1] != '=') {
            int val2 = strcspn(encoded_data + i+1, base64_chars);
            if (val2 >= 64) { free(result); return NULL; }

            result[j++] = ((val1 & 0x3F) << 2) | ((val2 & 0x3F) >> 4);

            if (i + 2 < len && encoded_data[i+2] != '=') {
                int val3 = strcspn(encoded_data + i+2, base64_chars);
                if (val3 >= 64) { free(result); return NULL; }

                result[j++] = ((val2 & 0x3F) << 4) | ((val3 & 0x3F) >> 2);

                if (i + 3 < len && encoded_data[i+3] != '=') {
                    int val4 = strcspn(encoded_data + i+3, base64_chars);
                    if (val4 >= 64) { free(result); return NULL; }

                    result[j++] = ((val3 & 0x3F) << 6) | (val4 & 0x3F);
                }
            }
        } else {
            result[j++] = ((val1 & 0x3F) << 2);
        }

        i += 3;
    }

    *decoded_len = j - pad_count;
    return result;
}
