```c
// server.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <ctype.h>
#include "base64.h"

#define PORT 8080
#define MAX_BACKLOG 5
#define BUFFER_SIZE 4096

void *handle_client(void *arg);
int connect_to_target(const char *host, int port);

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, MAX_BACKLOG) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("HTTP Tunnel Server listening on port %d...\n", PORT);

    while (1) {
        if ((new_socket = accept(server_fd, NULL, NULL)) < 0) {
            perror("Accept failed");
            continue;
        }

        pthread_t tid;
        if (pthread_create(&tid, NULL, handle_client, &new_socket) != 0) {
            perror("Thread creation failed");
            close(new_socket);
        } else {
            pthread_detach(tid);
        }
    }

    close(server_fd);
    return 0;
}

void *handle_client(void *arg) {
    int sock = *(int *)arg;
    char buffer[BUFFER_SIZE];
    char header[BUFFER_SIZE];
    char *body_start;
    int body_len = 0;

    // Read headers
    int n = recv(sock, header, BUFFER_SIZE - 1, 0);
    if (n <= 0) goto cleanup;

    header[n] = '\0';

    // Simple HTTP header parsing (just find \r\n\r\n)
    body_start = strstr(header, "\r\n\r\n");
    if (!body_start) {
        send(sock, "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n", 48, 0);
        goto cleanup;
    }

    body_start += 4;
    body_len = n - (body_start - header);

    // Extract body (Base64-encoded)
    int decoded_len = 0;
    unsigned char *raw_data = base64_decode(body_start, &decoded_len);
    if (!raw_data) {
        send(sock, "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n", 48, 0);
        goto cleanup;
    }

    // First 4 bytes: target port (network order)
    if (decoded_len < 4) {
        send(sock, "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n", 48, 0);
        free(raw_data);
        goto cleanup;
    }

    uint16_t target_port = (raw_data[0] << 8) | raw_data[1];
    uint16_t target_ip_len = (raw_data[2] << 8) | raw_data[3];

    if (target_ip_len > 15 || target_ip_len < 4) {
        send(sock, "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n", 48, 0);
        free(raw_data);
        goto cleanup;
    }

    char target_ip[16];
    strncpy(target_ip, (char*)(raw_data + 4), target_ip_len);
    target_ip[target_ip_len] = '\0';

    // Remove target IP + port from payload
    int payload_len = decoded_len - 4 - target_ip_len;
    unsigned char *payload = raw_data + 4 + target_ip_len;
    free(raw_data);

    printf("Connecting to %s:%u\n", target_ip, target_port);

    int target_sock = connect_to_target(target_ip, target_port);
    if (target_sock < 0) {
        send(sock, "HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\n\r\n", 46, 0);
        free(payload);
        goto cleanup;
    }

    // Forward payload to remote target
    send(target_sock, payload, payload_len, 0);

    // Loop: forward data both directions
    while (1) {
        int r = recv(sock, buffer, BUFFER_SIZE, 0);
        if (r <= 0) break;

        unsigned char *b64_data = base64_encode(buffer, r);
        send(target_sock, b64_data, strlen(b64_data), 0);
        free(b64_data);
    }

    // Read replies from target
    while (1) {
        int r = recv(target_sock, buffer, BUFFER_SIZE, 0);
        if (r <= 0) break;

        unsigned char *b64_data = base64_encode(buffer, r);
        send(sock, b64_data, strlen(b64_data), 0);
        free(b64_data);
    }

    shutdown(target_sock, SHUT_RDWR);
    close(target_sock);
    close(sock);
    pthread_exit(NULL);

cleanup:
    close(sock);
    pthread_exit(NULL);
}

int connect_to_target(const char *host, int port) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return -1;

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, host, &addr.sin_addr) <= 0) {
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(sock);
        return -1;
    }
    return sock;
}
