// client.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include "base64.h"

#define SERVER_HOST "localhost"
#define SERVER_PORT 8080
#define BUFFER_SIZE 4096

void *proxy_thread(void *arg);

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <target_host> <target_port> <local_port>\n", argv[0]);
        return 1;
    }

    const char *target_host = argv[1];
    int target_port = atoi(argv[2]);
    int local_port = atoi(argv[3]);

    // Create local listener
    int listening_sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(local_port);

    bind(listening_sock, (struct sockaddr*)&addr, sizeof(addr));
    listen(listening_sock, 1);

    printf("Listening on localhost:%d → tunneling to %s:%d\n", local_port, target_host, target_port);

    while (1) {
        int client_sock = accept(listening_sock, NULL, NULL);
        if (client_sock < 0) continue;

        pthread_t tid;
        if (pthread_create(&tid, NULL, proxy_thread, &client_sock) != 0) {
            perror("Thread creation failed");
            close(client_sock);
        } else {
            pthread_detach(tid);
        }
    }

    close(listening_sock);
    return 0;
}

void *proxy_thread(void *arg) {
    int client_sock = *(int*)arg;

    // Build payload: [port][hostname length][hostname][data]
    int port_bytes[2] = { (target_port >> 8) & 0xFF, target_port & 0xFF };
    int hlen = strlen(target_host);

    unsigned char *payload = malloc(4 + hlen + 1024);  // Extra room
    memcpy(payload, port_bytes, 2);
    payload[2] = hlen >> 8;
    payload[3] = hlen & 0xFF;
    memcpy(payload + 4, target_host, hlen);

    // Send request to server
    char request[1024];
    snprintf(request, 1024,
             "POST /tunnel HTTP/1.1\r\nHost: %s:%d\r\nContent-Type: application/octet-stream\r\nContent-Length: %zu\r\n\r\n",
             SERVER_HOST, SERVER_PORT, 4 + hlen);

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_HOST, &serv_addr.sin_addr) <= 0) {
        close(sock);
        goto cleanup;
    }

    if (connect(sock, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        close(sock);
        goto cleanup;
    }

    send(sock, request, strlen(request), 0);

    // Send rest of payload + Base64 encode
    int total_len = 4 + hlen;
    unsigned char *b64_data = base64_encode(payload, total_len);
    send(sock, b64_data, strlen(b64_data), 0);
    free(b64_data);
    free(payload);

    // Now: relay data bidirectional
    while (1) {
        int r = recv(client_sock, payload, 1024, 0);
        if (r <= 0) break;

        b64_data = base64_encode(payload, r);
        send(sock, b64_data, strlen(b64_data), 0);
        free(b64_data);
    }

    // Read from server
    while (1) {
        int r = recv(sock, payload, 1024, 0);
        if (r <= 0) break;

        int decoded_len = 0;
        unsigned char *raw = base64_decode((char*)payload, &decoded_len);
        if (!raw) continue;

        send(client_sock, raw, decoded_len, 0);
        free(raw);
    }

    close(sock);
    close(client_sock);
    free(payload);

cleanup:
    close(sock);
    close(client_sock);
    pthread_exit(NULL);
}
