#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FUNC_NAME_LEN 64
#define MAX_FUNCTIONS 1000

// Структура для узла дерева вызовов
typedef struct FunctionNode {
    char name[MAX_FUNC_NAME_LEN];
    int call_count; // сколько раз была вызвана
    struct FunctionNode* parents; // список вызывающих функций
    int parent_count;
    struct FunctionNode* children; // список вызываемых функций
    int child_count;
} FunctionNode;

// Глобальный массив функций
FunctionNode functions[MAX_FUNCTIONS];
int func_count = 0;

// Функция поиска функции по имени
FunctionNode* find_function(const char* name) {
    for (int i = 0; i < func_count; i++) {
        if (strcmp(functions[i].name, name) == 0) {
            return &functions[i];
        }
    }
    return NULL;
}

// Добавление функции (если ещё не существует)
FunctionNode* add_function(const char* name) {
    FunctionNode* node = find_function(name);
    if (node != NULL) {
        return node;
    }

    if (func_count >= MAX_FUNCTIONS) {
        fprintf(stderr, "Ошибка: слишком много функций!\n");
        exit(1);
    }

    strcpy(functions[func_count].name, name);
    functions[func_count].call_count = 0;
    functions[func_count].parent_count = 0;
    functions[func_count].child_count = 0;
    functions[func_count].parents = NULL;
    functions[func_count].children = NULL;

    return &functions[func_count++];
}

// Добавление связи: caller вызывает callee
void add_call(const char* caller_name, const char* callee_name) {
    FunctionNode* caller = add_function(caller_name);
    FunctionNode* callee = add_function(callee_name);

    // Проверяем, нет ли уже такого вызова
    for (int i = 0; i < caller->child_count; i++) {
        if (strcmp(caller->children[i].name, callee_name) == 0) {
            return; // дубль — игнорируем
        }
    }

    // Добавляем вызоваемую функцию
    if (caller->child_count >= MAX_FUNCTIONS) return;
    FunctionNode* new_child = &caller->children[caller->child_count];
    strcpy(new_child->name, callee_name);
    new_child->call_count = 1;
    caller->child_count++;

    // Добавляем в обратную зависимость: указатель на вызывающую
    if (callee->parent_count >= MAX_FUNCTIONS) return;
    FunctionNode* new_parent = &callee->parents[callee->parent_count];
    strcpy(new_parent->name, caller_name);
    callee->parent_count++;
}

// Проверка, является ли символ частью строки
bool is_inside_string(char ch, bool in_string) {
    return in_string ? (ch != '"') : false;
}

// Проверка, является ли символ частью комментария (многострочного)
bool is_inside_comment(char ch, bool in_comment) {
    static bool prev_was_star = false;
    if (in_comment) {
        if (ch == '/' && prev_was_star) {
