#include <stdio>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_LINES 1000
#define MAX_LINE 1024

typedef struct {
    char name[64];
    bool defined;
} Func;

Func functions[1000];
int func_count = 0;

// Найти функцию по имени
int find_func(const char* name) {
    for (int i = 0; i < func_count; i++) {
        if (strcmp(functions[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}

// Добавить функцию
int add_func(const char* name) {
    int idx = find_func(name);
    if (idx != -1) {
        return idx;
    }
    strcpy(functions[func_count].name, name);
    functions[func_count].defined = false;
    return func_count++;
}

// Добавить вызов
// (например, если видим "func()", то это вызов)
void add_call(const char* caller, const char* callee) {
    int c1 = add_func((char*)caller);
    int c2 = add_func((char*)callee);
    if (c1 != -1 && c2 != -1 && !functions[ c2 ].defined) {
        // Просто выводим
        printf("%s -> %s,\ ", caller, callee);
    }
}

