        int len = strlen(line);
        for (int i = 0; i < len - 1; i++) {
            if (line[i] == '(' && line[i+1] == ')' && i > 0) {
                // Найдено: `(...)` → ищем имя до нее
                int start = i - 1;
                while (start >= 0 && (isalnum(line[start]) || line[start] == '_')) {
                    start--;
                }
                start++;
                if (start == i) continue; // не было букв
                int len_name = i - start;
                char name[64] = {0};
                strncpy (name, line + start, len_name);
                name[len_name] = '\0';

                // Теперь `name` — вызываемая функция
                // Это вызов — но кто вызывает?
                // Нам нужен контекст
                // Пока — не можем, потому что не знаем, в какой функции

                // Допустим, что каждый вызов — вызов функции
                // А в любом месте — `foo()` — вызов
                // А `foo` — функция
                add_call("global", name); // временный вызов
            }
        }
    }

