### ✅ Code hoàn chỉnh trong C:

```c
#include <stdio.h>
#include <stdlib.h>

// Hàm kiểm tra số có phải là số đối xứng (palindrome) không
int laSoDoiXung(int n) {
    int temp = n;
    int reversed = 0;

    while (temp > 0) {
        reversed = reversed * 10 + temp % 10;
        temp /= 10;
    }

    return (n == reversed);
}

int main() {
    int n;
    printf("Nhập số lượng số nguyên: ");
    scanf("%d", &n);

    if (n <= 0) {
        printf("Số lượng phải lớn hơn 0.\n");
        return 1;
    }

    int numbers[1000]; // Dùng mảng lưu các số nhập vào
    int count = 0;     // Đếm số lượng số đối xứng
    long sum = 0;      // Tổng các số đối xứng

    // Nhập n số
    for (int i = 0; i < n; i++) {
        printf("Nhập số thứ %d: ", i + 1);
        scanf("%d", &numbers[i]);

        // Kiểm tra nếu số là đối xứng
        if (laSoDoiXung(numbers[i])) {
            count++;
            sum += numbers[i];
        }
    }

    // Tính và in kết quả
    if (count == 0) {
        printf("Không có số đối xứng nào trong danh sách.\n");
    } else {
        double trungBinh = (double)sum / count;
        printf("Có %d số đối xứng. Trung bình cộng của chúng là: %.2f\n", count, trungBinh);
    }

    return 0;
}
```

