#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/sem.h>
#include <string.h>

// Kody czynności z konsoli
#define LOCK_1   '1'
#define UNLOCK_1 'q'
#define LOCK_2   '2'
#define UNLOCK_2 'w'

// Funkcja inicjalizacji semafora
int init_semaphore(key_t key) {
    int semid = semget(key, 2, IPC_CREAT | 0666);
    if (semid == -1) {
        perror("semget");
        exit(1);
    }

    // Inicjalizacja obu semaforów do wartości 1 (dostępny)
    struct sembuf sb;
    sb.sem_num = 0; // semafor 1
    sb.sem_op = 1;
    sb.sem_flg = 0;
    if (semop(semid, &sb, 1) == -1) {
        perror("semop init 1");
        exit(1);
    }

    sb.sem_num = 1; // semafor 2
    if (semop(semid, &sb, 1) == -1) {
        perror("semop init 2");
        exit(1);
    }
    printf("Semaforzy zainicjalizowane.\n");
    return semid;
}

// Funkcja odczytywania klawisza z klawiatury
char get_command() {
    char ch;
    printf("Wybierz akcję:\n");
    printf("1 – zajmij semafor 1\n");
    printf("q – zwolnij semafor 1\n");
    printf("2 – zajmij semafor 2\n");
    printf("w – zwolnij semafor 2\n");

    fflush(stdout);
    scanf(" %c", &ch);  // Zerowa spacja przed %c usuwa białe znaki
    return ch;
}

int main() {
    // Unikalny klucz (można zmienić na inne liczby np. 1234)
    key_t key = 1234;

    int semid = init_semaphore(key);

    while (1) {
        char cmd = get_command();

        struct sembuf sb;
        int sem_num = -1;
        int sem_op = 0;

        switch (cmd) {
            case '1':
                sem_num = 0;
                sem_op = -1;
                break;
            case 'q':
                sem_num = 0;
                sem_op = +1;
                break;
            case '2':
                sem_num = 1;
                sem_op = -1;
                break;
            case 'w':
                sem_num = 1;
                sem_op = +1;
                break;
            default:
                printf("Nieznana komenda!\n");
                continue;
        }

        // Wykonaj operację semaforową
        sb.sem_num = sem_num;
        sb.sem_op = sem_op;
        sb.sem_flg = 0;

        printf("Oczekiwanie na semaphore %d (%c)\n", sem_num, cmd);
        if (semop(semid, &sb, 1) == -1) {
            perror("semop failed");
            exit(1);
        }

        printf("Operacja zakończona pomyślnie.\n");
    }

    return 0;
}
