#include <stdio.h>
#include <string.h>

int longestPalindromeLength(char* s) {
    int n = strlen(s);
    if (n == 0) return 0;

    int maxLen = 1; // حداقل یک کاراکتر پالیندروم است

    // بررسی تمام موقعیت‌های ممکن به عنوان مرکز
    for (int i = 0; i < n; i++) {
        // برای حالت فرد (مرکز روی یک کاراکتر)
        int left = i - 1;
        int right = i + 1;
        while (left >= 0 && right < n && s[left] == s[right]) {
            maxLen = (right - left + 1) > maxLen ? (right - left + 1) : maxLen;
            left--;
            right++;
        }

        // برای حالت زوج (مرکز بین دو کاراکتر)
        left = i;
        right = i + 1;
        while (left >= 0 && right < n && s[left] == s[right]) {
            maxLen = (right - left + 1) > maxLen ? (right - left + 1) : maxLen;
            left--;
            right++;
        }
    }

    return maxLen;
}

int main() {
    char s[1001]; // طول رشته حداکثر 1000
    scanf("%s", s);
    printf("%d\n", longestPalindromeLength(s));
    return 0;
}
```

