// Function to check if a string x is in L = {ww | w ∈ {a,b}*}
int is_in_L(char* x) {
    int len = strlen(x);
    // If odd length, cannot be ww
    if (len % 2 != 0) {
        return 0;
    }
    int half = len / 2;
    for (int i = 0; i < half; i++) {
        if (x[i] != x[i + half]) {
            return 0;
        }
    }
    return 1;
}

// Function to check if y is in L*
// Uses DP: dp[i] = true if y[0..i-1] can be written as concatenation of strings from L
int is_in_L_star(char* y) {
    int n = strlen(y);
    if (n == 0) {
        return 1;  // Empty string is in L^*
    }

    // dp[i] = 1 if prefix y[0..i-1] is in L^*
    int* dp = (int*)calloc(n + 1, sizeof(int));
    dp[0] = 1;  // Base case: empty string

    // Fill dp array
    for (int i = 1; i <= n; i++) {
        // Try every possible last string ending at position i (from j to i)
        for (int j = 0; j < i; j++) {
            int len_sub = i - j;
            // Extract substring y[j..i-1]
            // We can simulate it without copying: use pointer arithmetic
            char* substr = &y[j];
            // Check if this substring is in L
            if (is_in_L(substr)) {
                if (dp[j]) {
                    dp[i] = 1;
                    break;  // No need to check further: one valid split found
                }
            }
        }
    }

    int result = dp[n];
    free(dp);
    return result;
}

// Main function
