// Funzione 1: lettura del file magazzino
int leggi_magazzino(FILE *file_in, Prodotto magazzino[]) {
    int n = 0;
    char riga[256];

    while (fgets(riga, sizeof(riga), file_in) != NULL && n < MAX_PRODOTTI) {
        char codice[MAX_CODICE];
        double costo;
        int quantita;

        // Parsa la riga: codice, costo, quantità
