int verifica_aggiornamento(const char *codice, int variazione, const Prodotto magazzino[], int n_prodotti) {
    int index = -1;
    for (int i = 0; i < n_prodotti; i++) {
        if (strcmp(magazzino[i].codice, codice) == 0) {
            index = i;
            break;
        }
