### 📌 完整 C 代码如下：

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_VERTICES 100
#define INF INT_MAX

// 全局变量定义
int graph[MAX_VERTICES][MAX_VERTICES];  // 邻接矩阵
int D[MAX_VERTICES];                     // D[i]: 从V0到i的最短距离
int path[MAX_VERTICES];                  // path[i]: 路径中i的前驱节点
int visited[MAX_VERTICES];               // visited[i]: 是否已确定最短路径
int numVertices;                         // 顶点数

// 函数声明
void initializeGraph(int n);
void dijkstra(int start);
void printShortestPath(int start);

int main() {
    int i, j;

    printf("请输入顶点数量: ");
    scanf("%d", &numVertices);

    // 初始化图
    initializeGraph(numVertices);

    // 输入邻接矩阵（假设为有向图，若无向可对称处理）
    printf("请输入邻接矩阵 (用 -1 表示无边):\n");
    for (i = 0; i < numVertices; i++) {
        for (j = 0; j < numVertices; j++) {
            scanf("%d", &graph[i][j]);
            if (graph[i][j] == -1) graph[i][j] = INF;
        }
    }

    // 打印输入的图（可选）
    printf("\n输入的邻接矩阵:\n");
    for (i = 0; i < numVertices; i++) {
        for (j = 0; j < numVertices; j++) {
            if (graph[i][j] == INF)
                printf("%4s ", "∞");
            else
                printf("%4d ", graph[i][j]);
        }
        printf("\n");
    }

    // 所有顶点未被访问
    memset(visited, 0, sizeof(visited));

    // 运行 Dijkstra 算法，起点为 0 (V0)
    dijkstra(0);

    // 输出结果
    printShortestPath(0);

    return 0;
}

// 1）初始化：设置初始距离和路径
void initializeGraph(int n) {
    numVertices = n;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j)
                graph[i][j] = 0;
            else
                graph[i][j] = INF;
        }
    }
}

// 2）求最小：找出尚未访问且距离最小的顶点
int findMinDist() {
    int minDist = INF;
    int minIndex = -1;

    for (int i = 0; i < numVertices; i++) {
        if (!visited[i] && D[i] < minDist) {
            minDist = D[i];
            minIndex = i;
        }
    }
    return minIndex;
}

// 3）更新：更新与顶点k相邻的所有顶点的距离
void updateDistances(int k) {
    for (int i = 0; i < numVertices; i++) {
        if (graph[k][i] != INF && !visited[i]) {  // 存在边且未访问
            int newDist = D[k] + graph[k][i];
            if (newDist < D[i]) {
                D[i] = newDist;
                path[i] = k;
            }
        }
    }
}

// 4）主循环：执行 Dijkstra 算法
void dijkstra(int start) {
    // 步骤1：初始化
    for (int i = 0; i < numVertices; i++) {
        D[i] = graph[start][i];         // 初值为直接边权
        path[i] = (D[i] == INF) ? -1 : start;
        visited[i] = 0;
    }
    D[start] = 0;                      // 起点距离自己为0
    visited[start] = 1;                // 起点标记为已访问

    // 主循环：重复找最小顶点并更新
    for (int count = 1; count < numVertices; count++) {
        int k = findMinDist();  // 找最小值顶点
        if (k == -1) break;     // 若没有可达顶点则结束

        visited[k] = 1;         // 标记已访问

        updateDistances(k);     // 更新邻接顶点距离
    }
}

// 输出最短路径和距离
void printShortestPath(int start) {
    printf("\n从顶点 %d 到其他各顶点的最短路径及距离：\n", start);
    for (int i = 0; i < numVertices; i++) {
        if (i == start) continue;

        printf("到顶点 %d: ", i);
        if (D[i] == INF) {
            printf("不可达（距离为 ∞）\n");
        } else {
            printf("距离 = %d, 路径: ", D[i]);

            // 回溯路径
            int temp = i;
            int pathStack[MAX_VERTICES];
            int top = -1;

            while (temp != -1 && temp != start) {
                pathStack[++top] = temp;
                temp = path[temp];
            }
            pathStack[++top] = start;

            // 输出路径（从起点开始）
            for (int j = top; j >= 0; j--) {
                printf("%d", pathStack[j]);
                if (j > 0) printf(" -> ");
            }
            printf("\n");
        }
    }
}
```

