#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/err.h>

// Generate derived keys using X9.63 KDF
int derive_keys(const unsigned char *secret, size_t secret_len,
                const unsigned char *salt, size_t salt_len,
                const unsigned char *info, size_t info_len,
                unsigned char *aes_key, size_t aes_key_len,
                unsigned char *hmac_key, size_t hmac_key_len) {

    // Initialize context
    EVP_KDF_CTX *ctx = EVP_KDF_CTX_new_by_name("x963");
    if (!ctx) {
        fprintf(stderr, "Error: Failed to create KDF context\n");
        return -1;
    }

    // Set parameters: digest (SHA512), secret, salt, info
    if (!EVP_KDF_CTX_set_param(ctx, EVP_KDF_PARAM_DIGEST, "sha512") ||
        !EVP_KDF_CTX_set_param(ctx, EVP_KDF_PARAM_KEY, secret, secret_len) ||
        !EVP_KDF_CTX_set_param(ctx, EVP_KDF_PARAM_SALT, salt, salt_len) ||
        !EVP_KDF_CTX_set_param(ctx, EVP_KDF_PARAM_INFO, info, info_len)) {
        fprintf(stderr, "Error: Failed to set KDF parameters\n");
        EVP_KDF_CTX_free(ctx);
        return -1;
    }

    // Allocate buffer for output (we’ll split it later)
    size_t total_len = aes_key_len + hmac_key_len;
    unsigned char *derived = OPENSSL_malloc(total_len);
    if (!derived) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        EVP_KDF_CTX_free(ctx);
        return -1;
    }

    // Perform derivation
    if (!EVP_KDF_derive(ctx, derived, total_len)) {
        fprintf(stderr, "Error: KDF derivation failed\n");
        OPENSSL_free(derived);
        EVP_KDF_CTX_free(ctx);
        return -1;
    }

    // Split the output:
    memcpy(aes_key, derived, aes_key_len);  // First 16 bytes -> AES-128
    memcpy(hmac_key, derived + aes_key_len, hmac_key_len);  // Remaining -> HMAC

    OPENSSL_free(derived);
    EVP_KDF_CTX_free(ctx);

    return 0;  // Success
}

// Helper: print hex data
void print_hex(const char *label, const unsigned char *data, size_t len) {
    printf("%s: ", label);
    for (size_t i = 0; i < len; i++) {
        printf("%02X", data[i]);
    }
    printf("\n");
}

