以下是使用 C 語言編寫的程式，用來找出一串整數中**最長嚴格遞增子數列**（Longest Strictly Increasing Subsequence, LSIS）。

> ✅ **說明**：  
> - “子數列” 是指保持原順序但不要求連續的元素集合。  
> - “嚴格遞增” 意思是後一個數必須 **大於** 前一個數（不能相等）。  
> - 我們要求的是 **最長** 的這種子序列。

---

### ✅ 程式碼（使用動態規劃方法）：

```c
#include <stdio.h>
#include <stdlib.h>

// 函數：找最長嚴格遞增子數列的長度與對應的子數列
void findLongestIncreasingSubsequence(int arr[], int n) {
    if (n == 0) {
        printf("輸入陣列為空。\n");
        return;
    }

    // dp[i] 表示以 arr[i] 結尾的最長嚴格遞增子數列長度
    int *dp = (int*)calloc(n, sizeof(int));
    int *prev = (int*)calloc(n, sizeof(int)); // 用來記錄前一個索引，用於重建解

    // 初始化：每一個元素本身可以構成長度為 1 的子數列
    for (int i = 0; i < n; i++) {
        dp[i] = 1;
        prev[i] = -1;
    }

    // 填充 dp 表
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (arr[j] < arr[i]) {  // 严格递增条件
                if (dp[j] + 1 > dp[i]) {
                    dp[i] = dp[j] + 1;
                    prev[i] = j;
                }
            }
        }
    }

    // 找出最大值和其對應的索引
    int max_length = dp[0];
    int max_index = 0;
    for (int i = 1; i < n; i++) {
        if (dp[i] > max_length) {
            max_length = dp[i];
            max_index = i;
        }
    }

    // 重建最長遞增子數列
    int *result = (int*)malloc(max_length * sizeof(int));
    int idx = max_index;
    int pos = max_length - 1;

    while (idx != -1) {
        result[pos--] = arr[idx];
        idx = prev[idx];
    }

    // 輸出結果
    printf("最長嚴格遞增子數列長度: %d\n", max_length);
    printf("最長嚴格遞增子數列為: ");
    for (int i = 0; i < max_length; i++) {
        printf("%d ", result[i]);
    }
    printf("\n");

    // 釋放記憶體
    free(dp);
    free(prev);
    free(result);
}

// 測試主函數
int main() {
    int n;
    printf("請輸入整數個數: ");
    scanf("%d", &n);

    if (n <= 0) {
        printf("無效輸入！\n");
        return 1;
    }

    int *arr = (int*)malloc(n * sizeof(int));
    printf("請輸入 %d 個整數: ", n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    findLongestIncreasingSubsequence(arr, n);

    free(arr);
    return 0;
}
```

