// 用于存储遍历结果的数组和当前索引
int preOrder[101], inOrder[101], postOrder[101];
int idx_pre = 0, idx_in = 0, idx_post = 0;

// 先序遍历：根 -> 左 -> 右
void preorder(int root) {
    if (root == -1) return;
    preOrder[idx_pre++] = root;          // 访问根节点
    preorder(tree[root].left);           // 遍历左子树
    preorder(tree[root].right);          // 遍历右子树
}

// 中序遍历：左 -> 根 -> 右
void inorder(int root) {
    if (root == -1) return;
    inorder(tree[root].left);            // 遍历左子树
    inOrder[idx_in++] = root;            // 访问根节点
    inorder(tree[root].right);           // 遍历右子树
}

// 后序遍历：左 -> 右 -> 根
void postorder(int root) {
    if (root == -1) return;
    postorder(tree[root].left);          // 遍历左子树
    postorder(tree[root].right);         // 遍历右子树
    postOrder[idx_post++] = root;        // 访问根节点
}

