    // 读取每个节点的信息
    for (int i = 0; i < N; i++) {
        int node, l, r;
        scanf("%d %d %d", &node, &l, &r);
        tree[node].left = l;
        tree[node].right = r;
    }

    // 开始遍历，从根节点1开始
    idx_pre = idx_in = idx_post = 0;
    preorder(1);
    inorder(1);
    postorder(1);

    // 打印先序遍历
