Here's a complete **Quick Sort algorithm in C** with a function to generate an array of random `n` numbers:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Function to generate an array of n random integers
int* generateRandomArray(int n) {
    int *arr = (int*)malloc(n * sizeof(int));
    if (arr == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    for (int i = 0; i < n; i++) {
        arr[i] = rand() % 1000;  // Random numbers between 0 and 999
    }

    return arr;
}

// Partition function for QuickSort
int partition(int arr[], int low, int high) {
    int pivot = arr[high];  // Choose the rightmost element as pivot
    int i = low - 1;        // Index of smaller element

    for (int j = low; j < high; j++) {
        // If current element is smaller than or equal to pivot
        if (arr[j] <= pivot) {
            i++;
            // Swap arr[i] and arr[j]
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    // Place pivot in correct position
    int temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    return i + 1;
}

// Main QuickSort function
void quickSort(int arr[], int low, int high) {
    if (low < high) {
        // Partition index
        int pi = partition(arr, low, high);

        // Recursively sort elements before and after partition
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

// Function to print array
void printArray(int arr[], int n) {
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

// Main function to demonstrate the algorithm
int main() {
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    // Generate random array
    int *arr = generateRandomArray(n);

    printf("Original Array: ");
    printArray(arr, n);

    // Sort the array using QuickSort
    quickSort(arr, 0, n - 1);

    printf("Sorted Array:   ");
    printArray(arr, n);

    // Free allocated memory
    free(arr);

    return 0;
}
```

---

### 🔍 **How it works:**

- `generateRandomArray(n)`:
  - Dynamically allocates memory for `n` integers.
  - Fills them with random values (0–999).
  - Uses `srand(time(NULL))` to ensure different results each run.

- `partition()`:
  - Rearranges the array so that all elements less than or equal to the pivot come before it, and greater ones come after.

- `quickSort()`:
  - Applies divide-and-conquer recursively.

- `printArray()`:
  - A helper to display the data.

---

### 📌 Example Output:
```
Enter the number of elements: 6
Original Array: 456 23 789 12 678 34
Sorted Array:   12 23 34 456 678 789
```

---

### ✅ Notes:
- Time Complexity: Average case O(n log n), Worst case O(n²)
- Space Complexity: O(log n) due to recursion
- The pivot is chosen as the last element (can be improved by randomizing or median-of-three)

