    // Checa se há alguém na fila esperando por esse livro
    // Como só sabemos o código, procuramos na fila quem quer esse mesmo livro
    int encontrado = 0;
    for (int i = 0; i < MAX_FILA; i++) {
        if (strcmp(livros[indice].nome, fila[i].livroNome) == 0) {
            // Remove da fila
            for (int j = i; j < MAX_FILA - 1; j++) {
                fila[j] = fila[j + 1];
            }
            (*qtdFila)--;
            printf("\nAtenção: %s foi chamado(a) para retirar o livro '%s'.\n",
                   fila[i].nome, livros[indice].nome);
            encontrado = 1;
            break;
        }
    }

    if (!encontrado) {
        printf("\nNão há ninguém na fila esperando por este livro.\n");
    }
