// Environment: CSIM20 for discrete-event simulation
// Compiles: gcc -o cache_sim cache_invalidation_simulation.c csim20.c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>

// ------------------- Configuration -------------------
#define NUM_CLIENTS 5
#define DB_SIZE 500
#define CACHE_SIZE 100
#define DATA_ITEM_SIZE 1024 // bytes
#define BANDWIDTH 10000      // bits/sec
#define WARMUP_PERIOD 100    // seconds (to discard initial results)

// Time units: seconds
double T_QUERY_VALUES[] = {5, 10, 25, 50, 100};
double T_UPDATE_VALUES[] = {5, 10, 20, 100, 200};

int NUM_T_QUERY = 5;
int NUM_T_UPDATE = 5;

// Constants
#define MAX_DATA_ITEMS DB_SIZE
#define HOT_START 1
#define HOT_END 50
#define HOT_PROB 0.8     // probability of accessing hot data
#define UPD_PROB 0.33    // update probability for hot items

// Simulation state
double sim_time = 0;
double final_time = 1000; // Total simulation time (sec)
int warmup_completed = 0;

// Data Structures
typedef struct {
    int id;               // data item ID
    double last_updated;  // timestamp of last update
    int valid;            // 1 if current, 0 if stale
} DataItem;

typedef struct CacheEntry {
    int item_id;
    double last_accessed;
    int used; // for LRU tracking
} CacheEntry;

typedef struct Client {
    int id;
    CacheEntry cache[CACHE_SIZE];
    int cache_size;
    double last_query_time;
    int valid_check_sent;
    int num_queries, num_hits, num_misses, num_valid_checks, num_invalidated;
    double total_delay, avg_delay;
} Client;

DataItem server_db[MAX_DATA_ITEMS + 1];   // indexed 1 to 500
Client clients[NUM_CLIENTS];

// Utility: Random number generators
double random_exp(double lambda) {
    return (-log(1.0 - rand() / (double)RAND_MAX)) / lambda;
}

double random_uniform(int min, int max) {
    return min + (double)(rand()) / RAND_MAX * (max - min);
}

int random_choice(double prob) {
    return (rand() / (double)RAND_MAX < prob) ? 1 : 0;
}

// Helper: Get a random item (hot with 80% prob, cold with 20%)
int get_random_item() {
    if (random_choice(HOT_PROB)) {
        return (int)(random_uniform(HOT_START, HOT_END + 1));
    } else {
        return (int)(random_uniform(HOT_END + 1, DB_SIZE + 1));
    }
}

// Initialize the simulation
void initialize_simulation() {
    srand(time(NULL));

    // Init server DB
    for (int i = 1; i <= DB_SIZE; i++) {
        server_db[i].id = i;
        server_db[i].last_updated = 0.0;
        server_db[i].valid = 1;
    }

    // Init all clients
    for (int i = 0; i < NUM_CLIENTS; i++) {
        clients[i].id = i;
        clients[i].cache_size = 0;
        clients[i].num_queries = 0;
        clients[i].num_hits = 0;
        clients[i].num_misses = 0;
        clients[i].num_valid_checks = 0;
        clients[i].num_invalidated = 0;
        clients[i].total_delay = 0.0;
        clients[i].valid_check_sent = 0;
    }

    sim_time = 0.0;
    warmup_completed = 0;
}

// Event: Client generates query
void event_query(int cid) {
    Client* c = &clients[cid];
    c->num_queries++;

    int item_id = get_random_item();

    // Check if item is in cache
    int found = 0;
    for (int i = 0; i < c->cache_size; i++) {
        if (c->cache[i].item_id == item_id) {
            found = 1;
            break;
        }
    }

    if (found) {
        // Cache hit — send check message for validity
        c->num_hits++;
        c->num_valid_checks++;
        // Schedule a check message
        schedule_event(sim_time + 0.1, EVENT_CHECK, cid, item_id);
    } else {
        // Cache miss — request data from server
        c->num_misses++;
        schedule_event(sim_time + 0.1, EVENT_REQUEST, cid, item_id);
    }
}

// Event: Send request to server (cache miss)
void event_request(int cid, int item_id) {
    Client* c = &clients[cid];
    double latency = (DATA_ITEM_SIZE * 8.0) / BANDWIDTH;
    double now = sim_time + latency;

    // Request takes time
    schedule_event(now, EVENT_RESPONSE, cid, item_id);

    // Record delay
    c->total_delay += latency;
    c->avg_delay = c->total_delay / c->num_queries;
}

// Event: Receive response from server (full data) on cache miss
void event_response(int cid, int item_id) {
