        int lru_idx = 0;
        double min_time = c->cache[0].last_accessed;
        for (int i = 1; i < CACHE_SIZE; i++) {
            if (c->cache[i].last_accessed < min_time) {
                min_time = c->cache[i].last_accessed;
                lru_idx = i;
            }
        }
        c->cache[lru_idx].item_id = item_id;
        c->cache[lru_idx].last_accessed = sim_time;
    } else {
        c->cache[c->cache_size].item_id = item_id;
        c->cache[c->cache_size].last_accessed = sim_time;
        c->cache_size++;
    }

    // Update usage
    c->num_queries++;
}

// Event: Check validity of cached object (pull-based validation)
void event_check(int cid, int item_id) {
    Client* c = &clients[cid];
    double now = sim_time;

    // Assume checking overhead is negligible (e.g., 0.0s)
    // But check can return confirm or require refresh
    // Check if the server’s version is newer than cache
    if (server_db[item_id].last_updated > c->cache[0].last_accessed) { 
        // Stale! Invalidate and re-fetch
        c->num_invalidated++;
        schedule_event(sim_time + 0.1, EVENT_REQUEST, cid, item_id);
    } else {
        // Valid — serve from cache
        c->num_hits++;
    }
}

// Event: Server receives update
void event_update(int item_id) {
    // Only hot items updated
    if (item_id < HOT_START || item_id > HOT_END) {
        return;
    }

    server_db[item_id].last_updated = sim_time;
    server_db[item_id].valid = 1;
}

// Main simulation loop
void simulate(double T_query_mean, double T_update_mean) {
    initialize_simulation();
    double t_query_lambda = 1.0 / T_query_mean;
    double t_update_lambda = 1.0 / T_update_mean;

    double next_query_time[NUM_CLIENTS];
    double next_update_time = 0;

    for (int i = 0; i < NUM_CLIENTS; i++) {
        next_query_time[i] = random_exp(t_query_lambda);
    }

    next_update_time = random_exp(t_update_lambda);

    while (sim_time < final_time) {
        // Advance to earliest event
        double next_t = final_time;
        int event_cid = -1;
        int event_data = -1;

        // Check client queries
        for (int i = 0; i < NUM_CLIENTS; i++) {
            if (next_query_time[i] < next_t && next_query_time[i] <= sim_time) {
                next_t = next_query_time[i];
                event_cid = i;
                event_data = -1; // No data needed
            }
        }

        // Check updates
        if (next_update_time < next_t && next_update_time <= sim_time) {
            next_t = next_update_time;
            event_cid = -1;
            event_data = (int)(random_uniform(HOT_START, HOT_END + 1)); // Choose hot item
        }

        // Process nearest event
        if (next_t == final_time) break;
        sim_time = next_t;

        if (event_cid != -1) {
            // Client query event
            event_query(event_cid);
            next_query_time[event_cid] = sim_time + random_exp(t_query_lambda);
        } else if (event_data != -1) {
            // Update event
            event_update(event_data);
            next_update_time = sim_time + random_exp(t_update_lambda);
        }

        // Handle any pending events (can be done in scheduler if we had one,
        // but here we use simple logic)
        // Note: This is simplified – in real CSIM20, you'd use event queues
    }

    // Report results after warmup (skip first 100 seconds)
    printf("T_query=%g, T_update=%g\n", T_query_mean, T_update_mean);

    double total_queries = 0, total_hits = 0;
    double total_delay = 0.0;

    for (int i = 0; i < NUM_CLIENTS; i++) {
        total_queries += clients[i].num_queries;
        total_hits += clients[i].num_hits;
        total_delay += clients[i].total_delay;
    }

    if (total_queries > 0) {
        double hit_ratio = total_hits / total_queries;
        double avg_delay = total_delay / total_queries;
        printf("Cache Hit Ratio: %.3f\n", hit_ratio);
        printf("Average Query Delay: %.3f s\n", avg_delay);
    }

    // Write data to file? Or store in arrays for later plotting
    // We'll just output CSV-like format for graphing
    printf("HIT_RATIO,%.3f,T_QUERY,%g,T_UPDATE,%g\n",
           total_hits / total_queries, T_query_mean, T_update_mean);
}
```

