#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Функция для ввода строки массива
void inputRow(int row[], int cols) {
    for (int j = 0; j < cols; j++) {
        scanf("%d", &row[j]);
    }
}

// Функция для проверки, является ли столбец неубывающей последовательностью
// col: номер столбца
// rows: количество строк
// cols: количество столбцов
// arr: исходный двумерный массив
int isNonDecreasingColumn(int arr[][cols], int col, int rows) {
    for (int i = 1; i < rows; i++) {
        if (arr[i][col] < arr[i-1][col]) {
            return 0;
        }
    }
    return 1;
}

// Функция для формирования результирующего массива
// arr: исходный массив
// rows: количество строк исходного массива
// cols: количество столбцов исходного массива
void createResultArray(int arr[][cols], int rows, int cols, int result[][rows], int *resultRows) {
    *resultRows = 0;

    for (int j = 0; j < cols; j++) {
        if (isNonDecreasingColumn(arr, j, rows)) {
            for (int i = 0; i < rows; i++) {
                result[*resultRows][i] = arr[i][j];
            }
            (*resultRows)++;
        }
    }
}

// Функция для вывода результирующего массива
