        printf("Количество столбцов должно быть положительным.\n");
        return 1;
    }

    // Ввод начальной строки для определения количества строк
    int firstRow[cols];
    printf("Введите первую строку: ");
    inputRow(firstRow, cols);

    // Находим максимальный по модулю элемент в первой строке
    int maxAbs = abs(firstRow[0]);
    for (int j = 1; j < cols; j++) {
        if (abs(firstRow[j]) > maxAbs) {
            maxAbs = abs(firstRow[j]);
        }
    }

    // Количество строк — maxAbs, но не менее 1
    int rows = (maxAbs < 1) ? 1 : maxAbs;

    // Выделяем память для двумерного массива (исходного)
    int **arr = (int **)malloc(rows * sizeof(int *));
    for (int i = 0; i < rows; i++) {
        arr[i] = (int *)malloc(cols * sizeof(int));
    }

    // Ввод первой строки
    for (int j = 0; j < cols; j++) {
        arr[0][j] = firstRow[j];
    }

    // Ввод остальных строк
    for (int i = 1; i < rows; i++) {
        printf("Введите строку %d: ", i + 1);
        inputRow(arr[i], cols);
    }

    // Массив для результатов: каждая строка — подходящий столбец
    // В сущности, результирующий массив — это каждый подходящий столбец по строкам
    int result[cols][rows];  // максимум, сколько столбцов — столько результатов
    int resultRows = 0;

    createResultArray(arr, rows, cols, result, &resultRows);

    // Вывод результирующего массива
    if (resultRows == 0) {
        printf("Нет столбцов, образующих неубывающую последовательность.\n");
    } else {
        printf("Результирующий массив (каждая строка — столбец, удовлетворяющий условию):\n");
        printResultArray(result, resultRows, rows);
    }

    // Освобождение памяти
    for (int i = 0; i < rows; i++) {
        free(arr[i]);
    }
    free(arr);

    return 0;
