    for (int i = 0; i < k; i++) {
        int c, p;
        cin >> c >> p;
        fiber.push_back({c, p});
        adj[1].emplace_back(c, p);
        adj[c].emplace_back(1, p);
    }

    // Dijkstra on full graph
    vector<ll> dist(n+1, INF);
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    dist[1] = 0;
    pq.push({0, 1});

    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d != dist[u]) continue;
        for (auto &[v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }

    int ans = 0;

    // For each fiber edge
    for (int i = 0; i < k; i++) {
        int c = fiber[i].first;
        ll p = fiber[i].second;

        if (p > dist[c]) {
            ans++; // never used, safe to remove
            continue;
        }

        // p == dist[c] → check if we can still reach c with dist[c] without this fiber

        // Build graph without this fiber edge (1 <-> c with weight p)
        vector<vector<pair<int, ll>>> adj2(n+1);

        // Add all normal edges
        for (auto [a, b, l] : normal) {
            adj2[a].emplace_back(b, l);
            adj2[b].emplace_back(a, l);
        }

        // Add all fiber edges EXCEPT the i-th one
        for (int j = 0; j < k; j++) {
            if (j == i) continue;
            int cc = fiber[j].first;
            ll pp = fiber[j].second;
            adj2[1].emplace_back(cc, pp);
            adj2[cc].emplace_back(1, pp);
        }

        // Run Dijkstra on adj2
        vector<ll> dist2(n+1, INF);
        priority_queue<pli, vector<pli>, greater<pli>> pq2;
