    if (sem == SEM_FAILED) {
        perror("sem_open failed");
        exit(1);
    }

    ack_sem = sem_open(ACK_SEMA, O_CREAT | O_EXCL, 0644, 0);
    if (ack_sem == SEM_FAILED) {
        perror("ack_sem_open failed");
        exit(1);
    }

    // Create shared memory
    shm_fd = shm_open(SHM_NAME, O_CREAT | O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("shm_open failed");
        exit(1);
    }

    if (ftruncate(shm_fd, MAX_SIZE) == -1) {
        perror("ftruncate failed");
        exit(1);
    }

    shm_addr = mmap(NULL, MAX_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_addr == MAP_FAILED) {
        perror("mmap failed");
        exit(1);
    }

    printf("[Server] Waiting for commands...\n");

    while (1) {
        // Wait for client to write command
        if (sem_wait(sem) == -1) {
            perror("sem_wait failed");
            continue;
        }

        // Read command from shared memory
        char command[MAX_SIZE];
        memset(command, 0, MAX_SIZE);
        strcpy(command, (char *)shm_addr);

        printf("[Server] Received command: %s\n", command);

        // Clear shared memory
        memset(shm_addr, 0, MAX_SIZE);

        // Fork a thread to handle request
        pthread_t tid;
        if (pthread_create(&tid, NULL, handle_request, (void *)command) != 0) {
            perror("pthread_create failed");
        }
        pthread_detach(tid); // Don't join – let it clean up itself

        // Release semaphore to allow next client
        sem_post(sem);
    }

    return 0;
}

void *handle_request(void *arg) {
    char *cmd = (char *)arg;
    char action[16], filename[MAX_FILENAME_LEN];
    char *data_part = NULL;

