```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/shm.h>
#include <sys/stat.h>
#include <semaphore.h>
#include <pthread.h>

#define SHM_NAME "/fileshare"
#define SEM_NAME "/fileshare_sema"
#define ACK_SEMA "/fileshare_ack"

#define MAX_SIZE 1024

// Global
int shm_fd;
void *shm_addr;
sem_t *sem, *ack_sem;

int validate_command(const char *cmd) {
    char action[16], filename[64];
    sscanf(cmd, "%s %s", action, filename);

    if (strcmp(action, "read") == 0 && strlen(filename) > 0) return 1;
    if (strcmp(action, "write") == 0 && strlen(filename) > 0) return 1;

    return 0;
}

int main() {
    // Open existing semaphores
    sem = sem_open(SEM_NAME, 0);
    if (sem == SEM_FAILED) {
        perror("sem_open failed (client)");
        exit(1);
    }

    ack_sem = sem_open(ACK_SEMA, 0);
    if (ack_sem == SEM_FAILED) {
        perror("ack_sem_open failed (client)");
        exit(1);
    }

    // Open shared memory
    shm_fd = shm_open(SHM_NAME, O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("shm_open failed");
        exit(1);
    }

    shm_addr = mmap(NULL, MAX_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_addr == MAP_FAILED) {
        perror("mmap failed");
        exit(1);
    }

    char input[MAX_SIZE];
    printf("Enter command (read filename / write filename data): ");

    while (fgets(input, MAX_SIZE, stdin) != NULL) {
        // Remove newline
        input[strcspn(input, "\n")] = 0;

        // Validate format
        if (!validate_command(input)) {
            printf("Invalid command! Use: read filename OR write filename data\n");
            continue;
        }

        // Wait until no active process (exclusive access)
        if (sem_wait(sem) == -1) {
            perror("sem_wait failed");
            continue;
        }

        // Write command to shared memory
        strcpy((char *)shm_addr, input);
        printf("[Client] Command sent: %s\n", input);

        // If read, wait for response
        if (strncmp(input, "read", 4) == 0) {
            printf("[Client] Awaiting response...\n");

            // Wait for server signal via acknowledgment semaphore
            if (sem_wait(ack_sem) == -1) {
                perror("sem_wait failed (ack)");
                sem_post(sem);
                continue;
            }

            // Now read the key (response shared memory name)
            char key_buffer[MAX_SIZE];
            strcpy(key_buffer, (char *)shm_addr);

            if (strncmp(key_buffer, "key:", 4) != 0) {
                fprintf(stderr, "Unexpected response format\n");
                break;
            }

            char response_shm_name[32];
            strcpy(response_shm_name, key_buffer + 4);

            // Open response shared memory
            int resp_fd = shm_open(response_shm_name, O_RDONLY, 0666);
            if (resp_fd == -1) {
                perror("Failed to open response shm");
                sem_post(sem);
                continue;
            }

            void *resp_addr = mmap(NULL, MAX_SIZE, PROT_READ, MAP_SHARED, resp_fd, 0);
            if (resp_addr == MAP_FAILED) {
                perror("mmap response failed");
                close(resp_fd);
                sem_post(sem);
                continue;
            }

            // Display file content
            printf("[Client] File content:\n%s\n", (char *)resp_addr);

            // Cleanup
            munmap(resp_addr, MAX_SIZE);
            close(resp_fd);
            shm_unlink(response_shm_name);

            // Let server know we’re done
            sem_post(sem);
            break; // one read per run

        } else if (strncmp(input, "write", 5) == 0) {
            // Just send and exit
            sem_post(sem);
            printf("[Client] Write command sent. Exiting.\n");
            break;
        }

        // Reset loop
        printf("Enter another command (or press Ctrl+C to exit): ");
    }

    // Cleanup
    munmap(shm_addr, MAX_SIZE);
    close(shm_fd);

    // Optional: avoid removing semaphores
    // sem_close(sem); sem_unlink(SEM_NAME);   // Not safe if multiple clients
    // Instead, use separate cleanup function

    return 0;
}
```

