### ✅ Modified Code with Index Tracking

```c
#include <stdio.h>

int function(int arr[], int n, int indices[]) 
{
    int freq[n];
    int prev[n];  // To store the previous index in the chain
    int max_length = 1;
    int max_index = 0;  // Index where the longest sequence ends

    // Initialize arrays
    for (int i = 0; i < n; i++) {
        freq[i] = 1;
        prev[i] = -1;  // No predecessor initially
    }

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (arr[j] + 1 == arr[i]) {
                if (freq[j] + 1 > freq[i]) {
                    freq[i] = freq[j] + 1;
                    prev[i] = j;
                }
            }
        }

        // Update max_length and max_index if needed
        if (freq[i] > max_length) {
            max_length = freq[i];
            max_index = i;
        }
    }

    // Now reconstruct the indices using the prev array
    int k = 0;
    int temp_indices[1000];  // Assuming max possible length <= 1000

    // Traverse backwards from max_index
    int current = max_index;
    while (current != -1) {
        temp_indices[k++] = current;
        current = prev[current];
    }

    // Reverse the indices since we built them backwards
    for (int i = 0; i < k; i++) {
        indices[i] = temp_indices[k - 1 - i];
    }

    return k; // Return the length of the subsequence
}

int main() {

    int n;
    scanf("%d", &n);
    int arr[n];

    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

