#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <math.h>
#include <string.h>

#define MAX_EXPR_LEN 256
#define MAX_STACK_SIZE 128

// Структура стека для символов (операторы/скобки)
typedef struct {
    char data[MAX_STACK_SIZE];
    int top;
} CharStack;

// Структура стека для чисел (флоат)
typedef struct {
    double data[MAX_STACK_SIZE];
    int top;
} DoubleStack;

// Инициализация стеков
void initCharStack(CharStack *s) {
    s->top = -1;
}

void initDoubleStack(DoubleStack *s) {
    s->top = -1;
}

// Проверка, пуст ли стек
int isEmptyChar(const CharStack *s) {
    return s->top == -1;
}

int isEmptyDouble(const DoubleStack *s) {
    return s->top == -1;
}

// Вставка элемента в стек
void pushChar(CharStack *s, char c) {
    if (s->top >= MAX_STACK_SIZE - 1) {
        fprintf(stderr, "Ошибка: переполнение стека (символы)\n");
        exit(1);
    }
    s->data[++s->top] = c;
}

void pushDouble(DoubleStack *s, double d) {
    if (s->top >= MAX_STACK_SIZE - 1) {
        fprintf(stderr, "Ошибка: переполнение стека (числа)\n");
        exit(1);
    }
    s->data[++s->top] = d;
}

// Извлечение элемента из стека
char popChar(CharStack *s) {
    if (isEmptyChar(s)) {
        fprintf(stderr, "Ошибка: пустой стек (символы)\n");
        exit(1);
    }
    return s->data[s->top--];
}

double popDouble(DoubleStack *s) {
    if (isEmptyDouble(s)) {
        fprintf(stderr, "Ошибка: пустой стек (числа)\n");
        exit(1);
    }
    return s->data[s->top--];
}

// Видимый элемент вершины стека
char peekChar(const CharStack *s) {
    if (isEmptyChar(s)) {
        return '\0';
    }
    return s->data[s->top];
}

double peekDouble(const DoubleStack *s) {
    if (isEmptyDouble(s)) {
        return 0.0;
    }
    return s->data[s->top];
}

// Приоритет операторов
int getPrecedence(char op) {
    switch (op) {
        case '+':
        case '-': return 1;
        case '*':
        case '/':
        case '%': return 2;
        default: return 0;
    }
}

// Является ли символ оператором?
int isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '%';
}

