double parseNumber(const char *expr, int *idx) {
    double num = 0.0;
    int sign = 1;
    int decimal = 0;
    int digits_after_decimal = 0;

    // Обработка знака
    if (expr[*idx] == '-') {
        sign = -1;
        (*idx)++;
    } else if (expr[*idx] == '+') {
        (*idx)++;
    }

    while (isDigitOrDot(expr[*idx])) {
        if (expr[*idx] == '.') {
            if (decimal) {
                fprintf(stderr, "Ошибка: несколько точек в числе!\n");
                exit(1);
            }
            decimal = 1;
            (*idx)++;
            continue;
        }
        if (decimal) {
            digits_after_decimal++;
        }
        num = num * 10 + (expr[*idx] - '0');
        (*idx)++;
    }

    // Если была десятичная точка — делим на соответствующую степень 10
    if (decimal) {
        double div = pow(10, digits_after_decimal);
        num /= div;
    }

    return sign * num;
}

// Преобразование инфиксной записи в постфиксную (RPN)
void infixToPostfix(const char *expr, char *postfix) {
    CharStack operatorStack;
    initCharStack(&operatorStack);
    int postfixIdx = 0;
    int i = 0;
    int len = strlen(expr);

    while (i < len) {
        char c = expr[i];

        // Пропускаем пробелы
        if (isspace(c)) {
            i++;
            continue;
        }

        // Если это цифра или минус (часть числа)
        if (isdigit(c) || c == '.') {
            double num = parseNumber(expr, &i);
            // Добавляем число в результат
            sprintf(postfix + postfixIdx, "%.15g ", num);
            postfixIdx += strlen(postfix + postfixIdx);
            continue;
        }

        // Обработка отрицательных чисел (например, "-5")
        if (c == '-' && (i == 0 || expr[i-1] == '(' || isOperator(expr[i-1]))) {
            double num = parseNumber(expr, &i);
            sprintf(postfix + postfixIdx, "%.15g ", -num);
            postfixIdx += strlen(postfix + postfixIdx);
            continue;
        }

        // Открытие скобки
        if (c == '(') {
            pushChar(&operatorStack, c);
            i++;
            continue;
        }

        // Закрытие скобки — выталкиваем все до открывающей
        if (c == ')') {
            while (!isEmptyChar(&operatorStack) && peekChar(&operatorStack) != '(') {
                postfix[postfixIdx++] = popChar(&operatorStack);
                postfix[postfixIdx++] = ' ';
            }
            if (isEmptyChar(&operatorStack)) {
                fprintf(stderr, "Ошибка: несбалансированные скобки!\n");
                exit(1);
            }
            popChar(&operatorStack); // убираем '('
            i++;
            continue;
        }

        // Оператор
        if (isOperator(c)) {
            // Выталкиваем операторы с более высоким или равным приоритетом
            while (!isEmptyChar(&operatorStack) &&
                   peekChar(&operatorStack) != '(' &&
                   getPrecedence(peekChar(&operatorStack)) >= getPrecedence(c)) {
                postfix[postfixIdx++] = popChar(&operatorStack);
                postfix[postfixIdx++] = ' ';
            }
            pushChar(&operatorStack, c);
            i++;
            continue;
        }

        // Неожиданный символ
        fprintf(stderr, "Ошибка: недопустимый символ '%c' в выражении!\n", c);
        exit(1);
    }

    // Выталкиваем остаток операторов из стека
    while (!isEmptyChar(&operatorStack)) {
        char op = popChar(&operatorStack);
        if (op == '(' || op == ')') {
            fprintf(stderr, "Ошибка: несбалансированные скобки!\0");
            exit(1);
        }
        postfix[postfixIdx++] = op;
        postfix[postfixIdx++] = ' ';
    }

    postfix[postfixIdx] = '\0'; // завершить строку
}

// Вычисление постфиксного выражения
double evaluatePostfix(const char *postfix) {
    DoubleStack resultStack;
    initDoubleStack(&resultStack);
    int idx = 0;
    int len = strlen(postfix);

    while (idx < len) {
        char c = postfix[idx];

        if (isspace(c)) {
            idx++;
            continue;
        }

        if (isdigit(c) || c == '-') { // может быть число (не только положительное, но и отрицательное)
            double num = 0.0;
            int sign = 1;
            int start = idx;

            // Обработка знака
            if (c == '-') {
                sign = -1;
                idx++;
            } else if (c == '+') {
                idx++;
            }

            // Чтение цифры
            while (idx < len && (isdigit(postfix[idx]) || postfix[idx] == '.')) {
                idx++;
            }

            // Парсинг числа как подстроки
            char temp[64];
            strncpy(temp, postfix + start, idx - start);
            temp[idx - start] = '\0';
            num = atof(temp);
            num *= sign;

            pushDouble(&resultStack, num);
            continue;
        }

        // Оператор
        if (isOperator(c)) {
            // Ожидаем два аргумента
            if (isEmptyDouble(&resultStack) || isEmptyDouble(&resultStack) && resultStack.top == 0) {
                fprintf(stderr, "Ошибка: слишком мало операндов!\n");
                exit(1);
            }

            double b = popDouble(&resultStack); // второй операнд (на вершине)
            double a = popDouble(&resultStack); // первый

            double res = 0.0;
            switch (c) {
                case '+': res = a + b; break;
                case '-': res = a - b; break;
                case '*': res = a * b; break;
                case '/': 
                    if (b == 0.0) {
                        fprintf(stderr, "Ошибка: деление на ноль!\n");
                        exit(1);
                    }
                    res = a / b; break;
                case '%': 
                    if (b == 0.0) {
                        fprintf(stderr, "Ошибка: деление по модулю на ноль!\0");
                        exit(1);
                    }
                    res = fmod(a, b); break;
                default:
                    fprintf(stderr, "Ошибка: неизвестная операция '%c'\n", c);
                    exit(1);
            }

            pushDouble(&resultStack, res);
            idx++;
            continue;
        }

        idx++;
    }

    if (resultStack.top != 0) {
        fprintf(stderr, "Ошибка: некорректное выражение!\0");
        exit(1);
    }

    return popDouble(&resultStack);
}

// Главная функция
