// FCFS 算法：先来先服务
void fcfs(int requests[], int n, int initial, int direction) {
    printf("\n--- FCFS (先来先服务) ---\n");
    double total_seek = 0.0;
    int current = initial;

    printf("调度顺序: ");
    for (int i = 0; i < n; i++) {
        printf("%d -> ", requests[i]);
        total_seek += fabs(requests[i] - current);
        current = requests[i];
    }
    printf("结束");

    double avg_seek = total_seek / n;
    printf("\n总寻道长度: %.2f\n", total_seek);
    printf("平均寻道长度: %.2f\n", avg_seek);
}

// SSTF 算法：最短寻道时间优先
void sstf(int requests[], int n, int initial, int direction) {
    printf("\n--- SSTF (最短寻道时间优先) ---\n");

    // 复制请求数组用于操作
    int req_copy[MAX_REQUESTS];
    int used[MAX_REQUESTS] = {0}; // 标记已处理的请求
    for (int i = 0; i < n; i++) {
        req_copy[i] = requests[i];
    }

    double total_seek = 0.0;
    int current = initial;
    int count = 0;

    printf("调度顺序: ");

    while (count < n) {
        int min_seek = __INT_MAX__;
        int next_idx = -1;

        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                int seek = abs(req_copy[i] - current);
                if (seek < min_seek) {
