    int right_count = 0, left_count = 0;

    for (int i = 0; i < n; i++) {
        if (requests[i] >= initial) {
            right_req[right_count++] = requests[i];
        } else {
            left_req[left_count++] = requests[i];
        }
    }

    // 排序：右边从小到大，左边从大到小
    for (int i = 0; i < right_count - 1; i++) {
        for (int j = 0; j < right_count - i - 1; j++) {
            if (right_req[j] > right_req[j+1]) {
                int temp = right_req[j];
                right_req[j] = right_req[j+1];
                right_req[j+1] = temp;
            }
        }
    }

    for (int i = 0; i < left_count - 1; i++) {
        for (int j = 0; j < left_count - i - 1; j++) {
            if (left_req[j] < left_req[j+1]) {
                int temp = left_req[j];
                left_req[j] = left_req[j+1];
                left_req[j+1] = temp;
            }
        }
    }

    // 构建调度序列
    int final_seq[MAX_REQUESTS];
    int idx = 0;

    // 按照方向优先处理
    if (direction == 1) {
        // 向右扫描
        for (int i = 0; i < right_count; i++) {
            final_seq[idx++] = right_req[i];
        }

        // 到达最大磁道后反向，扫描所有左边的请求
        for (int i = 0; i < left_count; i++) {
            final_seq[idx++] = left_req[i];
        }
    } else {
        // 向左扫描
        for (int i = 0; i < left_count; i++) {
            final_seq[idx++] = left_req[i];
        }

        // 到达最小磁道后反向，扫描所有右边的请求
        for (int i = 0; i < right_count; i++) {
            final_seq[idx++] = right_req[i];
        }
    }

    // 计算总寻道长度
    double total_seek = 0.0;
    int current = initial;

    printf("调度顺序: ");
    for (int i = 0; i < n; i++) {
        printf("%d -> ", final_seq[i]);
        total_seek += abs(final_seq[i] - current);
        current = final_seq[i];
    }
    printf("结束");

    double avg_seek = total_seek / n;
    printf("\n总寻道长度: %.2f\n", total_seek);
    printf("平均寻道长度: %.2f\n", avg_seek);
}
```

