在C语言中，将内存中的图像数据保存为 `.bmp` 格式文件，需要了解 **BMP 文件格式** 的基本结构。以下是一个完整的、可直接编译运行的示例程序，展示如何将内存中的像素数据（例如：一个 24 位真彩色图像）输出为 `.bmp` 格式文件。

---

### ✅ 什么是 BMP 格式（简要说明）？

一个标准的 `.bmp`（DIB，设备无关位图）文件由几个部分组成：

1. **文件头（14 字节）**
   - `bfType`：必须是 "BM"（0x4D42）
   - `bfSize`：文件总大小（字节）
   - `bfOffBits`：从文件头到像素数据的偏移量

2. **信息头（40 字节）**
   - `biSize`：INFO 头大小（40）
   - `biWidth`, `biHeight`：图像宽度和高度（像素）
   - `biPlanes`：平面数（固定为 1）
   - `biBitCount`：每像素位数（常见 24 表示真彩色）
   - `biCompression`：压缩方式（0 表示不压缩）
   - `biSizeImage`：像素数据大小（可选，一般为 0 或根据计算得出）
   - `biXPelsPerMeter`, `biYPelsPerMeter`：分辨率，可设为 0
   - `biClrUsed`：调色板颜色数，通常为 0
   - `biClrImportant`：重要颜色数

3. **像素数据（按行排列，每行补足为 4 字节倍数）**

---

### ✅ 示例：将内存中的像素数据保存为 .bmp

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// 定义像素结构（24位真彩色，无 alpha）
typedef struct {
    unsigned char b; // 蓝
    unsigned char g; // 绿
    unsigned char r; // 红
} Pixel;

// 将像素数据写入 BMP
int save_image_to_bmp(const char* filename, int width, int height, const Pixel* pixels) {
    if (!filename || !pixels || width <= 0 || height <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return -1;
    }

    // 计算每行像素数据的字节数（必须是 4 的倍数）
    int row_size = width * 3;                    // 每个像素 3 字节（RGB）
    int padding = (4 - row_size % 4) % 4;        // 补齐到 4 字节倍数
    int padded_row_size = row_size + padding;     // 实际每行大小
    int total_data_size = padded_row_size * height;

    // 总文件大小 = 14(文件头) + 40(信息头) + 数据大小
    int file_size = 14 + 40 + total_data_size;

    // 打开文件
    FILE* fp = fopen(filename, "wb");
    if (!fp) {
        perror("Failed to open file for writing");
        return -1;
    }

    // ==== 1. 写入 BMP 头（14 bytes）====
    unsigned char bf_type[2] = {'B', 'M'};  // 0x4D42
    fwrite(bf_type, 1, 2, fp);

    // bfSize: 整个文件大小
    unsigned int bf_size = file_size;
    fwrite(&bf_size, sizeof(unsigned int), 1, fp);

    // bfOffBits: 从文件头到像素数据的偏移，即 14 + 40 = 54
    unsigned int bf_off_bits = 54;
    fwrite(&bf_off_bits, sizeof(unsigned int), 1, fp);

    // ==== 2. 写入信息头（40 bytes）====
    unsigned int bi_size = 40;           // 信息头大小
    fwrite(&bi_size, sizeof(unsigned int), 1, fp);

    fwrite(&width, sizeof(int), 1, fp);   // biWidth
    fwrite(&height, sizeof(int), 1, fp);  // biHeight

    unsigned short bi_planes = 1;
    fwrite(&bi_planes, sizeof(unsigned short), 1, fp); // biPlanes

    unsigned short bi_bit_count = 24;
    fwrite(&bi_bit_count, sizeof(unsigned short), 1, fp); // biBitCount

    unsigned int bi_compression = 0;      // 无压缩
    fwrite(&bi_compression, sizeof(unsigned int), 1, fp);

    unsigned int bi_size_image = total_data_size; // 像素数据大小
    fwrite(&bi_size_image, sizeof(unsigned int), 1, fp);

    // 辅助字段，设为 0
    unsigned int bi_xpels_per_meter = 0;
    unsigned int bi_ypels_per_meter = 0;
    fwrite(&bi_xpels_per_meter, sizeof(unsigned int), 1, fp);
    fwrite(&bi_ypels_per_meter, sizeof(unsigned int), 1, fp);

    unsigned int bi_clr_used = 0;
    fwrite(&bi_clr_used, sizeof(unsigned int), 1, fp);

    unsigned int bi_clr_important = 0;
    fwrite(&bi_clr_important, sizeof(unsigned int), 1, fp);

    // ==== 3. 写入像素数据 ====
    // 遍历每一行（注意：BMP 是倒序存储，从下往上）
    for (int y = height - 1; y >= 0; y--) {
        const Pixel* row = &pixels[y * width];  // 当前行
        // 写入像素数据
        fwrite(row, 3, width, fp);

        // 补充填充字节（如果需要）
        if (padding > 0) {
            unsigned char pad[3] = {0}; // 用零填充
            fwrite(pad, 1, padding, fp);
        }
    }

    fclose(fp);
    printf("Image saved as '%s' successfully.\n", filename);
    return 0;
}

// 演示：创建一个简单的测试图像（红色正方形）
void create_test_image(Pixel* pixels, int width, int height) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            // 中心区域绘制红色
            if (x >= width/4 && x < 3*width/4 &&
                y >= height/4 && y < 3*height/4) {
                pixels[y * width + x].r = 255;
                pixels[y * width + x].g = 0;
                pixels[y * width + x].b = 0;
            } else {
                pixels[y * width + x].r = 0;
                pixels[y * width + x].g = 0;
                pixels[y * width + x].b = 0;
            }
        }
    }
}

int main() {
    int width = 512;
    int height = 512;

    // 分配内存存放像素数据
    Pixel* image_pixels = (Pixel*)malloc(width * height * sizeof(Pixel));
    if (!image_pixels) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    // 创建测试图像
    create_test_image(image_pixels, width, height);

    // 输出为 BMP
    save_image_to_bmp("test_output.bmp", width, height, image_pixels);

    free(image_pixels);
    return 0;
}
```

