#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    double numbers[100];  // 存储输入的数据
    double sum = 0.0;

    // 读入 n 个数，并计算总和
    for (int i = 0; i < n; i++) {
        scanf("%lf", &numbers[i]);
        sum += numbers[i];
    }

    // 计算平均值
    double mean = sum / n;

    // 计算离均差平方和：Σ(xi - mean)²
    double sum_of_squares = 0.0;
    for (int i = 0; i < n; i++) {
        double diff = numbers[i] - mean;
        sum_of_squares += diff * diff;
    }

    // 计算标准差：√(离均差平方和 / n) 或 / (n-1)？
    // 根据题意"标准差"通常指总体标准差（除以 n），但注意：有些场景用样本标准差（除以 n-1）
    // 题目样例输出 12.46，我们验证一下：
    // 样例数据：89, 96, 78, 63, 81
    // 平均值 = 81.4
    // 离均差平方和 = 621.2
    // 总体标准差：√(621.2 / 5) = √124.24 ≈ 11.15 → 不对
    // 样本标准差：√(621.2 / 4) = √155.3 = ≈ 12.46 → 正确！

    // 所以题目用的是**样本标准差**（除以 n-1）
    double std_dev = 0.0;
    if (n > 1) {
        std_dev = sqrt(sum_of_squares / (n - 1));
    } else {
        std_dev = 0.0;  // n=1 时标准差为 0
    }

    // 输出结果，保留两位小数
    printf("%.2f\n", mean);
    printf("%.2f\n", sum_of_squares);
    printf("%.2f\n", std_dev);

    return 0;
}
```

