    double x1, y1, r1;
    double x2, y2, r2;

    // Ввод данных от пользователя
    printf("Введите координаты центра первой окружности (x1 y1): ");
    scanf("%lf %lf", &x1, &y1);
    printf("Введите радиус первой окружности: ");
    scanf("%lf", &r1);

    printf("Введите координаты центра второй окружности (x2 y2): ");
    scanf("%lf %lf", &x2, &y2);
    printf("Введите радиус второй окружности: ");
    scanf("%lf", &r2);

    // Вычисляем расстояние между центрами окружностей
    double dx = x2 - x1;
    double dy = y2 - y1;
    double d = sqrt(dx * dx + dy * dy);

    // Проверяем количество точек пересечения
    // Случай 1: окружности совпадают (одинаковые центры и радиусы)
    if (d == 0) {
        if (r1 == r2) {
            printf("Окружности совпадают — бесконечно много точек пересечения.\n");
        } else {
            printf("Окружности не пересекаются — нет общих точек.\n");
        }
    }
    // Случай 2: окружности не пересекаются (расстояние больше суммы радиусов)
    else if (d > r1 + r2) {
        printf("Окружности не пересекаются — нет общих точек.\n");
    }
    // Случай 3: окружности касаются внешним образом (расстояние равно сумме радиусов)
    else if (d == r1 + r2) {
        printf("Окружности касаются внешне — 1 точка пересечения.\n");
    }
    // Случай 4: окружности пересекаются в двух точках
    else if (d < r1 + r2 && d > fabs(r1 - r2)) {
        printf("Окружности пересекаются в двух точках.\n");
    }
    // Случай 5: одна окружность лежит внутри другой, не касаясь
    else if (d < fabs(r1 - r2)) {
        printf("Окружности не пересекаются — нет общих точек.\n");
    }
    // Случай 6: окружности касаются внутренним образом
    else if (d == fabs(r1 - r2) && d != 0) {
        printf("Окружности касаются внутренним образом — 1 точка пересечения.\n");
    }

    return 0;
}
```

### Объяснение логики:
- Вычисляется расстояние `d` между центрами окружностей.
- Сравнивается `d` с суммой радиусов (`r1 + r2`) и разностью радиусов (`|r1 - r2|`).
- Возможные случаи:
