        if (expr[i] == '(') {
            depth++;
        } else if (expr[i] == ')') {
            depth--;
        } else if (isOperator(expr[i])) {
            // 只考虑最外层的运算符（depth == 0）
            if (depth == 0) {
                int prec = getPrecedence(expr[i]);
                // 找优先级最低的操作符（+ 和 - 优先级为1，比 * / 低）
                // 因为最后执行的一定是 + 或 -（如果存在的话）
