    // 但通常表达式是：((a * b) + c)，所以我们应该检查有没有非括号部分
    // 如果找不到 + 或 -，则看是否有 * 或 /
    if (last_min_op == '\0') {
        depth = 0;
        for (int i = 0; i < n; i++) {
            if (expr[i] == '(') {
                depth++;
            } else if (expr[i] == ')') {
                depth--;
            } else if (isOperator(expr[i])) {
                if (depth == 0) {
                    // 一定有 * 或 /
                    return expr[i];  // 由于无 +-, 它们必然最外层，且是最后执行的
                }
            }
        }
    }

    return last_min_op;
}

