```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CANDIDATS 100
#define MAX_NOM_LENGTH 50

int main() {
    FILE *f_in = fopen("votes.txt", "r");
    FILE *f_out = fopen("resultats.txt", "w");

    if (!f_in || !f_out) {
        perror("Erreur d'ouverture des fichiers");
        return EXIT_FAILURE;
    }

    char noms[MAX_CANDIDATS][MAX_NOM_LENGTH];
    int nb_candidats = 0;
    int scores[MAX_CANDIDATS] = {0}; // Initialisé à 0
    int total_votes = 0;
    int votes_valides = 0;
    int votes_invalides = 0;

    // Lire les noms des candidats (jusqu'à la fin ou jusqu'à 100 candidats)
    for (int i = 0; i < MAX_CANDIDATS; i++) {
        if (fgets(noms[i], MAX_NOM_LENGTH, f_in) == NULL) break;
