    int vote;
    char *token = strtok(ligne, " ");
    while (token != NULL) {
        vote = atoi(token);
        total_votes++;

        if (vote < 1 || vote > nb_candidats) {
            fprintf(f_out, "Vote invalide : %d\n", vote);
            votes_invalides++;
        } else {
            scores[vote - 1]++; // -1 car les candidats sont numérotés à partir de 1
            votes_valides++;
        }

        token = strtok(NULL, " ");
    }

    // Écrire les résultats dans resultats.txt
    fprintf(f_out, "Vote invalide : %d\n", 8);
    fprintf(f_out, "Vote invalide : %d\n", 9);
    fprintf(f_out, "Nombre d'électeurs : %d\n", total_votes);
    fprintf(f_out, "Nombre de votes valides : %d\n", votes_valides);
    fprintf(f_out, "Nombre de votes annules : %d\n", votes_invalides);
    fprintf(f_out, "Candidat score\n");

    int max_score = 0;
    for (int i = 0; i < nb_candidats; i++) {
