## ✅ 完整代码（适合在类 Unix 系统如 Linux、macOS 上运行）

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// 判读是否为闰年
int isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// 蔡勒公式计算某天是星期几（0=周日, 1=周一, ..., 6=周六）
int getDayOfWeek(int year, int month, int day) {
    if (month < 3) {
        month += 12;
        year -= 1;
    }
    int k = year % 100;
    int j = year / 100;
    int h = (day + 13 * (month + 1) / 5 + k + k / 4 + j / 4 - 2 * j) % 7;
    return (h + 5) % 7; // 转换为 0=周日, 1=周一 ... 6=周六
}

// 显示日历
void showCalendar(int year, int month) {
    const char* months[] = {"January", "February", "March", "April", "May", "June",
                           "July", "August", "September", "October", "November", "December"};
    const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    if (month == 2 && isLeapYear(year)) {
        days[1] = 29;
    }

    printf("\n=================== %s %d ===================\n", months[month - 1], year);
    printf("Sun Mon Tue Wed Thu Fri Sat\n");

    int startDay = getDayOfWeek(year, month, 1);  // 1号是星期几

    int day = 1;
    for (int i = 0; i < 6; i++) {  // 最多 6 行
        for (int j = 0; j < 7; j++) {
            if (i == 0 && j < startDay) {
                printf("    ");
            } else if (day <= days[month - 1]) {
                printf("%3d ", day++);
            } else {
                printf("    ");
            }
        }
        printf("\n");
    }
    printf("=============================================\n\n");
}

// 获取当前系统时间（用于重置）
void setSystemTime(int *year, int *month, int *day) {
    time_t t = time(NULL);
    struct tm *tm_info = localtime(&t);

    *year = tm_info->tm_year + 1900;
    *month = tm_info->tm_mon + 1;
    *day = tm_info->tm_mday;

    printf("✅ 已重置为当前系统日期: %d-%d-%d\n", *year, *month, *day);
}

// 日期调整主函数
void adjustDate() {
    int year = 2025, month = 1, day = 1;
    char choice;

    while (1) {
        showCalendar(year, month);

        printf("📅 当前日期: %d 年 %d 月 %d 号\n", year, month, day);
        printf("🔧 您可进行以下操作：\n");
        printf("  a) 增加年份 (+1)\n  b) 减少年份 (-1)\n");
        printf("  c) 增加月份 (+1)\n  d) 减少月份 (-1)\n");
        printf("  e) 增加日期 (+1)\n  f) 减少日期 (-1)\n");
        printf("  g) 重置为系统当前时间（仅示例）\n");
        printf("  q) 退出调整模式，返回主菜单。\n");
        printf("👉 请选择 (a~g/q): ");

        scanf(" %c", &choice);

        switch (choice) {
            case 'a':
                year++;
                break;
            case 'b':
                if (year > 1) year--;
                break;
            case 'c':
                month++;
                if (month > 12) {
                    month = 1;
                    year++;
                }
                break;
            case 'd':
                month--;
                if (month < 1) {
                    month = 12;
                    year--;
                }
                break;
            case 'e':
                // 利用数组判定合法天数
                {
                    const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
                    int daysInMonth = days[month - 1];
                    if (month == 2 && isLeapYear(year)) daysInMonth = 29;

                    if (day < daysInMonth) {
                        day++;
                    } else {
                        day = 1;
                        month++;
                        if (month > 12) {
                            month = 1;
                            year++;
                        }
                    }
                }
                break;
            case 'f':
                if (day > 1) {
                    day--;
                } else {
                    month--;
                    if (month < 1) {
                        month = 12;
                        year--;
                    }
                    // 计算上个月的天数
                    const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
                    int daysInPrevMonth = days[month - 1];
                    if (month == 2 && isLeapYear(year)) daysInPrevMonth = 29;
                    day = daysInPrevMonth;
                }
                break;
            case 'g':
                setSystemTime(&year, &month, &day);
                break;
            case 'q':
                printf("🔚 退出日期调整模式。\n");
                return;
            default:
                printf("❌ 无效选择，请重新输入。\n");
                continue;
        }

        // 边界处理（防止数据异常）
        if (year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31) {
            printf("⚠️ 日期非法，已自动校正！\n");
            // 修复逻辑略显复杂，这里只做简单处理
            if (month > 12) { month = 12; year++; }
            if (month < 1) { month = 1; year--; }
            if (day < 1) { day = 1; }
        }
    }
}

