```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define PORT 4999
#define BUFFER_SIZE 1024

int main() {
    int server_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    // Utworzenie socketu UDP
    if ((server_socket = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Błąd tworzenia socketu");
        exit(EXIT_FAILURE);
    }

    // Konfiguracja adresu serwera
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;  // dowolny interfejs
    server_addr.sin_port = htons(PORT);

    // Przypisanie adresu do socketu
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Błąd przypisania adresu");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    printf("Serwer UDP działa na porcie %d...\n", PORT);

    while (1) {
        // Odbieranie datagramu od klienta
        int recv_length = recvfrom(server_socket, buffer, BUFFER_SIZE - 1, 0,
                                   (struct sockaddr*)&client_addr, &client_len);
        if (recv_length < 0) {
            perror("Błąd odbioru danych");
            continue;
        }

        buffer[recv_length] = '\0';  // zakończ ciąg znaków

        printf("Otrzymano od %s:%d: %s\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port), buffer);

        // Przekształcenie tekstu na duże litery
        for (int i = 0; buffer[i]; i++) {
            if (buffer[i] >= 'a' && buffer[i] <= 'z') {
                buffer[i] = buffer[i] - 'a' + 'A';
            }
        }

        // Wysłanie odpowiedzi z dużymi literami
        sendto(server_socket, buffer, strlen(buffer), 0,
               (struct sockaddr*)&client_addr, client_len);

        printf("Wyślij: %s\n", buffer);
    }

    close(server_socket);
    return 0;
}
```

