#define PORT 4999
#define BUFFER_SIZE 1024

int main() {
    int client_socket;
    struct sockaddr_in server_addr;
    char message[BUFFER_SIZE];
    char response[BUFFER_SIZE];

    // Utworzenie socketu UDP
    if ((client_socket = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Błąd tworzenia socketu");
        exit(EXIT_FAILURE);
    }

    // Konfiguracja adresu serwera
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Nieprawidłowy adres IP\n");
        close(client_socket);
        exit(EXIT_FAILURE);
    }

    // Ustalenie danych do wysłania (imię i nazwisko)
    strcpy(message, "Jan Kowalski");

    printf("Wysyłam: %s\n", message);

    // Wysłanie datagramu do serwera
    if (sendto(client_socket, message, strlen(message), 0,
               (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Błąd wysyłania");
        close(client_socket);
        exit(EXIT_FAILURE);
    }

    // Odbieranie odpowiedzi od serwera
    int recv_len = recvfrom(client_socket, response, BUFFER_SIZE - 1, 0,
                           NULL, NULL);
    if (recv_len < 0) {
        perror("Błąd odbioru odpowiedzi");
    } else {
        response[recv_len] = '\0';  // zakończ ciąg
        printf("Otrzymano od serwera: %s\n", response);
    }

    close(client_socket);
    return 0;
}
