struct TreeNode {
    int data;
    TreeNode* left;
    TreeNode* right;

    TreeNode(int val) : data(val), left(nullptr), right(nullptr) {}
};

void AddNode(TreeNode*& root, int value) {
    if (root == nullptr) {
        root = new TreeNode(value);
        return;
    }

    if (value < root->data) {
        AddNode(root->left, value);
    } else {
        AddNode(root->right, value);
    }
}

// Функция для создания полного (или почти полного) бинарного дерева с произвольным количеством узлов
void fullTree(TreeNode*& root, int n) {
    if (n <= 0) return;

    // Инициализируем генератор случайных чисел
    std::srand(static_cast<unsigned int>(std::time(0)));

    // Генерируем уникальные случайные числа
    std::vector<int> numbers;
    for (int i = 0; i < n; ++i) {
        numbers.push_back(std::rand() % (n * 10) + 1); // От 1 до 10 * n
    }

    // Добавляем каждый элемент в дерево
    for (int val : numbers) {
        AddNode(root, val);
    }
}
