## ✅ 1. Serwer (`server.c`)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/un.h>

#define SOCKET_PATH "/tmp/unix_socket"
#define BUFFER_SIZE 256

int main() {
    int server_fd, client_fd;
    struct sockaddr_un addr;
    char buffer[BUFFER_SIZE];

    // Tworzenie gniazda domeny Unix
    if ((server_fd = socket(AF_UNIX, SOCK_STREAM, 0)) == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Ustawienie adresu gniazda
    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);

    // Usunięcie istniejącego pliku FIFO (jeśli istnieje)
    unlink(SOCKET_PATH);

    // Przypisanie adresu do gniazda
    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) == -1) {
        perror("bind");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Nasłuchowanie połączeń (max 1 kliencie)
    if (listen(server_fd, 1) == -1) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Serwer uruchomiony. Oczekiwanie na połączenie...\n");

    // Akceptowanie klientów
    if ((client_fd = accept(server_fd, NULL, NULL)) == -1) {
        perror("accept");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Klient połączony.\n");

    // Odbieranie danych
    ssize_t received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (received == -1) {
        perror("recv");
        close(client_fd);
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    buffer[received] = '\0';
    printf("Otrzymano od klienta: %s\n", buffer);

    // Zamiana na duże litery
    for (int i = 0; buffer[i]; i++) {
        if (buffer[i] >= 'a' && buffer[i] <= 'z') {
            buffer[i] -= 'a' - 'A';
        }
    }

    // Wysyłanie odpowiedzi
    if (send(client_fd, buffer, strlen(buffer), 0) == -1) {
        perror("send");
        close(client_fd);
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Wysłano odpowiedź: %s\n", buffer);

    // Zamykanie połączeń
    close(client_fd);
    close(server_fd);
    unlink(SOCKET_PATH);  // Usunięcie pliku socketa

    printf("Połączenie zamknięte.\n");
    return 0;
}
```

