## ✅ 2. Klient (`client.c`)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/un.h>

#define SOCKET_PATH "/tmp/unix_socket"
#define BUFFER_SIZE 256

int main() {
    int client_fd;
    struct sockaddr_un addr;
    char buffer[BUFFER_SIZE];
    char name[256];

    // Tworzenie gniazda domeny Unix
    if ((client_fd = socket(AF_UNIX, SOCK_STREAM, 0)) == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Ustawienie adresu serwera
    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);

    // Połączenie z serwerem
    if (connect(client_fd, (struct sockaddr*)&addr, sizeof(addr)) == -1) {
        perror("connect");
        close(client_fd);
        exit(EXIT_FAILURE);
    }

    printf("Połączono z serwerem. Podaj imię i nazwisko: ");
    fgets(name, sizeof(name), stdin);

    // Usunięcie znaku nowej linii
    name[strcspn(name, "\n")] = '\0';

    // Wysyłanie danych
    if (send(client_fd, name, strlen(name), 0) == -1) {
        perror("send");
        close(client_fd);
        exit(EXIT_FAILURE);
    }

    printf("Dane wysłane: %s\n", name);

    // Odbieranie odpowiedzi
    ssize_t received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (received == -1) {
        perror("recv");
        close(client_fd);
        exit(EXIT_FAILURE);
    }

    buffer[received] = '\0';
    printf("Otrzymano od serwera: %s\n", buffer);

    // Zamykanie połączenia
    close(client_fd);

    return 0;
}
```

