#include "diary.h"

DiaryEntry entries[MAX_ENTRIES];
int entryCount = 0;
char password[32] = "123456"; // 默认密码

// 初始化系统：加载已保存的日志和密码
void initSystem() {
    printf("正在加载日记系统...\n");
    loadDiariesFromFile();
    printf("加载完成！共 %d 条日记。\n", entryCount);
}

// 从文件读取日记内容
void loadDiariesFromFile() {
    FILE *fp = fopen("diary.txt", "r");
    if (!fp) {
        printf("未找到日记文件，将创建新文件。\n");
        return;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (strlen(line) > 1 && line[0] == '\n') continue;

        // 第一行：日期
        strncpy(entries[count].date, line, 10);
        entries[count].date[10] = '\0';
        if (!strncmp(entries[count].date, "DATE:", 5)) {
            strcpy(entries[count].date, line + 5);
            entries[count].date[10] = '\0';
        } else {
            fgets(line, sizeof(line), fp); // 跳过错误格式
            continue;
        }

        // 关键字
        fgets(line, sizeof(line), fp);
        if (line[strcspn(line, "\n")] == 0) continue;
        strncpy(entries[count].keywords, line, 127);
        entries[count].keywords[127] = '\0';

        // 内容
        entries[count].content[0] = '\0';
        char temp[256];
        while (fgets(temp, sizeof(temp), fp) && strcmp(temp, "\n") != 0 && strncmp(temp, "-----", 5) != 0) {
            strncat(entries[count].content, temp, 1020 - strlen(entries[count].content));
        }
        count++;
    }
    fclose(fp);
    entryCount = count;

    // 排序
    sortEntriesByDate();
}

// 将日记保存到文件
void saveDiariesToFile() {
    FILE *fp = fopen("diary.txt", "w");
    if (!fp) {
        printf("无法创建或写入日记文件！\n");
        return;
    }

    for (int i = 0; i < entryCount; i++) {
        fprintf(fp, "DATE:%s\n", entries[i].date);
        fprintf(fp, "%s\n", entries[i].keywords);
        fprintf(fp, "%s\n", entries[i].content);
        fprintf(fp, "-----\n"); // 分隔符
    }

    fclose(fp);
    printf("日记已保存到 diary.txt\n");
}

// 比较两个日期字符串（格式："YYYY-MM-DD"）
int compareDates(const char *date1, const char *date2) {
    int y1 = atoi(date1), m1 = atoi(date1+5), d1 = atoi(date1+8);
    int y2 = atoi(date2), m2 = atoi(date2+5), d2 = atoi(date2+8);
    if (y1 != y2) return y1 - y2;
    if (m1 != m2) return m1 - m2;
    return d1 - d2;
}

// 按日期升序排序
void sortEntriesByDate() {
    for (int i = 0; i < entryCount - 1; i++) {
        for (int j = i + 1; j < entryCount; j++) {
            if (compareDates(entries[i].date, entries[j].date) > 0) {
                DiaryEntry temp = entries[i];
                entries[i] = entries[j];
                entries[j] = temp;
            }
        }
    }
}

// 添加日记
void addDiary() {
    if (entryCount >= MAX_ENTRIES) {
        printf("日记已达上限！\n");
        return;
    }

    printf("请输入日期 (YYYY-MM-DD): ");
    scanf("%s", entries[entryCount].date);

    // 验证日期合法性（简化版本）
    if (strlen(entries[entryCount].date) != 10 || 
        entries[entryCount].date[4] != '-' || entries[entryCount].date[7] != '-') {
        printf("日期格式错误！请使用 'YYYY-MM-DD'\n");
        return;
    }

    printf("请输入关键字（多个用空格分隔）: ");
    getchar(); // 消除前面的换行
    fgets(entries[entryCount].keywords, 128, stdin);
    entries[entryCount].keywords[strcspn(entries[entryCount].keywords, "\n")] = 0;

    printf("请输入日记内容（输入结束符 'END' 结束）:\n");
    entries[entryCount].content[0] = '\0';
    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        if (strcmp(line, "END\n") == 0) break;
        strncat(entries[entryCount].content, line, 1020 - strlen(entries[entryCount].content));
    }

    entryCount++;
    sortEntriesByDate();
    saveDiariesToFile();
    printf("日记添加成功！\n");
}

// 修改日记
void modifyDiary() {
    char date[11];
    printf("请输入要修改的日记的日期 (YYYY-MM-DD): ");
    scanf("%s", date);

    int found = -1;
    for (int i = 0; i < entryCount; i++) {
        if (strcmp(entries[i].date, date) == 0) {
            found = i;
            break;
        }
