    printf("当前日记信息：\n");
    printf("日期: %s\n关键字: %s\n内容:\n%s\n", 
           entries[found].date, entries[found].keywords, entries[found].content);

    printf("\n请输入新的内容（输入结束符 'END'）:\n");
    entries[found].content[0] = '\0';
    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        if (strcmp(line, "END\n") == 0) break;
        strncat(entries[found].content, line, 1020 - strlen(entries[found].content));
    }

    printf("请输入新的关键字: ");
    getchar();
    fgets(entries[found].keywords, 128, stdin);
    entries[found].keywords[strcspn(entries[found].keywords, "\n")] = 0;

    sortEntriesByDate();
    saveDiariesToFile();
    printf("日记已修改！\n");
}

// 删除日记
void deleteDiary() {
    char date[11];
    printf("请输入要删除的日记的日期 (YYYY-MM-DD): ");
