```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// 函数：对字符串进行排序（冒泡排序，按 ASCII 值）
void sortString(char *str) {
    int len = strlen(str);
    for (int i = 0; i < len - 1; i++) {
        for (int j = 0; j < len - i - 1; j++) {
            if (str[j] > str[j + 1]) {
                // 交换字符
                char temp = str[j];
                str[j] = str[j + 1];
                str[j + 1] = temp;
            }
        }
    }
}

// 函数：删除字符串中的重复字符
void removeDuplicates(char *str) {
    int len = strlen(str);
    if (len == 0) return;

    int writeIndex = 0;  // 写入位置
    for (int readIndex = 0; readIndex < len; readIndex++) {
        // 检查当前字符是否已在结果中
        int isDuplicate = 0;
        for (int i = 0; i < writeIndex; i++) {
            if (str[readIndex] == str[i]) {
                isDuplicate = 1;
                break;
            }
        }
        if (!isDuplicate) {
            str[writeIndex++] = str[readIndex];
        }
    }
    str[writeIndex] = '\0';  // 结束字符串
}

// 函数：合并两个字符串
void mergeStrings(char *s1, char *s2, char *result) {
    strcpy(result, s1);
    strcat(result, s2);
}

int main() {
    char str1[1000], str2[1000];
    char merged[2000];  // 存放合并后的结果

    printf("请输入第一个字符串: ");
    scanf("%s", str1);

    printf("请输入第二个字符串: ");
    scanf("%s", str2);

    // 步骤1：分别对两个字符串排序
    sortString(str1);
    sortString(str2);

    // 步骤2：合并两个排序后的字符串
    mergeStrings(str1, str2, merged);

    // 步骤3：对合并后的字符串再次排序
    sortString(merged);

    // 步骤4：删除重复字符
    removeDuplicates(merged);

    // 输出结果
    printf("合并并去重后的字符串（按ASCII排序）: %s\n", merged);

    return 0;
}
```

