// Function to check if a number is prime
int isPrime(int n) {
    // Handle edge cases
    if (n <= 1) {
        return 0; // Not prime
    }
    if (n == 2) {
        return 1; // Prime (only even prime)
    }
    if (n % 2 == 0) {
        return 0; // Even number > 2 is not prime
    }

    // Check for odd divisors from 3 to sqrt(n)
    for (int i = 3; i <= sqrt(n); i += 2) {
        if (n % i == 0) {
            return 0; // Not prime
        }
    }

    return 1; // Prime
}

