#include <iostream>
#include <cstring>
#include <climits>

// Функция: поиск самого надёжного пути от start до end
// Использует модифицированный алгоритм Дейкстры (по максимальному произведению)
double findMostReliablePath(int N, int start, int end, int edges[][3], double weights[], int E) {
    // Массив для хранения максимальной надёжности до каждой вершины
    double reliability[N];
    bool visited[N];

    // Инициализация
    for (int i = 0; i < N; i++) {
        reliability[i] = 0.0;
        visited[i] = false;
    }
    reliability[start] = 1.0; // Начальная надёжность = 1

    // Основной цикл: находим очередную вершину с максимальной надёжностью
    for (int step = 0; step < N; step++) {
        // Выбираем вершину с максимальной надёжностью, которая еще не посещена
        int u = -1;
        double maxRel = -1.0;

        for (int i = 0; i < N; i++) {
            if (!visited[i] && reliability[i] > maxRel) {
                maxRel = reliability[i];
                u = i;
            }
        }

        // Если не нашли ни одной доступной вершины — прерываемся
        if (u == -1) break;

        // Помечаем вершину как посещённую
        visited[u] = true;

        // Если дошли до цели, можно остановиться (дальше ничего не улучшится)
        if (u == end) break;

        // Обновляем надёжности для соседей вершины u
        for (int i = 0; i < E; i++) {
            int v1 = edges[i][0];
            int v2 = edges[i][1];
            double w = weights[i];

            // Если u — одна из вершин ребра
            if (u == v1) {
                int v = v2;
                double candidate = reliability[u] * w;
                if (candidate > reliability[v]) {
                    reliability[v] = candidate;
                }
            } else if (u == v2) {
                int v = v1;
                double candidate = reliability[u] * w;
                if (candidate > reliability[v]) {
                    reliability[v] = candidate;
                }
            }
        }
    }

    return reliability[end];
}
```

---

### 🔍 Пояснения:
- Мы используем **массивы C-style** (`double reliability[N]`, `bool visited[N]`).
- Структура `edges` хранит `from`, `to`, `weight` (как целое, можно преобразовать к дроби).
- Надёжности переводятся в дроби в диапазоне [0, 1].
- Алгоритм — **модифицированный Дейкстра для максимизации произведения**.
- Поскольку произведение убывает (при умножении на <1), мы ищем **максимальное значение**, как и в классическом Дейкстре.

> ⚠️ Важно: если надёжность — произведение, то мы не можем использовать сумму, поэтому используем **логарифмы** для преобразования в сумму, но в данном случае, так как граф мал, мы обходимся без логов.

---

### 📌 Ограничения:
- Не использует `std::vector`, `std::queue`.
- Граф должен быть непрерывным (иначе вернёт 0).
- Количество вершин `N` задаётся константой или как параметр.
- Если нет пути, возвращает `0.0`.

