```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE_LENGTH 256
#define MAX_ROWS 100
#define MAX_COLS 100
#define BUFFER_SIZE (MAX_ROWS * MAX_COLS)

int main() {
    FILE *file;
    char line[MAX_LINE_LENGTH];
    unsigned char data[BUFFER_SIZE];  // 存储所有字节数据
    int row = 0, col = 0;
    int total_bytes = 0;

    // 打开文件
    file = fopen("data.csv", "r");
    if (file == NULL) {
        printf("无法打开文件 data.csv\n");
        return 1;
    }

    // 逐行读取
    while (fgets(line, sizeof(line), file) != NULL) {
        // 去除换行符
        line[strcspn(line, "\n")] = 0;

        // 使用 strtok 分割 CSV 行
        char *token = strtok(line, ",");
        while (token != NULL) {
            // 转换为整数，并转换为字节
            int value = atoi(token);
            if (value < 0 || value > 255) {
                printf("警告: 值 %d 超出 0-255 范围，将被截断\n", value);
            }
            data[total_bytes++] = (unsigned char)(value & 0xFF);

            token = strtok(NULL, ",");
            col++;
        }

        row++;
        col = 0;  // 重置列计数
    }

    fclose(file);

    // 输出保存的字节
    printf("成功读取 %d 个字节:\n", total_bytes);
    for (int i = 0; i < total_bytes; i++) {
        printf("%02X ", data[i]);
        if ((i + 1) % 8 == 0) printf("\n");  // 每 8 个字节换行
    }
    printf("\n");

    return 0;
}
```

---

### 🔍 说明：

