```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 30
#define INF -1

// Function to compute transitive closure (Floyd-Warshall)
void floyd_warshall(int n, int adj[MAX_NODES][MAX_NODES], int reachable[MAX_NODES][MAX_NODES]) {
    // Initialize reachable
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            reachable[i][j] = adj[i][j];
        }
    }

    // Floyd-Warshall
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (reachable[i][k] && reachable[k][j]) {
                    reachable[i][j] = 1;
                }
            }
        }
    }
}

// Memoized DFS to count paths (only called when no cycle on path)
int count_paths(int i, int j, int n, int adj[MAX_NODES][MAX_NODES], int memo[MAX_NODES][MAX_NODES]) {
    if (i == j) return 1;
    if (memo[i][j] != -1) return memo[i][j];

    int count = 0;
    for (int k = 0; k < n; k++) {
        if (adj[i][k]) {
            count += count_paths(k, j, n, adj, memo);
        }
    }
    memo[i][j] = count;
    return count;
}

int main() {
    int city = 0;
    int m;

    while (scanf("%d", &m) != EOF) {
        int nodes = -1;
        int adj[MAX_NODES][MAX_NODES] = {0};
        int i, j;

        // Read m edges
        for (int k = 0; k < m; k++) {
            scanf("%d %d", &i, &j);
            adj[i][j] = 1;
            if (i > nodes) nodes = i;
            if (j > nodes) nodes = j;
        }

        // Max node index
        int n = nodes + 1;

        // Compute transitive closure
        int reachable[MAX_NODES][MAX_NODES] = {0};
        floyd_warshall(n, adj, reachable);

        // Mark which nodes are in cycles: reachable[k][k] == true
        int in_cycle[MAX_NODES] = {0};
        for (int k = 0; k < n; k++) {
            in_cycle[k] = (reachable[k][k] == 1);
        }

        // Output matrix
        printf("matrix for city %d\n", city);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (!reachable[i][j]) {
                    printf("0");
                } else {
                    // Check if there is any cycle node k such that:
                    // reachable[i][k] && reachable[k][j] && in_cycle[k]
                    int has_infinite = 0;
                    for (int k = 0; k < n && !has_infinite; k++) {
                        if (reachable[i][k] && reachable[k][j] && in_cycle[k]) {
                            has_infinite = 1;
                        }
                    }
                    if (has_infinite) {
                        printf("-1");
                    } else {
                        // Count finite paths from i to j
                        int memo[MAX_NODES][MAX_NODES];
                        for (int a = 0; a < n; a++) {
                            for (int b = 0; b < n; b++) {
                                memo[a][b] = -1;
                            }
                        }
                        int paths = count_paths(i, j, n, adj, memo);
                        printf("%d", paths);
                    }
                }
                if (j < n - 1) printf(" ");
            }
            printf("\n");
        }

        city++;
    }

    return 0;
}
```

---

### 📌 Notes:

- The `reachable` matrix is used to:
  1. Check if a path exists.
  2. Detect if a node is in a cycle (`reachable[k][k]`).
  3. Check if any path from `i` to `j` uses a cycle node reachable from `i` and leading to `j`.
- `count_paths` uses DFS with memoization, and is only called when it's safe (no infinite paths).
- Time complexity: O(n³) for Floyd-Warshall + O(n²) for each `(i,j)` pair. The `count_paths` DFS may run in exponential time in worst case, but the absence of cycles in the path allows it to complete.

