    for (int i = 0; i <= n; i++) {
        isPrime[i] = true;
    }

    // 0 và 1 không phải là số nguyên tố
    isPrime[0] = isPrime[1] = false;

    // Sàng Eratosthenes
    for (int i = 2; i * i <= n; i++) {
        if (isPrime[i]) {
            // Đánh dấu các bội số của i (không tính i chính) là không nguyên tố
            for (int j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }

    // In ra các số nguyên tố
    printf("Các số nguyên tố <= %d là:\n", n);
    for (int i = 2; i <= n; i++) {
        if (isPrime[i]) {
            printf("%d ", i);
        }
    }
    printf("\n");
}

