## 🔧 1. Server.cpp

```cpp
#include <windows.h>
#include <iostream>
#include <fstream>
#include <string>

#define PIPE_NAME "\\\\.\\pipe\\EmployeePipe"
#define BUFFER_SIZE 4096

// Глобальная переменная для файла
std::string g_filename = "employees.dat";
employee* g_employees = nullptr;
int g_employee_count = 0;

// Блокировка: true — запись блокируется, false — нет
bool g_write_lock = false;

// Функция для чтения файл
bool LoadEmployees() {
    std::ifstream file(g_filename, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Не удалось открыть файл " << g_filename << std::endl;
        return false;
    }

    // Подсчитываем размер файла
    file.seekg(0, std::ios::end);
    size_t size = file.tellg();
    file.seekg(0, std::ios::beg);

    g_employee_count = size / sizeof(employee);
    g_employees = new employee[g_employee_count];

    file.read(reinterpret_cast<char*>(g_employees), size);
    file.close();

    return true;
}

// Функция для записи обратно в файл
void SaveEmployees() {
    std::ofstream file(g_filename, std::ios::binary | std::ios::trunc);
    if (!file.is_open()) {
        std::cerr << "Не удалось открыть файл для записи." << std::endl;
        return;
    }

    file.write(reinterpret_cast<const char*>(g_employees), g_employee_count * sizeof(employee));
    file.close();
}

// Функция для вывода списка сотрудников
void PrintEmployees() {
    std::cout << "\n=== Список сотрудников ===\n";
    for (int i = 0; i < g_employee_count; i++) {
        std::cout << "ID: " << g_employees[i].num
                  << ", Имя: " << g_employees[i].name
                  << ", Часы: " << g_employees[i].hours << std::endl;
    }
    std::cout << "==========================\n" << std::endl;
}

// Обработка запроса от клиента
DWORD WINAPI HandleClient(LPVOID lpParam) {
    HANDLE hPipe = (HANDLE)lpParam;

    DWORD dwBytesRead;
    char buffer[BUFFER_SIZE];
    employee emp = {};

    while (true) {
        // Чтение запроса от клиента
        if (!ReadFile(hPipe, buffer, BUFFER_SIZE, &dwBytesRead, NULL)) {
            std::cerr << "Ошибка чтения из канала." << std::endl;
            break;
        }

        // Определяем тип запроса (0 = read, 1 = write)
        int request_type = buffer[0];
        int key = 0;
        memcpy(&key, buffer + 1, sizeof(int));

        std::cout << "Получен запрос: тип=" << request_type << ", ключ=" << key << std::endl;

        if (request_type == 0) { // Чтение
            bool found = false;
            for (int i = 0; i < g_employee_count; i++) {
                if (g_employees[i].num == key) {
                    emp = g_employees[i];
                    found = true;
                    break;
                }
            }

            if (found) {
                // Отправляем запись клиенту
                buffer[0] = 1; // Успешный ответ
                memcpy(buffer + 1, &emp, sizeof(employee));
                DWORD dwWritten;
                WriteFile(hPipe, buffer, sizeof(employee) + 1, &dwWritten, NULL);
            } else {
                buffer[0] = 0; // Ошибка
                WriteFile(hPipe, buffer, 1, NULL, NULL);
            }
        }
        else if (request_type == 1) { // Запись (модификация)
            // Ожидаем блокировку
            while (g_write_lock) {
                Sleep(10); // Ожидание разрешения
            }
            g_write_lock = true;

            // Получаем данные
            int dataSize = dwBytesRead - 1 - sizeof(int);
            if (dataSize == sizeof(employee)) {
                memcpy(&emp, buffer + 1 + sizeof(int), sizeof(employee));
            } else {
                g_write_lock = false;
                std::cerr << "Ошибка: неправильный размер данных." << std::endl;
                buffer[0] = 0;
                WriteFile(hPipe, buffer, 1, NULL, NULL);
                continue;
            }

            // Ищем сотрудника
            bool found = false;
            for (int i = 0; i < g_employee_count; i++) {
                if (g_employees[i].num == key) {
                    g_employees[i] = emp;
                    found = true;
                    break;
                }
            }

            if (found) {
                SaveEmployees(); // Сохраняем изменения
                buffer[0] = 1;
                WriteFile(hPipe, buffer, 1, NULL, NULL);
            } else {
                buffer[0] = 0;
                WriteFile(hPipe, buffer, 1, NULL, NULL);
            }

            g_write_lock = false;
        }
    }

    CloseHandle(hPipe);
    return 0;
}

int main() {
    std::cout << "=== Сервер управления файлом сотрудников ===\n";

    // 1. Ввод имени файла
    std::cout << "Введите имя файла (по умолчанию employees.dat): ";
    std::getline(std::cin, g_filename);
    if (g_filename.empty()) g_filename = "employees.dat";

    // 2. Создание и заполнение файла
    std::cout << "Создание бинарного файла: " << g_filename << "\n";
    std::ofstream file(g_filename, std::ios::binary | std::ios::trunc);
    if (file.is_open()) {
        employee empList[] = {
            {1001, "Ivan", 8.5},
            {1002, "Anna", 7.5},
            {1003, "Petr", 9.0}
        };
        int count = 3;
        file.write(reinterpret_cast<const char*>(empList), count * sizeof(employee));
        file.close();
    }

    // 3. Загрузка из файла
    if (!LoadEmployees()) {
        std::cerr << "Не удалось загрузить данные из файла." << std::endl;
        return -1;
    }

    // 4. Вывод на консоль
    PrintEmployees();

    // 5. Создание именованного канала
    HANDLE hPipe = CreateNamedPipe(
        PIPE_NAME,
        PIPE_ACCESS_DUPLEX,
        PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE,
        1,  // Максимальное количество подключений
        BUFFER_SIZE,
        BUFFER_SIZE,
        0,
        NULL
    );

    if (hPipe == INVALID_HANDLE_VALUE) {
        std::cerr << "Ошибка создания именованного канала: " << GetLastError() << std::endl;
        return -1;
    }

    std::cout << "Сервер запущен. Ожидание подключения клиента...\n";

    while (true) {
        if (ConnectNamedPipe(hPipe, NULL)) {
            std::cout << "Клиент подключился.\n";
            CreateThread(NULL, 0, HandleClient, (LPVOID)hPipe, 0, NULL);
        } else {
            if (GetLastError() == ERROR_PIPE_CONNECTED) {
                std::cout << "Клиент уже подключён.\n";
                CreateThread(NULL, 0, HandleClient, (LPVOID)hPipe, 0, NULL);
            } else {
                std::cerr << "Ошибка подключения клиента: " << GetLastError() << std::endl;
            }
        }

        // Ждём команду "выход"
        char cmd[100];
        std::cout << "Введите 'quit' для завершения сервера: ";
        std::cin.getline(cmd, 100);

        if (strcmp(cmd, "quit") == 0) {
            std::cout << "Завершение сервера...\n";

            // Закрываем канал
            CloseHandle(hPipe);

            // Выводим финальный файл
            PrintEmployees();

            delete[] g_employees;
            return 0;
        }
    }

    return 0;
}
```

