## ✅ 一、内核模块代码（`mmap_driver.c`）

```c
#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/mm.h>
#include <linux/slab.h>

#define DEVICE_NAME "mmap_dev"
#define BUFFER_SIZE 4096

static int major_num;
static char *shared_buffer;
static int buffer_size = BUFFER_SIZE;

// mmap 映射回调函数
static int mmap_callback(struct file *filp, struct vm_area_struct *vma)
{
    unsigned long size = vma->vm_end - vma->vm_start;

    // 检查请求大小是否匹配
    if (size > buffer_size) {
        printk(KERN_ERR "Requested size (%lu) exceeds buffer size (%d)\n", size, buffer_size);
        return -EINVAL;
    }

    // 设置虚拟内存区域属性
    vma->vm_flags |= VM_RESERVED | VM_IO | VM_DONTEXPAND;

    // 将物理页映射到用户空间
    if (remap_pfn_range(vma, vma->vm_start, virt_to_phys(shared_buffer) >> PAGE_SHIFT,
                        size, vma->vm_page_prot)) {
        printk(KERN_ERR "remap_pfn_range failed\n");
        return -EAGAIN;
    }

    printk(KERN_INFO "mmap successful: mapped %lu bytes\n", size);
    return 0;
}

// 设备文件操作函数
static int device_open(struct inode *inode, struct file *filp)
{
    printk(KERN_INFO "Device opened\n");
    return 0;
}

static int device_release(struct inode *inode, struct file *filp)
{
    printk(KERN_INFO "Device closed\n");
    return 0;
}

// 文件操作结构体
static struct file_operations fops = {
    .owner = THIS_MODULE,
    .open = device_open,
    .release = device_release,
    .mmap = mmap_callback,
};

// 模块初始化
static int __init mmap_init(void)
{
    // 分配共享内存
    shared_buffer = kmalloc(BUFFER_SIZE, GFP_KERNEL);
    if (!shared_buffer) {
        printk(KERN_ERR "kmalloc failed\n");
        return -ENOMEM;
    }

    // 注册字符设备
    major_num = register_chrdev(0, DEVICE_NAME, &fops);
    if (major_num < 0) {
        printk(KERN_ERR "register_chrdev failed\n");
        kfree(shared_buffer);
        return major_num;
    }

    printk(KERN_INFO "Mmap driver initialized. Major number: %d\n", major_num);
    return 0;
}

// 模块卸载
static void __exit mmap_exit(void)
{
    unregister_chrdev(major_num, DEVICE_NAME);
    kfree(shared_buffer);
    printk(KERN_INFO "Mmap driver removed\n");
}

module_init(mmap_init);
module_exit(mmap_exit);

MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("Simple mmap driver for user-kernel communication");
MODULE_AUTHOR("Your Name");
```

