## ✅ 二、用户空间程序（`user_app.c`）

```c
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>

#define DEVICE_PATH "/dev/mmap_dev"
#define BUFFER_SIZE 4096

int main(void)
{
    int fd;
    char *mapped_addr;

    // 打开设备
    fd = open(DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // 映射内存
    mapped_addr = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE,
                       MAP_SHARED, fd, 0);
    if (mapped_addr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // 修改共享内存内容
    printf("Writing to shared memory...\n");
    snprintf(mapped_addr, BUFFER_SIZE, "Hello from user space! Time: %ld", time(NULL));

    // 读取并打印
    printf("Read from shared memory: %s\n", mapped_addr);

    // 释放映射
    if (munmap(mapped_addr, BUFFER_SIZE) == -1) {
        perror("munmap");
    }

    close(fd);
    printf("Done.\n");
    return 0;
}
```

