#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <cstring>
#include <vector>
#include <map>
#include <stdexcept>

const int MAX_CLIENTS = 100;
const int BUFFER_SIZE = 1024;

class TCPServer {
private:
    int server_fd;
    fd_set read_fds, master_fds;
    std::map<int, std::string> client_buffer; // буфер для каждого клиента
    int max_fd;

public:
    TCPServer(int port) {
        // Создание серверного сокета
        server_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (server_fd < 0) {
            throw std::runtime_error("Ошибка создания сокета");
        }

        int opt = 1;
        if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
            throw std::runtime_error("Ошибка setsockopt");
        }

        // Настройка адреса
        sockaddr_in address;
        address.sin_family = AF_INET;
        address.sin_addr.s_addr = INADDR_ANY;
        address.sin_port = htons(port);

        if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
            throw std::runtime_error("Ошибка bind");
        }

        if (listen(server_fd, 3) < 0) {
            throw std::runtime_error("Ошибка listen");
        }

        std::cout << "Сервер запущен на порту " << port << std::endl;

        // Инициализация множества дескрипторов
        FD_ZERO(&master_fds);
        FD_SET(server_fd, &master_fds);
        max_fd = server_fd;
    }

    ~TCPServer() {
        close(server_fd);
    }

    void run() {
        while (true) {
            read_fds = master_fds; // Копируем основное множество

            // Ждём события (новые подключения или данные от клиентов)
            int activity = select(max_fd + 1, &read_fds, nullptr, nullptr, nullptr);
            if (activity < 0) {
                std::cerr << "Ошибка select" << std::endl;
                continue;
            }

            // Обработка событий
            for (int fd = 0; fd <= max_fd; ++fd) {
                if (FD_ISSET(fd, &read_fds)) {
                    if (fd == server_fd) {
                        // Новое клиентское соединение
                        accept_new_client();
                    } else {
                        // Данные от клиента
                        handle_client_data(fd);
                    }
                }
            }
        }
    }

private:
    void accept_new_client() {
        sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (client_fd < 0) {
            std::cerr << "Ошибка accept" << std::endl;
            return;
        }

        // Устанавливаем сокет в неблокирующий режим (опционально, но полезно)
        int flags = fcntl(client_fd, F_GETFL, 0);
        fcntl(client_fd, F_SETFL, flags | O_NONBLOCK);

        FD_SET(client_fd, &master_fds);
        if (client_fd > max_fd) {
            max_fd = client_fd;
        }

        client_buffer[client_fd] = "";
        std::cout << "Новый клиент подключен: " << client_fd << std::endl;
    }

    void handle_client_data(int client_fd) {
        char buffer[BUFFER_SIZE];
        int bytes_read = recv(client_fd, buffer, sizeof(buffer) - 1, 0);

        if (bytes_read < 0) {
            // Ошибка чтения (например, соединение разорвано)
            std::cerr << "Ошибка чтения от клиента " << client_fd << std::endl;
            cleanup_client(client_fd);
            return;
        }

        if (bytes_read == 0) {
            // Клиент отключился
            std::cout << "Клиент " << client_fd << " отключился" << std::endl;
            cleanup_client(client_fd);
            return;
        }

        buffer[bytes_read] = '\0';

        // Добавляем в буфер (если нужно — можно обрабатывать по байтам)
        client_buffer[client_fd] += buffer;

        // Обрабатываем сообщение (эхо-отправка)
        std::string response = "Эхо: " + client_buffer[client_fd];
        send(client_fd, response.c_str(), response.size(), 0);

        // Попробуем отправить ответ, если что-то в буфере
        // Можно улучшить: разбить на строки и обрабатывать построчно
    }

    void cleanup_client(int client_fd) {
        close(client_fd);
        FD_CLR(client_fd, &master_fds);
        client_buffer.erase(client_fd);
    }
};

int main() {
    try {
        TCPServer server(8080);
        server.run();
    } catch (const std::exception& e) {
        std::cerr << "Ошибка: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
