#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <dirent.h>
#include <ctype.h>
#include <errno.h>

#define MAX_PROCESSES 5
#define MAX_PATH 256
#define MAX_LINE 1024

// Structure to store process info
typedef struct {
    int pid;
    int ppid;
    char state[10]; // "Z" for zombie, otherwise running/terminated
    int is_defunct;
} ProcessInfo;

// Global process list and count
