int process_count = 0;

// Function to extract value from /proc/[pid]/status
int get_proc_status(int pid, char *key, char *value, int size) {
    char path[MAX_PATH];
    FILE *fp;

    snprintf(path, sizeof(path), "/proc/%d/status", pid);
    fp = fopen(path, "r");
    if (!fp) return -1;

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, key, strlen(key)) == 0) {
            // Copy value part after the colon and space
            char *val = line + strlen(key);
            while (*val == ' ' || *val == '\t') val++;
            char *end = val;
            while (*end && *end != '\n') end++;
            *end = '\0';
            strncpy(value, val, size - 1);
            value[size - 1] = '\0';
            fclose(fp);
            return 0;
        }
    }
    fclose(fp);
