#include <stdio.h>
#include <time.h>

// 判断是否为闰年
int is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// 获取某月有多少天
int days_in_month(int year, int month) {
    int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2 && is_leap_year(year)) {
        return 29;
    }
    return days[month - 1];
}

// 校验日期是否合法
int is_valid_date(int year, int month, int day) {
    if (year < 1 || month < 1 || month > 12 || day < 1) return 0;
    return day <= days_in_month(year, month);
}

// 增加年份
void add_year(int *year, int n) {
    *year += n;
}

// 增加月份
void add_month(int *year, int *month, int n) {
    *month += n;
    while (*month > 12) {
        (*year)++;
        (*month) -= 12;
    }
    while (*month < 1) {
        (*year]--;
        (*month) += 12;
    }
    // 修正日期若超过该月最大天数
    int max_day = days_in_month(*year, *month);
    if (*month > 12 || *month < 1) return;
    if (*day > max_day) {
        *day = max_day;
    }
}

// 增加日期
void add_day(int *year, int *month, int *day, int n) {
    *day += n;
    while (*day > days_in_month(*year, *month)) {
        *day -= days_in_month(*year, *month);
        (*month)++;
        if (*month > 12) {
            *month = 1;
            (*year)++;
        }
    }
    while (*day < 1) {
        *month--;
        if (*month < 1) {
            *month = 12;
            (*year)--;
        }
        *day += days_in_month(*year, *month);
    }
}

// 减少年份
void sub_year(int *year, int n) {
    *year -= n;
}

// 减少月份
void sub_month(int *year, int *month, int n) {
    *month -= n;
    while (*month > 12) {
        (*year)++;
        (*month) -= 12;
    }
    while (*month < 1) {
        (*year]--;
        (*month) += 12;
    }
    int max_day = days_in_month(*year, *month);
    if (*day > max_day) {
        *day = max_day;
    }
}

// 减少日期
void sub_day(int *year, int *month, int *day, int n) {
    *day -= n;
    while (*day < 1) {
        *month--;
