    *year = t->tm_year + 1900;
    *month = t->tm_mon + 1;
    *day = t->tm_mday;
}

// 主函数
int main() {
    int year, month, day;
    int orig_year, orig_month, orig_day; // 保存初始时间
    int choice, n;

    printf("请输入初始日期（年 月 日）：");
    scanf("%d %d %d", &year, &month, &day);

    // 检查初始日期合法性
    if (!is_valid_date(year, month, day)) {
        printf("错误：输入的日期不合法！\n");
        return 1;
    }

    // 保存初始时间
    orig_year = year;
    orig_month = month;
    orig_day = day;

    int running = 1;
    while (running) {
        printf("\n========= 万年历功能菜单 =========\n");
        printf("当前日期： %d年%d月%d日\n", year, month, day);
        printf("1. 增加年份\n");
        printf("2. 增加月份\n");
        printf("3. 增加日期\n");
        printf("4. 减少年份\n");
        printf("5. 减少月份\n");
        printf("6. 减少日期\n");
        printf("7. 重置为初始时间\n");
        printf("8. 退出程序\n");
        printf("请选择功能（1-8）：");

        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("请输入增加的年份数：");
                scanf("%d", &n);
                if (n < 0) {
