                scanf("%d", &n);
                if (n < 0) {
                    printf("请输入非负整数！\n");
                    break;
                }
                add_day(&year, &month, &day, n);
                show_date(year, month, day);
                break;

            case 4:
                printf("请输入减少的年份数：");
                scanf("%d", &n);
                if (n < 0) {
                    printf("请输入非负整数！\n");
                    break;
                }
                if (year < n) {
                    printf("错误：年份减少后将小于1年，不可操作！\n");
                    break;
                }
                sub_year(&year, n);
                show_date(year, month, day);
                break;

            case 5:
                printf("请输入减少的月份数：");
                scanf("%d", &n);
                if (n < 0) {
                    printf("请输入非负整数！\n");
                    break;
                }
                sub_month(&year, &month, n);
                show_date(year, month, day);
                break;

            case 6:
                printf("请输入减少的天数：");
                scanf("%d", &n);
                if (n < 0) {
                    printf("请输入非负整数！\n");
                    break;
                }
                if (n >= day) {
                    printf("错误：减少天数后日期将小于1号，不可操作！\n");
                    break;
                }
                sub_day(&year, &month, &day, n);
                show_date(year, month, day);
