下面是一个**使用 `libuv` 作为主事件循环、`libwebsockets` 作为 WebSocket 客户端**的完整示例。

---

## ✅ 要求准备

1. 安装 `libuv`（通常叫 `libuv-dev` 或 `libuv-devel`）
2. 安装 `libwebsockets`（推荐使用 4.3+ 版本）
3. 编译器支持 C++11 或以上（因为 `libwebsockets` 用 C++ 调用推荐 C++）

---

## ✅ 示例代码：使用 libuv + libwebsockets 的 WebSocket 客户端

```cpp
// websocket_client.cpp
#include <iostream>
#include <string>
#include <cstring>

// libuv 头文件
#include <uv.h>

// libwebsockets 头文件
#include <libwebsockets.h>

// 全局 UV 循环
uv_loop_t* loop;

// WebSocket 上下文和协议
struct lws* wsi = nullptr;
struct lws_context* context = nullptr;

// 命令行参数：服务器地址，例如 ws://localhost:9000
std::string server_url = "ws://localhost:9000";

// WebSocket 协议定义
static const struct lws_protocols protocols[] = {
    {
        "echo-protocol",  // 协议名
        lws_callback_handler,  // 回调函数
        0,  // per_session_data_size
        1024,  // rx_buffer_size
    },
    { NULL, NULL, 0, 0 }  // 终止
};

// 回调函数：处理 WebSocket 事件
int lws_callback_handler(struct lws* wsi, enum lws_callback_reasons reason, void* user, void* in, size_t len) {
    switch (reason) {
        case LWS_CALLBACK_CLIENT_ESTABLISHED:
            std::cout << "WebSocket connection established." << std::endl;
            break;

        case LWS_CALLBACK_CLIENT_RECEIVE:
            std::cout << "Received: " << std::string((char*)in, len) << std::endl;
            break;

        case LWS_CALLBACK_CLIENT_CLOSED:
            std::cout << "WebSocket connection closed." << std::endl;
            break;

        case LWS_CALLBACK_ERROR:
            std::cout << "WebSocket error occurred." << std::endl;
            break;

        case LWS_CALLBACK_CLIENT_CONNECTION_ERROR:
            std::cout << "Connection error to server." << std::endl;
            break;

        default:
            break;
    }

    return 0;
}

// libuv 的定时器回调：用于周期性发送消息
void timer_callback(uv_timer_t* handle) {
    if (wsi) {
        const char* msg = "Hello from libuv + libwebsockets!";
        if (lws_write(wsi, (unsigned char*)msg, strlen(msg), LWS_WRITE_TEXT) < 0) {
            std::cerr << "Failed to send message." << std::endl;
        }
    }
}

// libuv 的 WebSocket 事件回调（由 libwebsockets 调用）
void libwebsockets_poll_callback(uv_poll_t* handle, int status, int events) {
    if (status < 0) {
        std::cerr << "uv_poll error: " << uv_strerror(status) << std::endl;
        return;
    }

    // 将 libwebsockets 调用的事件通知给 libwebsockets 主循环
    lws_service(context, 0);
}

// 初始化 WebSocket
int init_websocket() {
    struct lws_context_creation_info info = {};
    memset(&info, 0, sizeof(info));

    info.gid = -1;
    info.uid = -1;
    info.port = CONTEXT_NO_LISTEN_PORT;
    info.protocols = protocols;
    info.extensions = lws_get_internal_extensions();
    info.ssl_cert_filepath = nullptr;
    info.ssl_private_key_filepath = nullptr;
    info.user = nullptr;
    info.options = LWS_SERVER_OPTION_DO_SSL_GLOBAL_INIT;

    context = lws_create_context(&info);
    if (!context) {
        std::cerr << "Failed to create libwebsockets context." << std::endl;
        return -1;
    }

    // 创建 WebSocket 客户端连接
    struct lws_client_connect_info i = {};
    memset(&i, 0, sizeof(i));
    i.context = context;
    i.address = "localhost";  // 替换为实际服务器地址
    i.port = 9000;
    i.path = "/";
    i.host = "localhost";
    i.origin = "localhost";
    i.protocol = "echo-protocol";
    i.ssl_connection = 0;  // 如果启用 SSL，改为 LWS_TLS_CLIENT

    wsi = lws_client_connect_via_info(&i);
    if (!wsi) {
        std::cerr << "Failed to connect to WebSocket server." << std::endl;
        return -1;
    }

    // 创建 UV poll handle，监视 libwebsockets 的事件
    uv_poll_t* poll_handle = (uv_poll_t*)malloc(sizeof(uv_poll_t));
    int fd = lws_get_socket_fd(wsi);
    if (uv_poll_init(loop, poll_handle, fd) < 0) {
        std::cerr << "Failed to initialize UV poll handle." << std::endl;
        return -1;
    }

    // 启用读事件监听
    if (uv_poll_start(poll_handle, UV_READABLE, libwebsockets_poll_callback)) {
        std::cerr << "Failed to start UV poll." << std::endl;
        return -1;
    }

    // 创建定时器，每 3 秒发送一次消息
    uv_timer_t* timer = (uv_timer_t*)malloc(sizeof(uv_timer_t));
    uv_timer_init(loop, timer);
    uv_timer_start(timer, timer_callback, 3000, 3000);  // 第一次延迟 3s，之后每 3s 一次

    std::cout << "WebSocket client started. Connected to " << server_url << std::endl;

    return 0;
}

// 主函数
int main(int argc, char* argv[]) {
    // 初始化 libuv
    loop = (uv_loop_t*)malloc(sizeof(uv_loop_t));
    if (uv_loop_init(loop) != 0) {
        std::cerr << "Failed to initialize libuv loop." << std::endl;
        return -1;
    }

    // 初始化 WebSocket 客户端
    if (init_websocket() != 0) {
        std::cerr << "Failed to initialize WebSocket client." << std::endl;
        return -1;
    }

    // 运行事件循环
    std::cout << "Running libuv event loop... Press Ctrl+C to quit." << std::endl;
    uv_run(loop, UV_RUN_DEFAULT);

    // 清理
    if (context) {
        lws_context_destroy(context);
    }

    free(loop);
    std::cout << "WebSocket client stopped." << std::endl;

    return 0;
}
```

