在 C 语言中实现“24点游戏”的算法，目标是**判断四个数字（1~13）是否可以通过 +、-、×、÷ 和括号组合得到 24**，并且要**算法复杂度最低**。为了达到这一目标，我们需要从以下几个方面优化：

---

### ✅ 目标
- 输入：4 个整数（1~13）
- 输出：是否能通过任意顺序、任意组合、任意括号，使用 `+ - * /` 得到 24
- 要求：算法时间复杂度尽可能低（O(1) 级别，实际为常数时间优化）

---

### 🚩 为什么“复杂度最低”是目标？
- 所有输入是 4 个数字，范围 1~13，总数为 `13^4 = 28561` 种组合，且有顺序和操作符组合。
- 所以，**可以预先计算所有可能的组合并存为哈希表或布尔数组**，达到 O(1) 查询。

---

## ✅ 最优解法：**预计算 + 哈希表查询（O(1)）**

### 思路
1. 枚举所有可能的 4 个数字组合（可重复，顺序不同算不同，但我们要去重顺序）。
2. 对每个组合尝试所有排列（4! = 24 种）。
3. 对每种排列，尝试所有运算符组合（4 个操作符位置，每个 4 种可能 → 4^3 = 64 种）。
4. 尝试所有括号组合（3 种结构）。
5. 使用浮点数计算（注意除法精度），并判断是否等于 24（允许浮点误差 ε=1e-6）。
6. 将所有可行的四元组放入一个哈希表（或布尔数组），以用于 O(1) 查询。

---

## 🧩 代码实现（预计算 + 哈希表 + O(1) 查询）

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define EPS 1e-6
#define SIZE 13
#define HASH_SIZE (SIZE * SIZE * SIZE * SIZE)

// 用于存储所有能凑出 24 的四元组（用整数表示：a*13^3 + b*13^2 + c*13 + d）
// 或者更简单：使用布尔数组
unsigned char can_make_24[SIZE][SIZE][SIZE][SIZE];

// 判断两个浮点数是否近似相等
int is_zero(double x) {
    return fabs(x) < EPS;
}

// 两个数的运算
double calc(double a, double b, int op) {
    switch (op) {
        case 0: return a + b;
        case 1: return a - b;
        case 2: return a * b;
        case 3: return b != 0 ? a / b : 1e9; // 避免除零
        default: return 0;
    }
}

// 括号的3种结构
// 1. ((a op b) op c) op d
// 2. (a op (b op c)) op d
// 3. (a op b) op (c op d)
// 4. a op (b op (c op d))
// 5. a op ((b op c) op d)

// 5 种结构
double evaluate(double a, double b, double c, double d, int op1, int op2, int op3) {
    double t1, t2, t3;

    // 结构1: ((a op1 b) op2 c) op3 d
    t1 = calc(a, b, op1);
    t2 = calc(t1, c, op2);
    t3 = calc(t2, d, op3);
    if (!is_zero(t3 - 24.0)) return t3;

    // 结构2: (a op1 (b op2 c)) op3 d
    t1 = calc(b, c, op2);
    t2 = calc(a, t1, op1);
    t3 = calc(t2, d, op3);
    if (!is_zero(t3 - 24.0)) return t3;

    // 结构3: (a op1 b) op2 (c op3 d)
    t1 = calc(a, b, op1);
    t2 = calc(c, d, op3);
    t3 = calc(t1, t2, op2);
    if (!is_zero(t3 - 24.0)) return t3;

    // 结构4: a op1 (b op2 (c op3 d))
    t1 = calc(c, d, op3);
    t2 = calc(b, t1, op2);
    t3 = calc(a, t2, op1);
    if (!is_zero(t3 - 24.0)) return t3;

    // 结构5: a op1 ((b op2 c) op3 d)
    t1 = calc(b, c, op2);
    t2 = calc(t1, d, op3);
    t3 = calc(a, t2, op1);
    if (!is_zero(t3 - 24.0)) return t3;

    return 1e9; // 不等于24
}

// 检查一个四元组能否凑出24
void can_make(int a, int b, int c, int d) {
    // 遍历所有排列
    int p[4] = {a, b, c, d};
    do {
        double x = p[0], y = p[1], z = p[2], w = p[3];

        // 3 次运算，每种有 4 种操作符
        for (int op1 = 0; op1 < 4; op1++)
            for (int op2 = 0; op2 < 4; op2++)
                for (int op3 = 0; op3 < 4; op3++) {
                    double res = evaluate(x, y, z, w, op1, op2, op3);
                    if (is_zero(res - 24.0)) {
                        can_make_24[a][b][c][d] = 1;
                        return;
                    }
                }
    } while (next_permutation(p, 4));
}

// 生成下一个排列
int next_permutation(int *p, int n) {
    int i = n - 2;
    while (i >= 0 && p[i] >= p[i + 1]) i--;
    if (i < 0) return 0;
    int j = n - 1;
    while (p[j] <= p[i]) j--;
    int t = p[i]; p[i] = p[j]; p[j] = t;
    for (int k = i + 1, l = n - 1; k < l; k++, l--) {
        t = p[k]; p[k] = p[l]; p[l] = t;
    }
    return 1;
}

// 初始化预计算表
void init_table() {
    memset(can_make_24, 0, sizeof(can_make_24));

    // 遍历所有可能的四元组 (数字1~13)
    for (int a = 1; a <= SIZE; a++)
        for (int b = 1; b <= SIZE; b++)
            for (int c = 1; c <= SIZE; c++)
                for (int d = 1; d <= SIZE; d++)
                    can_make(a, b, c, d);
}

// 主查询函数：O(1)
int can_make_24_query(int a, int b, int c, int d) {
    return can_make_24[a][b][c][d];
}

// ======================= 主函数测试 =======================
int main() {
    init_table();

    int a, b, c, d;
    printf("请输入四个数字 (1-13)：");
    scanf("%d %d %d %d", &a, &b, &c, &d);

    if (can_make_24_query(a, b, c, d)) {
        printf("✅ 可以凑出 24！\n");
    } else {
        printf("❌ 无法凑出 24。\n");
    }

    return 0;
}
```

---

## 📈 复杂度分析

| 阶段 | 复杂度 | 说明 |
|------|--------|------|
| 预计算 | O(13⁴ × 24 × 64 × 5) ≈ O(10^6) | 常数时间，仅运行一次 |
| 查询 | **O(1)** | 直接查数组，时间常数 |
| 空间 | O(13⁴) = O(28561) ≈ 28KB | 可忽略 |

> ⚠️ 注意：虽然内部循环较多，但总状态数为常数，因此**预计算总时间是 O(1)**，查询是 O(1)。

---

## ✅ 优势总结

- 逻辑清晰，不依赖运行时暴力搜索。
- 括号结构覆盖全面（5 种）。
- 使用浮点比较避免精度问题。
- 可应对重复数字、大数溢出（通过 `double`）。
- **最优化：查询复杂度是 O(1)，且预计算一次即可永久使用。**

---

