    printf("\nRepetition count of each number:\n");

    // We'll use a visited array to avoid counting same number multiple times
    int visited[n];
    for (int i = 0; i < n; i++) {
        visited[i] = 0;  // Initially none are visited
    }

    for (int i = 0; i < n; i++) {
        if (visited[i] == 1) continue;  // Skip if already counted

        int count = 1;  // Start count with 1 (the current number)

        // Check all other elements
        for (int j = i + 1; j < n; j++) {
            if (numbers[i] == numbers[j]) {
                count++;
                visited[j] = 1;  // Mark as visited
            }
        }

        // Print the number and its frequency
        printf("%d appears %d time(s)\n", numbers[i], count);
    }

    return 0;
}
