typedef struct Node {
    int data;
    struct Node* next;
} Node;

// Функция для создания нового узла
Node* createNode(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Ошибка: не удалось выделить память для узла.\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Функция для добавления элемента в конец списка
void append(Node** head, int data) {
    Node* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
        return;
    }
    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = newNode;
}

// Функция для чтения входных данных с проверкой
// Возвращает количество элементов в списке
int readSequence(Node** head) {
    int ch;
    int num = 0;
    int inNumber = 0;
    int sign = 1;

    while ((ch = getchar()) != EOF) {
        if (ch == '.') {
            // Конец последовательности
            if (inNumber) {
                // Добавляем последнее число
                append(head, num * sign);
                return 1;
            }
            return 0; // Пустая последовательность
        }

        if (ch == ' ' || ch == '\n' || ch == '\t') {
            if (inNumber) {
                // Завершаем число
                append(head, num * sign);
                num = 0;
                sign = 1;
                inNumber = 0;
            }
            continue;
        }

        if (ch == '-') {
            if (inNumber) {
                fprintf(stderr, "Ошибка: неверный формат числа.\n");
                exit(1);
            }
            sign = -1;
            continue;
        }

        if (isdigit(ch)) {
            inNumber = 1;
            num = num * 10 + (ch - '0');
        } else {
            fprintf(stderr, "Ошибка: неверный символ '%c'.\n", ch);
            exit(1);
        }
