// Функция для нахождения длины списка
int getListLength(Node* head) {
    int length = 0;
    Node* current = head;
    while (current != NULL) {
        length++;
        current = current->next;
    }
    return length;
}

// Функция для обмена элементов списка (по позициям: первый-последний, второй-предпоследний и т.д.)
void reverseListNodes(Node** head) {
    if (*head == NULL || (*head)->next == NULL) return;

    int n = getListLength(*head);
    Node* current = *head;

    // Проходим только до середины (включая центральную при нечётном количестве)
    for (int i = 0; i < n / 2; i++) {
        // Находим i-й узел с начала
        Node* left = current;
        Node* right = current;

        // Находим узел на позиции n - 1 - i (с конца)
        for (int j = 0; j < n - 1 - i; j++) {
            right = right->next;
        }

        // Меняем местами данные узлов
        int temp = left->data;
        left->data = right->data;
        right->data = temp;

        // Перемещаемся к следующему узлу с начала
        current = current->next;
    }
}

// Функция для вывода списка
void printList(Node* head) {
    if (head == NULL) {
        printf("NULL\n");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        printf("%d", current->data);
        if (current->next != NULL) {
            printf(" ");
        }
        current = current->next;
    }
    printf("\n");
}

// Функция для освобождения памяти
void freeList(Node* head) {
    Node* current = head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

