        printf("NULL\n");
        return 0;
    }

    // Меняем местами элементы (саму структуру узлов, а не только данные)
    reverseListNodes(&head);

    // Выводим результат
    printList(head);

    // Освобождаем память
    freeList(head);

    return 0;
}
