### ✅ کد C:

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// تابع کمکی برای گسترش از مرکز و یافتن طول بزرگترین زیررشتهٔ متقارن
int expandAroundCenter(char* s, int left, int right) {
    while (left >= 0 && right < strlen(s) && s[left] == s[right]) {
        left--;
        right++;
    }
    // طول زیررشتهٔ متناظر = right - left - 1
    return right - left - 1;
}

// تابع اصلی: یافتن طول بزرگترین زیررشتهٔ متقارن
int longestPalindromeLength(char* s) {
    int n = strlen(s);
    if (n == 0) return 0;

    int maxLen = 1; // حداقل یک کاراکتر متقارن است

    for (int i = 0; i < n; i++) {
        // برای مرکز فرد (مثل "aba")
        int len1 = expandAroundCenter(s, i, i);
        // برای مرکز زوج (مثل "abba")
        int len2 = expandAroundCenter(s, i, i + 1);

        // بزرگترین طول در این مرکز
        int currentMax = (len1 > len2) ? len1 : len2;
        if (currentMax > maxLen) {
            maxLen = currentMax;
        }
    }

    return maxLen;
}

int main() {
    char s[1001]; // بیشتر از 1000 کاراکتر نیست
    scanf("%s", s);

    int result = longestPalindromeLength(s);
    printf("%d\n", result);

    return 0;
}
```

