#include <netinet/in.h>
#include <time.h>
#include <signal.h>

#define PORT 2346
#define BROADCAST_ADDR "255.255.255.255"
#define BUFFER_SIZE 1024
#define MAX_SENDERS 100
#define CHECK_INTERVAL 30 // seconds

// Structure pour stocker les émetteurs
typedef struct {
    char ip[16];
    int port;
    time_t last_seen;
} Sender;

Sender senders[MAX_SENDERS];
int sender_count = 0;
volatile int should_exit = 0;

// Fonction pour ajouter un émetteur au tableau
void add_sender(const char *ip, int port) {
    for (int i = 0; i < sender_count; i++) {
        if (strcmp(senders[i].ip, ip) == 0 && senders[i].port == port) {
            senders[i].last_seen = time(NULL);
            return;
        }
    }

    if (sender_count < MAX_SENDERS) {
        strcpy(senders[sender_count].ip, ip);
        senders[sender_count].port = port;
        senders[sender_count].last_seen = time(NULL);
        sender_count++;
    }
}

