void print_senders() {
    printf("\n=== Liste des émetteurs reconnus (dernière vue à %s) ===\n", ctime(&time(NULL)));
    if (sender_count == 0) {
        printf("Aucun émetteur reçu.\n");
    } else {
        for (int i = 0; i < sender_count; i++) {
            printf("IP: %s, Port: %d (dernier message à %s)",
                   senders[i].ip, senders[i].port, ctime(&senders[i].last_seen));
