#include <stdio.h>

// Функция для нахождения НОК двух чисел
int NOK2(int A, int B) {
    // Сначала находим НОД с помощью алгоритма Евклида
    int temp;
    int a = A, b = B;
    while (b != 0) {
        temp = b;
        b = a % b;
        a = temp;
    }
    int nod = a; // НОД(A, B)

    // НОК = (A * B) / НОД(A, B)
    return (A * B) / nod;
}

int main() {
    int A, B, C, D;

    // Ввод чисел с клавиатуры
