## 四、客户端实现（UserClient.java）

### 4.1 GUI界面（`ClientUI.java`）

```java
import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.net.Socket;
import java.util.Date;

public class ClientUI extends JFrame implements ActionListener {
    private JTextField textField;
    private JTextArea messageArea;
    private JButton sendButton, sendFileButton, sendImageButton;
    private Socket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private Timer timer;
    private String username;
    private String chatHistoryFile;

    public ClientUI(String username) {
        this.username = username;
        chatHistoryFile = "chat_records/" + username + ".log";

        setTitle("用户聊天界面 - " + username);
        setSize(600, 500);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);
        setLayout(new BorderLayout());

        // 上部：聊天记录
        messageArea = new JTextArea(20, 50);
        messageArea.setEditable(false);
        JScrollPane scrollPane = new JScrollPane(messageArea);
        add(scrollPane, BorderLayout.CENTER);

        // 下部：输入
        JPanel bottomPanel = new JPanel(new FlowLayout());
        textField = new JTextField(25);
        sendButton = new JButton("发送");
        sendFileButton = new JButton("发送文件");
        sendImageButton = new JButton("发送图片");

        sendButton.addActionListener(this);
        sendFileButton.addActionListener(this);
        sendImageButton.addActionListener(this);
        textField.addActionListener(this);

        bottomPanel.add(textField);
        bottomPanel.add(sendButton);
        bottomPanel.add(sendFileButton);
        bottomPanel.add(sendImageButton);
        add(bottomPanel, BorderLayout.SOUTH);

        // 连接服务端
        connectToServer();

        // 加载历史记录
        loadChatHistory();

        // 设置超时提示定时器
        timer = new Timer(30000, e -> {
            if (socket != null && socket.isClosed()) {
                JOptionPane.showMessageDialog(this, "客服未响应，可能已离线。");
                timer.stop();
            }
        });
        timer.start();

        setVisible(true);
    }

    private void connectToServer() {
        try {
            socket = new Socket("localhost", 8888);
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());

            // 开启接收消息线程
            new Thread(this::receiveMessages).start();

            // 发送连接请求
            out.writeObject(new Message(username, "连接成功", Message.Type.SYSTEM));

        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "连接失败：" + e.getMessage());
            System.exit(1);
        }
    }

    private void receiveMessages() {
        try {
            while (!socket.isClosed()) {
                Message msg = (Message) in.readObject();
                SwingUtilities.invokeLater(() -> {
                    String text = String.format("[%s] %s: %s\n", 
                        msg.getTime(), msg.getSender(), msg.getContent());
                    messageArea.append(text);
                    if (msg.getType() == Message.Type.IMAGE && msg.getData() != null) {
                        ImageIcon icon = new ImageIcon(msg.getData());
                        JLabel label = new JLabel(icon);
                        JOptionPane.showMessageDialog(this, label, "收到图片", JOptionPane.INFORMATION_MESSAGE);
                    } else if (msg.getType() == Message.Type.FILE) {
                        saveFile(msg.getData(), msg.getFilename());
                    }
                });
            }
        } catch (Exception e) {
            if (!socket.isClosed()) {
                SwingUtilities.invokeLater(() -> 
                    JOptionPane.showMessageDialog(this, "与客服断开连接。"));
            }
        }
    }

    private void saveFile(byte[] data, String filename) {
        JFileChooser fc = new JFileChooser();
        fc.setSelectedFile(new java.io.File("downloads/" + filename));
        int result = fc.showSaveDialog(this);
        if (result == JFileChooser.APPROVE_OPTION) {
            java.io.File file = fc.getSelectedFile();
            try (java.io.FileOutputStream fos = new java.io.FileOutputStream(file)) {
                fos.write(data);
                messageArea.append("[系统] 文件已保存：" + file.getAbsolutePath() + "\n");
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    private void loadChatHistory() {
        java.io.File file = new java.io.File(chatHistoryFile);
        if (file.exists()) {
            try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
                String line;
                while ((line = br.readLine()) != null) {
                    messageArea.append(line + "\n");
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    private void saveChatRecord(String text) {
        java.io.File dir = new java.io.File("chat_records");
        if (!dir.exists()) dir.mkdirs();

        try (java.io.FileWriter fw = new java.io.FileWriter(chatHistoryFile, true)) {
            fw.write(text + "\n");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        String text = textField.getText().trim();
        if (text.isEmpty()) return;

        try {
            Message msg = new Message(username, text, Message.Type.TEXT);
            out.writeObject(msg);
            saveChatRecord("[本地] " + text);

            textField.setText("");

            // 触发定时器重置
            timer.restart();

        } catch (Exception ex) {
            JOptionPane.showMessageDialog(this, "发送失败：" + ex.getMessage());
        }

        if (e.getSource() == sendFileButton) {
            JFileChooser fc = new JFileChooser();
            int result = fc.showOpenDialog(this);
            if (result == JFileChooser.APPROVE_OPTION) {
                java.io.File file = fc.getSelectedFile();
                try (java.io.FileInputStream fis = new java.io.FileInputStream(file)) {
                    byte[] data = fis.readAllBytes();
                    Message fileMsg = new Message(username, data, file.getName(), Message.Type.FILE);
                    out.writeObject(fileMsg);
                    saveChatRecord("[本地] 发送文件：" + file.getName());
                } catch (Exception ex) {
                    ex.printStackTrace();
                }
            }
        } else if (e.getSource() == sendImageButton) {
            JFileChooser fc = new JFileChooser();
            fc.setFileSelectionMode(JFileChooser.FILES_ONLY);
            fc.setFileFilter(new javax.swing.filechooser.FileFilter() {
                @Override
                public boolean accept(java.io.File f) {
                    if (f.isDirectory()) return true;
                    return f.getName().toLowerCase().endsWith(".jpg") ||
                           f.getName().toLowerCase().endsWith(".png") ||
                           f.getName().toLowerCase().endsWith(".gif");
                }

                @Override
                public String getDescription() {
                    return "Image Files";
                }
            });
            int result = fc.showOpenDialog(this);
            if (result == JFileChooser.APPROVE_OPTION) {
                java.io.File file = fc.getSelectedFile();
                try (java.io.FileInputStream fis = new java.io.FileInputStream(file)) {
                    byte[] data = fis.readAllBytes();
                    Message imgMsg = new Message(username, data, file.getName(), Message.Type.IMAGE);
                    out.writeObject(imgMsg);
                    saveChatRecord("[本地] 发送图片：" + file.getName());
                } catch (Exception ex) {
                    ex.printStackTrace();
                }
            }
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new ClientUI("user123"));
    }
}
