## 五、客服端实现（Server.java）

### 5.1 `Server.java`

```java
import java.io.*;
import java.net.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class Server {
    private ServerSocket serverSocket;
    private ConcurrentHashMap<String, ObjectOutputStream> clientMap = new ConcurrentHashMap<>();
    private AtomicInteger clientCounter = new AtomicInteger(0);
    private Thread serverThread;

    public Server() {
        try {
            serverSocket = new ServerSocket(8888);
            System.out.println("客服端已启动，监听端口 8888");
            startAccepting();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void startAccepting() {
        serverThread = new Thread(() -> {
            while (!serverSocket.isClosed()) {
                try {
                    Socket clientSocket = serverSocket.accept();
                    new Thread(new ClientHandler(clientSocket)).start();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        });
        serverThread.start();
    }

    private class ClientHandler implements Runnable {
        private Socket socket;
        private ObjectInputStream in;
        private ObjectOutputStream out;
        private String username;

        public ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                out = new ObjectOutputStream(socket.getOutputStream());
                in = new ObjectInputStream(socket.getInputStream());

                Message msg = (Message) in.readObject();
                username = msg.getSender();
                System.out.println("用户[" + username + "]请求服务");

                // 弹出对话框询问是否接受
                int result = JOptionPane.showConfirmDialog(null,
                    "用户 " + username + " 请求服务，是否接受？",
                    "新服务请求", JOptionPane.YES_NO_OPTION);

                if (result == JOptionPane.YES_OPTION) {
                    out.writeObject(new Message("客服", "已接受服务，开始聊天", Message.Type.SYSTEM));
                    clientMap.put(username, out);

                    // 向用户发送确认
                    sendMessageToUser(username, new Message("客服", "欢迎！客服正在为您提供服务。", Message.Type.TEXT));
                    handleCommunication();
                } else {
                    out.writeObject(new Message("客服", "抱歉，当前无法服务您，稍后再试。", Message.Type.SYSTEM));
                    socket.close();
                    System.out.println("用户[" + username + "]服务请求被拒绝");
                }

            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                try {
                    socket.close();
                    clientMap.remove(username);
                    System.out.println("连接已关闭：用户 " + username);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        private void handleCommunication() {
            try {
                while (!socket.isClosed() && in != null) {
                    Message msg = (Message) in.readObject();
                    saveChatLog(msg);
                    broadcastMessage(msg);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        // 广播给用户
        private void broadcastMessage(Message msg) {
            if (msg.getType() == Message.Type.TEXT) {
                sendMessageToUser(username, msg);
            } else if (msg.getType() == Message.Type.IMAGE || msg.getType() == Message.Type.FILE) {
                sendMessageToUser(username, msg);
            }
        }

        private void sendMessageToUser(String user, Message msg) {
            ObjectOutputStream outStream = clientMap.get(user);
            if (outStream != null) {
                try {
                    outStream.writeObject(msg);
                    outStream.flush();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        private void saveChatLog(Message msg) {
            java.io.File dir = new java.io.File("chat_records");
            if (!dir.exists()) dir.mkdirs();
            String filename = "chat_records/" + username + "_server.log";
            try (PrintWriter pw = new PrintWriter(new FileWriter(filename, true))) {
                String log = String.format("[%s] %s: %s",
                    msg.getTime(), msg.getSender(), msg.getContent());
                pw.println(log);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        new Server();
    }
}
```

