## ✅ 示例代码：将 `byte[]` 图像数据编码为 H.264 视频

```java
import org.bytedeco.javacv.*;
import org.bytedeco.opencv.opencv_core.Mat;
import org.bytedeco.opencv.opencv_core.MatOfByte;
import org.bytedeco.opencv.opencv_imgcodecs;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;

public class ImageToH264Encoder {

    public static void main(String[] args) {
        String outputPath = "output_video.mp4"; // 输出文件路径
        int frameWidth = 640;
        int frameHeight = 480;
        int frameRate = 25;  // 每秒25帧

        // 1. 创建录制器，设置输出
        FFmpegFrameRecorder recorder = new FFmpegFrameRecorder(outputPath, frameWidth, frameHeight);
        recorder.setFormat("mp4"); // 输出格式为 mp4
        recorder.setVideoCodec(avcodec.AV_CODEC_ID_H264); // H.264 编码
        recorder.setFrameRate(frameRate);
        recorder.setVideoQuality(20); // 20~30之间，值越小质量越高（可选）
        recorder.setGopSize(25); // 关键帧间隔，建议 frameRate 的 1~2 倍

        try {
            recorder.start(); // 启动录制

            // 2. 模拟一组二进制图像数据（例如从文件或网络获取）
            // 这里用一个简单的例子，你可以替换为你的 byte[] 数据
            byte[] imageData1 = loadImageData("image1.jpg");
            byte[] imageData2 = loadImageData("image2.jpg");
            byte[] imageData3 = loadImageData("image3.jpg");

            // 3. 将每个 byte[] 转换为 BufferedImage，再转为 Frame
            BufferedImage image1 = toBufferedImage(imageData1);
            BufferedImage image2 = toBufferedImage(imageData2);
            BufferedImage image3 = toBufferedImage(imageData3);

            // 4. 将 BufferedImage 转为 Frame 并写入编码器
            Frame frame;
            frame = new Frame();
            // 使用 opencv 转换 BufferedImage -> Mat -> Frame
            Mat mat = new Mat();
            mat = opencv_imgcodecs.imdecode(new MatOfByte(imageData1), opencv_imgcodecs.IMREAD_COLOR);
            frame = new Frame(mat);

            recorder.record(frame); // 第一帧
            System.out.println("Recorded frame 1");

            mat = opencv_imgcodecs.imdecode(new MatOfByte(imageData2), opencv_imgcodecs.IMREAD_COLOR);
            frame = new Frame(mat);
            recorder.record(frame); // 第二帧
            System.out.println("Recorded frame 2");

            mat = opencv_imgcodecs.imdecode(new MatOfByte(imageData3), opencv_imgcodecs.IMREAD_COLOR);
            frame = new Frame(mat);
            recorder.record(frame); // 第三帧
            System.out.println("Recorded frame 3");

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            if (recorder != null) {
                try {
                    recorder.stop();
                    recorder.release();
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
    }

    // 从文件加载图像字节数据
    public static byte[] loadImageData(String imagePath) {
        try (var is = new java.io.FileInputStream(imagePath)) {
            return is.readAllBytes();
        } catch (IOException e) {
            e.printStackTrace();
            return new byte[0];
        }
    }

    // 将 byte[] 图像数据转换为 BufferedImage
    public static BufferedImage toBufferedImage(byte[] imageData) {
        try (var bais = new ByteArrayInputStream(imageData)) {
            return ImageIO.read(bais);
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }
}
```

