@RestController
@RequestMapping("/api/auth")
@CrossOrigin(origins = "*")
public class AuthController {

    @Autowired
    private AuthenticationManager authenticationManager;

    @Autowired
    private UserDetailsService userDetailsService;

    @Autowired
    private JwtUtil jwtUtil;

    @Autowired
    private UserService userService; // 自定义 Service

    @PostMapping("/register")
    public ResponseEntity<?> registerUser(@RequestBody RegisterRequest request) {
        if (request.getRole() == null) {
            return ResponseEntity.badRequest().body("Role is required");
        }

        if (userService.findByUsername(request.getUsername()).isPresent()) {
            return ResponseEntity.badRequest().body("Username already taken");
        }

        User newUser = new User(
                request.getUsername(),
                passwordEncoder().encode(request.getPassword()),
                Role.valueOf(request.getRole().toUpperCase())
        );

        userService.save(newUser);

        String token = jwtUtil.generateJwtToken(new org.springframework.security.core.userdetails.User(
                newUser.getUsername(),
                newUser.getPassword(),
                Collections.singleton(new SimpleGrantedAuthority("ROLE_" + newUser.getRole()))
        ));

        return ResponseEntity.ok(new JwtResponse(token, newUser.getUsername(), newUser.getRole().name()));
    }

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request) {
        try {
            Authentication authentication = authenticationManager.authenticate(
                new UsernamePasswordAuthenticationToken(request.getUsername(), request.getPassword())
            );
            SecurityContextHolder.getContext().setAuthentication(authentication);
            String jwt = jwtUtil.generateJwtToken(authentication);

            UserDetails userDetails = userDetailsService.loadUserByUsername(request.getUsername());
            Role role = Role.valueOf(userDetails.getAuthorities().stream()
                    .findFirst().get().getAuthority().substring(5));

            return ResponseEntity.ok(new JwtResponse(jwt, request.getUsername(), role.name()));
        } catch (BadCredentialsException e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid credentials");
        }
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
