public class CustomerServiceServer {
    private ServerSocket serverSocket;
    private ExecutorService executorService; // 线程池服务多个用户
    private Map<String, ClientHandler> activeSessions; // key: userId, value: 客服处理线程

    public CustomerServiceServer(int port) throws IOException {
        serverSocket = new ServerSocket(port);
        executorService = Executors.newCachedThreadPool();
        activeSessions = new ConcurrentHashMap<>();
        System.out.println("客服端启动，监听端口: " + port);
    }

    public void start() {
        while (true) {
            try {
                Socket clientSocket = serverSocket.accept();
                String userId = generateUserId();
                System.out.println("新用户连接: " + userId);

                ClientHandler handler = new ClientHandler(clientSocket, userId);
                activeSessions.put(userId, handler);
                executorService.execute(handler); // 多线程处理每个用户
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private String generateUserId() {
        return "user_" + System.currentTimeMillis();
    }

    // 服务拒绝/接受逻辑（可选）
    public void rejectConnection(String userId) {
        ClientHandler handler = activeSessions.remove(userId);
        if (handler != null) {
            handler.sendMsgToClient("系统提示：客服暂时无法响应，请稍后再试。");
            handler.close();
        }
    }

    public void acceptConnection(String userId) {
        ClientHandler handler = activeSessions.get(userId);
        if (handler != null) {
            handler.sendMsgToClient("已连接客服，开始服务...");
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(5, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
        try {
            serverSocket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        try {
            new CustomerServiceServer(8888).start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

