        });

        fileBtn.addActionListener(e -> {
            JFileChooser fc = new JFileChooser();
            if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
                File file = fc.getSelectedFile();
                sendFile(file);
            }
        });

        imgBtn.addActionListener(e -> {
            JFileChooser fc = new JFileChooser();
            fc.setFileFilter(new FileNameExtensionFilter("Image Files", "jpg", "png", "gif"));
            if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
                File file = fc.getSelectedFile();
                sendImage(file);
            }
        });
    }

    private void connectToServer() {
        try {
            socket = new Socket(serverIp, port);
            out = new PrintWriter(socket.getOutputStream(), true);
            in = new BufferedReader(new InputStreamReader(socket.getInputStream()));

            userId = in.readLine();
            chatArea.append("已连接客服端，用户ID: " + userId + "\n");
            startReceiveThread(); // 启动接收消息线程
            connectBtn.setEnabled(false);
            inputField.setEnabled(true);

            // 加载历史记录
            loadHistory(userId);

        } catch (IOException e) {
            chatArea.append("连接失败: " + e.getMessage() + "\n");
        }
    }

    private void startReceiveThread() {
        new Thread(() -> {
            try {
                String msg;
                while ((msg = in.readLine()) != null) {
                    if (msg.startsWith("TEXT:")) {
                        String content = msg.substring(5);
                        SwingUtilities.invokeLater(() -> chatArea.append("客服: " + content + "\n"));
                        saveToHistory("客服: " + content);
                    } else if (msg.startsWith("FILE:")) {
                        String fileName = msg.substring(5);
                        receiveFile(fileName);
                    } else if (msg.startsWith("IMG:")) {
                        receiveImage(msg.substring(4));
                    } else {
                        // 服务忙提示
                        if (msg.contains("忙") || msg.contains("无法响应")) {
                            chatArea.append("服务提示: " + msg + "\n");
                            connectBtn.setEnabled(true);
                            inputField.setEnabled(false);
                        }
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }).start();
    }

    private void sendMsg(String msg) {
        out.println("TEXT:" + msg);
        saveToHistory("我: " + msg);
    }

    private void sendFile(File file) {
        out.println("FILE:" + file.getName());
        try (FileInputStream fis = new FileInputStream(file);
             DataOutputStream dos = new DataOutputStream(socket.getOutputStream())) {
            dos.writeLong(file.length());
            byte[] buffer = new byte[8192];
            int len;
            while ((len = fis.read(buffer)) != -1) {
                dos.write(buffer, 0, len);
            }
            dos.flush();
        } catch (IOException e) {
            chatArea.append("发送失败: " + e.getMessage() + "\n");
        }
    }

    private void sendImage(File imageFile) {
        sendFile(imageFile);
    }

    private void receiveFile(String fileName) {
        JFileChooser fc = new JFileChooser();
        fc.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);
        if (fc.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
            File savePath = fc.getSelectedFile();
            File outputFile = new File(savePath, fileName);

            try (FileOutputStream fos = new FileOutputStream(outputFile);
                 DataInputStream dis = new DataInputStream(socket.getInputStream())) {

                long size = dis.readLong();
                byte[] buffer = new byte[8192];
                long total = 0;
                int len;
                while (total < size && (len = dis.read(buffer)) != -1) {
                    fos.write(buffer, 0, len);
                    total += len;
                }
                chatArea.append("已保存文件: " + outputFile.getAbsolutePath() + "\n");
            } catch (IOException e) {
                chatArea.append("接收失败: " + e.getMessage() + "\n");
            }
        }
    }

    private void receiveImage(String imgName) {
        JFileChooser fc = new JFileChooser();
        fc.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);
        if (fc.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
            File savePath = fc.getSelectedFile();
            File outputFile = new File(savePath, imgName);

            try (FileOutputStream fos = new FileOutputStream(outputFile);
                 DataInputStream dis = new DataInputStream(socket.getInputStream())) {

                long size = dis.readLong();
                byte[] buffer = new byte[8192];
                long total = 0;
                int len;
                while (total < size && (len = dis.read(buffer)) != -1) {
                    fos.write(buffer, 0, len);
                    total += len;
                }
                chatArea.append("已保存图片: " + outputFile.getAbsolutePath() + "\n");
                // 可弹出预览
            } catch (IOException e) {
                chatArea.append("接收图片失败: " + e.getMessage() + "\n");
            }
        }
    }

    private void loadHistory(String userId) {
        try (BufferedReader br = new BufferedReader(new FileReader("records/" + userId + ".txt"))) {
            String line;
            while ((line = br.readLine()) != null) {
                SwingUtilities.invokeLater(() -> chatArea.append(line + "\n"));
            }
        } catch (IOException e) {
            // 文件不存在，忽略
            chatArea.append("无历史记录\n");
        }
    }

    private void saveToHistory(String msg) {
        try (PrintWriter pw = new PrintWriter(new FileWriter("records/" + userId + ".txt", true))) {
            pw.println(LocalDateTime.now() + " " + msg);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            new UserClient();
        });
    }
}
