## 🔐 2. JWT Utility Service

```java
// JwtUtil.java
@Service
@RequiredArgsConstructor
public class JwtUtil {

    private final RedisTemplate<String, Object> redisTemplate;
    private final String jwtSecret = "your-very-secure-secret-key-here-32-characters-long";
    private final int jwtExpirationMs = 86400000; // 24 hours

    public String generateToken(User user) {
        String sessionId = UUID.randomUUID().toString();

        // Create JWT with session ID and user info
        String jwt = Jwts.builder()
                .setSubject(user.getUsername())
                .setIssuedAt(new Date())
                .setExpiration(new Date(System.currentTimeMillis() + jwtExpirationMs))
                .claim("sessionId", sessionId)
                .claim("username", user.getUsername())
                .signWith(SignatureAlgorithm.HS512, jwtSecret)
                .compact();

        // Store session in Redis
        SessionToken sessionToken = SessionToken.builder()
                .sessionId(sessionId)
                .username(user.getUsername())
                .createdAt(System.currentTimeMillis())
                .active(true)
                .build();

        redisTemplate.opsForValue().set("session:" + sessionId, sessionToken, Duration.ofDays(1));
        return jwt;
    }

    public boolean validateToken(String token, UserDetails userDetails) {
        String username = extractUsername(token);
        String sessionId = extractSessionId(token);

        // Check if token is valid and exists in Redis
        if (username == null || !username.equals(userDetails.getUsername())) {
            return false;
        }

        SessionToken session = (SessionToken) redisTemplate.opsForValue().get("session:" + sessionId);
        return session != null && session.getActive() && session.getUsername().equals(username);
    }

    public String extractUsername(String token) {
        return Jwts.parser()
                .setSigningKey(jwtSecret)
                .parseClaimsJws(token)
                .getBody()
                .getSubject();
    }

    public String extractSessionId(String token) {
        return Jwts.parser()
                .setSigningKey(jwtSecret)
                .parseClaimsJws(token)
                .getBody()
                .get("sessionId", String.class);
    }

    public void invalidateToken(String token) {
        String sessionId = extractSessionId(token);
        SessionToken session = (SessionToken) redisTemplate.opsForValue().get("session:" + sessionId);
        if (session != null) {
            session.setActive(false);
            redisTemplate.opsForValue().set("session:" + sessionId, session, Duration.ofDays(1));
        }
    }

    public void invalidateAllSessionsForUser(String username) {
        // You could use Redis scan to find all sessions for this user
        // For simplicity: we assume session keys follow "session:{sessionId}"
        // A real app should use a set to track user sessions.
        redisTemplate.keys("session:*")
                .forEach(key -> {
                    SessionToken session = (SessionToken) redisTemplate.opsForValue().get(key);
                    if (session != null && session.getUsername().equals(username)) {
                        session.setActive(false);
                        redisTemplate.opsForValue().set(key, session, Duration.ofDays(1));
                    }
                });
    }

    public boolean isTokenActive(String token) {
        String sessionId = extractSessionId(token);
        SessionToken session = (SessionToken) redisTemplate.opsForValue().get("session:" + sessionId);
        return session != null && session.getActive();
    }
}
```

