import java.io.Serializable;
import java.util.Date;

public class Message implements Serializable {
    private static final long serialVersionUID = 1L;

    public enum Type {
        TEXT, IMAGE, FILE, CONNECT_REQUEST, CONNECT_ACCEPT, CONNECT_REJECT,
        CHAT_HISTORY_REQUEST, CHAT_HISTORY_RESPONSE, HEARTBEAT
    }

    private Type type;
