    private String user; // 用户标识（用于保存聊天记录）

    public Message(Type type, String sender, String content, byte[] data, String user) {
        this.type = type;
        this.sender = sender;
        this.content = content;
        this.data = data;
        this.timestamp = new Date();
        this.user = user;
    }

    // Getters and Setters
