public class Client extends JFrame {
    private Socket socket;
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private String username;
    private String serverIp = "127.0.0.1";
    private int serverPort = 8888;
    private boolean connected = false;
    private Timer connectTimer; // 用于超时监控

    private JTextArea chatArea;
    private JTextField messageField;
    private JButton sendBtn, fileBtn, imgBtn;
    private String chatLogPath;

    public Client(String username) {
        this.username = username;
        chatLogPath = "chat_logs/" + username + ".log";

        setTitle("用户客服 - " + username);
        setSize(600, 500);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        setupUI();
        connectToServer();
    }

    private void setupUI() {
        setLayout(new BorderLayout());

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        chatArea.setFont(new Font("宋体", Font.PLAIN, 14));
        JScrollPane scrollPane = new JScrollPane(chatArea);
        add(scrollPane, BorderLayout.CENTER);

        JPanel bottomPanel = new JPanel(new FlowLayout());
        messageField = new JTextField(20);
        sendBtn = new JButton("发送");
        fileBtn = new JButton("发文件");
        imgBtn = new JButton("发图片");

        bottomPanel.add(messageField);
        bottomPanel.add(sendBtn);
        bottomPanel.add(fileBtn);
        bottomPanel.add(imgBtn);

        add(bottomPanel, BorderLayout.SOUTH);

        sendBtn.addActionListener(e -> sendMessage());
        fileBtn.addActionListener(e -> sendFile());
        imgBtn.addActionListener(e -> sendImage());
    }

    private void connectToServer() {
        try {
            socket = new Socket(serverIp, serverPort);
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());

            // 发送连接请求
            Message request = new Message(Message.Type.CONNECT_REQUEST, username, "连接请求", null, username);
            out.writeObject(request);

            // 开始轮询响应，10秒超时
            connectTimer = new Timer(10000, e -> {
                if (!connected) {
                    JOptionPane.showMessageDialog(this, "客服忙，请稍后再试");
                    System.exit(0);
                }
            });
            connectTimer.setRepeats(false);
            connectTimer.start();

            // 接收来自服务端响应
            new Thread(() -> {
                try {
                    while (true) {
                        Message msg = (Message) in.readObject();
                        handleMessage(msg);
                    }
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }).start();

        } catch (Exception e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(this, "无法连接服务器，请检查服务端是否运行");
            System.exit(1);
        }
