            if (msg.getType() == Message.Type.CONNECT_ACCEPT) {
                connected = true;
                connectTimer.stop();
                chatArea.append("✓ 客服已接入，可以开始聊天。\n");
                loadChatHistory(); // 加载历史记录
            } else if (msg.getType() == Message.Type.CONNECT_REJECT) {
                JOptionPane.showMessageDialog(this, "客服拒绝服务，请稍后重试");
