import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class AgentServer {
    private static final int PORT = 8888;
    private static final ExecutorService threadPool = Executors.newFixedThreadPool(10);
    private static final Map<String, Socket> userSockets = new ConcurrentHashMap<>();
    private static final Map<String, ObjectInputStream> userInputs = new ConcurrentHashMap<>();
    private static final Map<String, ObjectOutputStream> userOutputs = new ConcurrentHashMap<>();
    private static final Set<String> busyUsers = new HashSet<>();
    private static final String LOG_DIR = "chat_logs";

    public static void main(String[] args) {
        new File(LOG_DIR).mkdirs();

        ServerSocket serverSocket = null;
        try {
            serverSocket = new ServerSocket(PORT);
            System.out.println("客服系统启动，监听端口 " + PORT);

            while (true) {
                Socket socket = serverSocket.accept();
                System.out.println("新用户接入: " + socket.getInetAddress());

                // 开启新线程处理这个用户
                threadPool.execute(new UserHandler(socket));
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            threadPool.shutdown();
            if (serverSocket != null) {
                try {
                    serverSocket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    static class UserHandler implements Runnable {
        private Socket socket;
        private String username;
        private ObjectInputStream in;
        private ObjectOutputStream out;

        public UserHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                in = new ObjectInputStream(socket.getInputStream());
                out = new ObjectOutputStream(socket.getOutputStream());

                Message msg = (Message) in.readObject();
                if (msg.getType() == Message.Type.CONNECT_REQUEST) {
                    username = msg.getSender();
                    System.out.println("用户 " + username + " 请求服务");

                    // 显示提示
