                    int choice = JOptionPane.showOptionDialog(null,
                            "用户 " + username + " 请求服务，是否接受？",
                            "服务请求",
                            JOptionPane.YES_NO_OPTION,
                            JOptionPane.QUESTION_MESSAGE,
                            null, options, options[0]);

                    Message response = choice == JOptionPane.YES_OPTION ?
                            new Message(Message.Type.CONNECT_ACCEPT, "客服", "连接已接受", null, username) :
                            new Message(Message.Type.CONNECT_REJECT, "客服", "拒绝服务", null, username);

                    out.writeObject(response);
                    if (choice == JOptionPane.YES_OPTION) {
                        busyUsers.add(username);
                        userSockets.put(username, socket);
                        userInputs.put(username, in);
                        userOutputs.put(username, out);
                        System.out.println("已接受用户 " + username + " 的服务请求");
                    } else {
                        System.out.println("已拒绝用户 " + username + " 的服务请求");
                    }

                    // 启动聊天线程（持续服务）
                    if (choice == JOptionPane.YES_OPTION) {
                        handleChat(username);
                    }

                }

            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                closeConnection(username);
            }
        }

        private void handleChat(String user) {
            try {
                while (true) {
                    Message msg = (Message) in.readObject();
                    if (msg.getType() == Message.Type.TEXT || msg.getType() == Message.Type.IMAGE || msg.getType() == Message.Type.FILE) {
                        // 保存聊天记录
                        saveChatLog(user, msg);

                        // 回传给用户
                        out.writeObject(msg);
                    } else if (msg.getType() == Message.Type.HEARTBEAT) {
                        // 心跳，保持连接
                    }
                }
            } catch (Exception e) {
                System.out.println("用户 " + user + " 断开连接");
            } finally {
                closeConnection(user);
            }
        }

        private void saveChatLog(String user, Message msg) {
            File logFile = new File(LOG_DIR, user + ".log");
            try (FileWriter fw = new FileWriter(logFile, true)) {
                String timeStr = java.time.LocalDateTime.now().format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
                fw.write(timeStr + " | " + msg.getSender() + " | " + msg.getContent() + "\n");
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void closeConnection(String user) {
            System.out.println("关闭连接: " + user);

            synchronized (userSockets) {
                if (userSockets.containsKey(user)) {
                    try {
                        userOutputs.get(user).close();
                        userInputs.get(user).close();
                        userSockets.get(user).close();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                    userSockets.remove(user);
                    userInputs.remove(user);
                    userOutputs.remove(user);
                    busyUsers.remove(user);
                }
            }
        }
    }
}
```

