## 6️⃣ `service/TradeOpportunityFinder.java` – Trouve les meilleurs trades

```java
@Service
public class TradeOpportunityFinder {

    public List<TradeOpportunity> findBestTradeOpportunities(List<Skin> skins) {
        return skins.stream()
                .map(this::findBestOpportunityForSkin)
                .filter(Objects::nonNull)
                .collect(Collectors.toList());
    }

    private TradeOpportunity findBestOpportunityForSkin(Skin skin) {
        // On veut trouver : acheter à min, vendre à max
        Map<String, MarketPrice> prices = skin.getPrices();

        if (prices.size() < 2) return null;

        BigDecimal minPrice = prices.values().stream()
                .map(MarketPrice::getPrice)
                .min(BigDecimal::compareTo)
                .orElse(BigDecimal.ZERO);

        BigDecimal maxPrice = prices.values().stream()
                .map(MarketPrice::getPrice)
                .max(BigDecimal::compareTo)
                .orElse(BigDecimal.ZERO);

        if (maxPrice.compareTo(minPrice) <= 0) return null; // pas de profit

        BigDecimal profit = maxPrice.subtract(minPrice);
        BigDecimal profitPercent = profit.divide(minPrice, 4, RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100));

        // Trouver les marchands
        String buyFrom = null, sellTo = null;
        for (Map.Entry<String, MarketPrice> entry : prices.entrySet()) {
            if (entry.getValue().getPrice().equals(minPrice)) buyFrom = entry.getKey();
            if (entry.getValue().getPrice().equals(maxPrice)) sellTo = entry.getKey();
        }

        return new TradeOpportunity(skin.getName(), buyFrom, sellTo, minPrice, maxPrice, profit, profitPercent);
    }
}
```

