@Component
public class JsonUtils {

    private final ObjectMapper objectMapper = new ObjectMapper();

    public List<Skin> parseJsonFile(String filePath) throws IOException {
        Map<String, Object> map = objectMapper.readValue(new File(filePath), Map.class);

        return map.entrySet().stream().map(entry -> {
            String skinName = entry.getKey();
            Object data = entry.getValue();

            Skin skin = new Skin(skinName);
            if (data instanceof Map) {
                Map<String, Object> dataMap = (Map<String, Object>) data;
                dataMap.forEach((merchant, priceObj) -> {
                    if (priceObj instanceof Map) {
                        Map<String, Object> priceData = (Map<String, Object>) priceObj;
                        Object priceValue = priceData.get("price");
                        if (priceValue instanceof Number) {
                            BigDecimal price = new BigDecimal(priceValue.toString());
                            skin.addPrice(merchant, new MarketPrice(merchant, price));
                        }
                    } else if (priceObj instanceof String && !priceObj.equals("null")) {
                        BigDecimal price = new BigDecimal((String) priceObj);
                        skin.addPrice(merchant, new MarketPrice(merchant, price));
                    }
                });
            }
            return skin;
        }).collect(Collectors.toList());
    }
}
```

