```java
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.w3c.dom.Node;
import org.w3c.dom.Element;
import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class JiraXmlParser {

    public static void main(String[] args) {
        // Path to your Jira export XML file
        String filePath = "jira-export.xml";

        try {
            File file = new File(filePath);
            DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
            Document doc = dBuilder.parse(file);
            doc.getDocumentElement().normalize();

            // Extract all issues
            List<JiraIssue> issues = parseIssues(doc);
            displayIssues(issues);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static List<JiraIssue> parseIssues(Document doc) {
        List<JiraIssue> issues = new ArrayList<>();
        NodeList nodeList = doc.getElementsByTagName("Issue");

        for (int i = 0; i < nodeList.getLength(); i++) {
            Node node = nodeList.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) node;

                JiraIssue issue = new JiraIssue(
                    getTextValue(element, "Key"),
                    getTextValue(element, "Summary"),
                    getTextValue(element, "Status"),
                    getTextValue(element, "Created"),
                    getTextValue(element, "Updated"),
                    getTextValue(element, "Description"),
                    getTextValue(element, "Reporter"),
                    getTextValue(element, "Assignee")
                );
                issues.add(issue);
            }
        }
        return issues;
    }

    private static String getTextValue(Element element, String tag) {
        NodeList nodeList = element.getElementsByTagName(tag);
        if (nodeList.getLength() > 0) {
            return nodeList.item(0).getTextContent().trim();
        }
        return "";
    }

    private static void displayIssues(List<JiraIssue> issues) {
        System.out.println("Found " + issues.size() + " issues:");
        System.out.println("-".repeat(100));
        for (JiraIssue issue : issues) {
            System.out.println("Key: " + issue.getKey());
            System.out.println("Summary: " + issue.getSummary());
            System.out.println("Status: " + issue.getStatus());
            System.out.println("Created: " + issue.getCreated());
            System.out.println("Updated: " + issue.getUpdated());
            System.out.println("Description: " + issue.getDescription());
            System.out.println("Reporter: " + issue.getReporter());
            System.out.println("Assignee: " + issue.getAssignee());
            System.out.println("-".repeat(100));
        }
    }
}

// Simple POJO to represent a Jira Issue
class JiraIssue {
    private String key;
    private String summary;
    private String status;
    private String created;
    private String updated;
    private String description;
    private String reporter;
    private String assignee;

    public JiraIssue(String key, String summary, String status, String created,
                     String updated, String description, String reporter, String assignee) {
