## ✅ 正确实现：`FFmpegFrameRecorder` 输出到 `Socket`

我们利用 `FFmpegFrameRecorder` 支持的 `setOutput(OutputStream)` 特性：

### ✅ 完整正确代码（发送端）

```java
import org.bytedeco.javacv.*;
import org.bytedeco.javacv.Frame;

import java.io.DataOutputStream;
import java.io.IOException;
import java.net.InetAddress;
import java.net.Socket;

public class VideoSocketSender {

    private static final String HOST = "127.0.0.1";
    private static final int PORT = 8080;

    public static void main(String[] args) {
        FFmpegFrameGrabber grabber = new FFmpegFrameGrabber("0");
        FFmpegFrameRecorder recorder = new FFmpegFrameRecorder(new File("dummy"), 640, 480);

        try {
            grabber.start();

            // 设置输出为 Socket 输出流
            Socket socket = new Socket(InetAddress.getByName(HOST), PORT);
            DataOutputStream dos = new DataOutputStream(socket.getOutputStream());
            recorder.setOutput(dos);  // ✅ 设置输出流

            // 设置编码参数
            recorder.setFormat("mpeg4");
            recorder.setVideoCodec(avcodec.AV_CODEC_ID_H264);
            recorder.setVideoBitrate(1000000);
            recorder.setFrameRate(30);
            recorder.setVideoOption("crf", "23");
            recorder.setVideoOption("preset", "superfast");

            // 一定要在 start() 前设置输出流
            recorder.start();

            System.out.println("开始通过 Socket 推送视频... (按 Ctrl+C 停止)");

            Frame frame;
            while ((frame = grabber.grab()) != null) {
                recorder.record(frame);
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                if (grabber != null) grabber.stop();
                if (recorder != null) recorder.stop();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
