## ✅ 接收端代码（接收并播放）

接收端使用 `FFmpegFrameGrabber` 从 `Socket` 读取 H.264 数据并播放。

```java
import org.bytedeco.javacv.*;
import org.bytedeco.javacv.Frame;
import org.bytedeco.javacv.FrameGrabber.Exception;

import java.io.DataInputStream;
import java.net.ServerSocket;
import java.net.Socket;

public class VideoSocketReceiver {

    public static void main(String[] args) {
        try {
            ServerSocket serverSocket = new ServerSocket(8080);
            System.out.println("等待连接...");

            Socket socket = serverSocket.accept();
            DataInputStream dis = new DataInputStream(socket.getInputStream());

            FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(dis);  // ✅ 直接从 InputStream 读取
            grabber.setOption("format", "h264");
            grabber.setOption("codec", "h264");

            // 可选：设置解码器
            grabber.setImageWidth(640);
            grabber.setImageHeight(480);

            grabber.start();

            OpenCVFrameConverter.ToMat convert = new OpenCVFrameConverter.ToMat();

            CanvasFrame canvas = new CanvasFrame("接收端视频");

            Frame frame;
            while ((frame = grabber.grab()) != null) {
                canvas.showImage(convert.convert(frame));
                if (canvas.isDisposed()) break;
            }

            canvas.dispose();
            grabber.stop();
            serverSocket.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

