// Message.java
import java.io.Serializable;
import java.util.Date;

public class Message implements Serializable {
    private static final long serialVersionUID = 1L;

    private String sender; // "User" or "Agent"
    private String content; // 纯文本或文件路径
    private MessageType type; // TEXT, IMAGE, FILE
    private Date timestamp;

    public enum MessageType {
        TEXT, IMAGE, FILE, CONNECT, DISCONNECT, BUSY
    }

    // 构造函数
    public Message(String sender, String content, MessageType type) {
        this.sender = sender;
        this.content = content;
        this.type = type;
        this.timestamp = new Date();
    }

    // Getters and Setters
    public String getSender() { return sender; }
    public String getContent() { return content; }
    public MessageType getType() { return type; }
    public Date getTimestamp() { return timestamp; }

    @Override
    public String toString() {
        return String.format("[%s] %s (%s): %s", 
                timestamp.toString(), sender, type, content);
    }
}
```

