// FileManager.java
import java.io.*;
import java.nio.file.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

public class FileManager {

    private static final String BASE_DIR = "data/chat_history";
    private static final DateTimeFormatter FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd-HH-mm-ss");

    public static void saveChatHistory(List<Message> messages, String userId) {
        Path dirPath = Paths.get(BASE_DIR);
        if (!Files.exists(dirPath)) {
            try {
                Files.createDirectories(dirPath);
            } catch (IOException e) {
                System.err.println("无法创建聊天记录目录: " + e.getMessage());
            }
        }

        String filename = userId + "_" + LocalDateTime.now().format(FORMATTER) + ".ser";
        Path filePath = dirPath.resolve(filename);

        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filePath.toFile()))) {
            oos.writeObject(messages);
            System.out.println("聊天记录已保存至: " + filePath);
        } catch (IOException e) {
            System.err.println("保存失败：" + e.getMessage());
        }
    }

    public static List<Message> loadChatHistory(String userId) {
        List<Message> history = new ArrayList<>();
        Path dirPath = Paths.get(BASE_DIR);
        if (!Files.exists(dirPath)) return history;

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dirPath)) {
            for (Path file : stream) {
                if (file.toString().contains(userId) && file.toString().endsWith(".ser")) {
                    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file.toFile()))) {
                        List<Message> messages = (List<Message>) ois.readObject();
                        history.addAll(messages);
                    } catch (Exception e) {
                        System.err.println("读取聊天记录失败：" + e.getMessage());
                    }
                    break; // 只取最新一条（更合理）
                }
            }
        } catch (IOException e) {
            System.err.println("遍历目录失败：" + e.getMessage());
        }

        return history;
    }
}
```

