                ext.endsWith(".png") || ext.endsWith(".gif");
    }

    private String toJSON(Message msg) {
        return "{ \"sender\":\"" + msg.getSender() +
               "\", \"content\":\"" + msg.getContent() +
               "\", \"type\":\"" + msg.getType() +
               "\", \"time\":\"" + msg.getTimestamp() + "\" }";
    }

    private void receiveMessages() {
        try {
            while (connected && socket != null && !socket.isClosed()) {
                String line = in.readLine();
                if (line == null) break;

                Message msg = parseJSON(line);
                if (msg != null) {
                    appendToChat(msg);
                    if (msg.getType() == Message.MessageType.BUSY) {
                        showMessage("【系统】客服正在服务其他用户，请稍候...");
                    }
                }
            }
        } catch (Exception e) {
            if (connected) showNetworkError();
        } finally {
            disconnect();
        }
    }

    private Message parseJSON(String json) {
        try {
            // 简化的解析（生产环境建议用 Gson/JSON-lib）
            // 这里只做简单拆分
            String[] parts = json.split("\\{");
            if (parts.length < 2) return null;
            String data = "{" + parts[1];
            data = data.replaceAll("\"", "");

            String sender = extractValue(data, "sender");
            String content = extractValue(data, "content");
            String typeStr = extractValue(data, "type");
            Message.MessageType type = Message.MessageType.valueOf(typeStr);

            return new Message(sender, content, type);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    private String extractValue(String str, String key) {
        int start = str.indexOf(key + "=") + key.length() + 1;
        int end = str.indexOf(", ", start);
        if (end == -1) end = str.length();
        return str.substring(start, end).trim();
    }

    private void appendToChat(Message msg) {
        SwingUtilities.invokeLater(() -> {
            chatArea.append(msg.toString() + "\n");
            chatArea.setCaretPosition(chatArea.getDocument().getLength());
        });
    }

    private void showMessage(String text) {
        SwingUtilities.invokeLater(() -> {
            chatArea.append("[SYSTEM] " + text + "\n");
            chatArea.setCaretPosition(chatArea.getDocument().getLength());
        });
    }

    private void showNetworkError() {
        SwingUtilities.invokeLater(() -> {
            chatArea.append("【系统】网络连接断开。请重新连接。\n");
        });
    }

    private void loadPreviousChat() {
        List<Message> history = FileManager.loadChatHistory(userId);
        if (!history.isEmpty()) {
            showMessage("加载历史聊天记录（共 " + history.size() + " 条）");
            for (Message m : history) {
                appendToChat(m);
            }
        }
    }

    @Override
    public void run() {
        receiveMessages();
    }

    public void disconnect() {
        connected = false;
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (socket != null) socket.close();
        } catch (IOException e) {}
    }

    public boolean isConnected() {
        return connected;
    }
}
