    private Socket clientSocket;
    private BufferedReader in;
    private PrintWriter out;
    private String userId;

    public ChatServer(Socket clientSocket, String userId) {
        this.clientSocket = clientSocket;
        this.userId = userId;
        start();
    }

    @Override
    public void run() {
        try {
            in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
            out = new PrintWriter(clientSocket.getOutputStream(), true);

            out.println("{\"status\":\"connected\", \"message\":\"欢迎!\"}");

            // 保存对话记录
            List<Message> records = FileManager.loadChatHistory(userId);
            for (Message msg : records) {
                sendMsgToClient(msg);
            }

            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                Message msg = parseJSON(inputLine);
                if (msg != null) {
                    System.out.println("从 " + userId + " 收到消息: " + msg);
                    handleIncomingMessage(msg);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            terminate();
        }
    }

    private void handleIncomingMessage(Message msg) {
        switch (msg.getType()) {
            case TEXT:
                broadcastToClient(new Message("Agent", "收到消息：" + msg.getContent(), Message.MessageType.TEXT));
                break;
            case IMAGE:
                broadcastToClient(new Message("Agent", "收到图片文件: " + msg.getContent(), Message.MessageType.IMAGE));
                break;
            case FILE:
                broadcastToClient(new Message("Agent", "收到文件: " + msg.getContent(), Message.MessageType.FILE));
                break;
            default:
                break;
        }
    }

    // 将消息通过 socket 发送给客户端
    private void sendMsgToClient(Message msg) {
        try {
            out.println(toJSON(msg));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private Message parseJSON(String json) {
        // 同上，简化版
        try {
            String[] parts = json.split("\\{");
            if (parts.length < 2) return null;
            String data = "{" + parts[1];
            data = data.replaceAll("\"", "");

            String sender = extractValue(data, "sender");
            String content = extractValue(data, "content");
            String typeStr = extractValue(data, "type");
            Message.MessageType type = Message.MessageType.valueOf(typeStr);
            return new Message(sender, content, type);
        } catch (Exception e) {
            return null;
        }
    }

    private String extractValue(String str, String key) {
        int start = str.indexOf(key + "=") + key.length() + 1;
        int end = str.indexOf(", ", start);
        if (end == -1) end = str.length();
        return str.substring(start, end).trim();
    }

    private String toJSON(Message msg) {
        return "{ \"sender\":\"" + msg.getSender() +
               "\", \"content\":\"" + msg.getContent() +
               "\", \"type\":\"" + msg.getType() +
               "\", \"time\":\"" + msg.getTimestamp() + "\" }";
    }

    private void terminate() {
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (clientSocket != null) clientSocket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }

