// ServerApp.java
import java.net.ServerSocket;
import java.net.Socket;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ServerApp {
    private static final int PORT = 8888;
    private static ExecutorService executor = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        System.out.println("启动客服系统服务器... 端口: " + PORT);

        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("服务器已启动，等待用户连接...");

            while (true) {
                Socket clientSocket = serverSocket.accept();
                String clientId = "user_" + System.currentTimeMillis();
                System.out.println("新用户接入: " + clientId);

                // 提示客服
                notifyAgent(clientId);

                // 新建线程处理该用户
                executor.submit(new ChatServer(clientSocket, clientId));
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
    }

    private static void notifyAgent(String userId) {
        // 在 UI 上弹出提示框
        SwingUtilities.invokeLater(() -> {
            JOptionPane.showMessageDialog(null,
                    "有新用户申请服务：" + userId + "\n请决定是否接受。",
                    "新用户请求",
                    JOptionPane.INFORMATION_MESSAGE);
        });
    }
}
