### ✅ Java Code

```java
import java.io.*;
import java.util.*;

public class RandomWordSelector {

    public static void main(String[] args) {
        // Path to your text file
        String filePath = "words.txt"; // Change this to your actual file path

        try {
            List<String> words = readWordsFromFile(filePath);
            if (words.isEmpty()) {
                System.out.println("No words found in the file.");
                return;
            }

            int totalWords = words.size();
            System.out.println("Total words in file: " + totalWords);

            if (totalWords < 10) {
                System.out.println("Only " + totalWords + " words found. Selecting all of them:");
                for (String word : words) {
                    System.out.println(word);
                }
                return;
            }

            // Select 10 random words without duplicates
            List<String> selectedWords = selectRandomWords(words, 10);

            System.out.println("\nRandomly selected 10 words:");
            for (int i = 0; i < selectedWords.size(); i++) {
                System.out.println((i + 1) + ". " + selectedWords.get(i));
            }

        } catch (IOException e) {
            System.err.println("Error reading the file: " + e.getMessage());
        }
    }

    /**
     * Reads the file and returns a list of words split by whitespace.
     */
    private static List<String> readWordsFromFile(String filePath) throws IOException {
        List<String> words = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                // Split by any whitespace (spaces, tabs, newlines)
                String[] tokens = line.trim().split("\\s+");
                for (String token : tokens) {
                    if (!token.isEmpty()) {
                        words.add(token);
                    }
                }
            }
        }
        return words;
    }

    /**
     * Selects 'count' random unique words from the list using Random.
     * Uses Fisher-Yates shuffle approach to avoid duplicates.
     */
    private static List<String> selectRandomWords(List<String> words, int count) {
        List<String> copy = new ArrayList<>(words); // Make a copy
        Collections.shuffle(copy); // Shuffle the list
        return copy.subList(0, Math.min(count, copy.size()));
    }
}
```

