Here's a complete **Java Android application** that opens a TCP socket connection when started. The networking logic is implemented in a separate thread and encapsulated in a dedicated class called `NetworkConnection`. This design follows good practices for threading and separation of concerns.

---

## ✅ Project Structure (Android Studio)

- `app/src/main/java/com/example/yourapp/`
  - `MainActivity.java` – Entry point, starts the background connection
  - `NetworkConnection.java` – Encapsulates TCP socket handling in a background thread

---

### 🔧 1. `NetworkConnection.java` — Separate Thread & Connection Logic

```java
package com.example.yourapp;

import android.util.Log;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.net.Socket;

public class NetworkConnection implements Runnable {

    private static final String TAG = "NetworkConnection";
    private final String host;
    private final int port;
    private volatile boolean isConnected = false;
    private Socket socket;
    private PrintWriter out;
    private BufferedReader in;

    // Callback interface to notify main thread of events
    public interface OnConnectionListener {
        void onConnected();
        void onMessageReceived(String message);
        void onDisconnected();
        void onError(Exception e);
    }

    private OnConnectionListener listener;

    public NetworkConnection(String host, int port, OnConnectionListener listener) {
        this.host = host;
        this.port = port;
        this.listener = listener;
    }

    @Override
    public void run() {
        Log.d(TAG, "Starting network connection thread...");

        try {
            socket = new Socket(host, port);
            Log.d(TAG, "Connected to server: " + host + ":" + port);

            // Initialize I/O streams
            out = new PrintWriter(socket.getOutputStream(), true);
            in = new BufferedReader(new InputStreamReader(socket.getInputStream()));

            isConnected = true;

            // Notify success
            if (listener != null) {
                listener.onConnected();
            }

            // Read messages from server
            String inputLine;
            while (isConnected && (inputLine = in.readLine()) != null) {
                Log.d(TAG, "Received: " + inputLine);
                if (listener != null) {
                    listener.onMessageReceived(inputLine);
                }
            }

            // If we exited loop, connection closed
            Log.d(TAG, "Server disconnected or socket closed.");
            if (listener != null) {
                listener.onDisconnected();
            }

        } catch (IOException e) {
            Log.e(TAG, "Error during network communication", e);
            if (listener != null) {
                listener.onError(e);
            }
        } finally {
            closeConnection();
        }
    }

    // Send a message to the server
    public void sendMessage(String message) {
        if (out != null && isConnected) {
            out.println(message);
            Log.d(TAG, "Sent: " + message);
        } else {
            Log.w(TAG, "Cannot send: no active connection");
        }
    }

    // Close the socket and streams
    private void closeConnection() {
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (socket != null) socket.close();
        } catch (IOException e) {
            Log.e(TAG, "Error closing connection", e);
        }
        isConnected = false;
    }

    // Check if connected
    public boolean isConnected() {
        return isConnected;
    }

    public void disconnect() {
        isConnected = false;
        closeConnection();
    }

    // Optional: Return raw socket (for advanced use cases)
    public Socket getSocket() {
        return socket;
    }
}
```

