### 📱 2. `MainActivity.java` — Launches the NetworkConnection in a Thread

```java
package com.example.yourapp;

import android.os.Bundle;
import android.widget.Button;
import android.widget.TextView;
import androidx.appcompat.app.AppCompatActivity;

public class MainActivity extends AppCompatActivity {

    private TextView statusText;
    private Button connectButton;
    private NetworkConnection networkConnection;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // Initialize UI elements
        statusText = findViewById(R.id.statusText);
        connectButton = findViewById(R.id.connectButton);

        // Set up click listener
        connectButton.setOnClickListener(v -> startConnection());

        // Example: Connect to localhost on port 8080
        // Note: You must have a server running at this address!
        // For testing, use: nc -l 8080 (on Unix/Linux/macOS), or a simple server like NetCat.
    }

    private void startConnection() {
        String host = "127.0.0.1"; // Change this to your server IP (e.g., 192.168.x.x)
        int port = 8080;

        // Create the connection with callback
        networkConnection = new NetworkConnection(host, port, new NetworkConnection.OnConnectionListener() {
            @Override
            public void onConnected() {
                runOnUiThread(() -> {
                    statusText.setText("Connected to " + host + ":" + port);
                });
            }

            @Override
            public void onMessageReceived(String message) {
                runOnUiThread(() -> {
                    statusText.append("\nReceived: " + message);
                });
            }

            @Override
            public void onDisconnected() {
                runOnUiThread(() -> {
                    statusText.append("\nDisconnected.");
                });
            }

            @Override
            public void onError(Exception e) {
                runOnUiThread(() -> {
                    statusText.append("\nError: " + e.getMessage());
                });
            }
        });

        // Start in a separate thread
        Thread thread = new Thread(networkConnection);
        thread.setDaemon(true); // Makes it die when app closes
        thread.start();

        // Optional: disable button when connected
        connectButton.setEnabled(false);
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        if (networkConnection != null) {
            networkConnection.disconnect();
        }
    }
}
