### 1. **MainActivity.java**

```java
package com.example.betgame;

import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.TextView;
import androidx.appcompat.app.AppCompatActivity;

import java.util.Random;

public class MainActivity extends AppCompatActivity {

    private TextView balanceText, resultText;
    private EditText betAmountEdit;
    private Button headsButton, tailsButton, flipButton;
    private ImageView coinImage;
    private int balance = 100;
    private Random random = new Random();

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // Initialize views
        balanceText = findViewById(R.id.balanceText);
        betAmountEdit = findViewById(R.id.betAmountEdit);
        headsButton = findViewById(R.id.headsButton);
        tailsButton = findViewById(R.id.tailsButton);
        flipButton = findViewById(R.id.flipButton);
        resultText = findViewById(R.id.resultText);
        coinImage = findViewById(R.id.coinImage);

        updateBalance();

        // Set click listeners
        headsButton.setOnClickListener(v -> makeBet("Heads"));
        tailsButton.setOnClickListener(v -> makeBet("Tails"));
        flipButton.setOnClickListener(v -> flipCoin());
    }

    private void makeBet(String choice) {
        String betStr = betAmountEdit.getText().toString();
        if (betStr.isEmpty()) {
            resultText.setText("Enter a valid bet!");
            return;
        }
        int betAmount = Integer.parseInt(betStr);

        if (betAmount <= 0 || betAmount > balance) {
            resultText.setText("Invalid bet amount!");
            return;
        }

        resultText.setText("You bet $" + betAmount + " on " + choice + ". Flip the coin!");
    }

    private void flipCoin() {
        String betStr = betAmountEdit.getText().toString();
        if (betStr.isEmpty()) {
            resultText.setText("Set your bet first!");
            return;
        }

        int betAmount = Integer.parseInt(betStr);
        String choice = "";
        if (headsButton.getVisibility() == View.VISIBLE && headsButton.isPressed()) {
            choice = "Heads";
        } else if (tailsButton.getVisibility() == View.VISIBLE && tailsButton.isPressed()) {
            choice = "Tails";
        } else {
            resultText.setText("Choose Heads or Tails!");
            return;
        }

        // Flip the coin
        boolean isHeads = random.nextBoolean(); // true = Heads, false = Tails

        // Update image
        if (isHeads) {
            coinImage.setImageResource(R.drawable.heads); // Add head image
        } else {
            coinImage.setImageResource(R.drawable.tails); // Add tail image
        }

        // Check result
        if ((isHeads && choice.equals("Heads")) || (!isHeads && choice.equals("Tails"))) {
            balance += betAmount;
            resultText.setText("You won! $" + betAmount + " added.");
        } else {
            balance -= betAmount;
            resultText.setText("You lost! $" + betAmount + " deducted.");
        }

        updateBalance();
    }

    private void updateBalance() {
        balanceText.setText("Balance: $" + balance);
    }
}
```

