import okhttp3.*
import java.io.IOException

class PostRequestExample {

    private val client = OkHttpClient()

    fun sendPostRequest(url: String, jsonString: String) {
        // 定义请求体：JSON 字符串
        val requestBody = RequestBody.create(
            MediaType.get("application/json"), // MIME type
            jsonString
        )

        // 构建 POST 请
