```java
import java.io.*;
import java.net.*;

public class TCPPacketClient {
    private static final String HOST = "localhost";
    private static final int PORT = 1024;
    private static int serialNo = 1;

    public static void main(String[] args) {
        try (Socket socket = new Socket(HOST, PORT);
             BufferedReader input = new BufferedReader(new InputStreamReader(System.in));
             BufferedReader br = new BufferedReader(new InputStreamReader(socket.getInputStream()));
             PrintStream ps = new PrintStream(socket.getOutputStream())) {

            System.out.print("--Enter the data packet: ");
            String line;

            while (!(line = input.readLine()).equals("CLOSE")) {
                // Create Packet
                Packet packet = new Packet(serialNo++, line);

                // Serialize and send
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                ObjectOutputStream oos = new ObjectOutputStream(baos);
                oos.writeObject(packet);

                byte[] buffer = baos.toByteArray();
                ps.write(buffer);
                ps.flush();

                // Wait for ACK response
                byte[] ackBuffer = new byte[1024];
                int bytesRead = socket.getInputStream().read(ackBuffer);
                if (bytesRead > 0) {
                    ByteArrayInputStream bais = new ByteArrayInputStream(ackBuffer, 0, bytesRead);
                    ObjectInputStream ois = new ObjectInputStream(bais);
                    Packet responsePacket = (Packet) ois.readObject();

                    System.out.println("FROM SERVER: Packet SerialNo#" + responsePacket.getSerialNo() + " is received");
                }

                System.out.print("--Enter the data packet: ");
            }

            // Close command sent
            ps.println("CLOSE");
            ps.flush();

            // Read final ACK if any (optional safety)
            byte[] finalAck = new byte[1024];
            int len = socket.getInputStream().read(finalAck);
            if (len > 0) {
                ByteArrayInputStream bais = new ByteArrayInputStream(finalAck, 0, len);
                ObjectInputStream ois = new ObjectInputStream(bais);
                Packet finalPacket = (Packet) ois.readObject();
                System.out.println("FROM SERVER: " + finalPacket.getData());
            }

        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }
}
```

> ✅ Matches:
> - Uses `new Socket(InetAddress, port)` implicitly
> - Uses `getInputStream()` → `BufferedReader` and `ObjectInputStream`
> - Uses `getOutputStream()` → `PrintStream`
> - Uses `BufferedReader` to read keyboard input
> - Creates `new Packet(...)` with serialNo & data
