     * 根据 wmPoiId、noticeId 和字符串生成 MD5 值
     *
     * @param wmPoiId  long 类型的门店 ID
     * @param noticeId long 类型的通知 ID
     * @param str      附加字符串
     * @return MD5 字符串（32 位小写十六进制）
     */
    public static String generateMd5(long wmPoiId, long noticeId, String str) {
        // 拼接 wmPoiId + noticeId + str
        String input = Long.toString(wmPoiId) + Long.toString(noticeId) + str;

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not available", e);
        }
    }

    // 测试方法
    public static void main(String[] args) {
        long wmPoiId = 123456789L;
        long noticeId = 987654321L;
        String str = "exampleString";

        String md5 = generateMd5(wmPoiId, noticeId, str);
        System.out.println("MD5: " + md5);
    }
}
```

### 说明：
