            String input = scanner.nextLine().trim();

            LocalDate targetDate = LocalDate.parse(input, formatter);

            // Получаем текущую дату
            LocalDate today = LocalDate.now();

            // Вычисляем разницу в днях
            long daysLeft = targetDate.toEpochDay() - today.toEpochDay();

            // Выводим результат
            if (daysLeft > 0) {
                System.out.printf("✅ До %s (%s) осталось %d дней!\n", 
                        targetDate.format(formatter), 
                        getDayOfWeek(targetDate), 
                        daysLeft);
            } else if (daysLeft == 0) {
                System.out.println("🎉 Сегодня — ваш особенный день! Ура!");
            } else {
                System.out.printf("⚠️  Дата уже прошла. Прошло %d дней.\n", Math.abs(daysLeft));
            }

        } catch (DateTimeParseException e) {
            System.err.println("❌ Ошибка: некорректный формат даты. Введите дату в формате ДД.ММ.ГГГГ.");
        } catch (Exception e) {
            System.err.println("❌ Произошла неожиданная ошибка: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Возвращает строку с названием дня недели на русском
     */
    private static String getDayOfWeek(LocalDate date) {
        switch (date.getDayOfWeek()) {
            case MONDAY: return "понедельник";
            case TUESDAY: return "вторник";
            case WEDNESDAY: return "среда";
            case THURSDAY: return "четверг";
            case FRIDAY: return "пятница";
            case SATURDAY: return "суббота";
            case SUNDAY: return "воскресенье";
            default: return "неизвестно";
        }
    }
}
