import org.bytedeco.javacv.*;
import org.bytedeco.opencv.opencv_core.*;
import org.bytedeco.opencv.opencv_videoio.*;

import java.io.InputStream;
import java.net.ServerSocket;
import java.net.Socket;

public class H264StreamReceiver {

    public static void main(String[] args) {
        try (ServerSocket serverSocket = new ServerSocket(8080);
             Socket socket = serverSocket.accept();
             InputStream inputStream = socket.getInputStream()) {

            System.out.println("Client connected, receiving H.264 stream...");

            // 配置 FFmpeg 转换器
            FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(inputStream);
            grabber.setOption("rtsp_transport", "tcp");
            // 只针对 H.264 流，指定输入为 raw h264 data
            grabber.setOption("format", "h264");
            grabber.setImageWidth(640);
            grabber.setImageHeight(480);
            grabber.setVideoCodecName("h264");

            try {
                grabber.start();

                CanvasFrame canvas = new CanvasFrame("H.264 Stream Receiver", CanvasFrame.getDefaultAlignment());
                canvas.setDefaultCloseOperation(CanvasFrame.DISPOSE_ON_CLOSE);

                Frame frame;
                while ((frame = grabber.grabFrame()) != null) {
                    if (!canvas.isDisplayable()) break;
                    if (frame.image != null) {
                        canvas.showImage(frame);
                    }
                }

            } finally {
                grabber.stop();
                grabber.release();
                socket.close();
                serverSocket.close();
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

