## 🖥️ 三、完整实现：接收并播放接收到的 H.264 流

### ✅ 1. 主类：`H264StreamReceiver.java`

```java
import javafx.application.Application;
import javafx.beans.property.SimpleStringProperty;
import javafx.scene.Scene;
import javafx.scene.control.Label;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;
import org.bytedeco.ffmpeg.global.avcodec;
import org.bytedeco.ffmpeg.global.avformat;
import org.bytedeco.ffmpeg.global.avutil;
import org.bytedeco.ffmpeg.helper.AvUtil;
import org.bytedeco.javacv.*; // 包含 FrameRecorder, FFmpegFrameGrabber, etc.
import org.bytedeco.javacv.Frame;

import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;

public class H264StreamReceiver extends Application {

    private static final int PORT = 8000;
    private volatile boolean isRunning = true;

    // 用于显示视频的面板
    private OpenCVFrameGrabber grabber;

    public static void main(String[] args) {
        launch(args);
    }

    @Override
    public void start(Stage stage) throws Exception {
        Label label = new Label("H.264 视频接收中...");
        label.setStyle("-fx-font-size: 16px;");
        VBox root = new VBox(label);
        Scene scene = new Scene(root, 640, 480);

        stage.setTitle("H.264 流接收器");
        stage.setScene(scene);
        stage.show();

        // 启动后台接收线程
        Thread receiverThread = new Thread(this::startReceiving);
        receiverThread.setDaemon(true);
        receiverThread.start();
    }

    private void startReceiving() {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("等待客户端连接...");

            while (isRunning) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("客户端已连接: " + clientSocket.getInetAddress());

                try (InputStream inputStream = clientSocket.getInputStream()) {
                    byte[] buffer = new byte[4096];
                    int bytesRead;

                    // 创建一个用于接收原始 H.264 数据的帧抓取器
                    grabber = new OpenCVFrameGrabber(0); // 这里只是占位符，不用于本地摄像头
                    grabber.setImageHeight(480);
                    grabber.setImageWidth(640);
                    grabber.setFormat("h264");

                    // 初始化帧处理
                    ImagePipeline pipeline = new ImagePipeline();

                    // 开始读取数据
                    while ((bytesRead = inputStream.read(buffer)) != -1 && isRunning) {
                        // 假设数据是完整的 H.264 帧（Nal Unit 格式）
                        byte[] frameData = new byte[bytesRead];
                        System.arraycopy(buffer, 0, frameData, 0, bytesRead);

                        // 处理单帧（关键点：将原始 H.264 数据交给解码器）
                        decodeAndDisplay(frameData);
                    }
                } catch (Exception e) {
                    System.err.println("客户端连接异常: " + e.getMessage());
                } finally {
                    clientSocket.close();
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void decodeAndDisplay(byte[] h264Data) {
        // 此处用 ffmpeg-java + JavaCV 再次尝试解码
        try (FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(new ByteArrayInputStream(h264Data))) {
            grabber.setOption("f", "h264");
            grabber.setOption("probesize", "32");
            grabber.setOption("analyzeduration", "32");
            grabber.setOption("format", "h264");

            grabber.start();

            Frame frame = grabber.grab(); // 一次解码一帧
            if (frame != null) {
                // 假设有视频显示控件（如 ImageView）
                // 但这里我们只能发送到主窗口，所以用 JavaFX 的图像组件
                Platform.runLater(() -> { /* 更新界面 */ });
            }

            grabber.stop();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @Override
    public void stop() {
        isRunning = false;
        if (grabber != null) {
            try {
                grabber.release();
            } catch (Exception ignored) {}
        }
    }
}
```

