public class ChatRecordManager {
    private static final String RECORD_DIR = "chat_records";
    private static final ObjectMapper mapper = new ObjectMapper();

    static {
        try {
            Files.createDirectories(Paths.get(RECORD_DIR));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void saveRecord(String username, List<Message> messages) {
        String filename = RECORD_DIR + "/" + username + ".json";
        try (FileWriter writer = new FileWriter(filename)) {
            mapper.writeValue(writer, messages);
        } catch (IOException e) {
            System.err.println("保存聊天记录失败: " + filename);
            e.printStackTrace();
        }
    }

    public static List<Message> loadRecord(String username) {
        String filename = RECORD_DIR + "/" + username + ".json";
        File file = new File(filename);
        if (!file.exists()) return new ArrayList<>();

        try (FileReader reader = new FileReader(filename)) {
            return mapper.readValue(reader, mapper.getTypeFactory()
                    .constructCollectionType(ArrayList.class, Message.class));
        } catch (IOException e) {
            System.err.println("加载聊天记录失败: " + filename);
            e.printStackTrace();
            return new ArrayList<>();
        }
    }
}
