            int len;
            while ((len = fis.read(buffer)) > 0) {
                baos.write(buffer, 0, len);
            }

            Message msg = new Message("image", "user", file.getName(), baos.toByteArray());
            sendMsg(msg);
            showText("🖼️ 发送图片: " + file.getName());

        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "发送图片失败: " + e.getMessage());
