        int result = fc.showOpenDialog(this);
        if (result != JFileChooser.APPROVE_OPTION) return;

        File file = fc.getSelectedFile();
        try (FileInputStream fis = new FileInputStream(file);
             ByteArrayOutputStream baos = new ByteArrayOutputStream()) {

            byte[] buffer = new byte[4096];
            int len;
            while ((len = fis.read(buffer)) > 0) {
                baos.write(buffer, 0, len);
            }

            Message msg = new Message("file", "user", file.getName(), baos.toByteArray());
            sendMsg(msg);
            showText("📎 上传文件: " + file.getName());

        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "发送文件失败: " + e.getMessage());
        }
    }

    private void sendMsg(Message msg) {
        try {
            oos.writeObject(msg);
            oos.flush();
            waitResponse = true; // 开始等待客服回复
        } catch (Exception e) {
            showText("❌ 发送失败: " + e.getMessage());
        }
    }

    private void updateChat(Message msg) {
        if ("text".equals(msg.getType())) {
            showText("客服: " + msg.getContent());
        } else if ("image".equals(msg.getType())) {
            showText("客服: 显示图片 '" + msg.getFilename() + "'");
            // 可扩展：在界面上显示图片
        } else if ("file".equals(msg.getType())) {
            showText("客服: 已发送文件 '" + msg.getFilename() + "'");
            // 按需保存文件
            try (FileOutputStream fos = new FileOutputStream("downloaded_" + msg.getFilename())) {
                fos.write(msg.getData());
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        chatHistory.add(msg);
    }

    private void showText(String text) {
        chatArea.append(text + "\n");
        chatArea.setCaretPosition(chatArea.getDocument().getLength());
    }

    private boolean isConnected() {
        return socket != null && !socket.isClosed();
    }

    private void disconnect() {
        try {
            if (ois != null) ois.close();
            if (oos != null) oos.close();
            if (socket != null) socket.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
        connected = false;
        connectBtn.setEnabled(true);
        waitResponse = false;
        if (idleTimer != null) idleTimer.stop();
