```java
package com.ecommerce;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.*;

public class ServerUI extends JFrame {
    private ServerSocket serverSocket;
    private List<ClientHandler> clients = new ArrayList<>();
    private JTextArea logArea;
    private JButton startBtn;
    private final Map<String, List<Message>> sessionLogs = new HashMap<>();

    public ServerUI() {
        setTitle("客服端 - 电商客服系统");
        setSize(700, 600);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        initUI();
        startServer();
    }

    private void initUI() {
        JPanel mainPanel = new JPanel(new BorderLayout());
        JPanel topPanel = new JPanel(new FlowLayout());

        startBtn = new JButton("启动服务器");
        startBtn.addActionListener(e -> startServer());

        topPanel.add(startBtn);
        topPanel.add(new JLabel("服务端口: 8888"));

        logArea = new JTextArea();
        logArea.setEditable(false);
        logArea.setFont(new Font("Consolas", Font.PLAIN, 13));
        JScrollPane scrollPane = new JScrollPane(logArea);

        mainPanel.add(topPanel, BorderLayout.NORTH);
        mainPanel.add(scrollPane, BorderLayout.CENTER);
        mainPanel.setBorder(new EmptyBorder(10, 10, 10, 10));

        add(mainPanel);
    }

    private void startServer() {
        try {
            serverSocket = new ServerSocket(8888);
            startBtn.setEnabled(false);
            showLog("✅ 服务器已启动，等待客户端连接...");

            new Thread(() -> {
                while (!serverSocket.isClosed()) {
                    try {
                        Socket clientSocket = serverSocket.accept();
                        ClientHandler handler = new ClientHandler(clientSocket);
                        clients.add(handler);
                        showLog("👤 新用户连接: " + clientSocket.getInetAddress().getHostAddress());
                    } catch (IOException e) {
                        if (!serverSocket.isClosed()) {
                            showLog("❌ 无法接收新连接: " + e.getMessage());
                        }
                    }
                }
            }).start();

        } catch (IOException e) {
            showLog("服务器启动失败: " + e.getMessage());
        }
    }

    private void showLog(String msg) {
        logArea.append(msg + "\n");
        logArea.setCaretPosition(logArea.getDocument().getLength());
    }

    private class ClientHandler extends Thread {
        private final Socket socket;
        private ObjectInputStream ois;
        private ObjectOutputStream oos;
        private String username;
        private volatile boolean active = true;

        public ClientHandler(Socket socket) {
            this.socket = socket;
            start();
        }

        @Override
        public void run() {
            try {
                oos = new ObjectOutputStream(socket.getOutputStream());
                ois = new ObjectInputStream(socket.getInputStream());

                // 初始化消息
                Message firstMsg = (Message) ois.readObject();
                if (firstMsg != null) {
                    username = firstMsg.getContent();
                    showLog("💬 客服开始服务: " + username);
                    sessionLogs.put(username, new ArrayList<>());
                }

                // 消息循环
                while (active && !socket.isClosed()) {
                    Object obj = ois.readObject();
                    if (obj instanceof Message msg) {
                        handleIncomingMessage(msg);
                        sessionLogs.getOrDefault(username, new ArrayList<>()).add(msg);
                        ChatRecordManager.saveRecord(username, sessionLogs.get(username));
                    }
                }

            } catch (Exception e) {
                if ("user".equals(e.getMessage())) {
                    // 被动关闭，不输出异常
                } else {
                    showLog("❌ 用户[" + username + "]连接异常: " + e.getMessage());
                }
            } finally {
                cleanup();
            }
        }

        private void handleIncomingMessage(Message msg) {
            switch (msg.getType()) {
                case "text":
                    showMessage("客服: " + msg.getContent());
                    // 回复模拟（实际应由客服输入）
                    Message reply = new Message("text", "agent", "已收到您的消息，请稍等~");
                    sendReply(reply);

                    break;
                case "image":
                    showMessage("接收到图片: " + msg.getFilename());
                    Message rep = new Message("text", "agent", "图片已收到，正在处理...");
                    sendReply(rep);
                    break;
                case "file":
                    showMessage("接收到文件: " + msg.getFilename());
                    Message repf = new Message("text", "agent", "文件已收，后续会通过邮件发送");
                    sendReply(repf);
                    // 可保存到本地
                    try (FileOutputStream fos = new FileOutputStream("received_" + msg.getFilename())) {
                        fos.write(msg.getData());
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                    break;
            }
        }

        private void sendReply(Message msg) {
            try {
                oos.writeObject(msg);
                oos.flush();
            } catch (Exception e) {
                showLog("❌ 发送回复失败: " + e.getMessage());
            }
        }

        private void showMessage(String text) {
            showLog("🔄 " + text);
        }

        private void cleanup() {
            active = false;
            try {
                if (ois != null) ois.close();
                if (oos != null) oos.close();
                if (socket != null) socket.close();
            } catch (IOException ignored) {}
            clients.remove(this);
            showLog("🗑️ 用户 [" + username + "] 已断开");
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            new ServerUI();
        });
    }
}
