@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final UserService userService;
    private final JwtService jwtService;
    private final AuthenticationManagerBuilder authManagerBuilder;

    @PostMapping("/register")
    public ResponseEntity<Map<String, String>> register(@Valid @RequestBody RegisterRequest request) {
        User user = userService.register(request);

        return ResponseEntity.ok(Map.of(
            "message", "User registered successfully!",
            "username", user.getUsername()
        ));
    }

    @PostMapping("/login")
    public ResponseEntity<AuthResponse> login(@Valid @RequestBody LoginRequest request) {
        Authentication authentication = authManagerBuilder.getObject()
                .authenticate(new UsernamePasswordAuthenticationToken(request.getEmail(), request.getPassword()));

        SecurityContextHolder.getContext().setAuthentication(authentication);

        String token = jwtService.generateToken((UserDetails) authentication.getPrincipal());

        User user = userService.loadUserByEmail(request.getEmail());

        AuthResponse response = new AuthResponse();
        response.setToken(token);
        response.setUsername(user.getUsername());
        response.setEmail(user.getEmail());
        response.setRoles(Collections.singleton(new SimpleGrantedAuthority("ROLE_USER")));

        return ResponseEntity.ok(response);
    }

    private User loadUserByEmail(String email) {
        return userService.userRepository.findByEmail(email).orElseThrow();
    }
}
