```java
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;

import java.io.IOException;
import java.net.URL;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

public class NewsScraper {

    private static final String BASE_URL = "https://www.tyjrchina.org.cn";
    private static final String NEWS_LIST_URL = "https://www.tyjrchina.org.cn/newsInfor/news";

    public static void main(String[] args) {
        try {
            // 1. 连接主页面获取新闻列表
            Document mainDoc = Jsoup.connect(NEWS_LIST_URL)
                    .userAgent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36")
                    .timeout(10000)
                    .get();

            Elements newsItems = mainDoc.select("ul.news-list li");

            List<NewsItem> newsList = new ArrayList<>();

            for (Element item : newsItems) {
                Element titleLink = item.selectFirst("a.title"); // 假设标题链接用 class="title"
                if (titleLink == null) continue;

                String title = titleLink.text().trim();
                String detailUrl = BASE_URL + titleLink.attr("href"); // 相对路径转绝对路径

                // 2. 访问详细页面抓取正文和图片
                Document detailDoc = Jsoup.connect(detailUrl)
                        .userAgent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36")
                        .timeout(10000)
                        .get();

                // 3. 提取发布时间
                String publishTime = "";
                Element timeElement = detailDoc.selectFirst("span.time, .publish-time, .date");
                if (timeElement != null) {
                    publishTime = timeElement.text().trim();
                } else {
                    publishTime = "Unknown";
                }

                // 4. 提取并处理内容中的图片路径
                Element contentDiv = detailDoc.selectFirst(".news-content, #newsContent, .content");
                if (contentDiv == null) {
                    System.out.println("Warning: No content found for: " + title);
                    continue;
                }

                // 替换所有相对路径图片为绝对路径
                Elements imgElements = contentDiv.select("img");
                for (Element img : imgElements) {
                    String src = img.attr("src");
                    if (src.startsWith("/")) {
                        img.attr("src", BASE_URL + src); // 转为绝对路径
                    }
                    // 可选：添加 alt 属性或样式
                    if (!img.hasAttr("alt")) {
                        img.attr("alt", title);
                    }
                }

                // 5. 保留处理后的文本内容（可选：移除多余标签）
                String content = contentDiv.html(); // 原始带标签内容

                // 构建新闻对象
                NewsItem news = new NewsItem(title, publishTime, content);
                newsList.add(news);

                System.out.println("✅ 已抓取: " + title);
                System.out.println("   日期: " + publishTime);
                System.out.println("   内容长度: " + content.length() + " 字符");
                System.out.println("---");
            }

            // 打印结果或保存到文件
            System.out.println("\n共抓取 " + newsList.size() + " 条新闻。\n");

            // 可选：保存到文件（如保存为 HTML 格式）
            saveToHtml(newsList);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 将新闻保存为 HTML 格式
    private static void saveToHtml(List<NewsItem> newsList) {
        StringBuilder sb = new StringBuilder();
        sb.append("<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>新闻爬取结果</title></head><body>");
        sb.append("<h1>新闻动态抓取结果</h1>");

        for (NewsItem item : newsList) {
            sb.append("<div style='border:1px solid #ccc; padding:10px; margin:10px 0;'>");
            sb.append("<h2>").append(item.getTitle()).append("</h2>");
            sb.append("<p><strong>发布时间:</strong> ").append(item.getPublishTime()).append("</p>");
            sb.append("<div>").append(item.getContent()).append("</div>");
            sb.append("</div>");
        }

        sb.append("</body></html>");

        // 写入文件
        try (var writer = new java.io.FileWriter("news_export.html")) {
            writer.write(sb.toString());
            System.out.println("✅ 成功保存到 news_export.html");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // 内部类：新闻信息
    public static class NewsItem {
        private String title;
        private String publishTime;
        private String content;

        public NewsItem(String title, String publishTime, String content) {
            this.title = title;
            this.publishTime = publishTime;
            this.content = content;
        }

        // Getters
        public String getTitle() { return title; }
        public String getPublishTime() { return publishTime; }
        public String getContent() { return content; }
    }
}
