### ✅ 2. Создание контроллера для загрузки файла

Создайте класс `FileUploadController.java`:

```java
package com.example.demo.controller;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

@RestController
@RequestMapping("/api/files")
public class FileUploadController {

    // Путь к папке для хранения файлов
    @Value("${upload.path:/tmp/uploads}")
    private String uploadPath;

    // Метод для загрузки файла
    @PostMapping("/upload")
    public ResponseEntity<String> uploadFile(@RequestParam("file") MultipartFile file) {
        if (file.isEmpty()) {
            return ResponseEntity.badRequest().body("Пустой файл");
        }

        try {
            // Создаем папку, если её нет
            Path path = Paths.get(uploadPath);
            if (!path.toFile().exists()) {
                path.toFile().mkdirs();
            }

            // Формируем уникальное имя файла (чтобы избежать конфликтов)
            String filename = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss")) +
                              "_" + file.getOriginalFilename();

            Path dest = Paths.get(uploadPath, filename);
            file.transferTo(dest);  // Сохраняем файл

            return ResponseEntity.ok("Файл успешно загружен: " + filename);

        } catch (IOException e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body("Ошибка при сохранении файла: " + e.getMessage());
        }
    }

    // Опционально: получение файла по имени
    @GetMapping("/download/{filename}")
    public ResponseEntity<byte[]> downloadFile(@PathVariable String filename) {
        try {
            Path filePath = Paths.get(uploadPath, filename);
            byte[] fileBytes = java.nio.file.Files.readAllBytes(filePath);

            return ResponseEntity.ok()
                    .header("Content-Disposition", "attachment; filename=\"" + filename + "\"")
                    .body(fileBytes);

        } catch (IOException e) {
            return ResponseEntity.notFound().build();
        }
    }
}
```

