```java
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.type.MapType;
import com.fasterxml.jackson.databind.type.TypeFactory;

import java.io.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class IndexService {
    private final String indexPath;
    private final String basePath;
    private final Map<String, FileInfo> index;
    private final ObjectMapper mapper;
    private final ScheduledExecutorService scheduler;

    private boolean isRunning = true;

    public IndexService(String indexPath, String basePath) {
        this.indexPath = indexPath;
        this.basePath = basePath;
        this.index = new ConcurrentHashMap<>();
        this.mapper = new ObjectMapper();
        this.scheduler = Executors.newScheduledThreadPool(1);
    }

    // Start indexing drives and monitoring
    public void startIndexing() {
        loadIndex(); // Load existing index

        List<Path> drives = getDrives();
        System.out.println("Found " + drives.size() + " drives: " + drives);

        // Initial scan of all drives
        for (Path drive : drives) {
            if (Files.exists(drive)) {
                scanDrive(drive);
            } else {
                System.out.println("Drive not accessible: " + drive);
            }
        }

        // Save initial index
        saveIndex();

        // Start monitor thread
        startMonitoring(drives);
    }

    private List<Path> getDrives() {
        List<Path> drives = new ArrayList<>();

        // For Windows: C:, D:, etc.
        if (System.getProperty("os.name").toLowerCase().contains("windows")) {
            String[] roots = File.listRoots().length == 0 ?
                    new String[]{"C:"} : File.listRoots();
            for (String root : roots) {
                drives.add(Paths.get(root));
            }
        } else if (System.getProperty("os.name").toLowerCase().contains("mac")) {
            drives.add(Paths.get("/"));
        } else { // Linux/Unix
            drives.add(Paths.get("/"));
        }

        return drives;
    }

    private void scanDrive(Path drive) {
        System.out.println("🔄 Scanning drive: " + drive);
        try (var stream = Files.walk(drive)) {
            stream.filter(Files::isRegularFile)
                  .filter(path -> !isHidden(path))
                  .forEach(path -> {
                      try {
                          long size = Files.size(path);
                          long lastModified = Files.getLastModifiedTime(path).toInstant().toEpochSecond();
                          String relativePath = path.toString().substring(basePath.length());
                          index.put(path.toString(), new FileInfo(relativePath, size, lastModified));
                      } catch (IOException e) {
                          System.err.println("Could not read file: " + path + " | " + e.getMessage());
                      }
                  });
        } catch (IOException e) {
            e.printStackTrace();
        }
        System.out.println("✅ Completed scan for " + drive);
    }

    private boolean isHidden(Path path) {
        try {
            return Files.isHidden(path);
        } catch (IOException e) {
            return false; // assume not hidden if we can't check
        }
    }

    private void saveIndex() {
        try {
            String json = mapper.writeValueAsString(index);
            try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(indexPath), StandardOpenOption.WRITE, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
                writer.write(json);
            }
            System.out.println("💾 Index saved to: " + indexPath);
        } catch (JsonProcessingException | IOException e) {
            e.printStackTrace();
        }
    }

    private void loadIndex() {
        File indexFile = new File(indexPath);
        if (!indexFile.exists()) return;

        try (BufferedReader reader = Files.newBufferedReader(Paths.get(indexPath))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line);
            }
            String json = sb.toString();

            MapType mapType = TypeFactory.defaultInstance()
                    .mapType(Map.class, String.class, FileInfo.class);
            Map<String, FileInfo> loadedIndex = mapper.readValue(json, mapType);
            index.putAll(loadedIndex);
            System.out.println("📁 Loaded " + loadedIndex.size() + " files from index.");
        } catch (IOException e) {
            System.err.println("⚠️ Could not load index: " + e.getMessage());
        }
    }

    public List<String> searchFiles(String query) {
        List<String> results = new ArrayList<>();
        query = query.toLowerCase();
        for (Map.Entry<String, FileInfo> entry : index.entrySet()) {
            String path = entry.getKey();
            if (path.toLowerCase().contains(query)) {
                results.add(path);
            }
        }
        return results;
    }

    private void startMonitoring(List<Path> drives) {
        scheduler.scheduleAtFixedRate(() -> {
            try {
                List<WatchKey> watchKeys = new ArrayList<>();
                for (Path root : drives) {
                    WatchService watcher = FileSystems.getDefault().newWatchService();

                    // Register recursive watch on root
                    Path watchPath = root;
                    watchPath.register(watcher, StandardWatchEventKind.ENTRY_CREATE,
                            StandardWatchEventKind.ENTRY_DELETE, StandardWatchEventKind.ENTRY_MODIFY);

                    watchKeys.add(watcher.key());
                }

                // Process events forever
                while (isRunning) {
                    WatchKey key = watcher.poll();
                    if (key == null) continue;

                    for (WatchEvent<?> event : key.pollEvents()) {
                        WatchEvent.Kind<?> kind = event.kind();
                        Path changedPath = (Path) event.context();

                        Path fullPath = key.watchable().resolve(changedPath);
                        if (isHidden(fullPath)) continue;

                        switch (kind) {
                            case ENTRY_CREATE:
                                handleCreate(fullPath);
                                break;
                            case ENTRY_DELETE:
                                handleDelete(fullPath);
                                break;
                            case ENTRY_MODIFY:
                                handleModify(fullPath);
                                break;
                            default:
                                break;
                        }
                    }
                    key.reset();
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }, 1, 5, TimeUnit.SECONDS);
    }

    private void handleCreate(Path path) {
        System.out.println("🆕 Created: " + path);
        try {
            long size = Files.size(path);
            long lastModified = Files.getLastModifiedTime(path).toInstant().toEpochSecond();
            String relPath = path.toString().substring(basePath.length());

            index.put(path.toString(), new FileInfo(relPath, size, lastModified));
            saveIndex();
        } catch (IOException e) {
            System.err.println("Error handling create: " + path + " | " + e.getMessage());
        }
    }

    private void handleDelete(Path path) {
        System.out.println("🗑️ Deleted: " + path);
        index.remove(path.toString());
        saveIndex();
    }

    private void handleModify(Path path) {
        System.out.println("✏️ Modified: " + path);
        try {
            long lastModified = Files.getLastModifiedTime(path).toInstant().toEpochSecond();
            index.computeIfPresent(path.toString(), (k, v) -> {
                v.lastModified = lastModified;
                return v;
            });
            saveIndex();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void stop() {
        isRunning = false;
        scheduler.shutdownNow();
    }
}
```

