package protocol;

import java.io.Serializable;
import java.util.Date;

public class Message implements Serializable {
    private static final long serialVersionUID = 1L;

    public enum MessageType {
        TEXT, IMAGE, FILE, JOIN, LEAVE, PING, BUSY
    }

    private MessageType type;
    private String sender;      // "user" or "agent"
    private String content;     // 可能是文本或文件路径/图片数据（如为文件/图片，存储为Base64）
    private byte[] data;        // 二进制数据（图片、文件）
    private Date timestamp;

    public Message() {}

    public Message(MessageType type, String sender, String content) {
        this.type = type;
        this.sender = sender;
        this.content = content;
        this.timestamp = new Date();
    }

    public Message(MessageType type, String sender, byte[] data) {
        this.type = type;
        this.sender = sender;
        this.data = data;
        this.timestamp = new Date();
    }

    // Getters and Setters
    public MessageType getType() { return type; }
    public void setType(MessageType type) { this.type = type; }

    public String getSender() { return sender; }
    public void setSender(String sender) { this.sender = sender; }

    public String getContent() { return content; }
    public void setContent(String content) { this.content = content; }

    public byte[] getData() { return data; }
    public void setData(byte[] data) { this.data = data; }

    public Date getTimestamp() { return timestamp; }
    public void setTimestamp(Date timestamp) { this.timestamp = timestamp; }

    @Override
    public String toString() {
        return "[MESSAGE] [" + timestamp + "] " + sender + ": " + (content != null ? content : "<binary data>");
    }
