## 💾 3. 聊天记录管理（通用）

### `utils/ChatRecordManager.java`

```java
package utils;

import protocol.Message;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

public class ChatRecordManager {

    private static final DateTimeFormatter FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    public static void saveChatHistory(String userId, List<Message> messages) {
        try (FileWriter writer = new FileWriter(getFilePath(userId), false)) {
            for (Message msg : messages) {
                String timeStr = msg.getTimestamp().toInstant().atZone(java.time.ZoneId.systemDefault()).format(FORMATTER);
                String content = msg.getContent() != null ? msg.getContent() : "Binary Data";
                writer.write(String.format("[%s] %s: %s\n", timeStr, msg.getSender(), content));
            }
        } catch (IOException e) {
            System.err.println("保存聊天记录失败: " + e.getMessage());
        }
    }

    public static List<Message> loadChatHistory(String userId) {
        List<Message> messages = new ArrayList<>();
        File file = new File(getFilePath(userId));
        if (!file.exists()) return messages;

        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.contains("[")) {
                    // [2025-04-05 10:30:20] user: hello
                    String[] parts = line.split("]: ", 2);
                    if (parts.length == 2) {
                        String sender = parts[0].substring(1, parts[0].indexOf(":"));
                        String content = parts[1];
                        Message msg = new Message(Message.MessageType.TEXT, sender, content);
                        messages.add(msg);
                    }
                }
            }
        } catch (IOException e) {
            System.err.println("读取聊天记录失败: " + e.getMessage());
        }

        return messages;
    }

    private static String getFilePath(String userId) {
        return Constants.RECORD_DIR + userId + "_chat.log";
    }
}
