    private Socket socket;
    private ObjectInputStream ois;
    private ObjectOutputStream oos;
    private String userId = "user_" + System.currentTimeMillis();

    private List<Message> history = new ArrayList<>();

    public UserClient() {
        setLayout(new BorderLayout());
        initUI();
        setupConnection();
    }

    private void initUI() {
        setTitle("电商客服 - 用户端");
        setSize(600, 500);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        // 聊天区域
        chatArea = new JTextPane();
        chatArea.setEditable(false);
        JScrollPane scroll = new JScrollPane(chatArea);
        add(scroll, BorderLayout.CENTER);

        // 输入区
        JPanel bottomPanel = new JPanel(new BorderLayout());
        inputField = new JTextField(20);
        sendButton = new JButton("发送");
        imageButton = new JButton("发送图片");
        fileButton = new JButton("发送文件");
        connectButton = new JButton("连接客服");

        // 添加动作监听
        sendButton.addActionListener(e -> sendMessage());
        imageButton.addActionListener(e -> sendImage());
        fileButton.addActionListener(e -> sendFile());
        connectButton.addActionListener(e -> connect());

        // 布局
        bottomPanel.add(inputField, BorderLayout.CENTER);
        JPanel buttonPanel = new JPanel(new FlowLayout());
        buttonPanel.add(sendButton);
        buttonPanel.add(imageButton);
        buttonPanel.add(fileButton);
        buttonPanel.add(connectButton);
        bottomPanel.add(buttonPanel, BorderLayout.EAST);
        add(bottomPanel, BorderLayout.SOUTH);

        // 加载历史记录
        loadData();
        showHistory(history);
    }

    private void connect() {
        if (connected) {
            JOptionPane.showMessageDialog(this, "已连接");
            return;
        }

        try {
            socket = new Socket();
            socket.connect(new java.net.InetSocketAddress(Constants.SERVER_IP, Constants.PORT), 5000);

            socket.setSoTimeout(Constants.SOCKET_TIMEOUT);
            oos = new ObjectOutputStream(socket.getOutputStream());
            ois = new ObjectInputStream(socket.getInputStream());

            connected = true;
            connectButton.setText("已连接");
            chatArea.setText("连接成功！等待客服响应...\n");

            new Thread(() -> listenForMessages()).start();
            // 发送连接请求
            send(new Message(Message.MessageType.JOIN, userId, ""));

            showBusyIndicator();

        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "连接失败：" + e.getMessage());
        }
    }

    private void sendMessage() {
        String text = inputField.getText().trim();
        if (text.isEmpty()) return;
        send(new Message(MessageType.TEXT, userId, text));
        inputField.setText("");
    }

    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            String path = fc.getSelectedFile().getPath();
            try {
                byte[] data = FileUtil.imageToBytes(path);
                send(new Message(MessageType.IMAGE, userId, data));
                appendToChat("你发送了一张图片");
            } catch (Exception e) {
                JOptionPane.showMessageDialog(this, "图片转换失败：" + e.getMessage());
            }
        }
    }

    private void sendFile() {
        JFileChooser fc = new JFileChooser();
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            String path = fc.getSelectedFile().getPath();
            byte[] data = FileUtil.readFile(path);
            if (data.length == 0) return;
            send(new Message(MessageType.FILE, userId, path));
            appendToChat("你发送了文件：" + fc.getSelectedFile().getName());
        }
    }

    private void send(Message msg) {
        try {
            oos.writeObject(msg);
            oos.flush();
        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "发送失败：" + e.getMessage());
        }
    }

    private void listenForMessages() {
        try {
            while (connected && !socket.isClosed()) {
                Message msg = (Message) ois.readObject();
                switch (msg.getType()) {
                    case TEXT:
                        appendToChat("客服：" + msg.getContent());
                        break;
                    case IMAGE:
                        appendToChat("客服发来图片");
                        // 显示图片（需要额外组件）
                        showImage(msg.getData());
                        break;
                    case FILE:
                        String fileName = msg.getContent();
                        FileUtil.saveFileFromBytes(msg.getData(), "received_" + fileName);
                        appendToChat("文件已下载：" + fileName);
                        break;
                    case PING:
                        send(new Message(MessageType.PING, userId, "pong"));
                        break;
                    default:
                        appendToChat("收到未知消息：" + msg);
                }
                saveMessage(msg);
            }
        } catch (SocketTimeoutException e) {
            appendToChat("【客服忙】长时间未响应，可能正在处理其他客户。");
        } catch (IOException | ClassNotFoundException e) {
            errorOccurred(e.getMessage());
        }
    }

    private void showBusyIndicator() {
        Timer timer = new Timer(30000, e -> {
            try {
                oos.writeObject(new Message(MessageType.PING, userId, "ping"));
                oos.flush();
            } catch (IOException ex) {
            }
        });
        timer.start();
    }

    private void appendToChat(String text) {
        chatArea.setText(chatArea.getText() + text + "\n");
        chatArea.setCaretPosition(chatArea.getDocument().getLength());
    }

    private void showImage(byte[] imageData) {
        ImageIcon icon = new ImageIcon(imageData);
        JLabel label = new JLabel(icon);
        JOptionPane.showMessageDialog(this, label, "图片预览", 
                JOptionPane.PLAIN_MESSAGE);
    }

    private void saveMessage(Message msg) {
        history.add(msg);
        ChatRecordManager.saveChatHistory(userId, history);
    }

    private void loadData() {
        history = ChatRecordManager.loadChatHistory(userId);
    }

    private void showHistory(List<Message> msgs) {
        for (Message msg : msgs) {
            appendToChat(msg.getSender() + ": " + msg.getContent());
        }
    }

    private void errorOccurred(String msg) {
        JOptionPane.showMessageDialog(this, "异常: " + msg);
        disconnect();
    }

    private void disconnect() {
        try {
            if (ois != null) ois.close();
            if (oos != null) oos.close();
            if (socket != null) socket.close();
        } catch (IOException ignored) {}
        connected = false;
        chatArea.setText("已断开连接。\n");
    }
}
