public class CustomerServiceServer extends JFrame {
    private ServerSocket serverSocket;
    private Map<String, ChatSession> sessions = new HashMap<>();
    private JTextArea logArea;
    private JButton acceptButton, rejectButton;
    private List<ChatSession> activeSessions = new ArrayList<>();
    private volatile boolean running = false;
    private final Object lock = new Object();

    public CustomerServiceServer() {
        initUI();
        startServer();
    }

    private void initUI() {
        setTitle("电商客服系统（客服端）");
        setSize(700, 600);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        JPanel top = new JPanel(new BorderLayout());
        logArea = new JTextArea(10, 60);
        logArea.setEditable(false);
        JScrollPane scroll = new JScrollPane(logArea);
        top.add(new JLabel("日志信息"), BorderLayout.NORTH);
        top.add(scroll, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout());
        acceptButton = new JButton("接受");
        rejectButton = new JButton("拒绝");
        buttons.add(acceptButton);
        buttons.add(rejectButton);
        top.add(buttons, BorderLayout.SOUTH);

        add(top, BorderLayout.CENTER);

        acceptButton.addActionListener(e -> acceptRequest());
        rejectButton.addActionListener(e -> rejectRequest());

        updateLog("客服端启动完成，等待用户连接...");
    }

    private void startServer() {
        running = true;
        new Thread(() -> {
            try (ServerSocket ss = new ServerSocket(Constants.PORT)) {
                logArea.append("服务端已就绪，监听端口 " + Constants.PORT + "\n");
                while (running) {
                    Socket clientSocket = ss.accept();
                    createNewSession(clientSocket);
                }
            } catch (IOException e) {
                updateLog("服务器错误：" + e.getMessage());
            }
        }).start();
    }

    private void createNewSession(Socket socket) {
        ChatSession session = new ChatSession(this, socket, this::broadcastSystemMsg);
        synchronized (lock) {
            activeSessions.add(session);
        }
        session.start();
        updateLog("新用户连接: " + session.getUserId());
    }

    private void acceptRequest() {
        if (activeSessions.isEmpty()) {
            JOptionPane.showMessageDialog(this, "无待处理连接！");
            return;
        }
        ChatSession s = activeSessions.get(0);
        s.setAccepted(true);
        notifyUser(s, new Message(MessageType.TEXT, "agent", "你好，客服已为您服务。"));
        removeActiveSession(s);
        updateLog("已接受用户连接：" + s.getUserId());
    }

    private void rejectRequest() {
        if (activeSessions.isEmpty()) {
            JOptionPane.showMessageDialog(this, "无待处理连接！");
            return;
        }
        ChatSession s = activeSessions.get(0);
        notifyUser(s, new Message(MessageType.BUSY, "agent", "抱歉，当前客服繁忙，稍后再试。"));
        s.disconnect();
        removeActiveSession(s);
        updateLog("已拒绝用户连接：" + s.getUserId());
    }

    private void removeActiveSession(ChatSession session) {
        synchronized (lock) {
            activeSessions.remove(session);
        }
    }

    void broadcastSystemMsg(String message) {
        updateLog(message);
    }

    private void notifyUser(ChatSession session, Message msg) {
        try {
            session.send(msg);
        } catch (IOException e) {
            updateLog("通知用户失败: " + e.getMessage());
        }
    }

    private void updateLog(String message) {
        logArea.append(message + "\n");
        logArea.setCaretPosition(logArea.getDocument().getLength());
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new CustomerServiceServer().setVisible(true));
    }
}
