```java
package server;

import protocol.Message;
import utils.ChatRecordManager;
import utils.Constants;

import javax.swing.*;
import java.io.*;
import java.net.Socket;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Timer;
import java.util.TimerTask;

public class ChatSession extends Thread {
    private final CustomerServiceServer server;
    private final Socket socket;
    private final Runnable callback;
    private final List<Message> history = new ArrayList<>();
    private final String userId;
    private ObjectInputStream ois;
    private ObjectOutputStream oos;
    private volatile boolean accepted = false;
    private boolean stopped = false;

    public ChatSession(CustomerServiceServer server, Socket socket, Runnable callback) {
        this.server = server;
        this.socket = socket;
        this.callback = callback;
        this.userId = "user_" + socket.getInetAddress().getHostAddress();
        this.start();
    }

    public void run() {
        try {
            ois = new ObjectInputStream(socket.getInputStream());
            oos = new ObjectOutputStream(socket.getOutputStream());

            while (!stopped) {
                Message msg = (Message) ois.readObject();
                handleIncomingMessage(msg);
            }

        } catch (IOException | ClassNotFoundException e) {
            server.broadcastSystemMsg("用户 " + userId + " 断开：" + e.getMessage());
            disconnect();
        }
    }

    private void handleIncomingMessage(Message msg) {
        switch (msg.getType()) {
            case TEXT:
                if (!accepted) {
                    server.broadcastSystemMsg("用户 " + userId + " 请求服务，内容: " + msg.getContent());
                    notifyAgentAboutJoin();
                } else {
                    server.broadcastSystemMsg("用户: " + msg.getContent());
                    broadcastToAgent(msg);
                    saveMessage(msg);
                }
                break;
            case IMAGE:
                server.broadcastSystemMsg("用户发送图片");
                broadcastToAgent(msg);
                saveMessage(msg);
                break;
            case FILE:
                String fileName = msg.getContent();
                FileUtil.saveFileFromBytes(msg.getData(), "downloads/" + fileName);
                server.broadcastSystemMsg("用户上传文件: " + fileName);
                broadcastToAgent(msg);
                saveMessage(msg);
                break;
            case PING:
                send(new Message(Message.MessageType.PING, "agent", "pong"));
                break;
            default:
                server.broadcastSystemMsg("收到未知消息: " + msg.getType());
        }
    }

    private void notifyAgentAboutJoin() {
        send(new Message(Message.MessageType.JOIN, "user", "等待客服接入..."));
    }

    private void broadcastToAgent(Message msg) {
        server.broadcastSystemMsg("用户:" + msg.getContent());
    }

    public void send(Message msg) throws IOException {
        oos.writeObject(msg);
        oos.flush();
    }

    private void saveMessage(Message msg) {
        history.add(msg);
        ChatRecordManager.saveChatHistory(userId, history);
    }

    public void setAccepted(boolean accepted) {
        this.accepted = accepted;
        if (accepted) {
            send(new Message(Message.MessageType.TEXT, "agent", "欢迎，客服已就位。"));
        }
    }

    public String getUserId() {
        return userId;
    }

    public void disconnect() {
        try {
            if (ois != null) ois.close();
            if (oos != null) oos.close();
            if (socket != null) socket.close();
        } catch (IOException ignored) {}
        stopped = true;
    }

    public boolean isAccepted() {
        return accepted;
    }
}
