import com.sun.net.httpserver.HttpsConfigurator;
import com.sun.net.httpserver.HttpsServer;

import javax.net.ssl.*;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.security.KeyStore;

public class HttpsServerExample {

    public static void main(String[] args) {
        try {
            // Create HTTPS server on port 8443
            HttpsServer httpsServer = HttpsServer.create(new InetSocketAddress(8443), 0);

            // Configure SSL context
            SSLContext sslContext = SSLContext.getInstance("TLS");
            KeyStore keyStore = KeyStore.getInstance("PKCS12");
            keyStore.load(new java.io.FileInputStream("keystore.p12"), "changeit".toCharArray());

            KeyManagerFactory keyManagerFactory = KeyManagerFactory.getInstance("SunX509");
            keyManagerFactory.init(keyStore, "changeit".toCharArray());

            TrustManagerFactory trustManagerFactory = TrustManagerFactory.getInstance("SunX509");
            trustManagerFactory.init(keyStore); // Using same keystore as trust (self-signed)

            sslContext.init(keyManagerFactory.getKeyManagers(), trustManagerFactory.getTrustManagers(), null);

            // Set up HTTPS configuration
            httpsServer.setHttpsConfigurator(new HttpsConfigurator(sslContext));

            // Define a simple handler
            httpsServer.createContext("/", exchange -> {
                String response = "<h1>Hello from HTTPS Server!</h1><p>Connected securely.</p>";
                exchange.sendResponseHeaders(200, response.length());
                exchange.getResponseBody().write(response.getBytes());
                exchange.close();
            });

            // Start server
            httpsServer.start();
            System.out.println("HTTPS Server started on https://localhost:8443");

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

