## ✅ 完整代码如下：

```java
import com.sun.net.httpserver.*;
import java.io.*;
import java.net.InetSocketAddress;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;

public class ImageUploadServer {

    private static final String UPLOAD_DIR = "upload/";
    private static final String DEFAULT_FILE_NAME = "uploaded_image";

    public static void main(String[] args) {
        // 确保上传目录存在
        Path uploadPath = Paths.get(UPLOAD_DIR);
        if (!Files.exists(uploadPath)) {
            try {
                Files.createDirectories(uploadPath);
            } catch (IOException e) {
                System.err.println("无法创建上传目录: " + UPLOAD_DIR);
                return;
            }
        }

        HttpServer server = null;
        try {
            server = HttpServer.create(new InetSocketAddress(8080), 0);
        } catch (IOException e) {
            System.err.println("启动服务器失败：" + e.getMessage());
            return;
        }

        HttpContext context = server.createContext("/upload");
        context.setHandler(new ImageUploadHandler());

        server.start();
        System.out.println("✅ 服务端已启动，监听端口 8080");
        System.out.println("📌 上传接口：POST http://localhost:8080/upload");
    }

    static class ImageUploadHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            try {
                if ("POST".equals(exchange.getRequestMethod())) {
                    Headers headers = exchange.getRequestHeaders();
                    String contentTypeHeader = headers.getFirst("Content-Type");

                    if (contentTypeHeader == null || !contentTypeHeader.contains("multipart/form-data")) {
                        sendResponse(exchange, 400, "Content-Type 必须是 multipart/form-data");
                        return;
                    }

                    // 从 header 取 boundary
                    String boundary = getBoundary(contentTypeHeader);
                    if (boundary == null) {
                        sendResponse(exchange, 400, "无法解析 boundary");
                        return;
                    }

                    // 读取请求体
                    InputStream inputStream = exchange.getRequestBody();
                    byte[] bodyBytes = inputStream.readAllBytes();

                    // 手动解析 multipart
                    Map<String, byte[]> fields = parseMultipart(bodyBytes, boundary);

                    if (fields.isEmpty()) {
                        sendResponse(exchange, 400, "没有收到有效数据");
                        return;
                    }

                    // 查找图片字段（通常是 "file"）
                    byte[] imageData = fields.get("file"); // 假设前端传的是 "file"
                    if (imageData == null || imageData.length == 0) {
                        sendResponse(exchange, 400, "未找到文件数据");
                        return;
                    }

                    // 生成文件名
                    String fileName = findFileName(fields, "file"); // 也可以从表单中获取
                    if (fileName == null || fileName.isEmpty()) {
                        fileName = DEFAULT_FILE_NAME;
                    }

                    // 写入文件
                    String extension = getFileExtension(fileName);
                    Path filePath = Paths.get(UPLOAD_DIR + fileName + "." + extension);
                    Files.write(filePath, imageData);

                    sendResponse(exchange, 200, "✅ 图片上传成功！已保存至: " + filePath);

                } else {
                    sendResponse(exchange, 405, "仅支持 POST 方法");
                }
            } catch (Exception e) {
                e.printStackTrace();
                sendResponse(exchange, 500, "服务器内部错误: " + e.getMessage());
            }
        }

        // 手动提取 boundary
        private String getBoundary(String contentTypeHeader) {
            String[] parts = contentTypeHeader.split(";");
            for (String part : parts) {
                part = part.trim();
                if (part.startsWith("boundary=")) {
                    return part.substring(9); // 去掉 "boundary="
                }
            }
            return null;
        }

        // 解析 multipart/form-data
        private Map<String, byte[]> parseMultipart(byte[] body, String boundary) {
            Map<String, byte[]> result = new HashMap<>();
            String prefix = "--" + boundary;
            String suffix = "--" + boundary + "--";

            String bodyStr = new String(body, "UTF-8");
            String[] parts = bodyStr.split(prefix);

            for (int i = 1; i < parts.length; i++) {
                String part = parts[i];
                if (part.endsWith(suffix)) {
                    part = part.replace(suffix, "");
                }

                int headerEnd = part.indexOf("\r\n\r\n");
                if (headerEnd == -1) continue;

                String header = part.substring(0, headerEnd);
                String content = part.substring(headerEnd + 4); // 跳过 \r\n\r\n

                // 初步判断字段名
                if (header.contains("name=\"file\"") || header.contains("filename=")) {
                    // 假设这是上传的文件
                    result.put("file", content.getBytes());
                } else {
                    // 其他字段忽略，只关注 file
                    // 此处可扩展对其他字段的处理
                }
            }

            return result;
        }

        // 获取文件扩展名
        private String getFileExtension(String fileName) {
            int lastDot = fileName.lastIndexOf('.');
            if (lastDot >= 0 && lastDot < fileName.length() - 1) {
                return fileName.substring(lastDot + 1).toLowerCase();
            }
            return "bin"; // 未知类型
        }

        // 从头部中尝试获取原始文件名
        private String findFileName(Map<String, byte[]> fields, String fieldName) {
            for (String key : fields.keySet()) {
                if (key.equals(fieldName)) {
                    // 这里可以进一步从 multipart 头部提取文件名，简化版返回默认值
                    // 实际使用应更完整解析头信息
                    return "image";
                }
            }
            return "unknown";
        }

        // 发送响应
        private void sendResponse(HttpExchange exchange, int code, String message) throws IOException {
            exchange.sendResponseHeaders(code, message.length());
            OutputStream os = exchange.getResponseBody();
            os.write(message.getBytes("UTF-8"));
            os.close();
        }
    }
}
```

