// TaskManager.java
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class TaskManager {
    private static final ExecutorService WORKER_POOL = Executors.newFixedThreadPool(4); // Adjust based on PC cores
    private static final int PORT = 8080;
    private final InetSocketAddress ANDROID_ADDRESS;

    public TaskManager(String androidIP) {
        this.ANDROID_ADDRESS = new InetSocketAddress(androidIP, PORT);
    }

    // Split large workloads into subtasks
    public <T> List<Task<T>> splitWork(long totalWork, int numPartitions, Supplier<Task<T>> supplier) {
        List<Task<T>> tasks = new ArrayList<>();
        long chunkSize = totalWork / numPartitions;
        long current = 0;

        for (int i = 0; i < numPartitions; i++) {
            long end = Math.min(current + chunkSize, totalWork);
            tasks.add(supplier.get());
            current = end;
        }

        return tasks;
    }

    // Submit tasks to Android over network
    public void submitToAndroid(List<Task<?>> tasks) throws IOException {
        try (Socket socket = new Socket()) {
            socket.connect(ANDROID_ADDRESS, 5000); // 5s timeout

            try (ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream())) {
                out.writeObject(tasks);
                out.flush();
                System.out.println("✅ Sent " + tasks.size() + " tasks to Android");
            }

            try (ObjectInputStream in = new ObjectInputStream(socket.getInputStream())) {
                Object result = in.readObject();
                System.out.println("🔄 Received result: " + result);
            }
        }
    }

    // Submit tasks to local PC for processing
    public <T> CompletableFuture<List<T>> submitToLocalTasks(List<Task<T>> tasks) {
        return CompletableFuture.supplyAsync(() -> {
            List<T> results = new ArrayList<>();
            for (Task<T> task : tasks) {
                try {
                    T result = task.execute();
                    results.add(result);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return results;
        }, WORKER_POOL);
    }

    // Launch task pipeline
    public void runWorkload(long start, long end) {
        int numParts = Runtime.getRuntime().availableProcessors(); // Or dynamically tune per CPU load
        List<Task<Integer>> tasks = splitWork(end - start, numParts, () ->
            new PrimeCountTask((int)start, (int)end));

        // Dispatch half to Android, rest to local PC (example logic)
        int half = tasks.size() / 2;
        List<Task<Integer>> localTasks = new ArrayList<>(tasks.subList(0, half));
        List<Task<Integer>> androidTasks = new ArrayList<>(tasks.subList(half, tasks.size()));

        // Run concurrently
        CompletableFuture<List<Integer>> pcFuture = submitToLocalTasks(localTasks);

        try {
            submitToAndroid(androidTasks);
        } catch (IOException e) {
            System.err.println("Failed to send to Android: " + e.getMessage());
        }

        // Wait for PC result and aggregate
        try {
            List<Integer> pcResults = pcFuture.get();
            int totalPrimes = pcResults.stream().mapToInt(Integer::intValue).sum();

            // Simulate receiving Android result later... (would use callback/event system in production)
            System.out.println("🚀 Total primes found: " + totalPrimes);

            // In real app: await Android result via dedicated listener/thread
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        TaskManager tm = new TaskManager("192.168.1.101"); // IP of Android device on same LAN
        tm.runWorkload(1, 1_000_000);
    }
}
```

