import org.bytedeco.javacv.*;
import org.bytedeco.opencv.opencv_core.*;
import org.bytedeco.opencv.opencv_videoio.*;

import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;

public class H264VideoServer {

    public static void main(String[] args) {
        // 启动 JavaFX UI 线程
        javafx.application.Application.launch(VideoDisplayApp.class, args);
    }

    // 模拟接收线程 - 实际可以从一个连接中读取流
    public static void startStreaming() {
        try (ServerSocket serverSocket = new ServerSocket(5000)) {
            System.out.println("服务器启动，监听端口 5000...");

            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("客户端连接: " + clientSocket.getInetAddress());

                // 创建独立线程处理每个客户端
                new Thread(() -> {
                    try (BufferedInputStream in = new BufferedInputStream(clientSocket.getInputStream());
                         ByteArrayOutputStream out = new ByteArrayOutputStream()) {

                        int bytesRead;
                        byte[] buffer = new byte[1024];

                        // 从客户端持续读取数据
                        while ((bytesRead = in.read(buffer)) != -1) {
                            out.write(buffer, 0, bytesRead);

                            // 尝试从缓冲中提取 H.264 NAL 单元
                            byte[] data = out.toByteArray();
                            decodeAndShow(data);
                            out.reset(); // 清空缓冲区
                        }
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }).start();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 解码并显示视频帧
    private static void decodeAndShow(byte[] data) {
        if (data.length == 0) return;

        // JavaCV 的 VideoInputFrame 暂不支持直接解码字节流
        // 更推荐使用 FFmpeg 通过 InputStream 调用
        try (FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(new ByteArrayInputStream(data))) {
            grabber.setOption("codec", "h264");
            grabber.start();

            Frame frame = null;
            while ((frame = grabber.grabFrame()) != null) {
                // 显示到 JavaFX
                VideoDisplayApp.showFrame(frame.getMaterial());
            }

            grabber.stop();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

