public class GameLogic {
    private char[][] board = new char[3][3];
    private char currentPlayer = 'X';
    private boolean gameOver = false;

    public GameLogic() {
        resetBoard();
    }

    public void resetBoard() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                board[i][j] = ' ';
            }
        }
        currentPlayer = 'X';
        gameOver = false;
    }

    public boolean makeMove(int row, int col) {
        if (board[row][col] != ' ' || gameOver) return false;

        board[row][col] = currentPlayer;
        if (checkWin(row, col)) {
            gameOver = true;
            return true;
        }
        if (isBoardFull()) {
            gameOver = true;
            return false;
        }
        switchPlayer();
        return true;
    }

    private boolean checkWin(int row, int col) {
        char c = board[row][col];
        // Check row
        if (board[row][0] == c && board[row][1] == c && board[row][2] == c) return true;
        // Check col
        if (board[0][col] == c && board[1][col] == c && board[2][col] == c) return true;
        // Check diagonal
        if (row == col && board[0][0] == c && board[1][1] == c && board[2][2] == c) return true;
        if (row + col == 2 && board[0][2] == c && board[1][1] == c && board[2][0] == c) return true;
        return false;
    }

    private boolean isBoardFull() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == ' ') return false;
            }
        }
        return true;
    }

    private void switchPlayer() {
        currentPlayer = (currentPlayer == 'X') ? 'O' : 'X';
    }

    public char getCurrentPlayer() {
        return currentPlayer;
    }

    public boolean isGameOver() {
        return gameOver;
    }

    public char getCell(int row, int col) {
        return board[row][col];
    }

    public char[][] getBoard() {
        return board;
    }

    public char getWinner() {
        if (gameOver) {
            // Check win condition again safely
            for (int i = 0; i < 3; i++) {
                if (board[i][0] == board[i][1] && board[i][1] == board[i][2] && board[i][0] != ' ')
                    return board[i][0];
                if (board[0][i] == board[1][i] && board[1][i] == board[2][i] && board[0][i] != ' ')
                    return board[0][i];
            }
            if (board[0][0] == board[1][1] && board[1][1] == board[2][2] && board[0][0] != ' ')
                return board[0][0];
            if (board[0][2] == board[1][1] && board[1][1] == board[2][0] && board[0][2] != ' ')
                return board[0][2];
        }
        return ' ';
    }
}
```

