import java.net.ServerSocket;
import java.net.Socket;

public class Server extends Application {
    private GameLogic gameLogic = new GameLogic();
    private Socket clientSocket;
    private ObjectOutputStream out;
    private ObjectInputStream in;

    @Override
    public void start(Stage stage) throws Exception {
        VBox root = new VBox(10);
        root.setPrefSize(400, 300);

        Label statusLabel = new Label("Waiting for player to join...");
        Button btnReset = new Button("Reset Game");

        btnReset.setOnAction(e -> {
            gameLogic.resetBoard();
            sendStatusUpdate();
        });

        root.getChildren().addAll(statusLabel, btnReset);

        Scene scene = new Scene(root);
        stage.setTitle("Tic Tac Toe - Server (Host)");
        stage.setScene(scene);
        stage.show();

        // Start server thread
        new Thread(() -> {
            try (ServerSocket serverSocket = new ServerSocket(8888)) {
                System.out.println("Server waiting for connection on port 8888...");
                clientSocket = serverSocket.accept();
                System.out.println("Client connected!");

                out = new ObjectOutputStream(clientSocket.getOutputStream());
                in = new ObjectInputStream(clientSocket.getInputStream());

                // Send initial state
                sendStatusUpdate();

                while (!gameLogic.isGameOver()) {
                    // Wait for move from client
                    Integer[] move = (Integer[]) in.readObject();
                    int row = move[0], col = move[1];

                    if (gameLogic.makeMove(row, col)) {
                        Platform.runLater(() -> {
                            statusLabel.setText("Player O moved. Your turn.");
                        });
                        sendStatusUpdate();
