                            }
                            gameLogic.currentPlayer = player;
                            if (over) {
                                statusLabel.setText("Game Over!");
                            } else {
                                statusLabel.setText("Your turn (" + player + ")");
                            }
                        });
                    }
                }

            } catch (Exception e) {
                e.printStackTrace();
            }
        }).start();
    }

