```java
import org.bytedeco.javacv.*;
import org.bytedeco.opencv.opencv_core;

import java.io.*;
import java.net.*;

public class VideoStreamSender {
    public static void main(String[] args) {
        // 1. 打开摄像头（0 代表默认摄像头）
        FrameGrabber grabber = FrameGrabber.createDefault(0);
        try {
            grabber.start();

            // 2. 创建输出流连接目标地址（如本地 8080 端口）
            Socket socket = new Socket("localhost", 8080); // 接收端监听此端口
            ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());

            System.out.println("正在发送视频流...");

            // 3. 获取帧并转换为字节数组发送
            Frame frame;
            while ((frame = grabber.grab()) != null) {
                // 转换为 Mat
                opencv_core.Mat mat = new opencv_core.Mat();
                OpenCVFrameConverter.ToMat converter = new OpenCVFrameConverter.ToMat();
                converter.convert(frame, mat);

                // 将 Mat 转成 JPEG 二进制数据
                byte[] imageBytes = toJPEGBytes(mat);

                // 只发送图像是关键，可加帧索引或时间戳
                out.writeInt(imageBytes.length); // 首先发送长度
                out.write(imageBytes);
                out.flush();

                // 可选：控制帧率（每秒 10 帧）
                Thread.sleep(100);
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                if (grabber != null) grabber.stop();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    // 将 Mat 转换为 JPEG 字节数组
    private static byte[] toJPEGBytes(opencv_core.Mat mat) {
        // 保存为临时内存缓冲区
        try (MemoryBuffer buffer = new MemoryBuffer()) {
            // 保存为 JPEG 到缓冲区
            BufferedImage image = new OpenCVFrameConverter.ToImage().convert(mat);
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            javax.imageio.ImageIO.write(image, "jpg", baos);
            return baos.toByteArray();
        } catch (Exception e) {
            e.printStackTrace();
            return new byte[0];
        }
    }
}
```

