import org.json.JSONObject;
import java.util.Date;

public class ChatMessage {
    private String type;        // TEXT, IMAGE, FILE, LOGIN, CLOSE, STATUS
    private String sender;      // "customer" / "agent"
    private String content;     // 文本内容或文件路径
    private byte[] data;        // 图片/文件数据
    private Date timestamp;

    public ChatMessage(String type, String sender, String content, byte[] data) {
        this.type = type;
        this.sender = sender;
        this.content = content;
        this.data = data;
        this.timestamp = new Date();
    }

    // Getters and Setters
    public String getType() { return type; }
    public void setType(String type) { this.type = type; }

    public String getSender() { return sender; }
    public void setSender(String sender) { this.sender = sender; }

    public String getContent() { return content; }
    public void setContent(String content) { this.content = content; }

    public byte[] getData() { return data; }
    public void setData(byte[] data) { this.data = data; }

    public Date getTimestamp() { return timestamp; }
    public void setTimestamp(Date timestamp) { this.timestamp = timestamp; }

    public JSONObject toJson() {
        JSONObject json = new JSONObject();
        json.put("type", type);
        json.put("sender", sender);
        json.put("content", content);
        json.put("timestamp", timestamp.getTime());
        return json;
    }

    public static ChatMessage fromJson(JSONObject json) {
        String type = json.getString("type");
        String sender = json.getString("sender");
        String content = json.getString("content");
        long timeMillis = json.getLong("timestamp");
        ChatMessage msg = new ChatMessage(type, sender, content, null);
        msg.setTimestamp(new Date(timeMillis));
        return msg;
    }
}
