        chatArea.append(msg + "\n");
        chatArea.setCaretPosition(chatArea.getDocument().getLength());
    }

    private void saveMessageToLocal(ChatMessage msg) {
        messageHistory.add(msg);
        ensureRecordDirExists();

        try (FileWriter fw = new FileWriter(RECORD_FILE_NAME, true)) {
            fw.write(msg.toJson().toString());
            fw.write("\n");
        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "无法保存聊天记录", "错误", JOptionPane.ERROR_MESSAGE);
        }
    }

    private void loadHistory() {
        File recordFile = new File(RECORD_FILE_NAME);
        if (!recordFile.exists()) return;

        try (BufferedReader reader = new BufferedReader(new FileReader(recordFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                try {
                    JSONObject json = new JSONObject(line);
                    if ("TEXT".equals(json.getString("type"))) {
                        String content = json.getString("content");
                        String sender = json.getString("sender");
                        appendMessage(sender + ": " + content);
                    }
                } catch (Exception ignored) {}
            }
        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "读取历史记录失败！", "错误", JOptionPane.ERROR_MESSAGE);
        }
    }

    private void ensureRecordDirExists() {
        File dir = new File(RECORD_DIR);
        if (!dir.exists()) dir.mkdirs();
    }

