```java
package com.ecommerce.server;

import javax.swing.*;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class CustomerServer {
    private static final int PORT = 8888;
    private static Map<String, CustomerSession> sessions = new ConcurrentHashMap<>();
    private static Set<String> busyUsers = new HashSet<>();

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame frame = new JFrame("客服管理台");
            frame.setSize(600, 400);
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.setLayout(new BorderLayout());

            JTextArea logArea = new JTextArea();
            logArea.setEditable(false);
            JScrollPane scroll = new JScrollPane(logArea);
            frame.add(scroll, BorderLayout.CENTER);

            JButton btnRestart = new JButton("重启服务");
            btnRestart.addActionListener(e -> {
                try {
                    ServerSocket serverSocket = new ServerSocket(PORT);
                    logArea.setText("✅ 服务已启动（端口 " + PORT + "）\n");
                    new Thread(() -> {
                        while (true) {
                            try {
                                Socket client = serverSocket.accept();
                                CustomerConnectionHandler handler =
                                        new CustomerConnectionHandler(client, logArea, frames);
                                new Thread(handler).start();
                            } catch (IOException ignored) {}
                        }
                    }).start();
                } catch (IOException ex) {
                    JOptionPane.showMessageDialog(null, "启动失败：" + ex.getMessage());
                }
            });

            frame.add(btnRestart, BorderLayout.SOUTH);
            frame.setVisible(true);
        });

        // 启动服务
        startServer();
    }

    private static void startServer() {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("✅ 客服服务已启动在端口 " + PORT);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                CustomerConnectionHandler handler = new CustomerConnectionHandler(clientSocket, null, null);
                new Thread(handler).start();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 一个用户会话的包装类
    static class CustomerSession {
        Socket socket;
        BufferedReader in;
        PrintWriter out;
        String customerName;
        boolean isBusy;

        CustomerSession(Socket sock) {
            this.socket = sock;
            this.isBusy = false;
            try {
                this.in = new BufferedReader(new InputStreamReader(sock.getInputStream()));
                this.out = new PrintWriter(sock.getOutputStream(), true);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        void sendMessage(ChatMessage msg) {
            out.println(msg.toJson().toString());
        }
    }

    static class CustomerConnectionHandler implements Runnable {
        private Socket socket;
        private BufferedReader in;
        private PrintWriter out;
        private JTextArea logArea;  // 日志输出用
        private JFrame parentFrame;

        private String customerName;
        private CustomerSession session;

        public CustomerConnectionHandler(Socket socket, JTextArea logArea, JFrame parentFrame) {
            this.socket = socket;
            this.logArea = logArea;
            this.parentFrame = parentFrame;

            try {
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                out = new PrintWriter(socket.getOutputStream(), true);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        @Override
        public void run() {
            try {
                String line;
                while ((line = in.readLine()) != null) {
                    try {
                        JSONObject json = new JSONObject(line);
                        String type = json.getString("type");

                        if ("LOGIN".equals(type)) {
                            customerName = json.getString("content");
                            session = new CustomerSession(socket);
                            sessions.put(customerName, session);
                            showRequestPopup(customerName);
                        } else if ("TEXT".equals(type)) {
                            String content = json.getString("content");
                            broadcastMessage(customerName, "agent", content);
                        } else if ("IMAGE".equals(type)) {
                            String fileName = json.getString("content");
                            byte[] data = Base64.getDecoder().decode(json.getString("data"));
                            ChatMessage msg = new ChatMessage("IMAGE", "agent", fileName, data);
                            broadcastMessage(customerName, "agent", "[图片] " + fileName);
                            session.sendMessage(msg);
                        } else if ("FILE".equals(type)) {
                            String fileName = json.getString("content");
                            byte[] data = Base64.getDecoder().decode(json.getString("data"));
                            ChatMessage msg = new ChatMessage("FILE", "agent", fileName, data);
                            session.sendMessage(msg);
                            broadcastMessage(customerName, "agent", "[文件] " + fileName);
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            } catch (IOException e) {
                System.out.println("Client disconnected: " + customerName);
                sessions.remove(customerName);
                notifyAgent("User disconnected: " + customerName);
            }
        }

        private void showRequestPopup(final String userName) {
            SwingUtilities.invokeLater(() -> {
                int result = JOptionPane.showConfirmDialog(
                        parentFrame,
                        "用户 " + userName + " 请求服务，是否接收？",
                        "新会话请求",
                        JOptionPane.YES_NO_OPTION,
                        JOptionPane.QUESTION_MESSAGE
                );

                if (result == JOptionPane.YES_OPTION) {
                    sessions.get(userName).isBusy = true;
                    sessions.get(userName).sendMessage(new ChatMessage("STATUS", "service", "available", null));
                    notifyAgent("✅ 已接通用户: " + userName);
                } else {
                    sessions.get(userName).sendMessage(new ChatMessage("STATUS", "service", "busy", null));
                    notifyAgent("🚩 拒绝用户: " + userName);
                }
            });
        }

        private void broadcastMessage(String toUser, String from, String content) {
            CustomerSession s = sessions.get(toUser);
            if (s != null) {
                try {
                    ChatMessage msg = new ChatMessage("TEXT", from, content, null);
                    s.sendMessage(msg);
                    if (logArea != null) {
                        logArea.append("📩 " + from + " ➤ " + toUser + ": " + content + "\n");
                    }
                } catch (Exception ignored) {}
            }
        }

        private void notifyAgent(String msg) {
            if (logArea != null) {
                logArea.append("🔔 " + msg + "\n");
                logArea.setCaretPosition(logArea.getDocument().getLength());
            }
        }
    }
}
