        loadAdminPassword();
        loadPlayers();
    }

    private void loadAdminPassword() {
        try (BufferedReader reader = new BufferedReader(new FileReader(ADMIN_FILENAME))) {
            adminPasswordHash = reader.readLine().trim();
            if (adminPasswordHash == null || adminPasswordHash.isEmpty()) {
                throw new IOException("admin.txt is empty.");
            }
        } catch (IOException ex) {
            System.out.println("Error reading admin.txt: " + ex.getMessage());
            System.exit(1);
        }
    }

    private void loadPlayers() {
        try (FileInputStream fis = new FileInputStream(PLAYERS_FILENAME);
             ObjectInputStream ois = new ObjectInputStream(fis)) {

            boolean endOfFile = false;
            while (!endOfFile) {
                try {
                    Player player = (Player) ois.readObject();
                    players.add(player);
                } catch (EOFException e) {
                    endOfFile = true;
                }
            }

        } catch (IOException | ClassNotFoundException ex) {
            System.out.println("No existing players.bin found. Creating new one.");
            players = new ArrayList<>();
        }
    }

    private void savePlayers() {
        try (FileOutputStream fos = new FileOutputStream(PLAYERS_FILENAME);
             ObjectOutputStream oos = new ObjectOutputStream(fos)) {

            for (Player player : players) {
                oos.writeObject(player);
            }
            System.out.println("Players saved successfully.");

        } catch (IOException ex) {
            System.out.println("Error saving players.bin: " + ex.getMessage());
        }
    }

