import java.io.*;
import java.net.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

public class Server {
    public static void main(String[] args) {
        // 监听端口
        int port = 8888;
        System.out.println("服务器启动，监听端口 " + port + " ...");

        try (ServerSocket serverSocket = new ServerSocket(port)) {
            while (true) {
                try (Socket clientSocket = serverSocket.accept();
                     BufferedReader in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
                     PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true)) {

                    System.out.println("客户端已连接：" + clientSocket.getInetAddress());

                    String request = in.readLine();
                    if (request == null || request.isEmpty()) continue;

                    System.out.println("收到客户端请求: " + request);

                    // 解析请求
                    if (request.startsWith("From ") && request.contains(":")) {
                        String[] parts = request.split(":", 2);
                        String header = parts[0].trim();
                        String content = parts[1].trim();

                        // 提取学号和姓名
                        String[] info = header.split(" ", 3); // From 学号 姓名
                        if (info.length < 3) {
                            out.println("To Error: 格式错误，请按 'From 学号 姓名：内容' 发送");
                            continue;
                        }

                        String studentId = info[1];
                        String name = info[2];

                        if (content.equalsIgnoreCase("what time is it")) {
                            LocalDateTime now = LocalDateTime.now();
                            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
                            String currentTime = now.format(formatter);
                            String response = "To " + name + ": " + currentTime;
                            out.println(response);
                            System.out.println("回复客户端: " + response);

                        } else if (content.equalsIgnoreCase("exit")) {
                            String response = "To " + name + ": Bye";
                            out.println(response);
                            System.out.println("回复客户端退出消息: " + response);
                            break; // 退出本次客户端连接循环，但服务器继续运行

                        } 
                    } 

                    // 如果不是合法命令，提示错误
                    else {
                        out.println("To Error: 不支持的指令，请使用 'what time is it' or 'exit'");
                    }

                } catch (IOException e) {
                    System.err.println("客户端通信异常：" + e.getMessage());
                }
            }
        } catch (IOException e) {
            System.err.println("服务器启动失败：" + e.getMessage());
        }
    }
}
```

