## ✅ 七、DAO 层（JDBC 模板）

### `src/main/java/com/example/dao/CustomerDao.java`

```java
package com.example.dao;

import com.example.model.Customer;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;

@Repository
public class CustomerDao {

    private final JdbcTemplate jdbcTemplate;

    public CustomerDao(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    // 插入客户信息
    public void insert(Customer customer) {
        String sql = "INSERT INTO customers (unit_id, customer_name, phone, mobile, qq, email) VALUES (?, ?, ?, ?, ?, ?)";
        jdbcTemplate.update(sql, customer.getUnitId(), customer.getCustomerName(),
                customer.getPhone(), customer.getMobile(), customer.getQq(), customer.getEmail());
    }

    // 更新客户信息
    public void update(Customer customer) {
        String sql = "UPDATE customers SET unit_id=?, customer_name=?, phone=?, mobile=?, qq=?, email=? WHERE id=?";
        jdbcTemplate.update(sql, customer.getUnitId(), customer.getCustomerName(),
                customer.getPhone(), customer.getMobile(), customer.getQq(), customer.getEmail(), customer.getId());
    }

    // 删除客户
    public void delete(int id) {
        String sql = "DELETE FROM customers WHERE id=?";
        jdbcTemplate.update(sql, id);
    }

    // 查询所有客户
    public List<Customer> findAll() {
        String sql = "SELECT c.*, d.name AS department_name FROM customers c JOIN departments d ON c.unit_id = d.id";
        return jdbcTemplate.query(sql, new RowMapper<Customer>() {
            @Override
            public Customer mapRow(ResultSet rs, int rowNum) throws SQLException {
                Customer c = new Customer();
                c.setId(rs.getInt("id"));
                c.setUnitId(rs.getInt("unit_id"));
                c.setCustomerName(rs.getString("customer_name"));
                c.setPhone(rs.getString("phone"));
                c.setMobile(rs.getString("mobile"));
                c.setQq(rs.getString("qq"));
                c.setEmail(rs.getString("email"));
                c.setCreateTime(rs.getTimestamp("create_time"));
                return c;
            }
        });
    }

    // 根据条件模糊查询
    public List<Customer> search(String keyword, Integer unitId) {
        StringBuilder sql = new StringBuilder(
                "SELECT c.*, d.name AS department_name FROM customers c JOIN departments d ON c.unit_id = d.id WHERE 1=1");

        if (keyword != null && !keyword.trim().isEmpty()) {
            sql.append(" AND (c.customer_name LIKE ? OR c.mobile LIKE ? OR d.name LIKE ?)");
        }
        if (unitId != null) {
            sql.append(" AND c.unit_id = ?");
        }

        List<Customer> result = jdbcTemplate.query(sql.toString(), new RowMapper<Customer>() {
            @Override
            public Customer mapRow(ResultSet rs, int rowNum) throws SQLException {
                Customer c = new Customer();
                c.setId(rs.getInt("id"));
                c.setUnitId(rs.getInt("unit_id"));
                c.setCustomerName(rs.getString("customer_name"));
                c.setPhone(rs.getString("phone"));
                c.setMobile(rs.getString("mobile"));
                c.setQq(rs.getString("qq"));
                c.setEmail(rs.getString("email"));
                c.setCreateTime(rs.getTimestamp("create_time"));
                return c;
            }
        });

        return result;
    }

    // 获取某个单位的子单位（用于级联）
    public List<Department> findByParentId(Integer parentId) {
        String sql = "SELECT * FROM departments WHERE parent_id = ?";
        return jdbcTemplate.query(sql, new RowMapper<Department>() {
            @Override
            public Department mapRow(ResultSet rs, int rowNum) throws SQLException {
                Department d = new Department();
                d.setId(rs.getInt("id"));
                d.setName(rs.getString("name"));
                d.setParentId(rs.getInt("parent_id"));
                d.setLevel(rs.getInt("level"));
                return d;
            }
        }, parentId);
    }

    // 获取所有一级单位
    public List<Department> getAllTopUnits() {
        String sql = "SELECT * FROM departments WHERE parent_id IS NULL ORDER BY name";
        return jdbcTemplate.query(sql, new RowMapper<Department>() {
            @Override
            public Department mapRow(ResultSet rs, int rowNum) throws SQLException {
                Department d = new Department();
                d.setId(rs.getInt("id"));
                d.setName(rs.getString("name"));
                d.setParentId(rs.getInt("parent_id"));
                d.setLevel(rs.getInt("level"));
                return d;
            }
        });
    }
}
