package com.example.service;

import com.example.dao.CustomerDao;
import com.example.model.Customer;
import com.example.model.Department;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class CustomerService {

    @Autowired
    private CustomerDao customerDao;

    public void saveCustomer(Customer customer) {
        customerDao.insert(customer);
    }

    public void updateCustomer(Customer customer) {
        customerDao.update(customer);
    }

    public void deleteCustomer(int id) {
        customerDao.delete(id);
    }

    public List<Customer> getAllCustomers() {
        return customerDao.findAll();
    }

    public List<Customer> searchCustomers(String keyword, Integer unitId) {
        return customerDao.search(keyword, unitId);
    }

    public List<Department> getAllTopUnits() {
        return customerDao.getAllTopUnits();
    }

    public List<Department> getChildrenByParentId(Integer parentId) {
        return customerDao.findByParentId(parentId);
    }
}
