## ✅ 十、Servlet 控制器

### `src/main/java/com/example/web/CustomerServlet.java`

```java
package com.example.web;

import com.example.model.Customer;
import com.example.service.CustomerService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;

import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.List;

@Controller
@RequestMapping("/CustomerServlet")
public class CustomerServlet {

    @Autowired
    private CustomerService customerService;

    @GetMapping
    public void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("add".equals(action)) {
            handleAdd(req, resp);
        } else if ("query".equals(action)) {
            handleQuery(req, resp);
        } else if ("edit".equals(action)) {
            handleEdit(req, resp);
        } else if ("delete".equals(action)) {
            handleDelete(req, resp);
        } else {
            // 显示所有客户
            handleList(req, resp);
        }
    }

    @PostMapping
    public void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        handleAdd(req, resp);
    }

    private void handleAdd(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        Customer c = new Customer();
        c.setUnitId(Integer.parseInt(req.getParameter("dept3")));
        c.setCustomerName(req.getParameter("customerName"));
        c.setPhone(req.getParameter("phone"));
        c.setMobile(req.getParameter("mobile"));
        c.setQq(req.getParameter("qq"));
        c.setEmail(req.getParameter("email"));

        customerService.saveCustomer(c);
        resp.sendRedirect("listCustomers.jsp");
    }

    private void handleQuery(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String keyword = req.getParameter("nameLike");
        Integer unitId = req.getParameter("unitId") == null || req.getParameter("unitId").isEmpty()
                ? null : Integer.parseInt(req.getParameter("unitId"));

        List<Customer> results = customerService.searchCustomers(keyword, unitId);
        req.setAttribute("results", results);
        req.setAttribute("keyword", keyword);
        req.setAttribute("unitId", unitId);
        req.getRequestDispatcher("/views/queryCustomer.jsp").forward(req, resp);
    }

    private void handleList(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        List<Customer> customers = customerService.getAllCustomers();
        req.setAttribute("customers", customers);
        req.getRequestDispatcher("/views/listCustomers.jsp").forward(req, resp);
    }

    private void handleEdit(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        int id = Integer.parseInt(req.getParameter("id"));
        // 简化：跳转到编辑页（可扩展）
        resp.sendRedirect("addCustomer.jsp?id=" + id);
    }

    private void handleDelete(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        int id = Integer.parseInt(req.getParameter("id"));
        customerService.deleteCustomer(id);
        resp.sendRedirect("listCustomers.jsp");
    }
}
```

