```java
package com.example.web;

import com.example.service.CustomerService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseBody;

import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.List;

@Controller
@RequestMapping("/DeptAjaxServlet")
public class DeptAjaxServlet {

    @Autowired
    private CustomerService customerService;

    @GetMapping
    @ResponseBody
    public void getChildren(@RequestParam("parentId") Integer parentId, HttpServletResponse resp) throws IOException {
        List<com.example.model.Department> children = customerService.getChildrenByParentId(parentId);
        PrintWriter out = resp.getWriter();
        out.println("[");
        for (int i = 0; i < children.size(); i++) {
            com.example.model.Department d = children.get(i);
            out.print("{id:" + d.getId() + ",name:'" + d.getName() + "'}");
            if (i < children.size() - 1) out.print(",");
        }
        out.println("]");
    }
}
