    <dependency>
        <groupId>com.github.brandonlamb</groupId>
        <artifactId>ffmpeg-java</artifactId>
        <version>1.4.0</version>
    </dependency>

    <!-- 可选：用于处理 BufferedImage -->
    <dependency>
        <groupId>org.apache.commons</groupId>
