import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.file.Files;
import java.nio.file.Paths;

public class ImageToH264Streamer {

    // 输入图片路径
    private static final String IMAGE_PATH = "input.jpg";
    // 输出临时 h264 流文件
    private static final String OUTPUT_H264 = "output.h264";

    public static void main(String[] args) {
        try {
            // 步骤1: 读取图片并转为 BMP 格式（FFmpeg 一般接受 BMP 作为输入）
            BufferedImage image = javax.imageio.ImageIO.read(new File(IMAGE_PATH));
            File tempBmp = new File("temp.bmp");
            javax.imageio.ImageIO.write(image, "bmp", tempBmp);

            System.out.println("Image loaded and saved as BMP.");

            // 步骤2: 使用 FFmpeg 进行 H.264 编码（作为单帧视频）
            FFmpeg.atPath("/usr/bin/ffmpeg")  // Linux/Mac 路径；Windows: "C:/ffmpeg/bin/ffmpeg.exe"
                   .setInput(tempBmp.getAbsolutePath())
                   .addArguments("-c:v", "h264", "-f", "h264", "-vbsf", "h264_mp4toannexb")
                   .setOutput(OUTPUT_H264)
                   .execute();

            System.out.println("H.264 encoding completed.");

            // 步骤3: 通过 Socket 发送 H.264 数据
            sendH264ThroughSocket(OUTPUT_H264);

            // 清理临时文件
            tempBmp.delete();
            new File(OUTPUT_H264).delete();

        } catch (IOException | FFmpegException e) {
            e.printStackTrace();
        }
    }

    /**
     * 将 H.264 文件内容通过网络发送（模拟视频流）
     */
    private static void sendH264ThroughSocket(String filePath) {
        try (ServerSocket serverSocket = new ServerSocket(9999);
             Socket clientSocket = serverSocket.accept();
             var out = clientSocket.getOutputStream()) {

            System.out.println("Client connected. Sending H.264 data...");

            byte[] buffer = Files.readAllBytes(Paths.get(filePath));

            out.write(buffer);
            out.flush();

            System.out.println("H.264 data sent successfully.");

        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }
}
```

