import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class ChatRecordManager {
    private final String userId;

    public ChatRecordManager(String userId) {
        this.userId = userId;
    }

    // 保存聊天记录（追加）
    public void saveMessage(Message message) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(getFilePath(), true))) {
            oos.writeObject(message);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 读取历史记录
    public List<Message> loadMessages() {
        List<Message> messages = new ArrayList<>();
        File file = new File(getFilePath());
        if (!file.exists()) return messages;

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
            while (true) {
                try {
                    Message msg = (Message) ois.readObject();
                    messages.add(msg);
                } catch (EOFException e) {
                    break;
                }
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        return messages;
    }

    private String getFilePath() {
        return FileUtils.getRecordFilePath(userId);
    }
}
