package server;

import model.Message;
import utils.FileUtils;

import java.io.*;
import java.net.Socket;
import java.util.List;

public class ChatHandler implements Runnable {
    private final Socket socket;
    private final String userId;
    private final ObjectInputStream ois;
    private final ObjectOutputStream oos;
    private final ChatRecordManager recordManager;
    private volatile boolean running = true;

    public ChatHandler(Socket socket, String userId) {
        this.socket = socket;
        this.userId = userId;
        this.recordManager = new ChatRecordManager(userId);

        try {
            this.ois = new ObjectInputStream(socket.getInputStream());
            this.oos = new ObjectOutputStream(socket.getOutputStream());
        } catch (IOException e) {
            throw new RuntimeException("创建IO流失败", e);
        }
    }

    @Override
    public void run() {
        System.out.println("新用户[" + userId + "]已连接，开始监听...");
        try {
            // 加载历史记录
            List<Message> history = recordManager.loadMessages();
            for (Message msg : history) {
                oos.writeObject(msg);
                oos.flush();
            }

            while (running) {
                Message msg = (Message) ois.readObject();
                if (msg == null) break;

                System.out.println("收到消息：" + msg);
                recordManager.saveMessage(msg);

                // 回复给用户（可加逻辑判断，如关键词自动回复）
                Message reply = new Message("service", "收到：" + msg.getContent(), msg.getType(), msg.getFilePath(), FileUtils.getCurrentTime());
                oos.writeObject(reply);
                oos.flush();
            }
        } catch (Exception e) {
            if (running) {
                System.out.println("客户端[" + userId + "]断开连接");
            }
        } finally {
            close();
        }
    }

    public void stop() {
        running = false;
    }

    private void close() {
        try {
            if (ois != null) ois.close();
            if (oos != null) oos.close();
            if (socket != null) socket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

