public class CustomerServerGUI extends JFrame {
    private JTextArea logArea;
    private JButton startBtn, stopBtn;
    private final ExecutorService threadPool = Executors.newFixedThreadPool(10);
    private volatile boolean running = false;
    private Thread serverThread;

    public CustomerServerGUI() {
        initGUI();
    }

    private void initGUI() {
        setTitle("客服系统管理后台");
        setSize(700, 500);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        logArea = new JTextArea();
        logArea.setFont(new Font("宋体", Font.PLAIN, 12));
        logArea.setEditable(false);
        JScrollPane scroll = new JScrollPane(logArea);

        startBtn = new JButton("启动服务");
        stopBtn = new JButton("停止服务");
        stopBtn.setEnabled(false);

        JPanel btnPanel = new JPanel(new FlowLayout());
        btnPanel.add(startBtn);
        btnPanel.add(stopBtn);

        setLayout(new BorderLayout());
        add(scroll, BorderLayout.CENTER);
        add(btnPanel, BorderLayout.SOUTH);

        startBtn.addActionListener(e -> startServer());
        stopBtn.addActionListener(e -> stopServer());
    }

    private void startServer() {
        if (running) return;
        serverThread = new Thread(() -> {
            try {
                ServerSocket serverSocket = new ServerSocket(8888);
                running = true;
                SwingUtilities.invokeLater(() -> {
                    logArea.append("✅ 服务已启动，监听端口 8888\n");
                    startBtn.setEnabled(false);
                    stopBtn.setEnabled(true);
                });

                while (running) {
                    try {
                        java.net.Socket clientSocket = serverSocket.accept();
                        String userId = "user_" + System.currentTimeMillis();
                        SwingUtilities.invokeLater(() -> {
                            logArea.append("📌 新用户连接: " + userId + "\n");
                        });

                        ChatHandler handler = new ChatHandler(clientSocket, userId);
                        threadPool.submit(handler);
                    } catch (Exception e) {
                        if (!running) break;
                    }
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        serverThread.start();
    }

    private void stopServer() {
        running = false;
        threadPool.shutdown();
        try {
            threadPool.awaitTermination(1, java.util.concurrent.TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        SwingUtilities.invokeLater(() -> {
            logArea.append("❌ 服务已停止\n");
            stopBtn.setEnabled(false);
            startBtn.setEnabled(true);
        });
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            try {
                UIManager.setLookAndFeel(UIManager.getSystemLookAndFeel());
            } catch (Exception e) {
                e.printStackTrace();
            }
            new CustomerServerGUI().setVisible(true);
        });
    }
}
