        // Add name as a "new" entry to the table
        recordings.put(name, currentRecording);
        addRecordingToTable(name, 0); // will update later
    }

    private void stopRecording() {
        if (!isRecording || currentRecording == null) return;
        isRecording = false;
        String name = null;
        for (Map.Entry<String, List<Point>> entry : recordings.entrySet()) {
            if (entry.getValue() == currentRecording) {
                name = entry.getKey();
                break;
            }
        }
        if (name != null) {
            int size = currentRecording.size();
            tableModel.setValueAt(size, tableModel.getRowCount() - 1, 1); // update count
            JOptionPane.showMessageDialog(this, "Recording saved: " + name + " (" + size + " points)");
        } else {
            JOptionPane.showMessageDialog(this, "Recording not found!");
        }
        saveRecordingsToFile();
    }

    private void addRecordingToTable(String name, int count) {
        tableModel.addRow(new Object[]{name, count});
    }

    private void loadRecordings() {
        if (!recordingsFile.exists()) {
            System.out.println("No recordings file found. Starting fresh.");
            return;
        }

        try {
            String data = new String(Files.readAllBytes(Paths.get(recordingsFile.getAbsolutePath())));
            TypeFactory typeFactory = objectMapper.getTypeFactory();
            Map<String, List<Map<String, Integer>>> rawMap = objectMapper.readValue(data,
                    typeFactory.constructMapType(Map.class, String.class, List.class));

            // Convert back to List<Point>
            for (Map.Entry<String, List<Map<String, Integer>>> entry : rawMap.entrySet()) {
                List<Point> points = new ArrayList<>();
                for (Map<String, Integer> pointMap : entry.getValue()) {
                    int x = pointMap.get("x");
                    int y = pointMap.get("y");
                    points.add(new Point(x, y));
                }
                recordings.put(entry.getKey(), points);
                addRecordingToTable(entry.getKey(), points.size());
            }

        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "Failed to load recordings: " + e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
            e.printStackTrace();
        }
    }

    private void saveRecordingsToFile() {
        try {
            // Convert List<Point> to List<Map<String, Integer>>
            Map<String, List<Map<String, Integer>>> serializableMap = new HashMap<>();
            for (Map.Entry<String, List<Point>> entry : recordings.entrySet()) {
                List<Map<String, Integer>> pointList = new ArrayList<>();
                for (Point p : entry.getValue()) {
                    Map<String, Integer> pointMap = new HashMap<>();
                    pointMap.put("x", p.x);
                    pointMap.put("y", p.y);
                    pointList.add(pointMap);
                }
                serializableMap.put(entry.getKey(), pointList);
            }

            String json = objectMapper.writeValueAsString(serializableMap);
            Files.write(Paths.get(recordingsFile.getAbsolutePath()), json.getBytes());

            System.out.println("Recordings saved to " + recordingsFile.getAbsolutePath());
        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "Failed to save recordings: " + e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
            e.printStackTrace();
        }
    }

    private void replaySelected() {
        int selectedRow = table.getSelectedRow();
        if (selectedRow < 0) {
            JOptionPane.showMessageDialog(this, "Please select a recording to replay.");
            return;
        }

        String name = (String) table.getValueAt(selectedRow, 0);
        List<Point> points = recordings.get(name);

        if (points == null || points.isEmpty()) {
            JOptionPane.showMessageDialog(this, "No data to replay for " + name);
            return;
        }

        replaySequence(points);
    }

    private void replaySequence(List<Point> points) {
        // Run replay in background to avoid freezing UI
        scheduler.scheduleAtFixedRate(() -> {
            if (points.isEmpty()) {
                scheduler.shutdown();
                return;
            }

            Point p = points.remove(0);
            try {
                Robot robot = new Robot();
                // Use Robot to move cursor
                robot.mouseMove(p.x, p.y);
                // Add a tiny delay to simulate natural movement (adjustable)
                Thread.sleep(10);
                if (points.isEmpty()) {
                    scheduler.shutdown();
                }
            } catch (AWTException | InterruptedException e) {
                e.printStackTrace();
                scheduler.shutdown();
            }
        }, 0, 10, TimeUnit.MILLISECONDS);
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            try {
                UIManager.setLookAndFeel(UIManager.getSystemLookAndFeel());
            } catch (Exception e) {
                e.printStackTrace();
            }
            new MouseRecorderApp().setVisible(true);
        });
    }
}
