### 2. Java 服务端代码（接收 H.264 数据并解码显示）

```java
import org.bytedeco.javacv.*;
import org.bytedeco.opencv.opencv_core.*;
import java.io.*;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.net.Socket;

public class H264VideoServer {

    private static final int PORT = 8080;

    public static void main(String[] args) {
        System.out.println("H.264 Video Server is starting on port " + PORT + "...");

        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("Waiting for client connection...");
            Socket clientSocket = serverSocket.accept();
            System.out.println("Client connected: " + clientSocket.getInetAddress());

            // 使用 JavaCV 的 Frame 转换器
            FFmpegFrameGrabber grabber = new FFmpegFrameGrabber("pipe:");
            grabber.setOption("probesize", "32");
            grabber.setOption("analyzeduration", "5000000");
            grabber.setOption("fflags", "nobuffer");

            // 初始化解码器（这里通过管道输入字节流）
            grabber.start();

            // 用于显示的 OpenCV Frame
            OpenCVFrameConverter.ToMat converter = new OpenCVFrameConverter.ToMat();

            // JavaFX 显示窗口（推荐）
            new VideoDisplayWindow();

            try {
                // 读取客户端发来的 H.264 数据
                InputStream in = clientSocket.getInputStream();
                byte[] buffer = new byte[1024 * 1024]; // 1MB buffer
                int len;

                while ((len = in.read(buffer)) != -1) {
                    // 将接收到的数据传给 FFmpeg 解码器
                    grabber.push(new Frame(buffer, 0, len));

                    // 获取解码后的帧
                    Frame frame = grabber.grab();
                    if (frame != null && frame.image != null) {
                        // 转换为 Mat（OpenCV 格式）
                        Mat mat = converter.convert(frame);

                        // 用 JavaFX 显示
                        VideoDisplayWindow.showFrame(mat);
                    }
                }
            } finally {
                grabber.stop();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

