import javafx.application.Application;
import javafx.application.Platform;
import javafx.embed.swing.SwingNode;
import javafx.scene.Scene;
import javafx.scene.image.Image;
import javafx.scene.image.PixelFormat;
import javafx.scene.image.WritableImage;
import javafx.scene.layout.StackPane;
import javafx.stage.Stage;
import org.bytedeco.javacv.*;
import org.bytedeco.opencv.opencv_core.*;
import javax.imageio.ImageIO;
import java.awt.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class VideoDisplayWindow extends Application {

    private static SwingNode swingNode;
    private static ImageDisplayPanel panel;
    private static boolean initialized = false;

    public static void main(String[] args) {
        launch(args);
    }

    @Override
    public void start(Stage stage) {
        SwingUtilities.invokeLater(() -> {
            if (!initialized) {
                panel = new ImageDisplayPanel();
                swingNode = new SwingNode();
                swingNode.setContent(panel);
                initialized = true;
            }
        });

        StackPane root = new StackPane();
        root.getChildren().add(swingNode);
        Scene scene = new Scene(root, 640, 480);
        stage.setTitle("H.264 Video Display");
        stage.setScene(scene);
        stage.show();
    }

    public static void showFrame(Mat mat) {
        Platform.runLater(() -> {
            if (panel != null) {
                panel.updateImage(mat);
            }
        });
    }

    // 显示图像的 JPanel
    private static class ImageDisplayPanel extends JPanel {
        private WritableImage image;
        private Mat lastMat;

        public ImageDisplayPanel() {
            setPreferredSize(new Dimension(640, 480));
            image = new WritableImage(640, 480);
        }

        public void updateImage(Mat mat) {
            this.lastMat = mat;

            byte[] pixels = new byte[mat.cols() * mat.rows() * 3];
            mat.get(0, 0, pixels); // 获取 RGB 像素

            // 使用 ImageView 显示
            image = new WritableImage(mat.cols(), mat.rows());
            PixelFormat<ByteBuffer> format = PixelFormat.getByteRgbInstance();
            image.getPixelWriter().setPixels(0, 0, mat.cols(), mat.rows(), format, pixels, 0, mat.cols() * 3);

            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            if (image != null) {
                g.drawImage(image, 0, 0, getWidth(), getHeight(), null);
            }
        }
    }
}
