## 📌 Пример кода на Java (с Apache POI), который **вычисляет количество страниц**

> Предполагаем, что документ `*.docx` использует стандартные настройки страницы (например, A4, 2.54 см отступы и т.п.).

```java
import org.apache.poi.xwpf.usermodel.*;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class DocumentPageCounter {

    public static void main(String[] args) {
        String filePath = "document.docx"; // путь к документу
        int totalPages = countPagesInDocument(filePath);
        System.out.println("Общее количество страниц: " + totalPages);
    }

    public static int countPagesInDocument(String filePath) {
        try (FileInputStream fis = new FileInputStream(filePath);
             XWPFDocument document = new XWPFDocument(fis)) {

            // Получаем размеры страницы (по умолчанию A4)
            // Если нужно — можем считать из документа
            double pageWidth = document.getDocument().getBody().getSectPr().getPgSz().getW() / 1000.0; // в дюймах
            double pageHeight = document.getDocument().getBody().getSectPr().getPgSz().getH() / 1000.0; // в дюймах
            double marginTop = document.getDocument().getBody().getSectPr().getPgMar().getTop() / 1000.0;
            double marginBottom = document.getDocument().getBody().getSectPr().getPgMar().getBottom() / 1000.0;
            double marginLeft = document.getDocument().getBody().getSectPr().getPgMar().getLeft() / 1000.0;
            double marginRight = document.getDocument().getBody().getSectPr().getPgMar().getRight() / 1000.0;

            // Количество строк на странице — упрощённый подход
            double usableHeight = pageHeight - marginVertical;
            double lineSpacing = 0.25; // ~25% от размера шрифта (обычно 1.15–1.18)
            double avgLinesPerInch = 1.0 / lineSpacing; // ~4 строки на дюйм (в зависимости от шрифта)

            int maxLinesPerPage = (int) (usableHeight * avgLinesPerInch);

            // Собираем весь текст
            List<String> allText = new ArrayList<>();
            for (XWPFParagraph paragraph : document.getParagraphs()) {
                String text = paragraph.getText();
                if (text != null && !text.trim().isEmpty()) {
                    allText.add(text);
                }
            }

            // Псевдо-счётчик строк
            int totalLines = 0;
            for (String text : allText) {
                // Простое разбиение по строкам
                String[] lines = text.split("\n");
                totalLines += lines.length;
            }

            // Делим на строки на странице
            int totalPages = (int) Math.ceil((double) totalLines / maxLinesPerPage);

            // Дополнительно: можно учесть разрывы страниц, заголовки, рисунки...
            // Но это сложно без реального рендеринга (требует iText, Aspose и т.д.)

            return totalPages > 0 ? totalPages : 1;

        } catch (IOException e) {
            e.printStackTrace();
            return 1; // по умолчанию
        }
    }

    // Упростим отступы
    private static final double marginVertical = 1.0; // см (1 дюйм = 2.54 см)
    private static final double marginHorizontal = 1.5; // см (пример)
}
```

