            // Hash table to store subject -> number (e.g., "Order #12345678" -> "12345678")
            Hashtable<String, String> numberMap = new Hashtable<>();

            // Regex to extract numbers (digits only)
            Pattern numberPattern = Pattern.compile("\\d+");

            System.out.println("Found " + messages.length + " messages.");

            for (Message message : messages) {
                String subject = message.getSubject();
                String content = "";

                if (message instanceof MimeMessage) {
                    try {
                        content = ((MimeMessage) message).getContent().toString();
                    } catch (IOException | RuntimeException e) {
                        content = "(Failed to read content)";
                    }
                }

                // Extract number from subject or body
                String extractedNumber = null;

                // Try to extract from subject first
                if (subject != null) {
                    Matcher subjectMatcher = numberPattern.matcher(subject);
                    if (subjectMatcher.find()) {
                        extractedNumber = subjectMatcher.group();
                    }
                }

                // If not in subject, try body
                if (extractedNumber == null && content != null) {
                    Matcher bodyMatcher = numberPattern.matcher(content);
                    if (bodyMatcher.find()) {
                        extractedNumber = bodyMatcher.group();
                    }
                }

                // If a number was found, store it in the hashtable
                if (extractedNumber != null) {
                    // Use subject as key, number as value
                    numberMap.put(subject, extractedNumber);
                    System.out.println("Stored: Subject='" + subject + "' -> Number='" + extractedNumber + "'");
                } else {
                    System.out.println("No number found in: " + subject);
                }
            }

            // Display stored results
            System.out.println("\n=== Stored Numbers ===");
            numberMap.forEach((subject, number) -> {
                System.out.println("Subject: " + subject + " -> Number: " + number);
            });

            // Close folders
            inbox.close(false);
            store.close();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
