```java
import java.io.*;
import java.util.concurrent.CompletableFuture;

public class ImageToH264 {

    private static final String FFmpegPath = "ffmpeg"; // 确保 ffmpeg 在 PATH 中

    public static CompletableFuture<byte[]> encodeImageToH264(String imagePath, int width, int height) {
        return CompletableFuture.supplyAsync(() -> {
            ProcessBuilder pb = new ProcessBuilder(
                FFmpegPath,
                "-y", // 覆盖输出
                "-f", "rawvideo",
                "-pix_fmt", "rgb24",
                "-s", width + "x" + height,
                "-r", "25", // 帧率
                "-i", imagePath,
                "-c:v", "libx264",
                "-preset", "ultrafast",
                "-tune", "zerolatency", // 低延迟，适合实时传输
                "-f", "h264", // 输出 h264
                "-" // 输出到标准输出
            );

            Process process;
            try {
                process = pb.start();
            } catch (IOException e) {
                throw new RuntimeException("Failed to start FFmpeg process", e);
            }

            ByteArrayOutputStream output = new ByteArrayOutputStream();
            try (InputStream is = process.getInputStream();
                 InputStream es = process.getErrorStream()) {

                // 读取输出
                byte[] buffer = new byte[8192];
                int len;
                while ((len = is.read(buffer)) != -1) {
                    output.write(buffer, 0, len);
                }

                // 读取错误信息（避免阻塞）
                new Thread(() -> {
                    try (BufferedReader br = new BufferedReader(new InputStreamReader(es))) {
                        String line;
                        while ((line = br.readLine()) != null) {
                            System.err.println("FFmpeg: " + line);
                        }
                    } catch (IOException ignore) {}
                }).start();

                // 等待进程结束
                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    throw new RuntimeException("FFmpeg encoding failed with exit code: " + exitCode);
                }

            } catch (IOException | InterruptedException e) {
                throw new RuntimeException("Error during encoding", e);
            }

            return output.toByteArray();
        });
    }
}
```

> ✅ 说明：
> - 你传入 **图片路径、宽、高**，FFmpeg 会把单张图像编码为 `H.264` **帧**（即一个 `AVC` 码流）。
> - 使用 `-f h264 -` 输出到标准输出。
> - `ultrafast` + `zerolatency` 确保低延迟。
> - 一次只处理一张图片，生成一段 H.264 数据。

