### 步骤 2：WebSocket 服务端（传输 H.264 帧）

```java
import org.java_websocket.WebSocket;
import org.java_websocket.handshake.ClientHandshake;
import org.java_websocket.server.WebSocketServer;

import java.net.InetSocketAddress;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class VideoWebSocketServer extends WebSocketServer {

    private final LinkedBlockingQueue<byte[]> frameQueue = new LinkedBlockingQueue<>(100);
    private final ThreadPoolExecutor executor = new ThreadPoolExecutor(2, 4, 60L, TimeUnit.SECONDS, new LinkedBlockingQueue<>());

    public VideoWebSocketServer(int port) {
        super(new InetSocketAddress(port));
    }

    @Override
    public void onOpen(WebSocket conn, ClientHandshake handshake) {
        System.out.println("New client connected: " + conn.getRemoteAddress());
    }

    @Override
    public void onClose(WebSocket conn, int code, String reason, boolean remote) {
        System.out.println("Client disconnected: " + conn.getRemoteAddress());
    }

    @Override
    public void onMessage(WebSocket conn, String message) {
        System.out.println("Received: " + message);
    }

    @Override
    public void onMessage(WebSocket conn, byte[] data) {
        System.out.println("Received binary: " + data.length + " bytes");
    }

    @Override
    public void onError(WebSocket conn, Exception ex) {
        ex.printStackTrace();
    }

    // 从队列中读取帧并广播（模拟实时流）
    public void startStreaming() {
        executor.submit(() -> {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    byte[] frame = frameQueue.take();
                    // 广播给所有连接的客户端
                    for (WebSocket conn : getConnectionSet()) {
                        if (conn.isOpen()) {
                            conn.sendBinary(frame); // 发送原始 H.264 帧
                        }
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });
    }

    // 提供一个添加帧的方法（从图像编码后调用）
    public void sendFrame(byte[] h264Frame) {
        frameQueue.offer(h264Frame);
    }

    public static void main(String[] args) {
        int port = 8888;
        VideoWebSocketServer server = new VideoWebSocketServer(port);
        server.start();
        System.out.println("WebSocket server started on port " + port);

        // 模拟不断发送帧（真实场景：每秒 25 帧）
        new Thread(() -> {
            try {
                // 每 40ms 发送一帧（25 fps）
                for (int i = 0; i < 100; i++) {
                    String imagePath = "image" + i % 3 + ".jpg"; // 假设有 image0.jpg, image1.jpg, image2.jpg
                    byte[] h264Frame = ImageToH264.encodeImageToH264(imagePath, 640, 480).get();

                    server.sendFrame(h264Frame);

                    Thread.sleep(40); // 40ms = 25fps
                }
                System.out.println("Finished sending frames.");
            } catch (Exception e) {
                e.printStackTrace();
            }
        }).start();
    }
}
```

> ✅ 说明：
> - 用 `LinkedBlockingQueue` 缓冲待发送的 H.264 帧。
> - `sendFrame()` 方法由图像编码器调用。
> - `startStreaming()` 启动一个线程循环读取队列并广播。
> - 客户端收到的是原始 H.264 帧，可用于播放。

