                        DataSourceContextHolder.setDataSource(dataSourceKey);

                        // 交给处理逻辑，此时 handleClient 会使用正确数据源
                        handleClient(socket);

                    } catch (Exception e) {
                        log.error("Error handling client: {}", socket.getInetAddress(), e);
                    } finally {
                        DataSourceContextHolder.clearDataSource(); // 清理 ThreadLocal
                        try {
                            socket.close();
