package com.mediaworld.apimanager.configuration.redis;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.data.redis.core.ReactiveRedisTemplate;
import org.springframework.data.redis.serializer.GenericToStringSerializer;
import org.springframework.data.redis.serializer.JdkSerializationRedisSerializer;
import org.springframework.data.redis.serializer.RedisSerializationContext;
import org.springframework.data.redis.serializer.StringRedisSerializer;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import org.springframework.web.server.WebFilter;
import org.springframework.web.server.WebFilterChain;
import reactor.core.publisher.Mono;

import java.net.InetSocketAddress;
import java.time.Duration;
import java.time.LocalTime;

import static org.springframework.http.HttpStatus.TOO_MANY_REQUESTS;

@Component
public class RateLimiterWebFilter implements WebFilter {

    @Value("${MAX_REQUESTS_PER_MINUTE:20}") // Default to 20
    private Long maxRequestsPerMinute;

    private final ReactiveRedisTemplate<String, Long> redisTemplate;

    public RateLimiterWebFilter(ReactiveRedisTemplate<String, Long> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, WebFilterChain chain) {
        String key = buildKey(exchange.getRequest().getRemoteAddress());

        return redisTemplate.opsForValue().get(key)
                .flatMap(value -> value >= maxRequestsPerMinute ?
                        // Too many requests; reject
                        ServerResponse.status(TOO_MANY_REQUESTS).build().toBidiPublisher()
                                .then(Mono.error(new RuntimeException("Too many requests")))
                        :
                        // Increment and expire
                        incrAndExpireKey(key, exchange, chain))
                .switchIfEmpty(incrAndExpireKey(key, exchange, chain));
    }

    private String buildKey(Optional<InetSocketAddress> address) {
        int minute = LocalTime.now().getMinute();
        String host = address.map(InetSocketAddress::getHostName)
                             .orElse("unknown");
        return "rl_" + host + ":" + minute;
    }

    private Mono<Void> incrAndExpireKey(String key, ServerWebExchange exchange, WebFilterChain chain) {
        return redisTemplate.execute((connection) -> {
            ByteBuffer bbKey = ByteBuffer.wrap(key.getBytes());

            return Mono.zip(
                    connection.numberCommands().incr(bbKey),
                    connection.keyCommands().expire(bbKey, Duration.ofSeconds(59))
            ).then();
        }).then(chain.filter(exchange)); // Proceed only if allowed
    }
}
```

