            // Get cipher suite
            String cipherSuite = session.getCipherSuite();
            System.out.println("Cipher Suite: " + cipherSuite);

            // Check if the cipher suite uses Diffie-Hellman
            if (cipherSuite.contains("DH") || cipherSuite.contains("ECDH")) {
