# ✅ PHP Example

```php
<?php
function encryptNFCData($plaintext, $key, $iv) {
    // Ensure key is 16 bytes (AES-128)
    if (strlen($key) < 16) {
        $key = str_pad($key, 16, "\0");
    } elseif (strlen($key) > 16) {
        $key = substr($key, 0, 16);
    }

    // Ensure IV is 16 bytes
    if (strlen($iv) < 16) {
        $iv = str_pad($iv, 16, "\0");
    } elseif (strlen($iv) > 16) {
        $iv = substr($iv, 0, 16);
    }

    // Encrypt
    $ciphertext = openssl_encrypt(
        $plaintext,
        'AES-128-CBC',
        $key,
        OPENSSL_RAW_DATA,
        $iv
    );

    if ($ciphertext === false) {
        throw new Exception("Encryption failed: " . openssl_error_string());
    }

    // Combine IV + ciphertext
    $dataToWrite = $iv . $ciphertext;

    // Encode to base64 (safe for NFC storage as text)
    $base64Data = base64_encode($dataToWrite);

    return $base64Data;
}

