// service/AuthService.java
@Service
@Transactional
public class AuthService {

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private PasswordEncoder passwordEncoder;

    @Autowired
    private JwtUtil jwtUtil;

    @Autowired
    private QRCodeGenerator qrcodeGenerator; // 可选：生成MFA二维码（如用 google-authenticator）

    public LoginResponseDTO login(LoginRequestDTO loginRequest) {
        User user = userRepository.findByUsername(loginRequest.getUsername())
                .orElseThrow(() -> new IllegalArgumentException("用户不存在"));

        // 校验密码
        if (!passwordEncoder.matches(loginRequest.getPassword(), user.getPassword())) {
            throw new IllegalArgumentException("密码错误");
        }

        // 检查是否需要 MFA
        if (user.isMfaEnabled()) {
            if (loginRequest.getMfaCode() == null || loginRequest.getMfaCode().isEmpty()) {
                throw new MfaRequiredException("需要 MFA 验证，请提供验证码");
            }

            if (!validateMfaCode(user.getMfaSecret(), loginRequest.getMfaCode())) {
                throw new IllegalArgumentException("MFA 验证码错误");
            }
        }

        String token = jwtUtil.generateToken(user.getUsername());

        return new LoginResponseDTO(
                token,
                user.getUsername(),
                user.isMfaEnabled() && loginRequest.getMfaCode() == null,
                user.getId()
        );
    }

    private boolean validateMfaCode(String secret, String code) {
        // 使用 google-authenticator 库校验 6 位验证码
        // 示例：TotpUtil.validate(secret, code);
        // 这里简化为直接比较（仅测试用）
        return !secret.isEmpty() && code.equals("123456"); // 实际应用请用真实 MFA 库
    }

    // 可选：启用MFA
    public User enableMfa(String username) {
        User user = userRepository.findByUsername(username).orElseThrow();
        user.setMfaEnabled(true);
        user.setMfaSecret(generateSecret()); // 实际用 Google Authenticator 生成
        return userRepository.save(user);
    }

    private String generateSecret() {
        return Base32.getEncoder().encodeToString(new byte[10]); // 实际用 TOTP 库
    }
}
```

