// controller/AuthController.java
@RestController
@RequestMapping("/api/auth")
public class AuthController {

    @Autowired
    private AuthService authService;

    @PostMapping("/login")
    public ResponseEntity<LoginResponseDTO> login(@RequestBody @Valid LoginRequestDTO loginRequest) {
        try {
            LoginResponseDTO response = authService.login(loginRequest);
            return ResponseEntity.ok(response);
        } catch (MfaRequiredException e) {
            return ResponseEntity.status(HttpStatus.PRECONDITION_REQUIRED) // 428
                    .body(new LoginResponseDTO(null, null, true, null));
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(new LoginResponseDTO(null, null, false, null));
        }
    }

    // 用于开启 MFA 的接口（可选）
    @PostMapping("/mfa/enable")
    public ResponseEntity<String> enableMfa(@RequestBody Map<String, String> request) {
        String username = request.get("username");
        User user = authService.enableMfa(username);
        return ResponseEntity.ok("MFA 已开启，扫描二维码绑定");
    }
}
```

