// src/client/ClientUI.java
package client;

import common.Constants;
import javax.imageio.ImageIO;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.Socket;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Date;

public class ClientUI extends JFrame {
    private JTextField txtInput;
    private JTextArea txtChat;
    private JButton btnSend, btnImage, btnFile, btnConnect;
    private Socket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private String userId;
    private String chatLogFile;
    private Timer pingTimer;

    private boolean isConnected = false;

    public ClientUI() {
        userId = "user_" + System.currentTimeMillis();
        chatLogFile = "logs/" + userId + "_chat.log";
        new File("logs").mkdir(); // 创建日志目录

        setTitle("电商客服系统 - 用户端");
        setSize(600, 500);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        JPanel top = new JPanel(new FlowLayout());
        btnConnect = new JButton("连接客服");
        btnConnect.addActionListener(e -> connect());
        top.add(btnConnect);
        add(top, BorderLayout.NORTH);

        txtChat = new JTextArea(20, 40);
        txtChat.setEditable(false);
        txtChat.setFont(new Font("宋体", Font.PLAIN, 14));
        JScrollPane scroll = new JScrollPane(txtChat);
        add(scroll, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        txtInput = new JTextField(25);
        btnSend = new JButton("发送");
        btnImage = new JButton("图片");
        btnFile = new JButton("文件");

        btnSend.addActionListener(e -> sendText());
        btnImage.addActionListener(e -> sendImage());
        btnFile.addActionListener(e -> sendFile());

        JPanel inputPanel = new JPanel(new BorderLayout());
        inputPanel.add(txtInput, BorderLayout.CENTER);
        JPanel btnPanel = new JPanel(new FlowLayout());
        btnPanel.add(btnSend);
        btnPanel.add(btnImage);
        btnPanel.add(btnFile);
        inputPanel.add(btnPanel, BorderLayout.EAST);

        bottom.add(inputPanel, BorderLayout.CENTER);
        add(bottom, BorderLayout.SOUTH);

        // 启动心跳检测
        pingTimer = new Timer(10000, e -> {
            if (isConnected) {
                try {
                    out.writeObject(new Message(Constants.PING, userId, "Ping", null));
                    out.flush();
                } catch (IOException ex) {
                    JOptionPane.showMessageDialog(this, "心跳失败，连接中断！");
                    disconnect();
                }
            }
        });
        pingTimer.start();

        // 加载历史记录
        loadChatLog();

        setVisible(true);
    }

    private void connect() {
        try {
            socket = new Socket(Constants.SERVER_IP, Constants.SERVER_PORT);
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());

            // 发送连接请求
            out.writeObject(new Message(Constants.CONNECT, userId, "连接请求", null));
            out.flush();

            btnConnect.setEnabled(false);
            isConnected = true;

            // 启动监听线程
            new Thread(() -> {
                try {
                    while (isConnected) {
                        Message msg = (Message) in.readObject();
                        handleReceivedMessage(msg);
                    }
                } catch (Exception e) {
                    if (isConnected) {
                        JOptionPane.showMessageDialog(this, "与客服断开连接！");
                    }
                    disconnect();
                }
            }).start();

            JOptionPane.showMessageDialog(this, "已连接到客服服务器！");
        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "连接失败：" + e.getMessage());
        }
    }

    private void sendText() {
        String text = txtInput.getText().trim();
        if (text.isEmpty()) return;

        Message msg = new Message(Constants.TEXT, userId, text, null);
        sendToServer(msg);
        txtChat.append("我: " + text + "\n");
        txtInput.setText("");
        saveChatLog("我: " + text + " (" + new java.util.Date() + ")\n");
    }

    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        fc.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("图片文件", "jpg", "png", "bmp"));
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File file = fc.getSelectedFile();
            try {
                byte[] imageBytes = Files.readAllBytes(file.toPath());
                Message msg = new Message(Constants.IMAGE, userId, file.getName(), imageBytes);
                sendToServer(msg);

                txtChat.append("我: [图片] " + file.getName() + "\n");
                saveChatLog("我: [图片] " + file.getName() + " (" + new java.util.Date() + ")\n");
            } catch (IOException e) {
                JOptionPane.showMessageDialog(this, "读取图片失败：" + e.getMessage());
            }
        }
    }

    private void sendFile() {
        JFileChooser fc = new JFileChooser();
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File file = fc.getSelectedFile();
            try {
                byte[] fileBytes = Files.readAllBytes(file.toPath());
                Message msg = new Message(Constants.FILE, userId, file.getName(), fileBytes);
                sendToServer(msg);

                txtChat.append("我: [文件] " + file.getName() + "\n");
                saveChatLog("我: [文件] " + file.getName() + " (" + new java.util.Date() + ")\n");
            } catch (IOException e) {
                JOptionPane.showMessageDialog(this, "读取文件失败：" + e.getMessage());
            }
        }
    }

    private void sendToServer(Message msg) {
        try {
            out.writeObject(msg);
            out.flush();
        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "发送失败：" + e.getMessage());
        }
    }

    private void handleReceivedMessage(Message msg) {
        SwingUtilities.invokeLater(() -> {
            switch (msg.getType()) {
                case Constants.TEXT:
                    txtChat.append("客服: " + msg.getContent() + "\n");
                    saveChatLog("客服: " + msg.getContent() + " (" + new java.util.Date() + ")\n");
                    break;

                case Constants.IMAGE:
                    try {
                        ImageIcon icon = new ImageIcon(msg.getData());
                        Image img = icon.getImage().getScaledInstance(200, 150, Image.SCALE_SMOOTH);
                        ImageIcon preview = new ImageIcon(img);
                        JOptionPane.showMessageDialog(this, new JLabel(new ImageIcon(img)), "收到图片", JOptionPane.INFORMATION_MESSAGE);
                        txtChat.append("客服: [图片] " + msg.getContent() + "\n");
                        saveChatLog("客服: [图片] " + msg.getContent() + " (" + new java.util.Date() + ")\n");
                    } catch (Exception e) {
                        txtChat.append("客服: [图片显示失败]\n");
                    }
                    break;

                case Constants.FILE:
                    String filename = msg.getContent();
                    JFileChooser fc = new JFileChooser();
                    fc.setSelectedFile(new File("downloads/" + filename));
                    if (fc.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
                        File dest = fc.getSelectedFile();
                        Files.write(dest.toPath(), msg.getData());
                        txtChat.append("客服: [文件已保存至] " + dest.getAbsolutePath() + "\n");
                        saveChatLog("客服: [文件已保存至] " + dest.getAbsolutePath() + " (" + new java.util.Date() + ")\n");
                    }
                    break;

                case Constants.REJECT_SERVICE:
                    txtChat.append("客服: 抱歉，目前客服繁忙，请稍后再试！\n");
                    showBusyMessage();
                    break;

                case Constants.ACK_SERVICE:
                    txtChat.append("客服: 已连接，欢迎聊天！\n");
                    break;

                case Constants.PING:
                    break; // 心跳回复

                default:
                    txtChat.append("未知消息: " + msg + "\n");
            }
        });
    }

    private void showBusyMessage() {
        JOptionPane.showMessageDialog(this, "客服暂时忙碌，请稍后重试！");
    }

    private void loadChatLog() {
        try {
            String content = new String(Files.readAllBytes(Paths.get(chatLogFile)));
            txtChat.append(content);
        } catch (Exception e) {
            // 文件不存在或读取失败，忽略
        }
    }

    private void saveChatLog(String text) {
        try (PrintWriter writer = new PrintWriter(new FileWriter(chatLogFile, true))) {
            writer.append(text);
            writer.flush();
        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "保存失败：" + e.getMessage());
        }
    }

    private void disconnect() {
        isConnected = false;
        if (in != null) {
            try { in.close(); } catch (Exception ignored) {}
            in = null;
        }
        if (out != null) {
            try { out.close(); } catch (Exception ignored) {}
            out = null;
        }
        if (socket != null) {
            try { socket.close(); } catch (Exception ignored) {}
            socket = null;
        }
        btnConnect.setEnabled(true);
        txtChat.append("❌ 已断开连接，请重新连接。\n");
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new ClientUI());
    }
}
