// src/server/AgentHandler.java
package server;

import common.Constants;
import common.Message;
import java.io.*;
import java.util.concurrent.ConcurrentHashMap;

public class AgentHandler implements Runnable {
    private Socket socket;
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private String agentId = "agent_" + System.currentTimeMillis();
    private boolean connected = true;
    private String clientUserId = null;
    private String lastClientName = null;

    public AgentHandler(Socket socket) {
        this.socket = socket;
    }

    @Override
    public void run() {
        try {
            in = new ObjectInputStream(socket.getInputStream());
            out = new ObjectOutputStream(socket.getOutputStream());

            System.out.println("客服 " + agentId + " 已连接");

            while (connected) {
                Message msg = (Message) in.readObject();
                handleMsg(msg);
            }
        } catch (Exception e) {
            if (connected) {
                System.out.println("客服 " + agentId + " 断开连接");
            }
        } finally {
            disconnect();
        }
    }

    private void handleMsg(Message msg) {
        switch (msg.getType()) {
            case Constants.REQ_SERVICE:
                clientUserId = msg.getSender();
                lastClientName = msg.getContent();
                JOptionPane.showMessageDialog(null, "用户 " + clientUserId + " 请求服务！");
                showServiceDialog();
                break;

            case Constants.ACCEPT_SERVICE:
                if (clientUserId != null) {
                    sendMessage(msg.getSender(), new Message(Constants.ACK_SERVICE, agentId, "已接受服务", null));
                    System.out.println("客服 " + agentId + " 接受了用户 " + clientUserId + " 的请求");
                }
                break;

            case Constants.REJECT_SERVICE:
                if (clientUserId != null) {
                    sendMessage(clientUserId, new Message(Constants.REJECT_SERVICE, agentId, "抱歉，当前客服繁忙", null));
                    clientUserId = null;
                }
                break;

            case Constants.TEXT:
            case Constants.IMAGE:
            case Constants.FILE:
                // 转发给客户端
                sendMessage(clientUserId, msg);
                break;

            case Constants.PING:
                // 心跳回复
                sendMessage(msg.getSender(), new Message(Constants.PING, agentId, "Pong", null));
                break;

            default:
                System.out.println("未知消息类型");
        }
    }

    private void showServiceDialog() {
        int choice = JOptionPane.showConfirmDialog(null,
                "用户 " + clientUserId + " 请求服务，是否接受？",
                "服务请求",
                JOptionPane.YES_NO_OPTION);
        try {
            if (choice == JOptionPane.YES_OPTION) {
                sendMessage(clientUserId, new Message(Constants.ACCEPT_SERVICE, agentId, "服务已接受", null));
            } else {
                sendMessage(clientUserId, new Message(Constants.REJECT_SERVICE, agentId, "客服繁忙", null));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void sendMessage(String to, Message msg) {
        try {
            out.writeObject(msg);
            out.flush();
        } catch (IOException e) {
            System.err.println("无法发送消息给 " + to);
        }
    }

    private void disconnect() {
        connected = false;
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (socket != null) socket.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
