// src/server/ClientHandler.java
package server;

import common.Constants;
import common.Message;
import java.io.*;
import java.net.Socket;
import java.util.concurrent.ConcurrentHashMap;

public class ClientHandler implements Runnable {
    private Socket socket;
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private String userId;
    private boolean logged = false;
    private boolean connected = true;
    private String currentAgent = null;

    private static ConcurrentHashMap<String, AgentHandler> availableAgents = new ConcurrentHashMap<>();

    public ClientHandler(Socket socket) {
        this.socket = socket;
    }

    @Override
    public void run() {
        try {
            in = new ObjectInputStream(socket.getInputStream());
            out = new ObjectOutputStream(socket.getOutputStream());

            while (connected) {
                Message msg = (Message) in.readObject();
                handleClientMessage(msg);
            }
        } catch (Exception e) {
            if (connected) {
                System.out.println("用户 " + userId + " 断开");
            }
        } finally {
            cleanup();
        }
    }

    private void handleClientMessage(Message msg) {
        switch (msg.getType()) {
            case Constants.CONNECT:
                userId = msg.getSender();
                System.out.println("用户 " + userId + " 连接");
                sendMessage(userId, new Message(Constants.PING, "server", "连接成功", null));
                break;

            case Constants.REQ_SERVICE:
                userId = msg.getSender();
                System.out.println("用户 " + userId + " 请求服务");

                if (availableAgents.isEmpty()) {
                    sendMessage(userId, new Message(Constants.REJECT_SERVICE, "server", "客服繁忙，稍后再试", null));
                } else {
                    // 选择一个客服
                    AgentHandler agent = availableAgents.values().iterator().next();
                    currentAgent = agent.agentId;
                    agent.clientUserId = userId; // 关联客户端
                    sendMessage(userId, new Message(Constants.ACCEPT_SERVICE, "server", "服务接受中...", null));
                    try {
                        Thread.sleep(1000);
                        // 通知客服
                        agent.sendMessage(userId, msg);
                    } catch (Exception ignored) {
                    }
                }
                break;

            default:
                if (currentAgent != null) {
                    // 传递给客服
                    availableAgents.get(currentAgent).sendMessage(userId, msg);
                }
        }
    }

    private void sendMessage(String to, Message msg) {
        try {
            out.writeObject(msg);
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void cleanup() {
        connected = false;
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (socket != null) socket.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void addAgent(AgentHandler agent) {
        availableAgents.put(agent.agentId, agent);
    }

    public static void removeAgent(String id) {
        availableAgents.remove(id);
    }
}
