### 2. Java 代码：读取图片并编码为 H.264 流通过 Socket 发送

```java
import org.bytedeco.ffmpeg.avcodec.*;
import org.bytedeco.ffmpeg.avformat.*;
import org.bytedeco.ffmpeg.avutil.*;
import org.bytedeco.ffmpeg.global.avcodec.*;
import org.bytedeco.ffmpeg.global.avformat.*;
import org.bytedeco.ffmpeg.global.avutil.*;

import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;

public class ImageToH264Stream {

    public static void main(String[] args) {
        try {
            // 1. 设置编码参数
            // 找到 H.264 编码器
            AVCodecPtr codecPtr = avcodec_find_encoder_by_name("h264");
            if (codecPtr.isNull()) {
                System.err.println("H.264 编码器未找到，确保 FFmpeg 支持 H.264");
                return;
            }

            AVCodec codec = codecPtr.asAvCodec();
            AVCodecContextPtr codecContextPtr = avcodec_alloc_context3(codec);
            AVCodecContext codecContext = codecContextPtr.asAvCodecContext();

            codecContext.set_width(640);
            codecContext.set_height(480);
            codecContext.set_time_base(new AVRational(1, 30)); // 30 fps
            codecContext.set_pix_fmt(AV_PIX_FMT_YUV420P);
            codecContext.set_gop_size(30); // 关键帧间隔
            codecContext.set_bit_rate(1000000); // 1 Mbps

            // 2. 打开编码器
            int ret = avcodec_open2(codecContextPtr, codec, null);
            if (ret < 0) {
                System.err.println("无法打开编码器: " + ret);
                return;
            }

            // 3. 创建 AVFrame（用于保存图像数据）
            AVFramePtr framePtr = av_frame_alloc();
            AVFrame frame = framePtr.asAvFrame();
            frame.set_format(AV_PIX_FMT_YUV420P);
            frame.set_width(640);
            frame.set_height(480);
            av_frame_get_buffer(framePtr, 32);

            // 4. 创建编码器输出包
            AVPacketPtr packetPtr = av_packet_alloc();
            AVPacket packet = packetPtr.asAvPacket();

            // 5. 启动 Socket 服务
            ServerSocket serverSocket = new ServerSocket(8080);
            System.out.println("服务器启动，监听端口 8080...");

            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("客户端连接: " + clientSocket.getInetAddress());

                try (OutputStream out = clientSocket.getOutputStream()) {
                    // 读取图片文件（示例：10 张 JPEG 图像，循环发送）
                    for (int i = 1; i <= 10; i++) {
                        String imgPath = "image" + i + ".jpg";
                        File file = new File(imgPath);
                        if (!file.exists()) {
                            System.err.println("图片文件不存在：" + imgPath);
                            continue;
                        }

                        // 6. 读取图片并转换为 YUV420P（H.264 编码要求）
                        byte[] imageBytes = Files.readAllBytes(file.toPath());
                        // 使用 OpenCV 将 JPEG 转为 YUV420P（JavaCV 内部转换）
                        IplImage srcImage = cvLoadImage(imgPath);
                        IplImage yuvImage = cvCreateImage(cvGetSize(srcImage), IPL_DEPTH_8U, 3);
                        cvCvtColor(srcImage, yuvImage, CV_RGB2YUV);

                        // 复制到 AVFrame 的 buffer
                        for (int plane = 0; plane < 3; plane++) {
                            int size = frame.get_linesize(plane) * frame.get_height(plane);
                            System.arraycopy(yuvImage.getImageData().array(),
                                    yuvImage.getImageData().position() + plane * size,
                                    frame.get_data(plane).array(), 0, size);
                        }

                        // 设置时间戳
                        frame.set_pts(i * 30); // 30fps

                        // 7. 编码图像为 H.264
                        ret = avcodec_send_frame(codecContextPtr, framePtr);
                        if (ret < 0) {
                            System.err.println("编码失败: " + ret);
                            continue;
                        }

                        // 接收编码后数据包
                        while (true) {
                            ret = avcodec_receive_packet(codecContextPtr, packetPtr);
                            if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF) {
                                break;
                            } else if (ret < 0) {
                                System.err.println("接收包失败: " + ret);
                                break;
                            }

                            // 8. 从 AVPacket 中获取 H.264 NAL 数据
                            byte[] h264Data = new byte[packet.get_size()];
                            System.arraycopy(packet.get_data().array(), 0, h264Data, 0, packet.get_size());

                            // 9. 通过 socket 发送
                            out.write(h264Data);
                            out.flush();

                            System.out.println("发送 H.264 数据: " + packet.get_size() + " 字节");

                            av_packet_unref(packetPtr); // 释放包
                        }

                        cvReleaseImage(srcImage);
                        cvReleaseImage(yuvImage);
                    }

                    System.out.println("发送完成。");

                } catch (Exception e) {
                    e.printStackTrace();
                } finally {
                    clientSocket.close();
                }
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

