import com.github.bramp.ffmpeg.FFmpeg;
import com.github.bramp.ffmpeg.FFprobe;
import com.github.bramp.ffmpeg.probe.CodecInfo;
import com.github.bramp.ffmpeg.probe.FormatInfo;
import com.github.bramp.ffmpeg.tools.FFmpegProgress;
import java.io.File;
import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.file.Files;

public class ImageToH264Stream {

    private static final String INPUT_IMAGE = "input.jpg"; // 输入图片路径
    private static final String OUTPUT_H264 = "output.264"; // 临时 H.264 文件
    private static final int PORT = 8080;

    public static void main(String[] args) {
        try {
            // 1. 检查图像文件是否存在
            File imageFile = new File(INPUT_IMAGE);
            if (!imageFile.exists()) {
                System.err.println("图片文件不存在: " + INPUT_IMAGE);
                return;
            }

            // 2. 使用 FFmpeg 将图片编码为 H.264 NAL 单元
            // 将单张图片以 30fps 编码成 H.264 流
            FFmpeg ffmpeg = new FFmpeg("/usr/bin/ffmpeg"); // 可能需修改为系统路径
            ffmpeg
                .setInput(imageFile.getAbsolutePath())
                .addArguments("-f", "image2") // 输入为图像序列
                .addArguments("-framerate", "30") // 帧率
                .addArguments("-vcodec", "libx264") // 使用 H.264 编码
                .addArguments("-pix_fmt", "yuv420p") // 像素格式
                .addArguments("-tune", "zerolatency") // 低延迟
                .addArguments("-preset", "ultrafast") // 编码速度优先
                .addArguments("-f", "h264") // 输出 H.264 流
                .addArguments("-") // 输出到 stdout
                .redirectOutput(new File(OUTPUT_H264))
                .execute();

            System.out.println("H.264 编码完成，保存到: " + OUTPUT_H264);

            // 3. 启动 Socket 服务器，发送 H.264 数据
            try (ServerSocket serverSocket = new ServerSocket(PORT)) {
                System.out.println("等待客户端连接在端口 " + PORT + "...");
                try (Socket socket = serverSocket.accept();
                     var out = socket.getOutputStream()) {

                    System.out.println("客户端已连接，开始发送 H.264 流...");

                    byte[] buffer = new byte[1024];
                    int bytesRead;

                    // 读取 H.264 文件，逐块发送
                    try (var in = Files.newInputStream(new File(OUTPUT_H264).toPath())) {
                        while ((bytesRead = in.read(buffer)) != -1) {
                            out.write(buffer, 0, bytesRead);
                            out.flush();
                        }
                    }

                    System.out.println("H.264 流发送完成。");

                }
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

