</dependencies>
```

> ⚠️ 注意：虽然 `JavaCV` 支持 H.264 编码，但使用 FFmpeg 命令更简单、稳定。

---

### 2. 使用 FFmpeg 将图片转为 H.264 流（通过命令行）

#### 示例脚本（Java 执行 FFmpeg）：

```java
import java.io.*;
import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;

@Service
public class ImageToH264StreamService {

    private final ExecutorService executor = Executors.newFixedThreadPool(1);

    // 图片文件路径（例如：/images/1.jpg）
    public void sendImageAsH264Stream(String imagePath, String clientIp, int port) {
        executor.submit(() -> {
            try {
                // 构建 FFmpeg 命令：将单张图片转为 H.264 流
                ProcessBuilder pb = new ProcessBuilder(
                    "ffmpeg",
                    "-y", // 覆盖输出
                    "-loop", "1",           // 循环播放
                    "-framerate", "1",      // 每秒 1 帧
                    "-i", imagePath,         // 输入图
                    "-c:v", "h264",         // 编码为 H.264
                    "-pix_fmt", "yuv420p",  // 通用格式
                    "-f", "h264",           // 输出格式为 h264
                    "-"                     // 输出到 stdout
                );

                Process process = pb.start();

                // 获取输出流（H.264 流）
                InputStream ffmpegOutput = process.getInputStream();

                // 连接到客户端 socket
                try (Socket socket = new Socket(clientIp, port);
                     OutputStream out = socket.getOutputStream()) {

                    byte[] buffer = new byte[4096];
                    int bytesRead;

                    while ((bytesRead = ffmpegOutput.read(buffer)) != -1) {
                        out.write(buffer, 0, bytesRead);
                        out.flush();
                    }

                } catch (IOException e) {
                    e.printStackTrace();
                }

                process.waitFor();

            } catch (Exception e) {
                e.printStackTrace();
            }
        });
    }
}
```

