                    } else if (msg.getType() == ChatMessage.MessageType.FILE) {
                        byte[] data = (byte[]) in.readObject();
                        String fullPath = "data/received/" + msg.getFileName();
                        FileTransferUtil.saveBytesToFile(data, fullPath);
                        chatArea.append("📎 " + msg.getSender() + " 发送了文件: " + msg.getFileName() + " (已保存至: " + fullPath + ")\n");
