import java.net.ServerSocket;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ServerUI extends JFrame {
    private ServerSocket serverSocket;
    private ExecutorService pool = Executors.newCachedThreadPool();
    private Map<String, ServerHandler> clientHandlers = new ConcurrentHashMap<>();
    private JTextArea logArea;

    public ServerUI() {
        setTitle("客服端 - 电商客服系统");
        setSize(700, 600);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        JPanel panel = new JPanel(new BorderLayout());

        JScrollPane logScroll = new JScrollPane(logArea = new JTextArea(20, 60));
        logArea.setEditable(false);
        logArea.setFont(new Font("微软雅黑", Font.PLAIN, 12));

        JLabel lbl = new JLabel("当前服务用户列表：", JLabel.LEFT);
        JPanel listPanel = new JPanel(new BorderLayout());
        listPanel.add(lbl, BorderLayout.NORTH);

        JList<String> userList = new JList<>();
        DefaultListModel<String> model = new DefaultListModel<>();
        userList.setModel(model);

        JScrollPane userScroll = new JScrollPane(userList);
        listPanel.add(userScroll, BorderLayout.CENTER);

        JPanel bottomPanel = new JPanel(new BorderLayout());
        bottomPanel.add(listPanel, BorderLayout.CENTER);
        bottomPanel.add(logScroll, BorderLayout.SOUTH);

        panel.add(bottomPanel, BorderLayout.CENTER);

        JButton stopBtn = new JButton("停止服务");
        stopBtn.addActionListener(e -> stopServer());
        panel.add(stopBtn, BorderLayout.SOUTH);

        add(panel);

        startServer();

        Timer timer = new Timer(1000, e -> {
            model.clear();
            clientHandlers.keySet().forEach(k -> model.addElement("用户: " + k));
        });
        timer.start();
    }

    private void startServer() {
        try {
            serverSocket = new ServerSocket(8888);
            logArea.append("🌐 服务端启动成功，监听端口 8888\n");

            new Thread(() -> {
                try {
                    while (true) {
                        Socket clientSocket = serverSocket.accept();
                        String userId = "用户_" + UUID.randomUUID().toString().substring(0, 6);

                        SwingUtilities.invokeLater(() -> {
                            JOptionPane.showMessageDialog(this, "新用户申请服务，用户ID: " + userId);
                            int choice = JOptionPane.showConfirmDialog(this, "是否接受该用户会话？", "新会话", JOptionPane.YES_NO_OPTION);
                            if (choice == JOptionPane.YES_OPTION) {
                                ServerHandler handler = new ServerHandler(clientSocket, userId, logArea, this);
                                clientHandlers.put(userId, handler);
                                pool.execute(handler);
                            } else {
                                // 拒绝连接
                                try (new ObjectOutputStream(clientSocket.getOutputStream())) {
                                    clientSocket.close();
                                }
                                logArea.append("❌ 拒绝了用户: " + userId + "\n");
                            }
                        });
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }).start();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

