        ServerHandler handler = clientHandlers.get(userId);
        if (handler != null) {
            handler.send(msg);
        }
    }

    public void removeClient(String userId) {
        clientHandlers.remove(userId);
    }

    public void stopServer() {
        try {
            pool.shutdown();
            serverSocket.close();
            logArea.append("🛑 服务端已关闭\n");
        } catch (IOException e) {
            e.printStackTrace();
        }
        System.exit(0);
    }

