// Server/ServerHandler.java
import javax.swing.*;
import java.io.*;
import java.net.Socket;
import java.time.LocalDateTime;

public class ServerHandler implements Runnable {
    private Socket socket;
    private String userId;
    private JTextArea logArea;
    private ServerUI serverUI;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private volatile boolean running = true;

    public ServerHandler(Socket socket, String userId, JTextArea logArea, ServerUI serverUI) {
        this.socket = socket;
        this.userId = userId;
        this.logArea = logArea;
        this.serverUI = serverUI;

        try {
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());
            logArea.append("✅ 接受用户: " + userId + " 的会话\n");
            // 发送欢迎消息
            out.writeObject(new ChatMessage("系统", ChatMessage.MessageType.SYSTEM, "客服已上线，欢迎咨询！"));
            logArea.append("💬 用户 " + userId + " 已连接\n");
        } catch (IOException e) {
            e.printStackTrace();
        }

        // 加载历史记录
        loadHistory(userId);
    }

    @Override
    public void run() {
        try {
            while (running) {
                Object obj = in.readObject();
                if (obj instanceof ChatMessage msg) {
                    msg.setSender("客服");
                    msg.setTimestamp(System.currentTimeMillis());
                    logArea.append("💬 " + userId + " 发来消息: " + msg.getContent() + "\n");
                    saveHistory(userId, "用户:" + userId + ": " + msg.getContent());
                    broadcastMessage(msg);
                }
            }
        } catch (Exception e) {
            logArea.append("⚠️ 用户 " + userId + " 断开\n");
            running = false;
            serverUI.removeClient(userId);
        } finally {
            try {
                if (in != null) in.close();
                if (out != null) out.close();
                socket.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public void send(ChatMessage msg) {
        try {
            out.writeObject(msg);
        } catch (IOException e) {
            JOptionPane.showMessageDialog(null, "发送失败: " + e.getMessage());
        }
    }

    private void broadcastMessage(ChatMessage msg) {
        // 发送消息给所有客户端（简化：只发给这个用户）
        send(msg);
    }

    private void saveHistory(String userId, String text) {
        String path = "data/chatLogs/user_" + userId + ".txt";
        try (PrintWriter pw = new PrintWriter(new FileWriter(path, true))) {
            pw.println(LocalDateTime.now() + " | " + text);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void loadHistory(String userId) {
        String path = "data/chatLogs/user_" + userId + ".txt";
        File file = new File(path);
        if (!file.exists()) return;

        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = br.readLine()) != null) {
                logArea.append(line + "\n");
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
