import java.util.Random;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class QuickSortMultiThreading extends RecursiveTask<Void> {

    private int start, end;
    private int[] arr;
    private static final int THRESHOLD = 10; // Use sequential sort for small arrays

    public QuickSortMultiThreading(int start, int end, int[] arr) {
        this.start = start;
        this.end = end;
        this.arr = arr;
    }

    @Override
    protected Void compute() {
        // Base case: if the subarray has fewer than 2 elements, return
        if (start >= end) {
            return null;
        }

        // Use sequential sort for small arrays (avoid overhead)
        if (end - start + 1 <= THRESHOLD) {
            sequentialQuickSort(start, end);
            return null;
        }

        // Partition the array and get pivot index
        int pivotIndex = partition(start, end);

        // Create left and right subtasks
        QuickSortMultiThreading leftTask = new QuickSortMultiThreading(start, pivotIndex - 1, arr);
        QuickSortMultiThreading rightTask = new QuickSortMultiThreading(pivotIndex + 1, end, arr);

        // Fork the left task (run in parallel), compute the right task (can be parallel or not)
        leftTask.fork();
        rightTask.compute(); // Can be left as compute() if we want to use work-stealing efficiently

        // Wait for left task to complete
        leftTask.join();

        return null;
    }

    /**
     * Partition function using random pivot
     */
    private int partition(int start, int end) {
        Random rand = new Random();
        int pivotIndex = start + rand.nextInt(end - start + 1);

        // Move pivot to end
        swap(arr, pivotIndex, end);

        int i = start - 1; // Index of smaller element

        for (int j = start; j < end; j++) {
            if (arr[j] <= arr[end]) {
                i++;
                swap(arr, i, j);
            }
        }

        // Place pivot in correct position
        swap(arr, i + 1, end);
        return i + 1;
    }

    /**
     * Sequential quicksort for small subarrays (to avoid thread overhead)
     */
    private void sequentialQuickSort(int start, int end) {
        if (start >= end) return;

        int pivotIndex = partition(start, end);

        sequentialQuickSort(start, pivotIndex - 1);
        sequentialQuickSort(pivotIndex + 1, end);
    }

    /**
     * Utility method to swap two elements in the array
     */
    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    // Driver Code
    public static void main(String[] args) {
        int n = 7;
        int[] arr = {54, 64, 95, 82, 12, 32, 63};

        System.out.println("Original array: ");
        printArray(arr);

        // Use ForkJoinPool to run the task
        ForkJoinPool pool = ForkJoinPool.commonPool();
        pool.invoke(new QuickSortMultiThreading(0, n - 1, arr));

        System.out.println("Sorted array: ");
        printArray(arr);
    }

    // Helper method to print the array
    private static void printArray(int[] arr) {
        for (int value : arr) {
            System.out.print(value + " ");
        }
        System.out.println();
    }
}
