### 📌 示例：Java 客户端发送图片到 WebSocket 服务器

```java
import org.java_websocket.client.WebSocketClient;
import org.java_websocket.handshake.ServerHandshake;

import java.io.*;
import java.net.URI;
import java.net.URISyntaxException;

public class WebSocketImageClient {

    private WebSocketClient client;

    public WebSocketImageClient(String uri) throws URISyntaxException {
        this.client = new WebSocketClient(new URI(uri)) {

            @Override
            public void onOpen(ServerHandshake handshake) {
                System.out.println("Connected to server: " + handshake.getHttpStatus());
                // 发送图片
                sendImage("path/to/your/image.jpg");
            }

            @Override
            public void onMessage(String message) {
                System.out.println("Received text: " + message);
            }

            @Override
            public void onMessage(byte[] bytes) {
                System.out.println("Received binary data: " + bytes.length + " bytes");
                // 可选：保存接收到的图片（如果服务器返回了图片）
                saveImage(bytes, "received_image_from_server.jpg");
            }

            @Override
            public void onClose(int code, String reason, boolean remote) {
                System.out.println("Connection closed: " + reason);
            }

            @Override
            public void onError(Exception ex) {
                ex.printStackTrace();
            }
        };
    }

    private void sendImage(String imagePath) {
        try (FileInputStream fis = new FileInputStream(imagePath)) {
            byte[] imageBytes = fis.readAllBytes(); // 读取为字节数组

            // 使用 sendBinary 发送图片（二进制）
            client.send(imageBytes);
            System.out.println("Image sent successfully: " + imagePath);

        } catch (IOException e) {
            System.err.println("Error sending image: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void saveImage(byte[] bytes, String filename) {
        try (FileOutputStream fos = new FileOutputStream(filename)) {
            fos.write(bytes);
            System.out.println("Image saved as: " + filename);
        } catch (IOException e) {
            System.err.println("Error saving image: " + e.getMessage());
        }
    }

    public void connect() {
        client.connect();
    }

    public static void main(String[] args) {
        String serverUri = "ws://localhost:8080/websocket"; // 替换为你的 WebSocket 服务地址

        try {
            WebSocketImageClient client = new WebSocketImageClient(serverUri);
            client.connect();
        } catch (URISyntaxException e) {
            System.err.println("Invalid WebSocket URI: " + e.getMessage());
        }
    }
}
```

