### ✅ 服务器端（简单示例 - Java-WebSocket）

服务器接收二进制消息并保存图片：

```java
import org.java_websocket.WebSocket;
import org.java_websocket.handshake.ClientHandshake;
import org.java_websocket.server.WebSocketServer;

import java.net.InetSocketAddress;
import java.util.concurrent.CopyOnWriteArraySet;

import java.io.FileOutputStream;
import java.io.IOException;

public class WebSocketImageServer extends WebSocketServer {

    private final CopyOnWriteArraySet<WebSocket> connections = new CopyOnWriteArraySet<>();

    public WebSocketImageServer(int port) {
        super(new InetSocketAddress(port));
    }

    @Override
    public void onOpen(WebSocket conn, ClientHandshake handshake) {
        connections.add(conn);
        System.out.println("New connection: " + conn.getRemoteSocketAddress());
    }

    @Override
    public void onClose(WebSocket conn, int code, String reason, boolean remote) {
        connections.remove(conn);
        System.out.println("Connection closed: " + conn.getRemoteSocketAddress());
    }

    @Override
    public void onMessage(WebSocket conn, String message) {
        System.out.println("Received text: " + message);
    }

    @Override
    public void onMessage(WebSocket conn, byte[] bytes) {
        System.out.println("Received binary: " + bytes.length + " bytes");

        // 保存接收到的图片
        try (FileOutputStream fos = new FileOutputStream("received_image.jpg")) {
            fos.write(bytes);
            System.out.println("Image saved as received_image.jpg");
        } catch (IOException e) {
            e.printStackTrace();
        }

        // 可选：向客户端返回确认（例如反馈收到）
        conn.send("Image received and saved.");
    }

    @Override
    public void onError(WebSocket conn, Exception ex) {
        ex.printStackTrace();
    }

    public static void main(String[] args) {
        int port = 8080;
        WebSocketImageServer server = new WebSocketImageServer(port);
        server.start();
        System.out.println("WebSocket server started on port " + port);
    }
}
```

