## 3. `server/SocketServer.java`（Socket 服务端主类）

```java
package com.example.socketserver.server;

import com.example.socketserver.server.ClientHandler;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@Component
public class SocketServer {

    private static final Logger log = LoggerFactory.getLogger(SocketServer.class);

    @Value("${server.port:8080}")
    private int port;

    private ServerSocket serverSocket;
    private final ExecutorService executorService = Executors.newCachedThreadPool();

    public void start() {
        try {
            serverSocket = new ServerSocket(port);
            log.info("Socket 服务端启动，监听端口: {}", port);

            while (!Thread.currentThread().isInterrupted()) {
                Socket clientSocket = serverSocket.accept();
                log.info("客户端连接: {}", clientSocket.getInetAddress());

                // 提交任务给线程池处理客户端连接
                executorService.submit(new ClientHandler(clientSocket, log));
            }
        } catch (IOException e) {
            log.error("Socket 服务端启动失败", e);
        } finally {
            shutdown();
        }
    }

    public void shutdown() {
        if (serverSocket != null && !serverSocket.isClosed()) {
            try {
                serverSocket.close();
                executorService.shutdown();
                log.info("Socket 服务端已关闭");
            } catch (IOException e) {
                log.error("关闭 Socket 服务端失败", e);
            }
        }
    }
}
```

---

## 4. `server/ClientHandler.java`（客户端处理类）

```java
package com.example.socketserver.server;

import org.slf4j.Logger;
import org.springframework.stereotype.Component;

import java.io.*;
import java.net.Socket;

@Component
public class ClientHandler implements Runnable {

    private final Socket socket;
    private final Logger log;

    public ClientHandler(Socket socket, Logger log) {
        this.socket = socket;
        this.log = log;
    }

    @Override
    public void run() {
        try (
            BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter writer = new PrintWriter(socket.getOutputStream(), true)
        ) {
            String line;
            while ((line = reader.readLine()) != null) {
                log.info("收到客户端消息: {}", line);
                // 可以在此处处理逻辑，如返回响应
                writer.println("服务器已收到: " + line);
            }
        } catch (IOException e) {
            log.error("与客户端通信异常", e);
        } finally {
            try {
                socket.close();
                log.info("客户端连接已关闭");
            } catch (IOException e) {
                log.error("关闭客户端连接失败", e);
            }
        }
    }
}
```

