```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import com.fasterxml.jackson.dataformat.xml.ser.XmlOptions;

import java.io.IOException;

public class JsonToXmlConverter {

    private static final ObjectMapper jsonMapper = new ObjectMapper();
    private static final XmlMapper xmlMapper = new XmlMapper();

    /**
     * 将 JSON 字符串转换为 XML 字符串
     *
     * @param jsonString JSON 格式的字符串
     * @return XML 格式的字符串
     */
    public static String jsonToXml(String jsonString) {
        try {
            // 1. 将 JSON 字符串解析为 JsonNode
            JsonNode jsonNode = jsonMapper.readTree(jsonString);

            // 2. 将 JsonNode 转换为 XML 字符串
            // 使用 XmlMapper 序列化为 XML
            String xmlString = xmlMapper.writeValueAsString(jsonNode);

            return xmlString;

        } catch (IOException e) {
            throw new RuntimeException("JSON 转 XML 失败: " + e.getMessage(), e);
        }
    }

    /**
     * 重载方法：支持 JsonNode 输入
     */
    public static String jsonToXml(JsonNode jsonNode) {
        try {
            return xmlMapper.writeValueAsString(jsonNode);
        } catch (IOException e) {
            throw new RuntimeException("JsonNode 转 XML 失败: " + e.getMessage(), e);
        }
    }

    // ========== 测试主方法 ==========
    public static void main(String[] args) {
        // 示例 JSON 字符串
        String json = "{\n" +
                "  \"user\": {\n" +
                "    \"name\": \"张三\",\n" +
                "    \"age\": 30,\n" +
                "    \"active\": true,\n" +
                "    \"hobbies\": [\"读书\", \"编程\", \"游泳\"],\n" +
                "    \"address\": {\n" +
                "      \"city\": \"北京\",\n" +
                "      \"district\": \"朝阳区\"\n" +
                "    }\n" +
                "  }\n" +
                "}";

        // 转换
        String xml = jsonToXml(json);

        // 输出结果
        System.out.println("=== 转换结果 ===");
        System.out.println(xml);
    }
}
```

