// src/main/java/com/example/fileupload/controller/FileUploadController.java
package com.example.fileupload.controller;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

@RestController
@RequestMapping("/api/upload")
public class FileUploadController {

    @Value("${spring.servlet.multipart.location}")
    private String uploadDir;

    // Alternative: specify a custom upload directory
    // private final String uploadDir = "uploads/";

    @PostMapping("/file")
    public ResponseEntity<Map<String, Object>> uploadFile(@RequestParam("file") MultipartFile file) {
        Map<String, Object> response = new HashMap<>();

        // Check if file is empty
        if (file.isEmpty()) {
            response.put("success", false);
            response.put("message", "File is empty");
            return ResponseEntity.badRequest().body(response);
        }

        // Validate file size
        if (file.getSize() > 10 * 1024 * 1024) { // 10MB max
            response.put("success", false);
            response.put("message", "File size exceeds 10MB limit");
            return ResponseEntity.badRequest().body(response);
        }

        // Validate file type (optional)
        String contentType = file.getContentType();
        if (contentType == null || !contentType.startsWith("image/")) {
            response.put("success", false);
            response.put("message", "Only image files are allowed");
            return ResponseEntity.badRequest().body(response);
        }

        try {
            // Generate unique filename to avoid conflicts
            String originalFilename = file.getOriginalFilename();
            String extension = originalFilename.substring(originalFilename.lastIndexOf("."));
            String uniqueFilename = UUID.randomUUID().toString() + extension;

            Path uploadPath = Paths.get(uploadDir, uniqueFilename);
            Files.copy(file.getInputStream(), uploadPath, StandardCopyOption.REPLACE_EXISTING);

            // Return success response
            response.put("success", true);
            response.put("message", "File uploaded successfully");
            response.put("filename", uniqueFilename);
            response.put("size", file.getSize());
            response.put("uploadedAt", LocalDateTime.now());

            return ResponseEntity.ok(response);

        } catch (IOException e) {
            response.put("success", false);
            response.put("message", "Failed to save file: " + e.getMessage());
            return ResponseEntity.status(500).body(response);
        }
    }
}
```

