### ✅ Features:
- Uses `Hashtable<String, Object>` to store data (key: String, value: any serializable object).
- Persists data using Java's built-in serialization.
- Thread-safe storage via `Hashtable` (though you can use `ConcurrentHashMap` for better performance in multithreaded apps).
- Data stored in a `.db` file (e.g., `database.dat`).

---

### 📁 File: `MiniDB.java`

```java
import java.io.*;
import java.util.Hashtable;

public class MiniDB {
    private Hashtable<String, Object> dataStore;
    private final String DB_FILE = "database.dat";

    // Constructor: Load data from file or create new empty DB
    public MiniDB() {
        dataStore = new Hashtable<>();
        load();
    }

    // Save all data to file
    public void save() {
        try (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(DB_FILE))) {
            out.writeObject(dataStore);
            System.out.println("Database saved successfully.");
        } catch (IOException e) {
            System.err.println("Error saving database: " + e.getMessage());
        }
    }

    // Load data from file
    @SuppressWarnings("unchecked")
    public void load() {
        File file = new File(DB_FILE);
        if (file.exists()) {
            try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(DB_FILE))) {
                dataStore = (Hashtable<String, Object>) in.readObject();
                System.out.println("Database loaded successfully.");
            } catch (IOException | ClassNotFoundException e) {
                System.err.println("Error loading database: " + e.getMessage());
                dataStore = new Hashtable<>(); // Fallback to empty table
            }
        } else {
            System.out.println("No existing database found. Starting fresh.");
            dataStore = new Hashtable<>();
        }
    }

    // Put a key-value pair
    public void put(String key, Object value) {
        dataStore.put(key, value);
        save(); // Auto-save after update
    }

    // Get a value by key
    public Object get(String key) {
        return dataStore.get(key);
    }

    // Remove a key
    public boolean remove(String key) {
        if (dataStore.containsKey(key)) {
            dataStore.remove(key);
            save();
            return true;
        }
        return false;
    }

    // Check if key exists
    public boolean containsKey(String key) {
        return dataStore.containsKey(key);
    }

    // Print all keys and values
    public void printAll() {
        if (dataStore.isEmpty()) {
            System.out.println("Database is empty.");
        } else {
            System.out.println("=== Database Contents ===");
            dataStore.forEach((key, value) -> {
                System.out.println(key + " => " + value);
            });
        }
    }

    // Close / cleanup (not strictly needed but good practice)
    public void close() {
        save(); // Ensure final save
        System.out.println("Database session closed.");
    }

    // Main method to test the MiniDB
    public static void main(String[] args) {
        MiniDB db = new MiniDB();

        // Test operations
        db.put("user1", "Alice");
        db.put("user2", 25);
        db.put("config", new String[]{"theme=dark", "lang=en"});

        db.printAll();

        // Retrieve
        System.out.println("Retrieved user1: " + db.get("user1"));

        // Remove
        db.remove("user2");
        db.printAll();

        db.close();
    }
}
```

