```java
import java.io.*;
import java.net.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class HotelierServer {
    private static final int PORT = 8888;
    private static final ExecutorService threadPool = Executors.newCachedThreadPool();

    private UserManager userManager = new UserManager();
    private HotelManager hotelManager = new HotelManager();

    public static void main(String[] args) {
        new HotelierServer().start();
    }

    private void start() {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("Hotelier server avviato sulla porta " + PORT);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                threadPool.submit(new ClientHandler(clientSocket));
            }

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            threadPool.shutdown();
        }
    }

    private class ClientHandler implements Runnable {
        private Socket socket;
        private BufferedReader in;
        private PrintWriter out;

        public ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                out = new PrintWriter(socket.getOutputStream(), true);

                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    System.out.println("Ricevuto: " + inputLine);

                    Message msg = parseMessage(inputLine);
                    String response = handleCommand(msg);
                    out.println(response);
                }
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                try {
                    socket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        private Message parseMessage(String line) {
            String[] parts = line.split(":", 3);
            if (parts.length < 2) {
                return new Message("UNKNOWN", new String[]{});
            }
            return new Message(parts[0], parts.length > 1 ? parts[1].split(":") : new String[]{});
        }

        private String handleCommand(Message msg) {
            String cmd = msg.getCommand();
            String[] params = msg.getParams();

            switch (cmd) {
                case Protocol.REGISTER:
                    if (params.length < 2) return Protocol.RESP_ERROR;
                    if (userManager.register(params[0], params[1])) {
                        return Protocol.RESP_OK;
                    } else {
                        return Protocol.RESP_USERNAME_TAKEN;
                    }

                case Protocol.LOGIN:
                    if (params.length < 2) return Protocol.RESP_ERROR;
                    if (userManager.login(params[0], params[1])) {
                        return Protocol.RESP_OK;
                    } else {
                        return Protocol.RESP_INVALID_PASSWORD;
                    }

                case Protocol.LOGOUT:
                    if (params.length < 1) return Protocol.RESP_ERROR;
                    if (userManager.logout(params[0])) {
                        return Protocol.RESP_OK;
                    } else {
                        return Protocol.RESP_ERROR;
                    }

                case Protocol.SEARCH_HOTEL:
                    if (params.length < 2) return Protocol.RESP_ERROR;
                    String hotelName = params[0];
                    String city = params[1];
                    var res = hotelManager.searchHotel(hotelName, city);
                    return res.isEmpty() ? "HOTEL_NOT_FOUND" : res.get(0).toString();

                case Protocol.SEARCH_ALL_HOTELS:
                    if (params.length < 1) return Protocol.RESP_ERROR;
                    String city = params[0];
                    var hotels = hotelManager.searchAllHotels(city);
                    return hotels.isEmpty() ? "NO_HOTELS" : hotels.toString();

                case Protocol.INSERT_REVIEW:
                    if (params.length < 4) return Protocol.RESP_ERROR;
                    // Esempio parametri: [hotel, city, username, score, "cat1:5,cat2:4"]
                    // Scomposizione: hotel, city, username, score
                    String name = params[0];
                    String c = params[1];
                    String u = params[2];
                    double score = Double.parseDouble(params[3]);

                    // Simula singleScores: in un progetto reale dovrebbe essere parseato
                    // Qui lo ignoreremo per semplicità
                    if (!userManager.isUserLoggedIn(u)) {
                        return Protocol.RESP_NOT_LOGGED;
                    }
                    if (hotelManager.insertReview(name, c, u, score, null)) {
                        return Protocol.RESP_OK;
                    } else {
                        return Protocol.RESP_ERROR;
                    }

                case Protocol.SHOW_BADGES:
                    if (params.length < 1) return Protocol.RESP_ERROR;
                    User user = userManager.getUser(params[0]);
                    if (user == null || !user.isLoggedIn()) {
                        return Protocol.RESP_NOT_LOGGED;
                    }
                    return "BADGE:" + user.getLevelBadge();

                default:
                    return Protocol.RESP_ERROR;
            }
        }
    }
}
```

