import java.util.*;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class Sondage {
    private List<String> candidats;
    private Map<String, Integer> votes; // Nom du candidat → nombre de votes
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public Sondage(List<String> candidats) {
        this.candidats = new ArrayList<>(candidats);
        this.votes = new HashMap<>();
        for (String candidat : candidats) {
            votes.put(candidat, 0);
        }
    }

    // Retourne la liste des candidats
    public synchronized List<String> getCandidats() {
        return new ArrayList<>(candidats); // copie pour éviter les modifications externes
    }

    // Enregistre un vote pour le candidat numéro N (0-indexé)
    public synchronized String vote(int numero) {
        if (numero < 0 || numero >= candidats.size()) {
            return "ERR";
        }
        String candidat = candidats.get(numero);
        votes.merge(candidat, 1, Integer::sum);
        return "OK";
    }

    // Retourne le candidat le plus voté (dans le cas d'égalité, le premier est retourné)
    public synchronized String getResultat() {
        String meilleur = null;
        int max = -1;
        for (Map.Entry<String, Integer> entry : votes.entrySet()) {
            if (entry.getValue() > max) {
                max = entry.getValue();
                meilleur = entry.getKey();
            }
        }
        return meilleur != null ? meilleur : "Aucun vote";
    }
}
```

> ✅ On utilise `synchronized` sur les méthodes critiques pour assurer la **cohérence en cas de concurrence**. Alternative : `ReentrantReadWriteLock` pourrait être utilisée pour plus de performances, mais ici `synchronized` est suffisant.

