public class Serveur {
    private final int port;
    private final Sondage sondage;
    private final ExecutorService executor;
    private ServerSocket serverSocket;

    public Serveur(int port, List<String> candidats) {
        this.port = port;
        this.sondage = new Sondage(candidats);
        this.executor = Executors.newFixedThreadPool(50); // 50 clients max concurrents
    }

    public void start() {
