            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("Nouveau client connecté: " + clientSocket.getInetAddress());

                executor.submit(new ClientHandler(clientSocket, sondage));
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            stop();
        }
    }

    public void stop() {
        try {
            if (serverSocket != null) {
                serverSocket.close();
            }
            executor.shutdown();
            System.out.println("Serveur arrêté.");
        } catch (IOException e) {
            e.printStackTrace();
