```java
package com.example.secureclient;

import android.os.Build;
import android.util.Log;

import androidx.annotation.RequiresApi;

import java.io.*;
import java.net.InetAddress;
import java.net.Socket;
import java.net.UnknownHostException;
import java.security.KeyManagementException;
import java.security.KeyStore;
import java.security.NoSuchAlgorithmException;
import java.security.cert.CertificateException;
import java.security.cert.CertificateFactory;
import java.security.cert.X509Certificate;

import javax.net.ssl.*;

public class SecureTcpClient {

    private static final String TAG = "SecureTcpClient";
    private final String serverHost;
    private final int serverPort;
    private final String certificatePath; // Path to certificate file in res/raw

    private volatile boolean isConnected = false;
    private Socket socket;
    private BufferedReader in;
    private PrintWriter out;

    public interface ConnectionCallback {
        void onConnected();
        void onMessageReceived(String message);
        void onDisconnected();
        void onError(String error);
    }

    private ConnectionCallback callback;

    public SecureTcpClient(String serverHost, int serverPort, String certificatePath) {
        this.serverHost = serverHost;
        this.serverPort = serverPort;
        this.certificatePath = certificatePath;
    }

    public void setCallback(ConnectionCallback callback) {
        this.callback = callback;
    }

    @RequiresApi(api = Build.VERSION_CODES.O)
    public void connect() {
        new Thread(() -> {
            try {
                // Step 1: Create SSLContext and configure trust manager
                SSLContext sslContext = SSLContext.getInstance("TLS");
                TrustManagerFactory trustManagerFactory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
                CertificateFactory certFactory = CertificateFactory.getInstance("X.509");

                // Load custom CA or certificate (for pinning or trust)
                InputStream caInput = getCertificateInputStream();
                X509Certificate caCert = (X509Certificate) certFactory.generateCertificate(caInput);
                caInput.close();

                KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
                keyStore.load(null, null);
                keyStore.setCertificateEntry("ca", caCert);

                trustManagerFactory.init(keyStore);
                sslContext.init(null, trustManagerFactory.getTrustManagers(), new java.security.SecureRandom());

                // Step 2: Create SSLSocketFactory
                SSLSocketFactory sslSocketFactory = sslContext.getSocketFactory();

                // Step 3: Connect to server
                InetAddress address = InetAddress.getByName(serverHost);
                socket = (SSLSocket) sslSocketFactory.createSocket(address, serverPort);

                // Optional: Set protocols
                socket.setEnabledProtocols(new String[]{"TLSv1.2"});
                socket.setSoTimeout(10000); // 10 seconds timeout

                // Step 4: Get I/O streams
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                out = new PrintWriter(socket.getOutputStream(), true);

                // Notify success
                isConnected = true;
                if (callback != null) {
                    callback.onConnected();
                }

                // Step 5: Listen for messages
                String line;
                while (isConnected && (line = in.readLine()) != null) {
                    if (callback != null) {
                        callback.onMessageReceived(line);
                    }
                }

                // End of stream
                disconnect();

            } catch (Exception e) {
                Log.e(TAG, "Connection error", e);
                if (callback != null) {
                    callback.onError("Connection failed: " + e.getMessage());
                }
            }
        }).start();
    }

    public void sendMessage(String message) {
        if (out != null && isConnected) {
            out.println(message);
            Log.d(TAG, "Sent: " + message);
        } else {
            Log.e(TAG, "Socket not connected or output stream closed.");
        }
    }

    public void disconnect() {
        isConnected = false;
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (socket != null) socket.close();
            if (callback != null) {
                callback.onDisconnected();
            }
        } catch (IOException e) {
            Log.e(TAG, "Error closing connection", e);
        }
    }

    public boolean isConnected() {
        return isConnected;
    }

    private InputStream getCertificateInputStream() {
        // Load certificate from res/raw folder (e.g., ca.crt)
        try {
            return new FileInputStream(certificatePath);
        } catch (IOException e) {
            // If you want to load from assets, use:
            // return context.getAssets().open("ca.crt");

            // Example: Load from assets
            // return context.getAssets().open(certificatePath);

            Log.e(TAG, "Failed to open certificate file: " + certificatePath);
            // For demo, use embedded cert (not recommended for apps)
            // You can load from raw res if file is placed in res/raw/
            // return context.getResources().openRawResource(R.raw.ca_crt);
        }
        return null;
    }

    // Optional: If you're using a self-signed cert or want to pin
    public boolean isTrustAnchorValid() {
        // Can add certificate fingerprint pinning logic here
        return true;
    }
}
