        // Check if student with this ID already exists
        if (studentMap.containsKey(id.toString())) {
            System.out.println("Student with ID " + id + " already exists.");
            return false;
        }

        // Create a new student
        Student<T> student = new Student<>(id, name, age, major);
        studentMap.put(id.toString(), student);

        // Update major grouping
        studentsByMajor.computeIfAbsent(major, k -> new ArrayList<>()).add(student);

        System.out.println("Student " + name + " added successfully with ID: " + id);
        return true;
