import java.time.LocalDateTime;

public class Message {
    private String sender;       // 发送者：user / agent
    private String type;         // TEXT, IMAGE, FILE
    private String content;      // 文本内容 或 文件路径/图片路径
    private LocalDateTime time;
    private byte[] data;         // 二进制数据（用于图片/文件）

    public Message(String sender, String type, String content, byte[] data) {
        this.sender = sender;
        this.type = type;
        this.content = content;
        this.data = data;
        this.time = LocalDateTime.now();
    }

    // getters and setters...
    public String getSender() { return sender; }
    public void setSender(String sender) { this.sender = sender; }

    public String getType() { return type; }
    public void setType(String type) { this.type = type; }

    public String getContent() { return content; }
    public void setContent(String content) { this.content = content; }

    public byte[] getData() { return data; }
    public void setData(byte[] data) { this.data = data; }

    public LocalDateTime getTime() { return time; }
    public void setTime(LocalDateTime time) { this.time = time; }

    @Override
    public String toString() {
        return String.format("[%s] %s (%s): %s", 
                time.format(java.time.format.DateTimeFormatter.ofPattern("HH:mm:ss")), 
                sender, type, content);
    }
}
