import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.UUID;

public class FileUtil {

    // 生成唯一的聊天文件名
    public static String generateChatFileName(String userId) {
        return "chat_" + userId + "_" + UUID.randomUUID().toString().substring(0, 8) + ".log";
    }

    // 保存消息到本地文件
    public static void saveChatLog(String filename, String message) {
        try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(filename), java.nio.charset.StandardCharsets.UTF_8)) {
            writer.write(message + "\n");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 读取聊天记录
    public static String loadChatLog(String filename) {
        try {
            return new String(Files.readAllBytes(Paths.get(filename)), java.nio.charset.StandardCharsets.UTF_8);
        } catch (IOException e) {
            return "【无历史记录】";
        }
    }

    // 将图片/文件转为字节数组
    public static byte[] fileToBytes(File file) {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            Files.copy(file.toPath(), baos);
            return baos.toByteArray();
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }

    // 从字节数组保存文件
    public static boolean bytesToFile(byte[] data, String path) {
        try (FileOutputStream fos = new FileOutputStream(path)) {
            fos.write(data);
            return true;
        } catch (IOException e) {
            e.printStackTrace();
            return false;
        }
    }
}
