### ✅ 3. 客服端主服务类 `CustomerServiceServer.java`

```java
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;

public class CustomerServiceServer {
    private ServerSocket serverSocket;
    private ExecutorService executor = Executors.newFixedThreadPool(10);
    private final Map<String, ChatSession> sessions = new ConcurrentHashMap<>();
    private final Object lock = new Object();

    public CustomerServiceServer(int port) {
        try {
            serverSocket = new ServerSocket(port);
            System.out.println("客服服务端启动，监听端口 " + port);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void start() {
        while (true) {
            try {
                Socket clientSocket = serverSocket.accept();
                System.out.println("新用户连接：" + clientSocket.getInetAddress());

                ChatSession session = new ChatSession(clientSocket);
                executor.submit(session);

            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        new CustomerServiceServer(8080).start();
    }

    // 会话类
    class ChatSession implements Runnable {
        private Socket socket;
        private BufferedReader in;
        private PrintWriter out;
        private String userId;
        private boolean connected = true;

        public ChatSession(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                out = new PrintWriter(socket.getOutputStream(), true);

                while (connected && !socket.isClosed()) {
                    String line = in.readLine();
                    if (line == null) break;

                    String[] parts = line.split("\\|", 3);
                    if (parts.length < 3) continue;

                    String type = parts[0];
                    int length = Integer.parseInt(parts[1]);
                    String content = parts[2];

                    handleClientMessage(type, content, length);
                }
            } catch (IOException e) {
                System.out.println("用户断开连接：" + userId);
                close();
            }
        }

        private void handleClientMessage(String type, String content, int length) {
            if ("REQ_CONNECT".equals(type)) {
                userId = content;
                synchronized (lock) {
                    if (sessions.containsKey(userId)) {
                        send("REJECT|0|");
                        return;
                    }
                    sessions.put(userId, this);
                }
                System.out.println("用户 " + userId + " 已申请服务");
                send("ACCEPT|0|请等待客服连接...");
                broadcast("用户 " + userId + " 正在等待服务中...");
                return;
            }

            if ("TEXT".equals(type)) {
                String msg = "USER|" + userId + " says: " + content;
                System.out.println(msg);
                // 保存到本地
                FileUtil.saveChatLog("history/" + userId + ".log", msg);
                broadcast("[" + userId + "] " + content);
            }

            if ("IMAGE".equals(type)) {
                byte[] imgData = content.getBytes(); // 简化处理，实际应使用base64或流
                if (imgData.length > 0) {
                    String imgPath = "images/" + userId + "_" + System.currentTimeMillis() + ".jpg";
                    FileUtil.bytesToFile(imgData, imgPath);
                    System.out.println("图片已保存：" + imgPath);
                    broadcast("用户发送了图片：" + imgPath);
                }
            }
        }

        private void broadcast(String msg) {
            synchronized (lock) {
                for (ChatSession s : sessions.values()) {
                    if (s != this) s.send("TEXT|0|" + msg);
                }
            }
        }

        private void send(String msg) {
            try {
                out.println(msg);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        public void close() {
            connected = false;
            try {
                in.close();
                out.close();
                socket.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
            synchronized (lock) {
                sessions.remove(userId);
            }
        }
    }
}
```

