```java
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class UserClient extends JFrame {
    private JTextArea chatArea;
    private JTextField messageField;
    private JButton sendBtn, fileBtn, imageBtn;
    private JTextArea historyArea;
    private Socket socket;
    private BufferedReader in;
    private PrintWriter out;
    private String userId;
    private final BlockingQueue<String> messageQueue = new LinkedBlockingQueue<>();
    private final AtomicBoolean connected = new AtomicBoolean(false);

    // 预先加载上次聊天记录
    public UserClient(String userId) {
        this.userId = userId;
        initUI();
        connect();
        startListenThread();
    }

    private void initUI() {
        setTitle("用户端 - 电商客服系统");
        setSize(800, 600);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        // 左侧：聊天窗口
        chatArea = new JTextArea(20, 40);
        chatArea.setEditable(false);
        chatArea.setFont(new Font("微软雅黑", Font.PLAIN, 14));
        JScrollPane chatScroll = new JScrollPane(chatArea);

        // 右侧：历史记录
        historyArea = new JTextArea(20, 20);
        historyArea.setEditable(false);
        historyArea.setFont(new Font("微软雅黑", Font.PLAIN, 12));
        JScrollPane historyScroll = new JScrollPane(historyArea);
        JSplitPane splitPane = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, chatScroll, historyScroll);
        splitPane.setDividerLocation(400);

        // 底部：输入栏
        messageField = new JTextField(30);
        JPanel bottomPanel = new JPanel(new BorderLayout());
        sendBtn = new JButton("发送");
        fileBtn = new JButton("发送文件");
        imageBtn = new JButton("发送图片");
        bottomPanel.add(messageField, BorderLayout.CENTER);
        JPanel btnPanel = new JPanel(new FlowLayout());
        btnPanel.add(sendBtn);
        btnPanel.add(fileBtn);
        btnPanel.add(imageBtn);
        bottomPanel.add(btnPanel, BorderLayout.EAST);

        // 布局
        setLayout(new BorderLayout());
        add(splitPane, BorderLayout.CENTER);
        add(bottomPanel, BorderLayout.SOUTH);

        // 事件监听
        messageField.addActionListener(e -> sendMessage());
        sendBtn.addActionListener(e -> sendMessage());
        fileBtn.addActionListener(e -> sendFile());
        imageBtn.addActionListener(e -> sendImage());

        // 加载历史记录
        loadHistory();
    }

    private void connect() {
        try {
            socket = new Socket("localhost", 8080);
            in = new BufferedReader(new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8));
            out = new PrintWriter(socket.getOutputStream(), true);
            out.println("REQ_CONNECT|0|" + userId);
            connected.set(true);
            appendToChat("已连接客服，请等待响应...");

            // 客服响应超时判断
            new Timer().schedule(new TimerTask() {
                @Override
                public void run() {
                    if (connected.get()) {
                        appendToChat("【客服忙】客服暂时无法响应，请稍后重试...");
                    }
                }
            }, 20000); // 20秒无响应即提示

        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "连接失败：" + e.getMessage(), "错误", JOptionPane.ERROR_MESSAGE);
        }
    }

    private void startListenThread() {
        new Thread(() -> {
            try {
                while (connected.get()) {
                    String line = in.readLine();
                    if (line == null) break;

                    String[] parts = line.split("\\|", 3);
                    if (parts.length < 3) continue;

                    String type = parts[0];
                    int len = Integer.parseInt(parts[1]);
                    String content = parts[2].trim();

                    switch (type) {
                        case "TEXT":
                            appendToChat("客服: " + content);
                            break;
                        case "REJECT":
                            appendToChat("【服务拒绝】当前无客服可用，请稍后重试。");
                            connected.set(false);
                            break;
                        case "ACCEPT":
                            appendToChat("【已连接】客服正在为您服务...");
                            break;
                        default:
                            appendToChat("未知消息: " + line);
                    }
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }).start();
    }

    private void sendMessage() {
        String msg = messageField.getText().trim();
        if (msg.isEmpty()) return;

        out.println("TEXT|0|" + msg);
        appendToChat("我: " + msg);
        messageField.setText("");
    }

    private void sendFile() {
        JFileChooser fc = new JFileChooser();
        int result = fc.showOpenDialog(this);
        if (result == JFileChooser.APPROVE_OPTION) {
            File file = fc.getSelectedFile();
            byte[] data = FileUtil.fileToBytes(file);
            if (data != null) {
                String base64 = java.util.Base64.getEncoder().encodeToString(data);
                out.println("FILE|" + base64.length() + "|" + base64);
                appendToChat("发送文件: " + file.getName());
            }
        }
    }

    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        fc.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Image Files", "jpg", "jpeg", "png"));
        int result = fc.showOpenDialog(this);
        if (result == JFileChooser.APPROVE_OPTION) {
            File file = fc.getSelectedFile();
            byte[] data = FileUtil.fileToBytes(file);
            if (data != null) {
                String base64 = java.util.Base64.getEncoder().encodeToString(data);
                out.println("IMAGE|" + base64.length() + "|" + base64);
                appendToChat("发送图片: " + file.getName());
            }
        }
    }

    private void appendToChat(String msg) {
        SwingUtilities.invokeLater(() -> {
            chatArea.append(msg + "\n");
            chatArea.setCaretPosition(chatArea.getDocument().getLength());
        });
    }

    private void loadHistory() {
        String filename = "history/" + userId + ".log";
        String history = FileUtil.loadChatLog(filename);
        SwingUtilities.invokeLater(() -> {
            historyArea.setText("=== 历史聊天记录 ===\n" + history);
        });
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            new UserClient("user_001").setVisible(true);
        });
    }
}
