using System;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Threading.Tasks;

class Socks5Server
{
    static async Task Main()
    {
        var listener = new TcpListener(IPAddress.Any, 1080);
        listener.Start();
        Console.WriteLine("Socks5 服务器启动在 1080 端口");

        while (true)
        {
            var client = await listener.AcceptTcpClientAsync();
            _ = HandleClientAsync(client);
        }
    }

    static async Task HandleClientAsync(TcpClient client)
    {
        var stream = client.GetStream();
        var buffer = new byte[4096];

        // 1. 读取 Socks5 握手
        var len = await stream.ReadAsync(buffer, 0, 2);
        if (len < 2 || buffer[0] != 0x05) return;

        // 2. 发送支持的认证方式：NO AUTH (0x00)
        await stream.WriteAsync(new byte[] { 0x05, 0x00 }, 0, 2);

        // 3. 读取请求
        len = await stream.ReadAsync(buffer, 0, 4);
        if (len < 4 || buffer[0] != 0x05) return;

        var command = buffer[1];
        var addrType = buffer[3];

        // 解析目标地址（IPv4）
        if (addrType == 0x01)
        {
            var host = new IPAddress(new[] { buffer[4], buffer[5], buffer[6], buffer[7] });
            var port = (buffer[8] << 8) | buffer[9];

            // 4. 建立与目标服务器的连接
            var target = new TcpClient();
            await target.ConnectAsync(host, port);

            // 5. 发送成功响应
            await stream.WriteAsync(new byte[] { 0x05, 0x00, 0x00, 0x01, 0,0,0,0, 0,0 }, 0, 10);

            // 6. 双向转发
            await Task.WhenAll(
                CopyAsync(stream, target.GetStream()),
                CopyAsync(target.GetStream(), stream)
            );
        }
        else
        {
            // 其他地址类型（域名、IPv6）可扩展
            await stream.WriteAsync(new byte[] { 0x05, 0x08, 0x00, 0x01, 0,0,0,0, 0,0 }, 0, 10); // 0x08: Command not supported
        }

        client.Close();
    }

    static async Task CopyAsync(Stream src, Stream dest)
    {
        var buffer = new byte[4096];
        int len;
        while ((len = await src.ReadAsync(buffer, 0, buffer.Length)) > 0)
        {
            await dest.WriteAsync(buffer, 0, len);
        }
    }
}
