## 4. 🧠 `ScriptManager.kt` – Orchestrates JS Modules

```kotlin
// src/main/kotlin/script/ScriptManager.kt
package com.example.mymod.script

import javax.script.*
import net.minecraftforge.fml.common.FMLCommonHandler
import java.io.File
import java.net.URI
import kotlin.system.exitProcess

object ScriptManager {
    private lateinit var engine: ScriptEngine
    private val scriptCache = mutableMapOf<String, Script>()
    private const val SCRIPTS_DIR = "scripts"
    private const val SCRIPT_EXT = ".js"

    fun init() {
        val manager = ScriptEngineManager()
        engine = manager.getEngineByName("nashorn") ?: throw IllegalStateException("Nashorn not available!")
        println("[JS Mod] Nashorn engine initialized.")
        setupNodeJSInterface()
        loadAllScripts()
    }

    private fun setupNodeJSInterface() {
        val globalScope = engine.eval("({})") as ScriptContext

        // Mock console.log
        engine.put("console", object {
            fun log(message: Any?) {
                println("JS> ${message ?: ""}")
            }
        })

        // Mock process (minimal)
        engine.put("process", object {
            fun exit(code: Int) {
                println("JS> process.exit($code)")
                exitProcess(code)
            }

            val argv = arrayOf()
        })

        // Mock require (basic)
        engine.put("require", object {
            fun call(moduleName: String): Any? {
                return when (moduleName) {
                    "fs" -> {
                        println("JS> fs module loaded (stub)")
                        object {
                            fun writeFileSync(path: String, data: String) {
                                println("JS> Writing to $path: $data")
                            }
                        }
                    }
                    "path" -> {
                        println("JS> path module loaded (stub)")
                        object {
                            fun join(vararg parts: String): String {
                                return parts.joinToString(separator = "/")
                            }
                        }
                    }
                    else -> {
                        println("JS> require('$moduleName') not implemented")
                        null
                    }
                }
            }
        })

        // Inject global context
        engine.put("global", engine.context)
    }

    fun loadAllScripts() {
        val scriptsDir = File("src/main/resources/assets/mymod/$SCRIPTS_DIR")
        if (!scriptsDir.exists() || !scriptsDir.isDirectory) {
            println("[JS Mod] No scripts directory found: $scriptsDir")
            return
        }

        scriptsDir.listFiles()?.filter { it.isFile && it.name.endsWith(SCRIPT_EXT) }?.forEach { file ->
            try {
                val script = Script(file.nameWithoutExtension, file.readText())
                script.run()
                scriptCache[file.nameWithoutExtension] = script
                println("[JS Mod] Loaded script: ${file.name}")
            } catch (e: Exception) {
                println("[JS Mod] Error loading script ${file.name}: ${e.message}")
                e.printStackTrace()
            }
        }
    }

    class Script(private val name: String, private val code: String) {
        fun run() {
            try {
                engine.eval(code, engine.context)
            } catch (e: ScriptException) {
                println("[JS Mod] Script error in $name: ${e.message}")
                e.printStackTrace()
            }
        }
    }
}
```

