import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;

@WebServlet("/DivideServlet")
public class DivideServlet extends HttpServlet {

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        // 1. 获取表单参数
        String strNum1 = request.getParameter("num1");
        String strNum2 = request.getParameter("num2");

        // 2. 设置响应内容类型
        response.setContentType("text/html;charset=UTF-8");

        // 3. 获取输出流
        PrintWriter out = response.getWriter();

        // 4. 初始化结果
        double num1 = 0.0;
        double num2 = 0.0;
        double result = 0.0;

        try {
            // 5. 尝试将字符串转换为 double 类型
            num1 = Double.parseDouble(strNum1);
            num2 = Double.parseDouble(strNum2);

            // 6. 判断除数是否为 0
            if (num2 == 0) {
                out.println("<h3 style='color:red'>错误：除数不能为 0！</h3>");
                out.println("<a href='divide.html'>返回重新输入</a>");
                return;
            }

            // 7. 执行除法运算
            result = num1 / num2;

            // 8. 输出结果
            out.println("<h3>计算结果：</h3>");
            out.println("<p>" + num1 + " ÷ " + num2 + " = " + result + "</p>");
            out.println("<a href='divide.html'>返回重新计算</a>");

        } catch (NumberFormatException e) {
            // 9. 输入格式错误（如输入非数字）
            out.println("<h3 style='color:red'>错误：请输入有效的数字！</h3>");
            out.println("<a href='divide.html'>返回重新输入</a>");
        } finally {
            out.close();
        }
    }
}
```

> ✅ 该 Servlet 必须放在 `src/main/java` 目录下，包名如 `com.example.servlet`（需根据项目结构调整），并确保项目已配置为支持 Servlet（如使用 Maven 或配置 `web.xml`）。

