```java
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;
import org.w3c.dom.Document;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import java.io.StringWriter;

public class XmlExtractor {

    /**
     * Extracts a specific XML fragment by tag name from a given XML string.
     * 
     * @param xmlString The full XML as a string
     * @param tagName The tag name to extract (e.g., "record", "user")
     * @return The extracted XML fragment as a string, or null if not found
     */
    public static String extractXmlByTagName(String xmlString, String tagName) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();

            // Parse the XML string into a Document
            Document doc = builder.parse(new java.io.ByteArrayInputStream(xmlString.getBytes("UTF-8")));

            // Normalize the document
            doc.getDocumentElement().normalize();

            // Get all elements with the specified tag name
            NodeList nodeList = doc.getElementsByTagName(tagName);

            if (nodeList.getLength() == 0) {
                System.out.println("No elements found with tag name: " + tagName);
                return null;
            }

            // Extract the first matching node (you can modify this to extract multiple)
            Node node = nodeList.item(0);

            // Convert the Node to a String
            return nodeToString(node);

        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    /**
     * Converts a DOM Node to a String representation of XML.
     * 
     * @param node The DOM Node to convert
     * @return The XML string representation
     */
    private static String nodeToString(Node node) {
        try {
            TransformerFactory factory = TransformerFactory.newInstance();
            Transformer transformer = factory.newTransformer();
            transformer.setOutputProperty(javax.xml.transform.OutputKeys.OMIT_XML_DECLARATION, "yes");
            transformer.setOutputProperty(javax.xml.transform.OutputKeys.INDENT, "no"); // Remove indentation

            StringWriter writer = new StringWriter();
            transformer.transform(new DOMSource(node), new StreamResult(writer));

            return writer.getBuffer().toString();

        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    // Example usage
    public static void main(String[] args) {
        String xmlString = 
            "<catalog>" +
                "  <book id=\"1\">" +
                "    <title>Java Programming</title>" +
                "    <author>John Doe</author>" +
                "    <year>2020</year>" +
                "  </book>" +
                "  <book id=\"2\">" +
                "    <title>Advanced Java</title>" +
                "    <author>Jane Smith</author>" +
                "    <year>2021</year>" +
                "  </book>" +
                "  <info>" +
                "    <status>active</status>" +
                "  </info>" +
                "</catalog>";

        // Extract all <book> elements
        String extractedBook = extractXmlByTagName(xmlString, "book");
        if (extractedBook != null) {
            System.out.println("Extracted Book:\n" + extractedBook);
        }

        // Extract <status> element
        String extractedStatus = extractXmlByTagName(xmlString, "status");
        if (extractedStatus != null) {
            System.out.println("Extracted Status:\n" + extractedStatus);
        }
    }
}
```

### Key Features:
- **Parses** the input XML string into a DOM `Document`.
- **Finds** nodes by tag name using `getElementsByTagName()`.
- **Converts** the extracted `Node` back into an XML string.
- **Handles exceptions** gracefully.
- **Customizable** — you can modify the extraction logic (e.g., extract by attribute, XPath, etc.).

### Output Example:
```
Extracted Book:
<book id="1">
    <title>Java Programming</title>
    <author>John Doe</author>
    <year>2020</year>
</book>
Extracted Status:
<status>active</status>
```

---

### Alternative: Using XPath (for more complex selections)

If you need to extract based on attributes or complex conditions, use **XPath**:

```java
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathFactory;

public static String extractByXPath(String xmlString, String xpathExpression) {
    try {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(new java.io.ByteArrayInputStream(xmlString.getBytes("UTF-8")));

        XPath xPath = XPathFactory.newInstance().newXPath();
        Node node = (Node) xPath.compile(xpathExpression).evaluate(doc, XPathConstants.NODE);

        if (node != null) {
            return nodeToString(node);
        }
        return null;
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}
```

