import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.FileReader;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.List;
import java.util.ArrayList;

// javac -cp ".:lib/gson-2.10.1.jar" HOTELIERServer.java Hotel.java
// java -cp ".:lib/gson-2.10.1.jar" HOTELIERServer

public class HOTELIERServer {

    private List<Hotel> hotels;

    public HOTELIERServer(String jsonFilePath) {
        loadHotelsFromJson(jsonFilePath);
    }

    private void loadHotelsFromJson(String jsonFilePath) {
        Gson gson = new Gson();
        try (FileReader reader = new FileReader(jsonFilePath)) {
            Type hotelListType = new TypeToken<ArrayList<Hotel>>() {}.getType();
            hotels = gson.fromJson(reader, hotelListType);

            // Se la lista è null, creiamo una lista vuota
            if (hotels == null) {
                hotels = new ArrayList<>();
            }

            // Forziamo l'inizializzazione dei punteggi a 0 per ogni hotel, anche se nel JSON mancano
            for (Hotel hotel : hotels) {
                if (hotel.ratings == null) {
                    hotel.ratings = new Hotel.Ratings();
                }
                // Assicurati che i punteggi siano 0
                hotel.ratings.cleaning = 0;
                hotel.ratings.position = 0;
                hotel.ratings.services = 0;
                hotel.ratings.quality = 0;
            }

        } catch (IOException e) {
            e.printStackTrace();
            hotels = new ArrayList<>(); // evita null pointer
        }
    }

    // Aggiungi metodo per ottenere i dati degli hotel
    public List<Hotel> getHotels() {
        return hotels;
    }

    public static void main(String[] args) {
        String jsonFilePath = "Hotels.json";
        HOTELIERServer server = new HOTELIERServer(jsonFilePath);

        // Stampa tutti gli hotel
        System.out.println("=== Elenco Hotel ===");
        for (Hotel hotel : server.hotels) {
            System.out.println("Nome: " + hotel.name);
            System.out.println("  City: " + hotel.city);
            System.out.println("  Rate: " + hotel.rate);
            System.out.println("  Ratings - Cleaning: " + hotel.ratings.cleaning +
                               ", Position: " + hotel.ratings.position +
                               ", Services: " + hotel.ratings.services +
                               ", Quality: " + hotel.ratings.quality);
            System.out.println();
        }
    }
}

class Hotel {
    int id;
    String name;
    String description;
    String city;
    String phone;
    List<String> services;
    int rate;

    Ratings ratings;

    // Costruttore di default che inizializza Ratings a 0
    public Hotel() {
        this.ratings = new Ratings();
