import java.security.MessageDigest;
import java.util.Objects;

public class Transaction {
    private String sender;
    private String receiver;
    private double amount;

    public Transaction(String sender, String receiver, double amount) {
        this.sender = sender;
        this.receiver = receiver;
        this.amount = amount;
    }

    // Simple hash of the transaction (for demo)
    public String getHash() {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            String input = sender + receiver + amount;
            byte[] hash = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error hashing transaction", e);
        }
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Transaction that = (Transaction) o;
        return Double.compare(that.amount, amount) == 0 &&
               Objects.equals(sender, that.sender) &&
               Objects.equals(receiver, that.receiver);
    }

    @Override
    public int hashCode() {
        return Objects.hash(sender, receiver, amount);
    }

    // Getters
    public String getSender() { return sender; }
    public String getReceiver() { return receiver; }
    public double getAmount() { return amount; }

    @Override
    public String toString() {
        return String.format("Tx{from=%s, to=%s, amount=%.2f, hash=%s}",
                sender, receiver, amount, getHash().substring(0, 8));
    }
}
