```java
import java.util.ArrayList;
import java.util.List;

public class Blockchain {
    private List<Block> chain;
    private int difficulty;

    public Blockchain() {
        this.chain = new ArrayList<>();
        this.difficulty = 3; // Number of leading zeros in hash
        // Genesis block
        Block genesisBlock = new Block(0, List.of(), "0");
        genesisBlock.mineBlock(difficulty);
        chain.add(genesisBlock);
    }

    public void addBlock(List<Transaction> transactions) {
        Block newBlock = new Block(chain.size(), transactions, chain.get(chain.size() - 1).getHash());
        newBlock.mineBlock(difficulty);
        chain.add(newBlock);
        System.out.println("Block added: " + newBlock);
    }

    public boolean isChainValid() {
        for (int i = 1; i < chain.size(); i++) {
            Block current = chain.get(i);
            Block previous = chain.get(i - 1);

            if (!current.getHash().equals(current.calculateHash())) {
                System.out.println("Block " + i + " hash mismatch!");
                return false;
            }

            if (!current.getPreviousHash().equals(previous.getHash())) {
                System.out.println("Block " + i + " previous hash mismatch!");
                return false;
            }
        }
        return true;
    }

    public List<Block> getChain() {
        return chain;
    }

    public void printChain() {
        System.out.println("=== Blockchain ===");
        for (Block block : chain) {
            System.out.println(block);
            for (Transaction tx : block.getTransactions()) {
                System.out.println("  " + tx);
            }
        }
        System.out.println("==================");
    }
}
```

