import java.util.concurrent.atomic.AtomicLong;

public class BankAccountSimulation {

    // 使用 AtomicLong 保证线程安全的累加操作（替代 synchronized）
    private static final AtomicLong totalAmount = new AtomicLong(0);

    // 顾客汇款的次数（每个顾客汇款次数不同）
    private static final int CUSTOMER_COUNT = 3;
    private static final int MAX_TRANSFER_PER_CUSTOMER = 5;

    // 银行账户类
    public static class BankAccount {
        public static void deposit(long amount) {
            // 使用原子操作累加，线程安全
            totalAmount.addAndGet(amount);
            System.out.println("汇款成功: " + amount + " 元，当前总额: " + totalAmount.get());
        }
    }

    // 顾客类（线程）
    public static class Customer implements Runnable {
        private final int customerId;
        private final int numTransfers;

        public Customer(int customerId, int numTransfers) {
            this.customerId = customerId;
            this.numTransfers = numTransfers;
        }

        @Override
        public void run() {
            for (int i = 0; i < numTransfers; i++) {
                // 模拟每次汇款的时间差异（随机延迟）
                try {
                    Thread.sleep((long) (Math.random() * 1000)); // 0 ~ 999ms 延迟
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }

                // 随机汇款金额（100 ~ 1000 元）
                long amount = 100 + (long) (Math.random() * 900);

                // 汇款
                BankAccount.deposit(amount);

                // 模拟汇款完成
                System.out.println("顾客 " + customerId + " 第 " + (i + 1) + " 次汇款完成。");
            }
        }
    }

    public static void main(String[] args) {
        System.out.println("=== 银行账户汇款模拟开始 ===");

        // 创建并启动所有顾客线程
        Thread[] threads = new Thread[CUSTOMER_COUNT];
        for (int i = 0; i < CUSTOMER_COUNT; i++) {
            // 每个顾客的汇款次数随机（1~5次）
            int numTransfers = 1 + (int) (Math.random() * MAX_TRANSFER_PER_CUSTOMER);
            threads[i] = new Thread(new Customer(i + 1, numTransfers));
            threads[i].start();
        }

        // 等待所有线程执行完毕
        for (Thread t : threads) {
            try {
                t.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        // 输出总汇款金额
        System.out.println("=== 汇款结束，总汇款金额: " + totalAmount.get() + " 元 ===");

        // 重置总额，为下次运行准备
        totalAmount.set(0);
    }
}
```

