  await page.goto('https://your-website.com/checkout', { waitUntil: 'networkidle2' });

  try {
    // Wait for the Stripe Checkout iframe to be loaded
    const iframe = await page.waitForSelector('iframe#stripe-checkout-iframe', {
      visible: true,
      timeout: 10000,
    });

    // Get the iframe element and access its frame
    const frame = await iframe.contentFrame();

    if (!frame) {
      console.error('Could not access iframe content');
      return;
    }

    // Now interact with elements inside the iframe
    // Use proper selectors inside the iframe

    // ✅ Card Number
    const cardNumberInput = await frame.waitForSelector('#cardNumber', { visible: true });
    await cardNumberInput.type('4242424242424242'); // Test Visa card

    // ✅ Expiry Date (MM/YY)
    const expiryInput = await frame.waitForSelector('#cardExpiry', { visible: true });
    await expiryInput.type('1225'); // MMYY format

    // ✅ CVC
    const cvcInput = await frame.waitForSelector('#cardCvc', { visible: true });
    await cvcInput.type('123');

    // ✅ Cardholder Name
    const nameInput = await frame.waitForSelector('#billingName', { visible: true });
    await nameInput.type('John Doe');

    // ✅ Country (select)
