const Student = require('../models/Student');

// Lister tous les étudiants
exports.getAllStudents = async (req, res) => {
  try {
    const students = await Student.find().populate('idChambre');
    res.json(students);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};

// Obtenir un étudiant par ID
exports.getStudentById = async (req, res) => {
  try {
    const student = await Student.findById(req.params.id).populate('idChambre');
    if (!student) return res.status(404).json({ message: 'Étudiant non trouvé' });
    res.json(student);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};

// Créer un nouvel étudiant
exports.createStudent = async (req, res) => {
  const { matricule, nom, prenom, email, telephone, filiere, niveau, dateArrivee, idChambre } = req.body;

  try {
    const student = new Student({
      matricule,
      nom,
      prenom,
      email,
      telephone,
      filiere,
      niveau,
      dateArrivee,
      idChambre
    });

    const savedStudent = await student.save();

    // Mettre à jour la disponibilité de la chambre
    if (idChambre) {
      await mongoose.models.Room.findByIdAndUpdate(idChambre, { disponible: false });
    }

    res.status(201).json(savedStudent);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
};

// Mettre à jour un étudiant
exports.updateStudent = async (req, res) => {
  try {
    const student = await Student.findById(req.params.id);
    if (!student) return res.status(404).json({ message: 'Étudiant non trouvé' });

    Object.assign(student, req.body);
    await student.save();

    res.json(student);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
};

// Supprimer un étudiant
exports.deleteStudent = async (req, res) => {
  try {
    const student = await Student.findById(req.params.id);
    if (!student) return res.status(404).json({ message: 'Étudiant non trouvé' });

    await student.remove();

    // Réactiver la chambre si elle était occupée
    if (student.idChambre) {
      await mongoose.models.Room.findByIdAndUpdate(student.idChambre, { disponible: true });
    }

    res.json({ message: 'Étudiant supprimé avec succès' });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};
