import React, { useEffect, useState } from 'react';
import { getStudents, deleteStudent } from '../services/api';

export default function StudentsList() {
  const [students, setStudents] = useState([]);

  useEffect(() => {
    const fetchStudents = async () => {
      try {
        const res = await getStudents();
        setStudents(res.data);
      } catch (err) {
        alert('Erreur chargement étudiants');
      }
    };
    fetchStudents();
  }, []);

  const handleDelete = async (id) => {
    if (window.confirm('Supprimer cet étudiant ?')) {
      await deleteStudent(id);
      setStudents(students.filter(s => s._id !== id));
    }
  };

  return (
    <div>
      <h2>Gestion des Étudiants</h2>
      <table className="table">
        <thead>
          <tr>
            <th>Matière</th>
            <th>Nom</th>
            <th>Email</th>
            <th>Chambre</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {students.map(s => (
            <tr key={s._id}>
              <td>{s.matricule}</td>
              <td>{s.prenom} {s.nom}</td>
              <td>{s.email}</td>
              <td>{s.idChambre?.numero || 'Non assigné'}</td>
              <td>
                <button onClick={() => handleDelete(s._id)} className="btn btn-danger">Supprimer</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
