<body>

<canvas id="canvas"></canvas>

<div id="vmc-menu">
  <h4>VMC Menu</h4>
  <button id="add-point">Add Point</button>
  <button id="draw-line">Draw Line</button>
  <button id="clear-all">Clear All</button>
  <button id="toggle-grid">Toggle Grid</button>
</div>

<div class="info">
  <span id="info-status">Mode: Idle</span><br/>
  <span id="info-3d">3D (X:0°, Y:0°, Z:0°)</span>
</div>

<div class="instructions">
  <strong>VMC Controls:</strong><br/>
  - Click & drag to rotate model.<br/>
  - Hold 'Add Point' or 'Draw Line' to snap to grid.<br/>
  - Hover over canvas to show menu (click to activate).<br/>
  - Use keyboard: R=Reset, C=Clear, G=Toggle Grid.
</div>

<script>
  // === STATE MANAGEMENT ===
  const state = {
    // 3D grid snapping points (3D space array of {x,y,z})
    gridPoints: [],

    // Stored actual 3D wireframe model points (just vertices)
    modelPoints: [],

    // Drawn line segments: [ {start: {x,y,z}, end: {x,y,z}} ]
    drawnLines: [],

    // Model rotation angles (in degrees)
    rotX: 0, rotY: 0, rotZ: 0,

    // Mouse state
    isDragging: false,
    lastX: 0, lastY: 0,
    dragTarget: null, // 'model' or 'line'

    // Snap mode
    snapMode: null, // 'add-point', 'draw-line'
    snapDistance: 20, // max snap distance (in 2D screen space)
    showGrid: true,

    // Current action states
    currentLine: null, // {start: {x,y,z}}
    tempPoint: null, // temporary point during line draw
  };

  // === CANVAS & CONTEXT ===
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');

  // Resize canvas to window
  function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  }
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  // === MATRIX & 3D MATH UTILITIES ===
  const pi = Math.PI;
  const degToRad = (deg) => deg * (pi / 180);

  // 3D to 2D Projection (Simple Perspective)
  function project3D(x, y, z, width, height, fov = 1000) {
    const scale = fov / (fov + z);
    const px = width / 2 + x * scale;
    const py = height / 2 + y * scale;
    return { x: px, y: py, scale };
  }

  // Rotate point around X, Y, Z axes (in radians)
  function rotate3D(point, rotX, rotY, rotZ) {
    const { x, y, z } = point;
    const cosX = Math.cos(rotX), sinX = Math.sin(rotX);
    const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
    const cosZ = Math.cos(rotZ), sinZ = Math.sin(rotZ);

    // Rotate around X
    let ry = y * cosX - z * sinX;
    let rz = y * sinX + z * cosX;

    // Rotate around Y
    let rx = x * cosY + rz * sinY;
    rz = -x * sinY + rz * cosY;

    // Rotate around Z
    rx = rx * cosZ - ry * sinZ;
    ry = rx * sinZ + ry * cosZ;

    return { x: rx, y: ry, z: rz };
  }

  // === GRID GENERATION ===
  function generateGridPoints() {
    const grid = [];
    const size = 10; // Grid size (e.g. -5 to +5)
    const step = 1;

    for (let x = -size; x <= size; x += step) {
      for (let y = -size; y <= size; y += step) {
        for (let z = -size; z <= size; z += step) {
          grid.push({ x, y, z });
        }
      }
    }
    return grid;
  }

  // Initialize grid
  state.gridPoints = generateGridPoints();

  // === VMC MENU INTERACTION ===
  const menu = document.getElementById('vmc-menu');
  const buttons = {
    'add-point': document.getElementById('add-point'),
    'draw-line': document.getElementById('draw-line'),
    'clear-all': document.getElementById('clear-all'),
    'toggle-grid': document.getElementById('toggle-grid'),
  };

  // Show menu when hovering canvas, hide on leave
  canvas.addEventListener('mouseenter', () => {
    menu.classList.add('visible');
  });

  canvas.addEventListener('mouseleave', () => {
    menu.classList.remove('visible');
  });

  // Button click handlers
  buttons['add-point'].addEventListener('click', () => {
    state.snapMode = 'add-point';
    updateStatus('Mode: Add Point (Click grid point)');
  });

  buttons['draw-line'].addEventListener('click', () => {
    state.snapMode = 'draw-line';
    updateStatus('Mode: Draw Line (Click & drag to start/end)');
  });

  buttons['clear-all'].addEventListener('click', () => {
    state.drawnLines = [];
    state.modelPoints = [];
    state.currentLine = null;
    state.tempPoint = null;
    updateStatus('All cleared');
  });

  buttons['toggle-grid'].addEventListener('click', () => {
    state.showGrid = !state.showGrid;
    updateStatus(state.showGrid ? "Grid: ON" : "Grid: OFF");
  });

  // Keyboard shortcuts
  window.addEventListener('keydown', (e) => {
    if (e.key === 'r' || e.key === 'R') {
      state.rotX = 0; state.rotY = 0; state.rotZ = 0;
      updateStatus("Model reset");
    } else if (e.key === 'c' || e.key === 'C') {
      buttons['clear-all'].click();
    } else if (e.key === 'g' || e.key === 'G') {
      buttons['toggle-grid'].click();
    }
  });

  // Update status label
  function updateStatus(msg) {
    const status = document.getElementById('info-status');
    if (status) status.textContent = msg;
  }

  // === HELPER: Find Closest Grid Point ===
  function findClosestGridPoint(px, py) {
    let minDist = Infinity;
    let closest = null;

    for (let point of state.gridPoints) {
      const rotated = rotate3D(point, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));
      const { x, y } = project3D(rotated.x, rotated.y, rotated.z, canvas.width, canvas.height);

      const dx = x - px;
      const dy = y - py;
      const dist = dx * dx + dy * dy;

      if (dist < minDist && dist < state.snapDistance ** 2) {
        minDist = dist;
        closest = point;
      }
    }

    return closest;
  }

  // === DRAWING FUNCTIONS ===
  function drawGrid() {
    if (!state.showGrid) return;

    ctx.strokeStyle = '#333';
    ctx.lineWidth = 0.5;
    ctx.globalAlpha = 0.2;

    const size = 10;
    const step = 1;

    // Draw XZ plane grid
    for (let x = -size; x <= size; x += step) {
      for (let z = -size; z <= size; z += step) {
        const p1 = { x: x, y: 0, z: z };
        const p2 = { x: x + step, y: 0, z: z };
        const p3 = { x: x, y: 0, z: z };
        const p4 = { x: x, y: 0, z: z + step };

        const r1 = rotate3D(p1, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));
        const r2 = rotate3D(p2, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));
        const r3 = rotate3D(p3, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));
        const r4 = rotate3D(p4, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));

        const p1v = project3D(r1.x, r1.y, r1.z, canvas.width, canvas.height);
        const p2v = project3D(r2.x, r2.y, r2.z, canvas.width, canvas.height);
        const p3v = project3D(r3.x, r3.y, r3.z, canvas.width, canvas.height);
        const p4v = project3D(r4.x, r4.y, r4.z, canvas.width, canvas.height);

        ctx.beginPath();
        ctx.moveTo(p1v.x, p1v.y);
        ctx.lineTo(p2v.x, p2v.y);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(p3v.x, p3v.y);
        ctx.lineTo(p4v.x, p4v.y);
        ctx.stroke();
      }
    }

    ctx.globalAlpha = 1;
  }

  function drawModelPoints() {
    ctx.fillStyle = '#0f9';
    for (const point of state.modelPoints) {
      const rotated = rotate3D(point, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));
      const proj = project3D(rotated.x, rotated.y, rotated.z, canvas.width, canvas.height);

      ctx.beginPath();
      ctx.arc(proj.x, proj.y, 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
  }

  function drawDrawnLines() {
    ctx.strokeStyle = '#f00';
    ctx.lineWidth = 2;

    for (const line of state.drawnLines) {
      const startRot = rotate3D(line.start, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));
      const endRot = rotate3D(line.end, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));

      const startProj = project3D(startRot.x, startRot.y, startRot.z, canvas.width, canvas.height);
      const endProj = project3D(endRot.x, endRot.y, endRot.z, canvas.width, canvas.height);

      ctx.beginPath();
      ctx.moveTo(startProj.x, startProj.y);
      ctx.lineTo(endProj.x, endProj.y);
      ctx.stroke();
    }
  }

  function drawCurrentLine() {
    if (!state.currentLine || !state.tempPoint) return;

    ctx.strokeStyle = '#0f0';
    ctx.lineWidth = 2;

    const startRot = rotate3D(state.currentLine.start, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));
    const endRot = rotate3D(state.tempPoint, degToRad(state.rotX), degToRad(state.rotY), degToRad(state.rotZ));

    const startProj = project3D(startRot.x, startRot.y, startRot.z, canvas.width, canvas.height);
    const endProj = project3D(endRot.x, endRot.y, endRot.z, canvas.width, canvas.height);

    ctx.beginPath();
    ctx.moveTo(startProj.x, startProj.y);
    ctx.lineTo(endProj.x, endProj.y);
    ctx.stroke();
  }

  function drawVMCMenu() {
    const rect = canvas.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();

    if (menu.classList.contains('visible')) {
      const mouseX = state.lastX;
      const mouseY = state.lastY;

      let adjustedX = mouseX + 10;
      let adjustedY = mouseY + 10;

      // Prevent menu from going off-screen
      if (adjustedX + menuRect.width > rect.right) adjustedX = mouseX - menuRect.width - 10;
      if (adjustedY + menuRect.height > rect.bottom) adjustedY = mouseY - menuRect.height - 10;

      menu.style.left = `${adjustedX}px`;
      menu.style.top = `${adjustedY}px`;
    }
  }

  function update3DStatus() {
    const el = document.getElementById('info-3d');
    if (el) {
      el.textContent = `3D: X:${state.rotX.toFixed(1)}°, Y:${state.rotY.toFixed(1)}°, Z:${state.rotZ.toFixed(1)}°`;
    }
  }

  // === RENDER LOOP ===
  function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw background
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw grid (only if enabled)
    drawGrid();

    // Draw lines first (so they are behind points)
    drawDrawnLines();

    // Draw model points
    drawModelPoints();

    // Draw current line (if drawing)
    drawCurrentLine();

    // Draw VMC menu
    drawVMCMenu();

    // Update rotation status
    update3DStatus();

    requestAnimationFrame(render);
  }

  // Start rendering
  render();

  // === MOUSE EVENTS ===
  canvas.addEventListener('mousedown', (e) => {
    const mouseX = e.clientX;
    const mouseY = e.clientY;

    state.isDragging = true;
    state.lastX = mouseX;
    state.lastY = mouseY;

    const closest = findClosestGridPoint(mouseX, mouseY);

    if (state.snapMode === 'add-point' && closest) {
      state.modelPoints.push({ ...closest }); // Store 3D point
      updateStatus(`Point added: (${closest.x},${closest.y},${closest.z})`);
      state.snapMode = null; // Reset
      menu.classList.remove('visible'); // Hide menu
    } else if (state.snapMode === 'draw-line' && closest) {
      state.currentLine = { start: { ...closest } };
      state.tempPoint = null; // Start line
      updateStatus("Drawing line...");
    } else {
      // Default: rotate model if no snap mode
      state.dragTarget = 'model';
    }
  });

  canvas.addEventListener('mousemove', (e) => {
    const mouseX = e.clientX;
    const mouseY = e.clientY;

    state.lastX = mouseX;
    state.lastY = mouseY;

    // Only update menu position
    const rect = canvas.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const x = e.clientX + 10;
    const y = e.clientY + 10;

    // Update menu position (hover)
    menu.style.left = `${x}px`;
    menu.style.top = `${y}px`;

    // If currently drawing line
    if (state.snapMode === 'draw-line' && state.currentLine) {
      const closest = findClosestGridPoint(mouseX, mouseY);
      if (closest) {
        state.tempPoint = { ...closest };
      } else {
        state.tempPoint = null;
      }
    }
  });

  canvas.addEventListener('mouseup', () => {
    if (state.isDragging) {
      state.isDragging = false;
      state.dragTarget = null;

      if (state.snapMode === 'draw-line' && state.currentLine && state.tempPoint) {
        // Finalize line
        const line = {
          start: { ...state.currentLine.start },
          end: { ...state.tempPoint }
        };

        state.drawnLines.push(line);
        updateStatus(`Line drawn: ${line.start.x},${line.start.y},${line.start.z} → ${line.end.x},${line.end.y},${line.end.z}`);
        state.currentLine = null;
        state.tempPoint = null;
      }
      state.snapMode = null;
    }
  });

  // === MOUSE DRAG TO ROTATE MODEL ===
  canvas.addEventListener('mousemove', function (e) {
    if (state.isDragging && state.dragTarget === 'model') {
      const deltaX = e.clientX - state.lastX;
      const deltaY = e.clientY - state.lastY;

      state.rotY += deltaX * 0.5; // Y rotation (horizontal drag)
      state.rotX += deltaY * 0.5; // X rotation (vertical drag)

      // Update state
      updateStatus("Rotating model");
    }
    state.lastX = e.clientX;
    state.lastY = e.clientY;
  });

  // Enable hover-to-show menu on mouse enter
  canvas.addEventListener('mouseenter', () => {
    menu.classList.add('visible');
  });

  canvas.addEventListener('mouseleave', () => {
    menu.classList.remove('visible');
  });

  // Optional: click on canvas to activate menu
  canvas.addEventListener('click', () => {
    if (state.snapMode) {
      // Hide menu when clicking, allow normal actions
      menu.classList.remove('visible');
    }
  });

</script>

