router.post('/potwierdz-email', async (req, res) => {
  const { token } = req.body; // albo z query string: const token = req.query.token;
  // Zależnie od sposobu przekazywania – lepiej przez query string
  const { token: tokenFromQuery } = req.query;

  const realToken = token || tokenFromQuery;

  if (!realToken) {
    return res.status(400).json({ success: false, message: 'Brak tokena.' });
  }

  try {
    // Znajdź użytkownika po tokenie
    const user = await User.findOne({ potwierdzenieToken: realToken });

    if (!user) {
      return res.status(400).json({ success: false, message: 'Nieprawidłowy lub wygasły token.' });
    }

    // Sprawdź, czy token nie wygasł (np. po 24h)
    const expiracyTime = 24 * 60 * 60 * 1000; // 24h
    const dataUtworzenia = user.dataRejestracji.getTime();
    const teraz = Date.now();

    if (teraz - dataUtworzenia > expiracyTime) {
      return res.status(400).json({ success: false, message: 'Token wygasł. Zarejestruj się ponownie.' });
    }

    // ✅ Ustaw status:
    user.emailPotwierdzony = true;
    user.potwierdzenieToken = undefined; // usuń token – nie będzie się ponownie używać
    user.aktywne = true; // włącz konto
    await user.save();

    // ✅ Teraz użytkownik może się logować!
    // (Wszystko jest zaplanowane w bazie)

    res.status(200).json({
      success: true,
      message: 'Konto zostało pomyślnie potwierdzone!'
    });

  } catch (error) {
    console.error('Błąd podczas potwierdzania:', error);
    res.status(500).json({ success: false, message: 'Wewnętrzny błąd serwera.' });
