```js
function extractSoundCloudTrackId(url) {
    try {
        const urlObj = new URL(url);
        const path = urlObj.pathname;
        const segments = path.split('/').filter(Boolean); // remove empty parts

        // Проверка, что это трек, а не профиль/альбом
        if (segments.length >= 2) {
            const lastSegment = segments[segments.length - 1];

            // Если в URL есть /tracks/XXX — это ID
            if (path.includes('/tracks/')) {
                const idMatch = path.match(/\/tracks\/(\d+)/);
                if (idMatch && idMatch[1]) {
                    return idMatch[1];
                }
            }

            // Если последний сегмент — число (возможно, ID)
            const possibleId = parseInt(lastSegment);
            if (!isNaN(possibleId)) {
                return possibleId;
            }
        }

        // Альтернатива: попробовать извлечь из "tracks/" в пути
        const trackMatch = path.match(/\/(tracks\/)(\d+)/);
        if (trackMatch && trackMatch[2]) {
            return trackMatch[2];
        }

        return null;
    } catch (e) {
        return null;
    }
}
```

