### 🔍 Problem Recap:
You're sending:
```bash
--form 'data="{\"orderId\": \"2023/270/4\", \"LabID\": \"RN885181\"}";type=application/json'
```

This means:
- `file` is uploaded as a binary file.
- `data` is sent as a **form field with `type=application/json`**, but it's still a **string** in the body — not parsed into a JavaScript object.

So `req.body` will not automatically parse the `data` field into an object unless you **explicitly parse it**.

---

## ✅ Solution: Parse the `data` field manually

Here’s the corrected and robust version of your endpoint:

```js
const express = require('express');
const multer = require('multer'); // assuming you're using multer
const logger = require('./logger'); // your logger

const app = express();

// Multer setup (ensure you're using it correctly)
const upload = multer({ dest: 'uploads/' }); // or use memory storage for smaller files

app.post('/api/lab/accept-lab-reports', upload.single("file"), async (req, res) => {
    try {
        const file = req.file;
        const { orderId, LabID, reportStatus } = req.body;

        // 🔴 The key fix: parse `data` if it's a JSON string
        let data = {};
        if (req.body.data) {
            try {
                data = JSON.parse(req.body.data);
            } catch (parseError) {
                logger.error('Failed to parse JSON in `data` field:', parseError.message);
                return res.status(400).json({
                    error: 'Invalid JSON in data field'
                });
            }
        }

        // Now extract from parsed `data` object
        const orderIdFromData = data.orderId;
        const LabIDFromData = data.LabID;

        // Validate required fields
        if (!orderIdFromData || !LabIDFromData) {
            const errMsg = 'orderId and LabID are required';
            logger.error(errMsg);
            return res.status(400).json({ error: errMsg });
        }

        // Use the values
        const finalOrderId = orderIdFromData;
        const finalLabID = LabIDFromData;

        // ✅ Read the file and convert to Base64
        const base64File = file.buffer.toString('base64'); // this is the base64 string

        // Optional: Save or process file (e.g., call your service)
        await postReceivedAttachment(finalOrderId, finalLabID, {
            filename: file.originalname,
            mimetype: file.mimetype,
            buffer: base64File,
            size: file.size,
        });

        return res.status(200).json({
            Status: 'SUCCESS',
            StatusMessage: 'Lab report accepted successfully',
            StatusCode: 0,
            data: {
                orderId: finalOrderId,
                LabID: finalLabID,
                file: {
                    filename: file.originalname,
                    size: file.size,
                    mimetype: file.mimetype,
                    // base64 is already stored, or send it only if needed
                }
            }
        });

    } catch (error) {
        console.error('Error during Lab Result Attachment processing:', error.message ? error.message : error);
        logger.error('Error in /api/lab/accept-lab-reports:', error);

        return res.status(500).json({
            Status: 'FAILED',
            StatusMessage: 'Internal Server Error',
            StatusCode: 1,
        });
    }
});
```

