```js
require('dotenv').config();
const { Bot, GrammyError, HttpError } = require('grammy');

const bot = new Bot(process.env.BOT_API_KEY);

// Список разрешённых пользователей (ID или логины)
const allowedUsers = ['785492955', 'user2', 'user3']; // Замените на реальные ID

// Множество для отслеживания заблокированных пользователей (по ID)
const blockedUsers = new Set();

// Метод для проверки, разрешён ли пользователь
const isUserAllowed = (userId) => allowedUsers.includes(userId.toString());

// Middleware: блокировка пользователей, если они заблокированы
bot.use(async (ctx, next) => {
  const userId = ctx.from.id.toString();

  if (blockedUsers.has(userId)) {
    await ctx.reply('Вы временно заблокированы от отправки сообщений. Пожалуйста, подождите две минуты.');
    return; // Прерываем выполнение
  }

  if (isUserAllowed(userId)) {
    return next(); // Продолжаем, если разрешён
  }

  await ctx.reply('У вас нет разрешения на выполнение этой команды.');
});

// Команда /start
bot.command('start', async (ctx) => {
  await ctx.reply('Я работаю, но ебано');
});

