bot.command('push', async (ctx) => {
  const chatId = '-1001980493060'; // ID группы

  const messageText = ctx.message.text.replace(/\/push\s*/i, '').trim();

  if (!messageText) {
    await ctx.reply('Пожалуйста, укажите текст для рассылки.');
    return;
  }

  try {
    // Отправляем сообщение в группу
    await bot.api.sendMessage(chatId, messageText);

    // Блокируем отправителя на 2 минуты
    const userId = ctx.from.id.toString();
    blockedUsers.add(userId);
    setTimeout(() => {
      blockedUsers.delete(userId);
      console.log(`Пользователь ${userId} разблокирован.`);
    }, 120000); // 2 минуты

    await ctx.reply('Сообщение отправлено в группу. Все пользователи заблокированы на 2 минуты.');
  } catch (err) {
    console.error('Ошибка при отправке сообщения:', err);
    if (err instanceof GrammyError) {
      await ctx.reply(`Ошибка Telegram API: ${err.description}`);
    } else if (err instanceof HttpError) {
      await ctx.reply('Ошибка HTTP при отправке сообщения.');
    } else {
      await ctx.reply('Неизвестная ошибка.');
    }
  }
});

