  if (err.error instanceof GrammyError) {
    console.error('Ошибка в запросе:', err.error.description);
  } else if (err.error instanceof HttpError) {
    console.error('Ошибка HTTP:', err.error.message);
  }
});

// Запуск бота
bot.start();
