  const directions = [
    [-1, 0], // up
    [1, 0],  // down
    [0, -1], // left
    [0, 1]   // right
  ];
  for (const [dr, dc] of directions) {
    let r = row + dr;
    let c = col + dc;
    while (isInBounds(r, c)) {
      const piece = getPieceElement(r, c);
      if (!piece) {
        moves.push({ from: [row, col], to: [r, c] });
      } else {
        if (isEnemyPiece(r, c)) {
          moves.push({ from: [row, col], to: [r, c] });
        }
        break;
      }
      r += dr;
      c += dc;
    }
  }
  return moves;
}

function generateKnightMoves(board, row, col, color) {
  const moves = [];
  const offsets = [
    [-2, -1], [-2, 1],
    [-1, -2], [-1, 2],
    [1, -2], [1, 2],
    [2, -1], [2, 1]
  ];
  for (const [dr, dc] of offsets) {
    const r = row + dr;
    const c = col + dc;
    if (isInBounds(r, c)) {
      if (!isOwnPiece(r, c)) {
        moves.push({ from: [row, col], to: [r, c] });
      }
    }
  }
  return moves;
}

function getRandomPiece(board, color) {
  const pieces = [];
  for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
      const piece = getPieceElement(row, col);
      if (piece && (piece.id.startsWith('r') || piece.id.startsWith('n')) && piece.id.endsWith(color.charAt(0))) {
        pieces.push({ piece, row, col });
      }
    }
  }
  if (pieces.length === 0) return null;
  return pieces[Math.floor(Math.random() * pieces.length)];
}

function applyMove(move) {
  const fromRow = move.from[0];
  const fromCol = move.from[1];
  const toRow = move.to[0];
  const toCol = move.to[1];
  const fromPiece = getPieceElement(fromRow, fromCol);
  const toCellId = getCellId(toRow, toCol);
