}

function getLegalMovesForPiece(row, col, piece) {
  const color = piece.id.endsWith('w') ? 'white' : 'black';
  if (piece.id.startsWith('r')) {
    return generateRookMoves(null, row, col, color);
  } else if (piece.id.startsWith('n')) {
    return generateKnightMoves(null, row, col, color);
  }
  return [];
}

function makeRandomMove() {
  const pieceData = getRandomPiece(null, currentTurn.color);
  if (!pieceData) {
    currentTurn.color = currentTurn.color === 'white' ? 'black' : 'white';
    return;
  }
  const { row, col, piece } = pieceData;
  const legalMoves = getLegalMovesForPiece(row, col, piece);
  if (legalMoves.length === 0) {
    currentTurn.color = currentTurn.color === 'white' ? 'black' : 'white';
    return;
  }
  const move = legalMoves[Math.floor(Math.random() * legalMoves.length)];
  applyMove(move);
}

