# Creating a Real-Time Chat with Express and WebSocket

Below is a complete implementation of a real-time chat application using Express and WebSocket (using the `ws` library).

## 1. Initialize the Project

```bash
mkdir express-websocket-chat
cd express-websocket-chat
npm init -y
npm install express ws
npm install --save-dev nodemon
```

## 2. Create the Server File (`server.js`)

```javascript
const express = require('express');
const http = require('http');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Middleware to serve static files
app.use(express.static('public'));

// Store connected clients
const clients = new Map();

// Handle WebSocket connections
wss.on('connection', (ws, req) => {
  // Generate a unique ID for the client
  const clientId = Date.now().toString(36) + Math.random().toString(36).substr(2, 5);

  // Store the client with their ID
  clients.set(clientId, {
    ws,
    username: `User${Math.floor(Math.random() * 1000)}`
  });

  console.log(`Client connected: ${clientId}`);

  // Send welcome message to the new client
  ws.send(JSON.stringify({
    type: 'welcome',
    message: `Welcome to the chat, ${clients.get(clientId).username}!`,
    clientId: clientId
  }));

  // Send the list of current users to the new client
  const userNames = Array.from(clients.values()).map(client => client.username);
  ws.send(JSON.stringify({
    type: 'users',
    users: userNames
  }));

  // Broadcast to all clients that a new user has joined
  const newUserMessage = {
    type: 'user-joined',
    username: clients.get(clientId).username,
    timestamp: new Date().toLocaleTimeString()
  };

  broadcast(JSON.stringify(newUserMessage));

  // Handle incoming messages from the client
  ws.on('message', (data) => {
    try {
      const message = JSON.parse(data);

      // Handle different message types
      switch (message.type) {
        case 'chat-message':
          // Broadcast the chat message to all clients
          const chatMessage = {
            type: 'chat-message',
            username: clients.get(clientId).username,
            message: message.message,
            timestamp: new Date().toLocaleTimeString()
          };
          broadcast(JSON.stringify(chatMessage));
          break;

        case 'username-change':
          const oldUsername = clients.get(clientId).username;
          const newUsername = message.username;

          // Update username
          clients.get(clientId).username = newUsername;

          // Notify all clients about the username change
          const usernameChangeMessage = {
            type: 'username-change',
            oldUsername: oldUsername,
            newUsername: newUsername,
            timestamp: new Date().toLocaleTimeString()
          };

          broadcast(JSON.stringify(usernameChangeMessage));

          // Send confirmation to the client
          ws.send(JSON.stringify({
            type: 'username-changed',
            message: `Username changed to ${newUsername}`
          }));

          break;

        default:
          console.log('Unknown message type:', message.type);
      }
    } catch (error) {
      console.error('Error parsing message:', error);
    }
  });

  // Handle client disconnection
  ws.on('close', () => {
    console.log(`Client disconnected: ${clientId}`);

    // Remove client from the map
    const username = clients.get(clientId)?.username;
    clients.delete(clientId);

    // Notify all clients that a user has left
    if (username) {
      const leaveMessage = {
        type: 'user-left',
        username: username,
        timestamp: new Date().toLocaleTimeString()
      };
      broadcast(JSON.stringify(leaveMessage));
    }
  });
});

// Function to broadcast a message to all connected clients
function broadcast(message) {
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

// Start the server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server is running on http://localhost:${PORT}`);
});
```

