## 6. Create the JavaScript File (`public/js/app.js`)

```javascript
class ChatApp {
  constructor() {
    this.ws = null;
    this.clientId = null;
    this.username = 'User' + Math.floor(Math.random() * 1000);
    this.messageInput = document.getElementById('messageInput');
    this.chatForm = document.getElementById('chatForm');
    this.chatMessages = document.getElementById('chatMessages');
    this.userList = document.getElementById('userList');
    this.userCount = document.getElementById('userCount');
    this.statusIndicator = document.querySelector('.status-indicator');

    this.init();
  }

  init() {
    this.connectWebSocket();
    this.bindEvents();
    this.updateUserCount();
  }

  connectWebSocket() {
    const wsUrl = window.location.protocol === 'https:' 
      ? 'wss://' + window.location.host 
      : 'ws://' + window.location.host;

    this.ws = new WebSocket(wsUrl);

    this.ws.addEventListener('open', (event) => {
      console.log('Connected to WebSocket server');
      this.statusIndicator.className = 'status-indicator online';
    });

    this.ws.addEventListener('message', (event) => {
      const data = JSON.parse(event.data);

      switch (data.type) {
        case 'welcome':
          this.clientId = data.clientId;
          this.username = data.message.split(', ')[1].split('!')[0];
          this.updateUserList();
          break;

        case 'chat-message':
          this.addMessage(data);
          break;

        case 'user-joined':
          this.addUserMessage(data);
          this.updateUserList();
          break;

        case 'user-left':
          this.addUserMessage(data);
          this.updateUserList();
          break;

        case 'username-change':
          this.addUserMessage(data);
          this.updateUserList();
          break;

        case 'users':
          this.updateUserList(data.users);
          break;

        default:
          console.log('Unknown message type:', data.type);
      }
    });

    this.ws.addEventListener('close', (event) => {
      console.log('WebSocket connection closed');
      this.statusIndicator.className = 'status-indicator offline';
      // Try to reconnect after 3 seconds
      setTimeout(() => {
        console.log('Attempting to reconnect...');
        this.connectWebSocket();
      }, 3000);
    });

    this.ws.addEventListener('error', (error) => {
      console.error('WebSocket error:', error);
    });
  }

  bindEvents() {
    this.chatForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const message = this.messageInput.value.trim();
      if (message) {
        this.sendMessage({
          type: 'chat-message',
          message: message
        });
        this.messageInput.value = '';
      }
    });

    this.messageInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        this.chatForm.dispatchEvent(new Event('submit'));
      }
    });
  }

  sendMessage(data) {
    if (this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(data));
    } else {
      console.error('WebSocket is not open. Current state:', this.ws.readyState);
    }
  }

  addMessage(data) {
    const messageDiv = document.createElement('div');
    messageDiv.className = `message ${data.username === this.username ? 'outgoing' : 'incoming'}`;

    const timestamp = new Date().toLocaleTimeString();
    messageDiv.innerHTML = `
      <div class="user">${data.username}</div>
      <div class="content">${data.message}</div>
      <div class="timestamp">${timestamp}</div>
    `;

    this.chatMessages.appendChild(messageDiv);
    this.chatMessages.scrollTop = this.chatMessages.scrollHeight;
  }

  addUserMessage(data) {
    const messageDiv = document.createElement('div');
    messageDiv.className = 'message';
    messageDiv.style.color = '#999';
    messageDiv.style.fontStyle = 'italic';

    const timestamp = new Date().toLocaleTimeString();

    let messageText = '';
    switch (data.type) {
      case 'user-joined':
        messageText = `${data.username} has joined the chat`;
        break;
      case 'user-left':
        messageText = `${data.username} has left the chat`;
        break;
      case 'username-change':
        messageText = `${data.oldUsername} is now known as ${data.newUsername}`;
        break;
      default:
        messageText = data.message || 'Unknown event';
    }

    messageDiv.innerHTML = `<div class="content">${messageText}</div>`;
    this.chatMessages.appendChild(messageDiv);
    this.chatMessages.scrollTop = this.chatMessages.scrollHeight;
  }

  updateUserList(userNames) {
    const users = userNames || Array.from(clients.values()).map(client => client.username);
    this.userList.innerHTML = '';
    this.userCount.textContent = users.length;

    users.forEach(username => {
      const li = document.createElement('li');
      li.innerHTML = `
        <span class="user-icon">${username.charAt(0).toUpperCase()}</span>
        <span class="username">${username}</span>
      `;
      this.userList.appendChild(li);
    });
  }

  updateUserCount() {
    const users = Array.from(clients.values()).map(client => client.username) || [];
    this.userCount.textContent = users.length;
  }
}

// Initialize the application when the DOM is loaded
document.addEventListener('DOMContentLoaded', () => {
  const app = new ChatApp();
});
```

