  const resultDetail = document.createElement('p');
  resultDetail.classList.add('quiz__result__details');
  resultDetail.textContent = `Procent poprawnych odpowiedzi: ${percentage}%`;

  quizQuestionBox.appendChild(resultElement);
  quizQuestionBox.appendChild(resultDetail);

  // Ukryj przycisk "Kolejne pytanie", pokazuj przycisk restartu
  nextButton.style.display = 'none';
  restartButton.style.display = 'inline-block';
};

// Restart quizu (czyli nowa seria pytań)
const restartQuiz = () => {
  score = 0;
