```js
// public/script.js
let microphoneStream;
let audioContext;
let analyser;
let dataArray;
let isListening = false;
let audioSource;
let bpm = 0;
let lastBeatTime = 0;
let beatInterval = 0;
let beatTimes = [];

// DOM Elements
const startBtn = document.getElementById('startBtn');
const stopBtn = document.getElementById('stopBtn');
const bpmDisplay = document.getElementById('bpmDisplay');
const statusDiv = document.getElementById('status');

// Start listening
startBtn.addEventListener('click', async () => {
  try {
    // Request microphone access
    microphoneStream = await navigator.mediaDevices.getUserMedia({ audio: true });

    // Create Web Audio context
    audioContext = new (window.AudioContext || window.webkitAudioContext)();
    analyser = audioContext.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    // Connect stream to audio context
    audioSource = audioContext.createMediaStreamSource(microphoneStream);
    audioSource.connect(analyser);

    // Create data array for audio analysis
    dataArray = new Uint8Array(analyser.frequencyBinCount);

    // Start processing
    isListening = true;
    startBtn.disabled = true;
    stopBtn.disabled = false;
    statusDiv.textContent = "Listening... Detecting BPM...";

    // Start BPM detection loop
    requestAnimationFrame(visualize);
  } catch (err) {
    alert("Error accessing microphone: " + err.message);
    console.error("Microphone error:", err);
  }
});

// Stop listening
stopBtn.addEventListener('click', () => {
  // Stop stream and reset
  if (microphoneStream) {
    microphoneStream.getTracks().forEach(track => track.stop());
  }
  isListening = false;
  startBtn.disabled = false;
  stopBtn.disabled = true;
  statusDiv.textContent = "Listening stopped.";
  bpmDisplay.textContent = "--";
  beatTimes = [];
});

// Visualization loop (real-time audio analysis and BPM detection)
function visualize() {
  if (!isListening) return;

  // Get the latest data
  analyser.getByteTimeDomainData(dataArray);

  // Find peaks (sudden increases in amplitude)
  let threshold = 120;
  let peakDetected = false;

  for (let i = 0; i < dataArray.length; i++) {
    // Convert to signed value (0-255 → -128 to 127)
    let val = dataArray[i] - 128;
    if (val > threshold) {
      // Detect peak
      const now = Date.now();
      const timeDiff = now - lastBeatTime;

      if (lastBeatTime === 0 || timeDiff > 500) {
        // New beat detected
        lastBeatTime = now;
        beatTimes.push(now);

        // Keep only last 5 beats
        if (beatTimes.length > 5) {
          beatTimes.shift();
        }

        // Calculate average interval
        if (beatTimes.length >= 2) {
          let totalInterval = 0;
          for (let i = 1; i < beatTimes.length; i++) {
            totalInterval += beatTimes[i] - beatTimes[i - 1];
          }
          const avgIntervalMs = totalInterval / (beatTimes.length - 1);
          if (avgIntervalMs > 0) {
            bpm = Math.round(60000 / avgIntervalMs);
            bpmDisplay.textContent = bpm;
          }
        } else {
          bpmDisplay.textContent = bpm || "--";
        }

        peakDetected = true;
      }
      break;
    }
  }

  // Optional: Visual feedback (just for demonstration)
  // You can add a visualizer here using canvas later.

  requestAnimationFrame(visualize);
}
```

