const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const cors = require('cors');
const helmet = require('helmet');
const dotenv = require('dotenv');

dotenv.config();

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server, path: '/ws' });

// Middleware
app.use(helmet());
app.use(cors());
app.use(express.json());

// Подключение к базе
const connectDB = require('./utils/db');
connectDB();

// Маршруты (Express)
const authController = require('./controllers/authController');

app.post('/auth/register', authController.register);
app.post('/auth/login', authController.login);

// Управление игроками (закрыто для аутентифицированных пользователей)
const playerController = require('./controllers/playerController');
app.use('/api/player', require('./middlewares/auth'));

app.post('/api/player', playerController.createPlayer);
app.get('/api/player/:playerId', playerController.getPlayer);
app.put('/api/player/position', playerController.updatePosition);
app.post('/api/player/skill', playerController.useSkill);

// WebSocket-сокеты
const connectedClients = new Map();

wss.on('connection', (ws, req) => {
  let userId = null;

  // Авторизация через заголовки
  const token = req.headers.authorization?.split(' ')[1];
  if (token) {
    try {
      const decoded = jwt.verify(token, process.env.JWT_SECRET);
      userId = decoded.userId;
    } catch (err) {
      ws.close(4000, 'Неверный токен');
      return;
    }
  }

  // Сохранение клиента
  connectedClients.set(userId, { ws, x: 0, y: 0 });

  console.log(`🟢 Подключился игрок: ${userId}`);

  // Получаем позицию игрока
  Player.findOne({ userId }).then(player => {
    if (player) {
      ws.send(JSON.stringify({
        type: 'player-init',
        data: {
          id: player.userId,
          x: player.x,
          y: player.y,
          health: player.health,
          inventory: player.inventory,
          skills: player.skills
        }
      }));
    }
  });

  // Обработка сообщений от клиента
  ws.on('message', async (data) => {
    const msg = JSON.parse(data);

    switch (msg.type) {
      case 'move':
        const { x, y } = msg.data;
        await Player.findOneAndUpdate(
          { userId },
          { x, y },
          { new: true }
        );
        // Отправляем изменения всем
        connectedClients.forEach((client, id) => {
          if (id !== userId) {
            client.ws.send(JSON.stringify({
              type: 'player-move',
              data: { userId, x, y }
            }));
          }
        });
        break;

      case 'use-skill':
        const { skillId } = msg.data;
        const player = await Player.findOne({ userId });
        if (player) {
          const skill = player.skills.find(s => s.id === skillId);
          if (skill) {
            // Здесь запустить логику
            console.log(`Игрок ${userId} использует навык: ${skill.name}`);
            // Можно изменить health и т.п. через playerController
          }
        }
        break;

      case 'ping':
        ws.send(JSON.stringify({ type: 'pong' }));
        break;
    }
  });

  ws.on('close', () => {
    connectedClients.delete(userId);
    console.log(`⚪ Отключился игрок: ${userId}`);
  });

  ws.on('error', (err) => {
    console.error('WebSocket ошибка:', err);
  });
});

// Запуск сервера
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`✅ Север запущен на порту ${PORT}`);
});
