Uploading a large file from an Express server to AWS S3 with **progress tracking** involves a few key concepts:

1. **Streaming the file** (avoid loading the entire file into memory).
2. **Using the AWS SDK v3** (which supports async/await and is modular).
3. **Monitoring upload progress** via events or a custom progress callback.

Here’s a complete, **working example** using **Express**, **AWS SDK v3 (`@aws-sdk/client-s3`)**, and **streaming with progress tracking**.

---

### ✅ Step 1: Install Dependencies

```bash
npm install express @aws-sdk/client-s3 multer
```

> `multer` is used to handle file uploads via HTTP form data.

---

### ✅ Step 2: Set Up Express Server with S3 Upload (Streaming + Progress)

```javascript
// server.js
const express = require('express');
const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');
const multer = require('multer');
const path = require('path');

const app = express();

// AWS Configuration (use environment variables in production)
const s3Client = new S3Client({
  region: 'us-east-1', // change to your region
  credentials: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },
});

// Multer setup for handling file uploads
const upload = multer({ dest: 'uploads/' }); // Temp folder for large files

// POST endpoint to upload file to S3 with progress
app.post('/upload', upload.single('file'), async (req, res) => {
  const file = req.file;
  const bucketName = 'your-bucket-name'; // Replace with your S3 bucket name

  if (!file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  const fileName = file.originalname;
  const filePath = file.path;

  try {
    // Use a readable stream from the file
    const fileStream = require('fs').createReadStream(filePath);

    // Create S3 PutObjectCommand
    const uploadParams = {
      Bucket: bucketName,
      Key: `uploads/${fileName}`,
      Body: fileStream,
      ContentType: req.get('Content-Type') || 'application/octet-stream',
    };

    // Monitor progress using a custom stream wrapper with a progress event
    const progress = {
      uploaded: 0,
      total: 0,
    };

    // Create a Transform stream to track progress
    const progressStream = new require('stream').Transform({
      transform(chunk, encoding, callback) {
        progress.uploaded += chunk.length;
        const percent = Math.round((progress.uploaded / progress.total) * 100);

        // Optionally, log or emit progress (e.g., via WebSocket or SSE)
        console.log(`Upload progress: ${percent}% (${progress.uploaded}/${progress.total} bytes)`);

        // You can emit progress to frontend via WebSockets/SSE later
        callback(null, chunk);
      },
    });

    // Set total size (before upload starts)
    const stats = require('fs').statSync(filePath);
    progress.total = stats.size;

    // Pipe the file stream through progress tracking, then to S3
    const uploadCommand = new PutObjectCommand(uploadParams);
    const uploadStream = fileStream.pipe(progressStream);

    // Set up S3 upload with progress tracking
    const response = await s3Client.send(uploadCommand);

    // Cleanup: remove temp file
    require('fs').unlinkSync(filePath);

    res.json({
      message: 'File uploaded successfully!',
      location: `https://${bucketName}.s3.amazonaws.com/${uploadParams.Key}`,
      progress: { uploaded: progress.uploaded, total: progress.total },
    });
  } catch (error) {
    console.error('Upload failed:', error);
    res.status(500).json({ error: 'Upload failed', details: error.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

---

### ✅ Step 3: Frontend (HTML + JavaScript) with Progress

```html
<!-- upload.html -->
<!DOCTYPE html>
<html>
<head>
  <title>Upload with Progress</title>
</head>
<body>
  <h2>Upload Large File to S3</h2>
  <input type="file" id="fileInput" />
  <button onclick="uploadFile()">Upload</button>

  <div id="progress">0%</div>

  <script>
    async function uploadFile() {
      const fileInput = document.getElementById('fileInput');
      const file = fileInput.files[0];
      if (!file) return alert('Select a file');

      const formData = new FormData();
      formData.append('file', file);

      const xhr = new XMLHttpRequest();
      xhr.open('POST', 'http://localhost:3000/upload', true);

      // Track upload progress
      xhr.upload.onprogress = function (e) {
        if (e.lengthComputable) {
          const percent = Math.round((e.loaded / e.total) * 100);
          document.getElementById('progress').textContent = `Progress: ${percent}%`;
        }
      };

      // Handle response
      xhr.onload = function () {
        if (xhr.status === 200) {
          alert('Upload successful!');
          console.log(xhr.responseText);
        } else {
          alert('Upload failed');
        }
      };

      xhr.onerror = function () {
        alert('Network error');
      };

      // Send file
      xhr.send(formData);
    }
  </script>
</body>
</html>
```

> 💡 Note: The `progress` in `xhr.upload.onprogress` reflects the **upload to the Express server**, not S3. To get **S3 upload progress**, you need a **WebSocket** or **Server-Sent Events (SSE)** to deliver progress from the server.

---

### ✅ Step 4: Optional – Real S3 Progress (via Server-Sent Events / SSE)

If you want to **stream actual S3 upload progress** back to the frontend (e.g. 10% → 50% → 100%), use **SSE (Server-Sent Events)**:

#### 1. Update your endpoint to support SSE:

```javascript
app.post('/upload-stream', upload.single('file'), async (req, res) => {
  const file = req.file;
  const bucketName = 'your-bucket-name';

  if (!file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  const filePath = file.path;

  // Set SSE headers
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive',
  });

  // Send initial event
  res.write(`data: ${JSON.stringify({ event: 'start', message: 'Upload started' })}\n\n`);

  try {
    const stats = require('fs').statSync(filePath);
    const total = stats.size;

    const fileStream = require('fs').createReadStream(filePath);
    const uploadParams = {
      Bucket: bucketName,
      Key: `uploads/${file.originalname}`,
      Body: fileStream,
      ContentType: file.mimetype,
    };

    const progress = { uploaded: 0 };

    const progressStream = new require('stream').Transform({
      transform(chunk, encoding, callback) {
        progress.uploaded += chunk.length;
        const percent = Math.round((progress.uploaded / total) * 100);

        const data = JSON.stringify({
          event: 'progress',
          uploaded: progress.uploaded,
          total: total,
          percent: percent,
        });

        // Send progress update
        res.write(`data: ${data}\n\n`);

        callback(null, chunk);
      },
    });

    const uploadCommand = new PutObjectCommand(uploadParams);
    const uploadStream = fileStream.pipe(progressStream);

    await s3Client.send(uploadCommand);

    res.write(`data: ${JSON.stringify({ event: 'complete', message: 'Upload complete' })}\n\n`);
    res.end(); // Close stream

  } catch (error) {
    res.write(`data: ${JSON.stringify({ event: 'error', message: error.message })}\n\n`);
    res.end();
  }
});
```

#### 2. Update Frontend to listen via SSE:

```javascript
const eventSource = new EventSource('http://localhost:3000/upload-stream');

eventSource.onmessage = function (event) {
  const data = JSON.parse(event.data);
  if (data.event === 'progress') {
    document.getElementById('progress').textContent = `S3 Progress: ${data.percent}%`;
  } else if (data.event === 'complete') {
    alert('Upload complete!');
  } else if (data.event === 'error') {
    alert('Error: ' + data.message);
  }
};
```

> ✅ This way you **see the real S3 upload progress**.

---

### 🔐 Security Note

Never hardcode AWS keys in code. Use environment variables:

```bash
export AWS_ACCESS_KEY_ID=your-access-key
export AWS_SECRET_ACCESS_KEY=your-secret-key
```

---

### 🚀 Summary

| Feature | Implemented? | How |
|-------|--------------|-----|
| Large file upload | ✅ | Streaming via Node.js `fs.createReadStream` |
| Progress tracking | ✅ | With `Transform` stream or `xhr.upload.onprogress` |
| Real S3 progress (to client) | ✅ | Via SSE (`EventSource`) |
| Secure setup | ✅ | Use env vars and IAM roles |

