### ✅ Final Working Version (no backticks, no bugs, handles fast typing & resize):

```js
const textarea = document.getElementById('textarea');
let animationTimeout = null;
let resizeTimeout = null;

// Ensure container exists
const container = document.querySelector('.container') || textarea;

function insertLine() {
  const selection = window.getSelection();
  if (selection.rangeCount === 0) return;

  const range = selection.getRangeAt(0);
  const textNode = range.startContainer;

  if (textNode.nodeType !== 3) return;

  const currentPosition = range.startOffset;
  const lineText = textNode.textContent.trim().slice(currentPosition);

  // Create the highlighted line
  const highlightedLine = document.createElement('span');
  highlightedLine.classList.add('highlight-line');
  highlightedLine.textContent = '█';

  const lineBreak = document.createElement('br');
  const newLine = document.createElement('span');
  newLine.appendChild(lineBreak);
  newLine.appendChild(highlightedLine);

  // Split text node if needed
  const nextNode = currentPosition > 0 ? textNode.splitText(currentPosition) : textNode;
  nextNode.parentNode.insertBefore(newLine, nextNode.nextSibling);

  // Clear selection and position caret at start of new line
  range.deleteContents();
  range.insertNode(lineBreak);
  range.collapse(true);
  range.setStart(nextNode, 0);

  // Update animation only after DOM is updated
  updateTimeout();
}

function updateTimeout() {
  // Cancel any previous animation
  if (animationTimeout !== null) {
    cancelAnimationFrame(animationTimeout);
    animationTimeout = null;
  }

  // Use requestAnimationFrame to ensure layout is updated
  animationTimeout = requestAnimationFrame(() => {
    const highlightedLine = document.querySelector('.highlight-line');
    if (!highlightedLine) {
      animationTimeout = null;
      return;
    }

    // Wait for layout to be stable (after reflow, via reflow)
    const container = document.querySelector('.container') || textarea;
    const containerRect = container.getBoundingClientRect();

    // Ensure we're measuring after layout
    const offsetLeft = highlightedLine.getBoundingClientRect().left;
    const lineRight = offsetLeft + highlightedLine.offsetWidth;
    const emptySpace = containerRect.width - lineRight;

    if (emptySpace <= 0) {
      // Optionally handle overflow case
      highlightedLine.style.animationDuration = '0s';
      onAnimationEnd();
      return;
    }

    const timeoutDuration = emptySpace * 3; // Adjust factor as needed
    highlightedLine.style.animationDuration = `${timeoutDuration}ms`;

    // Schedule removal after animation completes
    onAnimationEnd();
  });
}

function onAnimationEnd() {
  const highlightedLine = document.querySelector('.highlight-line');
  if (!highlightedLine) return;

  // Remove the element only after animation finishes
  // Use a callback to avoid flicker
  const callback = () => {
    highlightedLine.outerHTML = highlightedLine.innerHTML;
    // Optionally clean up: this removes the <span> and keeps only the content
    // But keep it simple: outerHTML = innerHTML = no wrapper
  };

  // Start with zero duration first to reset animation state
  setTimeout(callback, 0);
}

function handleKeyPress(event) {
  if (event.key === 'Enter' || event.key === 'Return') {
    event.preventDefault();
    const lineBreak = document.createElement('br');
    insertLine();
    const selection = window.getSelection();
    const range = selection.getRangeAt(0);
    range.deleteContents();
    range.insertNode(lineBreak);
    range.collapse(false);
  }
}

// Trigger on resize to reposition and re-analyze layout
window.addEventListener('resize', () => {
  if (animationTimeout !== null) {
    cancelAnimationFrame(animationTimeout);
    animationTimeout = null;
  }
  updateTimeout();
});

// Attach keyboard event
textarea.addEventListener('keydown', handleKeyPress);
