const bodyParser = require('body-parser');

const app = express();
const PORT = 3000;

// Middleware para parsear JSON
app.use(bodyParser.json());

// Simulación de base de datos (en producción usarías MongoDB, PostgreSQL, etc.)
let tareas = [
  { id: 1, titulo: 'Hacer la compra', completado: false },
  { id: 2, titulo: 'Estudiar Node.js', completado: true }
];

// Ruta: GET /tareas - Obtener todas las tareas
app.get('/tareas', (req, res) => {
  res.json(tareas);
});

// Ruta: GET /tareas/:id - Obtener una tarea por ID
app.get('/tareas/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const tarea = tareas.find(t => t.id === id);

  if (!tarea) {
    return res.status(404).json({ error: 'Tarea no encontrada' });
  }

  res.json(tarea);
});

// Ruta: POST /tareas - Crear una nueva tarea
app.post('/tareas', (req, res) => {
  const { titulo, completado = false } = req.body;

  // Validación básica
  if (!titulo) {
    return res.status(400).json({ error: 'El título es obligatorio' });
  }

  const nuevaTarea = {
    id: tareas.length > 0 ? Math.max(...tareas.map(t => t.id)) + 1 : 1,
    titulo,
    completado
  };

  tareas.push(nuevaTarea);
  res.status(201).json(nuevaTarea);
});

// Ruta: PUT /tareas/:id - Actualizar una tarea
app.put('/tareas/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const index = tareas.findIndex(t => t.id === id);

  if (index === -1) {
    return res.status(404).json({ error: 'Tarea no encontrada' });
  }

  const { titulo, completado } = req.body;

  // Actualizamos solo los campos que lleguen
  tareas[index] = {
    ...tareas[index],
    titulo: titulo !== undefined ? titulo : tareas[index].titulo,
    completado: completado !== undefined ? completado : tareas[index].completado
  };

  res.json(tareas[index]);
});

// Ruta: DELETE /tareas/:id - Eliminar una tarea
app.delete('/tareas/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const index = tareas.findIndex(t => t.id === id);

  if (index === -1) {
    return res.status(404).json({ error: 'Tarea no encontrada' });
  }

  tareas.splice(index, 1);
  res.status(204).send(); // No content
});

// Ruta raíz
app.get('/', (req, res) => {
  res.send('<h1>Bienvenido a mi API REST con Node.js y Express</h1>');
});

// Manejo de rutas no encontradas
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Ruta no encontrada' });
});

// Iniciar el servidor
