function removeTagsAndApplyStyles(element) {
  // Ensure element is a valid DOM element
  if (!element || !element.nodeType) return;

  // Create a temporary div to preserve styles during parsing
  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = element.innerHTML; // Preserve inner HTML

  // Get all text nodes and their associated tags
  const walker = document.createTreeWalker(
    tempDiv,
    NodeFilter.SHOW_TEXT,
    null,
    false
  );

  const fragment = document.createDocumentFragment();

  let node;
  while ((node = walker.nextNode())) {
    const textContent = node.textContent;

    // Create a new span to apply styles
    const span = document.createElement('span');
    span.textContent = textContent;

    // Check the parent elements of this text node for style tags
    let parent = node.parentElement;
    let hasBold = false;
    let hasItalic = false;
    let hasUnderline = false;

    while (parent) {
      if (parent.tagName === 'B' || parent.tagName === 'STRONG') {
        hasBold = true;
      }
      if (parent.tagName === 'I' || parent.tagName === 'EM') {
        hasItalic = true;
      }
      if (parent.tagName === 'U') {
        hasUnderline = true;
      }
      parent = parent.parentElement;
    }

    // Apply styles based on tags
    if (hasBold) span.style.fontWeight = 'bold';
    if (hasItalic) span.style.fontStyle = 'italic';
    if (hasUnderline) span.style.textDecoration = 'underline';

    fragment.appendChild(span);
  }

  // Replace original content with styled text
  element.innerHTML = '';
  element.appendChild(fragment);
}
