```js
const express = require("express");
const cors = require("cors");
const axios = require("axios");
require("dotenv").config();

const app = express();

// Middleware
app.use(express.json({ limit: "10mb" })); // Handle larger payloads
app.use(
  cors({
    origin: process.env.CLIENT_URL || "http://localhost:3000", // Allow only trusted origins
    credentials: true,
  })
);

// Config
const apiKey = process.env.APIKEY;

if (!apiKey) {
  console.error("❌ Missing API key: APIKEY is not set in environment variables.");
  process.exit(1);
}

const BASE_URL = "https://open-weather13.p.rapidapi.com/city/";

// Validation utility
function validateCities(cities) {
  if (!Array.isArray(cities)) {
    return { valid: false, error: "Invalid input: 'cities' must be an array" };
  }
  if (cities.length === 0) {
    return { valid: false, error: "No cities provided" };
  }
  const validCities = cities.filter((city) => typeof city === "string" && city.trim() !== "");
  if (validCities.length === 0) {
    return { valid: false, error: "No valid city names provided" };
  }
  return { valid: true, cities: validCities };
}

// Fetch weather for a single city
async function fetchWeather(city) {
  const config = {
    method: "GET",
    url: `${BASE_URL}${encodeURIComponent(city)}`, // Proper encoding
    headers: {
      "X-RapidAPI-Key": apiKey,
      "X-RapidAPI-Host": "open-weather13.p.rapidapi.com",
    },
  };

  try {
    const response = await axios.request(config);
    const temp = response.data.main?.temp;
    return {
      city: city,
      temperature: temp !== undefined ? Math.round(temp) : "N/A",
      status: "success",
    };
  } catch (error) {
    const status = error.response?.status || "N/A";
    // Optional: Log only error codes (avoid flooding logs)
    console.warn(`⚠️ Failed to fetch weather for "${city}":`, status);

    return {
      city: city,
      temperature: "N/A",
      status: "failed",
      error: error.message,
    };
  }
}

// Main route
app.post("/weather", async (req, res) => {
  const { cities } = req.body;

  // Validate input
  const validation = validateCities(cities);
  if (!validation.valid) {
    return res.status(400).json({ error: validation.error });
  }

  const cityList = validation.cities;

  // Use Promise.allSettled to get all results even if some fail
  const weatherPromises = cityList.map((city) => fetchWeather(city));
  const results = await Promise.allSettled(weatherPromises);

  // Transform results into structured response
  const weatherData = results.map((promise) => {
    if (promise.status === "fulfilled") {
      return promise.value;
    } else {
      // Handle rejection
      return {
        city: "Unknown",
        temperature: "N/A",
        status: "failed",
        error: "Request failed",
      };
    }
  });

  // Optionally: return summary
  const successCount = weatherData.filter((d) => d.status === "success").length;
  const failedCount = weatherData.length - successCount;

  return res.status(200).json({
    totalCities: weatherData.length,
    successful: successCount,
    failed: failedCount,
    data: weatherData,
  });
});

// Health check route
