import { GetStaticProps } from 'next'; // Import GetStaticProps for SSR

// Import the API endpoint
const API_ENDPOINT = '/api/flights';

// Server-side rendering: fetch flights before rendering
export const getStaticProps = async () => {
  try {
    // Fetch flight data from the API during build time (SSR)
    const res = await fetch(`${process.env.NEXT_PUBLIC_SITE_URL || ''}${API_ENDPOINT}`);

    if (!res.ok) {
      throw new Error(`Failed to fetch flights. Status: ${res.status}`);
    }

    const { flights } = await res.json();

    // Return data as props to be used in the component
    return {
      props: { flights }, // This will be passed to the component
      revalidate: 10, // Re-fetch data every 10 seconds, enabling ISR (Incremental Static Regeneration)
    };
  } catch (error) {
    console.error('Error during static generation:', error);
    return {
      props: { flights: [] },
      revalidate: 10,
    };
  }
};

// Main component (the rendered page)
export default function FlightDashboard({ flights }) {
  const [flightData, setFlightData] = useState(flights); // Initialize with SSR data

  // Client-side: poll for updates every 5 seconds
  useEffect(() => {
    const pollFlights = async () => {
      try {
        const res = await fetch(API_ENDPOINT);

        if (!res.ok) {
          console.error('Failed to fetch updated flights');
          return;
        }

        const { flights: updatedFlights } = await res.json();

        // Update state only if data changed
        if (JSON.stringify(updatedFlights) !== JSON.stringify(flightData)) {
          setFlightData(updatedFlights);
          console.log('🔁 Flight data updated from database');
        }
      } catch (error) {
        console.error('Polling error:', error);
      }
    };

    // Poll every 5 seconds
    const intervalId = setInterval(pollFlights, 5000);

    // Clean up interval on unmount
    return () => clearInterval(intervalId);
  }, [flightData]); // Runs on mount and when flightData changes

  // Render UI
  return (
    <div style={{ fontFamily: 'Arial', padding: '20px' }}>
      <h1>✈️ Flight Information Dashboard</h1>
      <p><em>Real-time updates from the database</em></p>
      <br />

      {/* Display number of flights */}
      <p><strong>Total Flights:</strong> {flightData.length}</p>

      {/* Flight Table */}
      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
        <thead>
          <tr style={{ backgroundColor: '#f2f2f2', fontWeight: 'bold' }}>
