            <th style={{ padding: '10px', border: '1px solid #ccc' }}>Arrival</th>
            <th style={{ padding: '10px', border: '1px solid #ccc' }}>Status</th>
          </tr>
        </thead>
        <tbody>
          {flightData.length === 0 ? (
            <tr>
              <td colSpan="7" style={{ textAlign: 'center', padding: '15px', color: '#888' }}>
                No flights available
              </td>
            </tr>
          ) : (
            flightData.map((flight) => (
              <tr key={flight.flightNumber} style={{ textAlign: 'center' }}>
                <td style={{ padding: '10px', border: '1px solid #ccc' }}>{flight.flightNumber}</td>
                <td style={{ padding: '10px', border: '1px solid #ccc' }}>{flight.airline}</td>
                <td style={{ padding: '10px', border: '1px solid #ccc' }}>{flight.origin}</td>
                <td style={{ padding: '10px', border: '1px solid #ccc' }}>{flight.destination}</td>
                <td style={{ padding: '10px', border: '1px solid #ccc' }}>
                  {new Date(flight.departureTime).toLocaleTimeString()}
                </td>
                <td style={{ padding: '10px', border: '1px solid #ccc' }}>
                  {new Date(flight.arrivalTime).toLocaleTimeString()}
                </td>
                <td style={{
                  padding: '10px',
                  border: '1px solid #ccc',
                  color: flight.status === 'Delayed' ? 'orange' : 
                         flight.status === 'Cancelled' ? 'red' : 
                         flight.status === 'Boarding' ? 'blue' : 'green'
                }}>
                  {flight.status}
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      {/* Update Timestamp */}
      <p style={{ marginTop: '20px', fontSize: '0.9em', color: '#666' }}>
        Last updated: {new Date().toLocaleTimeString()}
      </p>
    </div>
  );
}
```

---

### ✅ Step 6: Environment Variable (`.env.local`)
