下面是一个使用 **Node.js** 编写的函数，能够分析 `.tsx` 文件中引入的依赖（即 `import` 语句中的模块路径），并提取出所有外部依赖（包括 npm 包、相对路径、绝对路径等）。

---

### ✅ 功能说明

- 读取 `.tsx` 文件内容。
- 使用 `@babel/parser` 解析 AST（抽象语法树）。
- 提取所有 `import` 语句中的模块路径。
- 区分：
  - **npm 包**（如 `react`、`lodash`）
  - **相对路径**（如 `./components/Button`、`../utils`）
  - **绝对路径**（如 `/src/utils`，通常需配合 `baseUrl` 配置）
- 支持 `import` 和 `import type`、`import * as` 等语法。

---

### 📦 依赖安装

```bash
npm install @babel/parser @babel/types
```

---

### ✅ Node.js 函数代码（`analyzeTsxDeps.js`）

```js
const fs = require('fs');
const path = require('path');
const parser = require('@babel/parser');
const t = require('@babel/types');

/**
 * 分析 TypeScript/TSX 文件中的依赖引入
 * @param {string} filePath - TSX 文件路径
 * @returns {Object} 包含依赖信息的对象
 */
function analyzeTsxDeps(filePath) {
  // 读取文件内容
  let code;
  try {
    code = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    throw new Error(`无法读取文件: ${filePath}，错误: ${err.message}`);
  }

  // 使用 Babel 解析 TSX 代码（支持 TSX 语法）
  let ast;
  try {
    ast = parser.parse(code, {
      sourceType: 'module',
      plugins: [
        'jsx',
        'typescript',
        'decorators-legacy',
        'classProperties'
      ]
    });
  } catch (err) {
    throw new Error(`解析文件失败: ${filePath}，错误: ${err.message}`);
  }

  const imports = [];
  const dependencies = {
    npmPackages: new Set(),
    relativePaths: new Set(),
    absolutePaths: new Set(),
    other: new Set()
  };

  // 遍历 AST 的所有节点
  t.traverse(ast, {
    ImportDeclaration: (path) => {
      const source = path.node.source.value;

      // 去除引号
      const modulePath = source.trim();

      // 分析模块路径类型
      if (modulePath.startsWith('.')) {
        dependencies.relativePaths.add(modulePath);
      } else if (modulePath.startsWith('/')) {
        dependencies.absolutePaths.add(modulePath);
      } else {
        // 假设是 npm 包（如 react、lodash、@types/react）
        // 简单判断：只含字母、数字、-、@、/
        const isNpmPackage = /^[a-zA-Z0-9@\-_]+(?:\/[a-zA-Z0-9@\-_]+)*$/.test(modulePath);
        if (isNpmPackage) {
          dependencies.npmPackages.add(modulePath);
        } else {
          // 其他情况（如别名、特殊路径，暂时归为 other）
          dependencies.other.add(modulePath);
        }
      }

      // 保留原始 import 信息（可选）
      imports.push({
        specifiers: path.node.specifiers.map(s => ({
          type: s.type,
          imported: s.imported?.name || s.imported?.value,
          local: s.local.name
        })),
        source: modulePath
      });
    }
  });

  return {
    filePath,
    imports,
    dependencies: {
      npmPackages: Array.from(dependencies.npmPackages),
      relativePaths: Array.from(dependencies.relativePaths),
      absolutePaths: Array.from(dependencies.absolutePaths),
      other: Array.from(dependencies.other)
    }
  };
}

// 示例调用
if (require.main === module) {
  const tsxFilePath = path.resolve(process.argv[2] || './example.tsx');

  if (!fs.existsSync(tsxFilePath)) {
    console.error('文件不存在:', tsxFilePath);
    process.exit(1);
  }

  try {
    const result = analyzeTsxDeps(tsxFilePath);
    console.log('✅ 分析完成：');
    console.log('文件路径:', result.filePath);
    console.log('\n🧩 依赖信息:');
    console.log('  npm 包:', result.dependencies.npmPackages.length > 0 ? result.dependencies.npmPackages : '无');
    console.log('  相对路径:', result.dependencies.relativePaths.length > 0 ? result.dependencies.relativePaths : '无');
    console.log('  绝对路径:', result.dependencies.absolutePaths.length > 0 ? result.dependencies.absolutePaths : '无');
    console.log('  其他:', result.dependencies.other.length > 0 ? result.dependencies.other : '无');
  } catch (err) {
    console.error('❌ 分析失败:', err.message);
    process.exit(1);
  }
}

module.exports = analyzeTsxDeps;
```

---

### 🧪 示例：`example.tsx`

```tsx
