### 📌 Шаг 3: Создание сервера (server.js)

```js
const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const app = express();
const PORT = 3000;

// Подключаемся к базе данных
const dbPath = path.join(__dirname, 'data', 'database.db');
const db = new sqlite3.Database(dbPath);

// Подготовка базы данных (создание таблицы и вставка данных)
function initializeDB() {
  const schema = `
    CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        email TEXT NOT NULL
    );

    INSERT OR IGNORE INTO users (name, email) VALUES
        ('Анна', 'anna@example.com'),
        ('Иван', 'ivan@example.com'),
        ('Мария', 'maria@example.com');
  `;

  db.exec(schema, (err) => {
    if (err) {
      console.error('Ошибка при инициализации базы:', err);
    } else {
      console.log('База данных инициализирована');
    }
  });
}

// Эндпоинт для получения двумерного массива
app.get('/api/users', (req, res) => {
  const query = 'SELECT * FROM users';

  db.all(query, [], (err, rows) => {
    if (err) {
      console.error('Ошибка при запросе:', err);
      return res.status(500).json({ error: 'Ошибка сервера' });
    }

    // Преобразуем результат в двумерный массив: массив массивов строк
    const resultArray = rows.map(row => [
      row.id,
      row.name,
      row.email
    ]);

    // Отправляем двумерный массив
    res.json(resultArray);
  });
});

// Запуск сервера
app.listen(PORT, () => {
  console.log(`Сервер запущен на http://localhost:${PORT}`);
  initializeDB();
});
```

