```javascript
require('dotenv').config();
const express = require('express');
const { OpenAI } = require('openai');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware para parsear JSON
app.use(express.json());

// Inicializa a API do OpenAI
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
});

// Rota principal para enviar uma mensagem ao modelo
app.post('/api/chat', async (req, res) => {
  try {
    const { messages } = req.body;

    if (!messages || !Array.isArray(messages)) {
      return res.status(400).json({
        error: 'O campo "messages" é obrigatório e deve ser um array.',
      });
    }

    // Chama a API do OpenAI
    const response = await openai.chat.completions.create({
      model: 'gpt-3.5-turbo', // ou 'gpt-4', 'gpt-4-turbo'
      messages: messages,
      temperature: 0.7,
      max_tokens: 150,
      top_p: 1,
      frequency_penalty: 0,
      presence_penalty: 0,
    });

    const aiMessage = response.choices[0]?.message?.content || '';

    res.json({
      success: true,
      response: aiMessage,
      usage: response.usage,
    });
  } catch (error) {
    console.error('Erro ao chamar a OpenAI:', error);

    if (error.response) {
      // Erros da API OpenAI (ex: limite de tokens, key inválida)
      return res.status(error.response.status).json({
        error: error.response.data.error?.message || 'Erro na API do OpenAI',
      });
    }

    res.status(500).json({
      error: 'Erro interno do servidor.',
    });
  }
});

// Rota de teste
app.get('/api/health', (req, res) => {
  res.json({ status: 'OK', message: 'API está funcionando!' });
});

// Inicia o servidor
app.listen(PORT, () => {
  console.log(`✅ Servidor rodando na porta ${PORT}`);
  console.log(`🔗 Acesse: http://localhost:${PORT}/api/health`);
});
```

