      // Optional: modify data
      // const modifiedData = transform(data);  // e.g., add headers, wrap
      // originalSend(modifiedData);

      originalSend(data);
    };

    // Attach event listeners
    socket.addEventListener('message', (event) => {
      console.log('Incoming message:', event.data);
      // Optional: modify or log incoming data
    });

    socket.addEventListener('open', (event) => {
      console.log('WebSocket opened:', event);
    });

    socket.addEventListener('close', (event) => {
      console.log('WebSocket closed:', event);
    });

    socket.addEventListener('error', (event) => {
      console.error('WebSocket error:', event);
    });

    // Return the real socket, but we can't return a Proxy unless we wrap more carefully
    // We'll use a Proxy to expose the socket with the same interface

    return new Proxy(socket, {
      get(target, prop) {
        // If property exists on socket, return it
        if (prop in target) {
          return target[prop];
        }
        // Otherwise try to fall back to the socket
        return target[prop];
      },
      // Optional: customize toString, etc.
      has(target, prop) {
        return prop in target || prop in OriginalWebSocket.prototype;
      }
    });
  }
}

// Replace the global WebSocket constructor
window.WebSocket = WebSocketInterceptor;

// Now all WebSocket instances are intercepted!
```

---

## ✅ How to Use It — Works Everywhere

```js
// ANY existing code that does this will now be intercepted:
const ws = new WebSocket('wss://example.com');

// Example behavior:
ws.send('Hello, server!'); // Logs: Outgoing message intercepted: Hello, server!
ws.onmessage = (e) => console.log('Received:', e.data); // Also works
```

> ✅ This intercepts all WebSocket connections, regardless of who creates them.

---

## ⚠️ Important Notes & Caveats

### 1. **Only works once!**
You can only replace `window.WebSocket` once. If another script does `window.WebSocket = ...` later, it will override your intercept.

> **Best to do this at the very top of your global script**, ideally via a `<script>` tag that loads first.

### 2. **Some libraries may store references to the original constructor**
For example, some libs cache `WebSocket` during setup. So if you load your interceptor after a lib has already used `WebSocket`, that lib won’t be affected.

> Fix: Load your interceptor **as soon as possible**, ideally before any other scripts.

### 3. **`instanceof WebSocket` may fail due to Proxy**
Because the returned object is a `Proxy`, `instanceof WebSocket` might not work.

But it's often acceptable since you're just using the socket API — most code doesn't rely on `instanceof`.

If needed, you can check `socket instanceof WebSocket` only if the `Proxy` forwards it via `getPrototypeOf`, but it's fragile.

### 4. **Performance**
Only slight overhead — one `send` wrap and event listeners. Not significant.

---

## ✅ Bonus: Modify Outbound Messages?

If you want to **modify outgoing messages**, you can do:

```js
socket.send = function (data) {
  const modified = JSON.stringify({
    timestamp: Date.now(),
    message: data
  });

  console.log('Intercepted & modified:', modified);
  originalSend(modified);
};
```

