| ✅ Task | How |
|------|-----|
| Intercept ALL WebSocket connections | Replace `window.WebSocket` |
| Intercept `send()` | Override `send` method on the real socket |
| Intercept messages | Add `message` listener |
| Maintain API compatibility | Use `Proxy` carefully |
| Ensure it works early | Load this script first |

---

## ✅ Final Working Example (Copy-Paste Ready)

```js
const OriginalWebSocket = window.WebSocket;

class WebSocketInterceptor {
  constructor(url, protocols) {
    const socket = new OriginalWebSocket(url, protocols);

    const originalSend = socket.send.bind(socket);

    socket.send = function (data) {
      console.log('📤 Outgoing:', data);
      originalSend(data);
    };

    socket.addEventListener('message', (e) => {
      console.log('📥 Incoming:', e.data);
    });

    socket.addEventListener('open', (e) => {
      console.log('🔗 Connected:', e);
    });

    socket.addEventListener('close', (e) => {
      console.log('🛑 Disconnected:', e);
    });

    socket.addEventListener('error', (e) => {
      console.error('❌ Error:', e);
    });

    return new Proxy(socket, {
      get(target, prop) {
        return target[prop];
      }
    });
  }
}

// 🔥 Replace global WebSocket
window.WebSocket = WebSocketInterceptor;

// Now all new WebSocket connections are intercepted!
```

