### Шаг 2: Определение схем (Schemas)

```js
// models/User.js
const mongoose = require('mongoose');

const userSchema = new mongoose.Schema({
  name: String,
  email: String
});

// Важно: схема User не хранит посты, она просто "ссылается" на них
module.exports = mongoose.model('User', userSchema);
```

```js
// models/Post.js
const mongoose = require('mongoose');

const postSchema = new mongoose.Schema({
  title: String,
  content: String,
  // 🔗 Ссылка на пользователя (ID)
  author: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User', // указывает на модель User
    required: true
  },
  createdAt: {
    type: Date,
    default: Date.now
  }
});

module.exports = mongoose.model('Post', postSchema);
```

> ⚠️ Здесь `author: { type: mongoose.Schema.Types.ObjectId, ref: 'User' }` — это **ссылка** на `User` по ID.

---

### Шаг 3: Создание данных

```js
// Пример: создание пользователя и поста

const User = require('./models/User');
const Post = require('./models/Post');

async function createData() {
  try {
    // Создаём пользователя
    const user = await User.create({
      name: 'Анна',
      email: 'anna@example.com'
    });

    // Создаём пост, ссылаясь на пользователя по ID
    const post = await Post.create({
      title: 'Мой первый пост',
      content: 'Привет, я написал пост!',
      author: user._id // здесь хранится ID пользователя
    });

    console.log('Пост создан:', post);
  } catch (err) {
    console.error(err);
  }
}

