  name: String,
  email: String,
  // 👇 Теперь User хранит массив постов (по их ID)
  posts: [
    {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Post' // Важно: ref = имя модели
    }
  ]
});

module.exports = mongoose.model('User', userSchema);
```

> Теперь ты можешь сделать `populate('posts')`.

---

### 🔁 Теперь так будет работать:

```js
