  try {
    const users = await User
      .find()
      .populate('posts') // Заполняем массив posts реальными постами
      .exec();

    users.forEach(user => {
      console.log(`${user.name}`);
      user.posts.forEach(post => {
        console.log(`  - ${post.title}`);
      });
    });
  } catch (err) {
    console.error(err);
  }
