const fs = require('fs');
const crypto = require('crypto');

// Ustawienia
const inputFile = 'plik.js';         // Plik do zaszyfrowania
const outputFile = 'plik.js.enc';    // Wyjściowy plik zaszyfrowany
const password = 'moje_szyfrowanie_123'; // Hasło do szyfrowania (możesz zmienić)

// Generujemy 32-bajtowy klucz z hasła (SHA-256)
const key = crypto.scryptSync(password, 'salt', 32); // 32 bajty = 256 bitów

// Generujemy losowy IV (16 bajtów dla AES)
const iv = crypto.randomBytes(16);

// Tworzymy szyfrator
const cipher = crypto.createCipheriv('aes-256-cbc', key, iv);

// Odczytujemy plik wejściowy
