// Zaszyfrowanie pliku
const readStream = fs.createReadStream(inputFile, { encoding: 'utf8' });
const writeStream = fs.createWriteStream(outputFile);

readStream
  .on('data', (chunk) => {
    const encrypted = cipher.update(chunk, 'utf8', 'hex');
    encryptedData += encrypted;
  })
  .on('end', () => {
    const final = cipher.final('hex');
    encryptedData += final;

    // Zapisujemy IV + zaszyfrowane dane do pliku (IV wstawiamy na początek)
    const combined = iv.toString('hex') + encryptedData;
