const fs = require('fs');
const crypto = require('crypto');

// Ustawienia
const inputFile = 'plik.js.enc';     // Zaszyfrowany plik
const outputFile = 'odszfrowany.js'; // Wyjściowy plik
const password = 'moje_szyfrowanie_123'; // To samo hasło!

// Generujemy klucz z hasła
const key = crypto.scryptSync(password, 'salt', 32);

// Odczytujemy plik zaszyfrowany
const data = fs.readFileSync(inputFile, 'utf8');

// Wyodrębniamy IV (pierwsze 32 znaków hex = 16 bajtów)
const ivHex = data.slice(0, 32);
const encryptedData = data.slice(32);

// Konwertujemy IV
const iv = Buffer.from(ivHex, 'hex');

// Tworzymy dekryptor
const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);

// Odszyfrowanie
let decrypted = '';
decipher.on('readable', () => {
  let chunk;
  while (null !== (chunk = decipher.read())) {
    decrypted += chunk.toString('utf8');
  }
});

decipher.on('end', () => {
  fs.writeFileSync(outputFile, decrypted, 'utf8');
  console.log(`✓ Plik został odszyfrowany: ${outputFile}`);
});

decipher.write(encryptedData, 'hex');
decipher.end();
```

