      // Upgrade needed (first time or schema change)
      request.onupgradeneeded = (event) => {
        this.db = event.target.result;

        // Create object store for blog posts
        if (!this.db.objectStoreNames.contains("posts")) {
          const postsStore = this.db.createObjectStore("posts", { keyPath: "id" });

          // Create indexes for faster search
          postsStore.createIndex("title", "title", { unique: false });
          postsStore.createIndex("date", "date", { unique: false });
          postsStore.createIndex("tags", "tags", { unique: false });
        }
      };
    });
  }
}
```

> 💡 You can call `await db.openDB()` when your app starts.

