## 🔹 2. CRUD Operations for Blog Posts

Let’s add methods to **create, read, update, delete** blog posts.

### ✅ Add a New Blog Post

```javascript
async addPost(post) {
  const db = await this.openDB();
  const tx = db.transaction("posts", "readwrite");
  const store = tx.objectStore("posts");

  const id = Date.now().toString(); // Generate unique ID
  const newPost = {
    id,
    title: post.title || "Untitled",
    content: post.content || "",
    tags: Array.isArray(post.tags) ? post.tags : [],
    date: post.date || new Date().toISOString(),
    status: post.status || "draft"
  };

  return new Promise((resolve, reject) => {
    const request = store.add(newPost);

    request.onsuccess = () => resolve(newPost);
    request.onerror = () => reject(new Error("Failed to add post"));
  });
}
```

### ✅ Get All Blog Posts

```javascript
async getAllPosts() {
  const db = await this.openDB();
  const tx = db.transaction("posts", "readonly");
  const store = tx.objectStore("posts");

  return new Promise((resolve, reject) => {
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(new Error("Failed to fetch posts"));
  });
}
```

### ✅ Get Post by ID

```javascript
async getPostById(id) {
  const db = await this.openDB();
  const tx = db.transaction("posts", "readonly");
  const store = tx.objectStore("posts");

  return new Promise((resolve, reject) => {
    const request = store.get(id);

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(new Error("Failed to get post"));
  });
}
```

### ✅ Update a Blog Post

```javascript
async updatePost(id, updates) {
  const db = await this.openDB();
  const tx = db.transaction("posts", "readwrite");
  const store = tx.objectStore("posts");

  return new Promise((resolve, reject) => {
    const request = store.get(id);

    request.onsuccess = () => {
      const post = request.result;
      if (!post) {
        reject(new Error("Post not found"));
        return;
      }

      // Merge updates
      const updatedPost = { ...post, ...updates, id };

      const updateRequest = store.put(updatedPost);
      updateRequest.onsuccess = () => resolve(updatedPost);
      updateRequest.onerror = () => reject(new Error("Failed to update post"));
    };

    request.onerror = () => reject(new Error("Failed to fetch post"));
  });
}
```

### ✅ Delete a Post

```javascript
async deletePost(id) {
  const db = await this.openDB();
  const tx = db.transaction("posts", "readwrite");
  const store = tx.objectStore("posts");

  return new Promise((resolve, reject) => {
    const request = store.delete(id);

    request.onsuccess = () => resolve(true);
    request.onerror = () => reject(new Error("Failed to delete post"));
  });
}
```

