## 🔹 3. Search & Filter Blog Posts (Using Indexes)

Now you can search posts efficiently using indexes.

### 🔎 Search by Title (Case-insensitive)

```javascript
async searchPostsByTitle(keyword) {
  const db = await this.openDB();
  const tx = db.transaction("posts", "readonly");
  const store = tx.objectStore("posts");
  const index = store.index("title");

  return new Promise((resolve, reject) => {
    const request = index.getAll(IDBKeyRange.lowerBound(keyword.toLowerCase()));

    request.onsuccess = () => {
      const results = request.result.filter(post => 
        post.title.toLowerCase().includes(keyword.toLowerCase())
      );
      resolve(results);
    };

    request.onerror = () => reject(new Error("Search failed"));
  });
}
```

### 🏷️ Get Posts by Tag

```javascript
async getPostsByTag(tag) {
  const db = await this.openDB();
  const tx = db.transaction("posts", "readonly");
  const store = tx.objectStore("posts");
  const index = store.index("tags");

  return new Promise((resolve, reject) => {
    const request = index.getAll(IDBKeyRange.only(tag));

    request.onsuccess = () => {
      const results = request.result.filter(post =>
        post.tags.includes(tag)
      );
      resolve(results);
    };

    request.onerror = () => reject(new Error("Tag search failed"));
  });
}
```

