#include <iostream>
#include <memory>
#include <thread>
#include <atomic>
#include <pion/webrtc.hpp>
#include <opencv2/opencv.hpp>

using namespace pion;
using namespace std;

class VideoCall {
private:
    std::shared_ptr<webrtc::PeerConnection> pc;
    std::atomic<bool> running{true};
    cv::VideoCapture cap;

public:
    VideoCall() {
        cap.open(0);
        if (!cap.isOpened()) {
            cerr << "Error: Could not open webcam!" << endl;
            exit(1);
        }
    }

    void start() {
        // Create peer connection
        pc = webrtc::PeerConnection::Create();

        // Add video source
        auto video_track = webrtc::VideoTrack::Create("localVideo", "localVideo");
        pc->AddTrack(video_track, {});

        // Start sending video (simply capture and send)
        std::thread([this]() {
            cv::Mat frame;
            while (running) {
                cap >> frame;
                if (frame.empty()) continue;

                // Convert BGR to I420 (required for WebRTC)
                cv::Mat yuv_frame;
                cv::cvtColor(frame, yuv_frame, cv::COLOR_BGR2YUV_I420);

                // Send frame to WebRTC
                video_track->Send(std::make_shared<webrtc::VideoFrame>(yuv_frame, 0));

                std::this_thread::sleep_for(std::chrono::milliseconds(33)); // ~30 FPS
            }
        }).detach();

        // Handle incoming tracks
        pc->OnTrack([this](const std::shared_ptr<webrtc::Track>& track) {
            std::cout << "Incoming track: " << track->Kind() << std::endl;
            // We'll display incoming video shortly
        });

        // Create offer
        pc->CreateOffer([this](const std::string& sdp) {
            std::cout << "Offer: " << sdp << std::endl;
            pc->SetLocalDescription(sdp);
        });

        // Handle ICE candidates
        pc->OnIceCandidate([this](const webrtc::IceCandidate& candidate) {
            std::cout << "ICE Candidate: " << candidate.Candidate() << std::endl;
            // You'd send this to peer via signaling server (e.g. WebSocket)
            // For pure P2P, use STUN/TURN or use a simple discovery (e.g. UDP hole-punching)
        });

        // Keep app alive
        while (running) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    void stop() {
        running = false;
    }
};

int main() {
    VideoCall call;
    std::cout << "Starting P2P video call... Press Ctrl+C to exit." << std::endl;
    call.start();
    return 0;
}
```

