### ✅ Archivo: `script.js`

```javascript
// Respuestas correctas
const correctAnswers = {
  q1: "París",
  q2: "Mercurio",
  q3: "8",
  q4: "1969",
  q5: "Gabriel García Márquez",
  q6: "Nilo",
  q7: "Mercurio",
  q8: "Yen",
  q9: "8",
  q10: "India"
};

// Estado actual del cuestionario
let currentQuestion = 1;
const totalQuestions = 10;
const questionContainers = document.querySelectorAll('.question-container');
const prevBtn = document.getElementById('prevBtn');
const nextBtn = document.getElementById('nextBtn');
const submitBtn = document.getElementById('submitBtn');
const resultDiv = document.getElementById('result');
const finalScore = document.getElementById('finalScore');
const feedback = document.getElementById('feedback');

// Mostrar la pregunta actual
function showQuestion(index) {
  questionContainers.forEach((q, i) => {
    q.classList.remove('active');
  });
  document.getElementById(`question-${index}`).classList.add('active');

  // Habilitar o deshabilitar botón anterior
  prevBtn.disabled = index === 1;

  // Cambiar el botón siguiente
  if (index === totalQuestions) {
    nextBtn.style.display = 'none';
    submitBtn.style.display = 'inline-block';
  } else {
    nextBtn.style.display = 'inline-block';
    submitBtn.style.display = 'none';
  }
}

// Evento: Siguiente pregunta
nextBtn.addEventListener('click', () => {
  if (currentQuestion < totalQuestions) {
    currentQuestion++;
    showQuestion(currentQuestion);
  }
});

// Evento: Anterior pregunta
prevBtn.addEventListener('click', () => {
  if (currentQuestion > 1) {
    currentQuestion--;
    showQuestion(currentQuestion);
  }
});

// Evento: Terminar y calcular resultado
submitBtn.addEventListener('click', () => {
  let score = 0;
  for (let i = 1; i <= totalQuestions; i++) {
    const selected = document.querySelector(`input[name="q${i}"]:checked`);
    if (selected && selected.value === correctAnswers[`q${i}`]) {
      score++;
    }
  }

  // Mostrar resultado
  finalScore.textContent = `Tu puntaje es: ${score}/${totalQuestions}`;
  if (score === totalQuestions) {
    feedback.textContent = "¡Excelente! Respuestas perfectas. 🎉";
  } else if (score >= totalQuestions * 0.7) {
    feedback.textContent = "¡Muy bien! Tienes buenos conocimientos. 👏";
  } else {
    feedback.textContent = "Sigue practicando, puedes mejorar. 💪";
  }

  resultDiv.style.display = 'block';
  nextBtn.style.display = 'none';
  submitBtn.style.display = 'none';
  prevBtn.style.display = 'none';
});

// Inicializar: Mostrar la primera pregunta
showQuestion(currentQuestion);
```

