```js
const db = require('../data/db');

class Article {
  static async getAllPublished() {
    return new Promise((resolve, reject) => {
      db.all(
        `SELECT *, (SELECT COUNT(*) FROM comments WHERE comments.article_id = articles.id) as comment_count
         FROM articles
         WHERE is_draft = 0
         ORDER BY published_at DESC`,
        [],
        (err, rows) => {
          if (err) reject(err);
          else resolve(rows);
        }
      );
    });
  }

  static async getAllDrafts() {
    return new Promise((resolve, reject) => {
      db.all(
        `SELECT * FROM articles WHERE is_draft = 1 ORDER BY created_at DESC`,
        [],
        (err, rows) => {
          if (err) reject(err);
          else resolve(rows);
        }
      );
    });
  }

  static async getById(id) {
    return new Promise((resolve, reject) => {
      db.get(
        `SELECT *, (SELECT COUNT(*) FROM comments WHERE comments.article_id = articles.id) as comment_count
         FROM articles
         WHERE id = ?`,
        [id],
        (err, row) => {
          if (err) reject(err);
          else resolve(row);
        }
      );
    });
  }

  static async create(title, subtitle, body) {
    return new Promise((resolve, reject) => {
      db.run(
        `INSERT INTO articles (title, subtitle, body, is_draft) VALUES (?, ?, ?, 1)`,
        [title, subtitle, body],
        function (err) {
          if (err) reject(err);
          else resolve(this.lastID);
        }
      );
    });
  }

  static async update(id, title, subtitle, body) {
    return new Promise((resolve, reject) => {
      db.run(
        `UPDATE articles SET title = ?, subtitle = ?, body = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?`,
        [title, subtitle, body, id],
        function (err) {
          if (err) reject(err);
          else resolve(this.changes > 0);
        }
      );
    });
  }

  static async publish(id) {
    return new Promise((resolve, reject) => {
      db.run(
        `UPDATE articles SET is_draft = 0, published_at = CURRENT_TIMESTAMP WHERE id = ?`,
        [id],
        function (err) {
          if (err) reject(err);
          else resolve(this.changes > 0);
        }
      );
    });
  }

  static async delete(id) {
    return new Promise((resolve, reject) => {
      db.run(`DELETE FROM articles WHERE id = ?`, [id], function (err) {
        if (err) reject(err);
        else resolve(this.changes > 0);
      });
    });
  }

  static async like(id) {
    return new Promise((resolve, reject) => {
      db.run(`UPDATE articles SET likes = likes + 1 WHERE id = ?`, [id], function (err) {
        if (err) reject(err);
        else resolve(this.changes > 0);
      });
    });
  }

  static async addComment(articleId, body) {
    return new Promise((resolve, reject) => {
      db.run(
        `INSERT INTO comments (article_id, body) VALUES (?, ?)`,
        [articleId, body],
        function (err) {
          if (err) reject(err);
          else resolve(this.lastID);
        }
      );
    });
  }

  static async getComments(articleId) {
    return new Promise((resolve, reject) => {
      db.all(
        `SELECT * FROM comments WHERE article_id = ? ORDER BY created_at ASC`,
        [articleId],
        (err, rows) => {
          if (err) reject(err);
          else resolve(rows);
        }
      );
    });
  }
}

module.exports = Article;
```

