### 🛠️ Функция, преобразующая подобный массив в объект

```js
function arrayToTree(arr) {
    const root = {};

    let current = root;

    for (let i = 0; i < arr.length; i++) {
        const item = arr[i];

        // Если это строка — создаём вложенный объект
        if (typeof item === 'string') {
            // Переходим в следующий уровень
            if (!current[item]) {
                current[item] = {};
            }
            current = current[item];
        }

        // Если это массив — обрабатываем его
        else if (Array.isArray(item)) {
            // Используем строку, которая была перед массивом, как ключ
            // Но мы должны учитывать, что текущий `current` — это объект, в который нужно добавить
            // Но проблема: строка перед массивом — это `current`-ключ?
            // Нет — `current` — это текущий "текущий узел", а ключ надо брать из предыдущего элемента

            // В нашем цикле — `item` — это массив, и `arr[i-1]` — это строка, которая определяет ключ
            if (i > 0 && typeof arr[i - 1] === 'string') {
                const key = arr[i - 1];
                current[key] = item; // Устанавливаем массив как значение для строки `key`
                // Остаемся на том же уровне, т.к. массив — это "значение", а не узел для вложения
            }
            // Пропускаем массив, не меняем current
        }
    }

    return root;
}
```

