### 🔄 Пример с расширенной логикой (если нужно разбить по типу операций)

Предположим, что:
- `Get Version`, `Get Date & Time` → "Positive" (чтение, положительные значения).
- `Alert` → "Write".

Тогда можно добавить:

```js
function arrayToTreeWithTypes(arr) {
    const root = {};

    let current = root;

    // Словарь для определения типа операции
    const operationType = {
        "Get Version": "Positive",
        "Get Date & Time": "Instantaneous",
        "Alert": "Write"
    };

    for (let i = 0; i < arr.length; i++) {
        const item = arr[i];

        if (typeof item === 'string') {
            if (!current[item]) {
                current[item] = {};
            }
            current = current[item];
        }

        else if (Array.isArray(item)) {
            const key = arr[i - 1]; // ключ перед массивом
            if (typeof key !== 'string') continue;

            // Инициализируем нужное вложение
            const target = current;
            if (!target[key]) {
                target[key] = {};
            }

            // Теперь пройдём по элементам массива и распределим их
            item.forEach(operation => {
                const type = operationType[operation];
                if (!type) return;

                if (!target[key][type]) {
                    target[key][type] = [];
                }
                target[key][type].push(operation);
            });
        }
    }

    return root;
}
```

