const url = require("url"); // URL 解析模块，用来解析浏览器请求的地址信息
const uuid = require("uuid"); // 生成唯一标识符的工具，用来给上传的文件命名，避免重名

// 静态文件服务的目录，所有用户上传的文件和网页都放在这里
const staticBasePath = "./uploads";
let hostName = ""; // 用来保存客户端请求的主机名（比如 localhost:3000）

const server = http.createServer((req, res) => {
    // 把客户端请求中的 host（比如 localhost:3000）存下来
    hostName = req.headers.host;

    // 解析请求的 URL，比如 /index.html 或 /uploads/photo.jpg
    const parsedUrl = url.parse(req.url);

    // 清理路径，防止路径遍历攻击（比如 ../../ 之类的恶意路径）
    const sanitizePath = path.normalize(parsedUrl.pathname).replace(/^(\.\.[\/\\])+/, "");

    // 拼出完整的文件路径，比如 ./uploads/index.html
    let pathname = path.join(staticBasePath, sanitizePath);

    // 检查这个文件是否存在
    fs.exists(pathname, exist => {
        if (!exist) {
            // 如果文件不存在，返回 404 错误
            res.statusCode = 404;
            res.end(`文件 ${pathname} 未找到!`);
            return;
        }

        // 文件存在，开始读取文件内容
        fs.readFile(pathname, (err, data) => {
            if (err) {
                // 读取出错，返回 500 错误
                res.statusCode = 500;
                res.end(`无法读取文件: ${err}.`);
            } else {
                // 根据文件后缀设置正确的 MIME 类型（告诉浏览器该怎么处理这个文件）
                if (pathname.endsWith(".html")) {
                    res.setHeader("Content-Type", "text/html"); // HTML 文件
                } else if (pathname.endsWith(".css")) {
                    res.setHeader("Content-Type", "text/css"); // CSS 文件
                } else if (pathname.endsWith(".js")) {
                    res.setHeader("Content-Type", "application/javascript"); // JS 文件
                } else if (pathname.endsWith(".jpg") || pathname.endsWith(".jpeg")) {
                    res.setHeader("Content-Type", "image/jpeg"); // JPEG 图片
                } else if (pathname.endsWith(".png")) {
                    res.setHeader("Content-Type", "image/png"); // PNG 图片
                }

                // 把文件内容返回给浏览器
                res.end(data);
            }
        });
    });
});

// 创建 WebSocket 服务，绑定到上面的 HTTP 服务器
const wss = new WebSocket.Server({ server });

// 当有客户端连接上来时触发
wss.on("connection", ws => {
    // 客户端发送消息时触发
    ws.on("message", message => {
        // 把客户端发来的 JSON 字符串解析成对象
        const data = JSON.parse(message);

        // 如果是文本消息（聊天内容）
        if (data.type === "text") {
            // 把这条消息广播给所有连接的客户端
            broadcast(JSON.stringify({ type: data.type, name: data.name, message: data.message }));
        }
        // 如果是文件或图片上传
        else if (data.type === "file" || data.type === "image") {
            const uploadPath = "./uploads"; // 上传文件存放的目录

            // 如果目录不存在，就创建它（递归创建，包括子目录）
            if (!fs.existsSync(uploadPath)) {
                fs.mkdirSync(uploadPath, { recursive: true });
            }

            // 从 base64 数据中提取实际的图片/文件内容（去掉前缀 data:image/jpeg;base64,）
            const base64Data = data.filedata.split(";base64,")[1];

            // 生成一个唯一的文件名，加上传的原始文件名的后缀（如 .jpg）
            const filename = uuid.v4() + path.extname(data.originalName);

            // 拼出完整的文件保存路径
            const filepath = path.join(uploadPath, filename);

            // 把 base64 数据写入文件（注意编码是 base64）
            fs.writeFile(filepath, base64Data, { encoding: "base64" }, err => {
                if (err) {
                    // 写入失败，打印错误，并通知上传者
                    console.error("无法保存文件: ", err);
                    ws.send(JSON.stringify({ type: "error", message: "无法保存文件" }));
                } else {
                    // 保存成功，生成一个相对路径的 URL（给前端显示用）
                    const fileUrl = `/uploads/${filename}`;

                    // 广播一条消息：谁上传了什么文件，以及文件的下载路径
                    broadcast(JSON.stringify({
                        type: data.type,
                        name: data.name,
                        originalName: data.originalName,
                        url: fileUrl
                    }));
                }
            });
        }
    });

    // 客户端断开连接时触发
    ws.on("close", () => {
        console.log("WebSocket 已关闭");
    });
});

// 这个函数用来向所有在线的客户端发送消息
function broadcast(message) {
    wss.clients.forEach(client => {
        // 只有连接状态是 OPEN（打开）的时候才能发消息
        if (client.readyState === WebSocket.OPEN) {
            client.send(message);
        }
    });
}

