class WebSocketManager {
  /**
   * Creates a new WebSocketManager instance.
   * Initializes an internal event emitter using the `mitt` library.
   */
  constructor() {
    this.emitter = mitt()
  }

  /**
   * Opens a WebSocket connection to the specified server endpoint.
   * Sets up event listeners to handle incoming messages and parse JSON data.
   * Emits events based on received actions:
   * - `update_station`: triggered when a specific station is updated (includes `uuid`)
   * - `update_station_list`: triggered when the list of stations is updated
   * - `update_inventory`: triggered when inventory data changes (includes `factory_uuid` and `inventory_name`)
   *
   * @example
   * websocketApi.open()
   */
  open() {
