   *
   * @param {Object} data - The data object to send to the server.
   * @param {string} [data.action] - The action to trigger on the server (e.g., 'request_status').
   * @param {string} [data.uuid] - Optional UUID identifier.
   * @param {string} [data.factory] - Optional factory identifier.
   * @example
   * websocketApi.sendMessage({ action: 'sync_data', uuid: 'abc123' })
   */
  sendMessage(data) {
    if (this.socket && this.socket.readyState === WebSocket.OPEN) {
      this.socket.send(JSON.stringify(data))
    } else {
      console.error('WebSocket is not open. Cannot send message.')
    }
  }
}

