### ✅ 3. `main.js`

```javascript
// 模型数据存储
let allModels = [];
let currentCategory = 'all';
let currentPage = 1;
const modelsPerPage = 20;

// 加载模型
document.addEventListener('DOMContentLoaded', async () => {
  try {
    const response = await fetch('models/');
    const text = await response.text();
    const parser = new DOMParser();
    const doc = parser.parseFromString(text, 'text/html');
    const links = doc.querySelectorAll('a');

    // 提取模型文件路径
    const modelFiles = [];
    links.forEach(a => {
      const href = a.href;
      const name = a.textContent.trim();
      const ext = name.toLowerCase().split('.').pop();

      // 只处理 GLB/GLTF 和图片
      if (['glb', 'gltf', 'gls', 'fbx', 'obj'].includes(ext)) {
        modelFiles.push(href);
      }
    });

    // 为每个模型找同名的预览图
    modelFiles.forEach(modelPath => {
      const basename = modelPath.split('/').pop();
      const baseNameWithoutExt = basename.split('.').slice(0, -1).join('.');
      const previewExt = ['jpg', 'jpeg', 'png', 'webp'].map(ext => `${baseNameWithoutExt}.${ext}`);
      const previewPath = previewExt.find(ext => modelFiles.includes(ext));

      const category = getCategoryFromName(basename);
      allModels.push({
        name: basename,
        url: modelPath,
        preview: previewPath || `https://via.placeholder.com/200?text=No+Preview`,
        category: category
      });
    });

    console.log("共加载模型:", allModels.length);

    // 初始化分类单选框
    setupCategoryFilter();

    // 渲染第一页
    renderModels();
  } catch (err) {
    console.error("加载失败:", err);
    alert("无法加载模型，请检查 models/ 文件夹是否存在且包含文件。");
  }
});

// 从文件名判断分类（示例逻辑，可根据命名调整）
function getCategoryFromName(filename) {
  const lower = filename.toLowerCase();
  if (lower.includes('project') || lower.includes('scene')) return '项目文件';
  if (lower.includes('doc') || lower.includes('file') || lower.includes('manual')) return '文档';
  if (lower.includes('hdrp') || lower.includes('high') || lower.includes('render')) return 'HDRP资源';
  return '其他';
}

// 设置分类筛选
function setupCategoryFilter() {
  const radios = document.querySelectorAll('input[name="category"]');
  radios.forEach(radio => {
    radio.addEventListener('change', () => {
      currentCategory = radio.value;
      currentPage = 1;
      renderModels();
    });
  });
}

// 渲染模型
function renderModels() {
  const grid = document.getElementById('modelGrid');
  grid.innerHTML = '';

  const filtered = allModels.filter(m => currentCategory === 'all' || m.category === currentCategory);
  const totalPages = Math.ceil(filtered.length / modelsPerPage);
  const startIndex = (currentPage - 1) * modelsPerPage;
  const currentModels = filtered.slice(startIndex, startIndex + modelsPerPage);

  // 更新分页信息
  document.getElementById('pageInfo').textContent = `第 ${currentPage} 页，共 ${totalPages} 页`;

  // 检查按钮状态
  document.getElementById('prevBtn').disabled = currentPage === 1;
  document.getElementById('nextBtn').disabled = currentPage === totalPages;

  // 渲染每张模型卡片
  currentModels.forEach(model => {
    const card = document.createElement('div');
    card.className = 'model-card';

    const imgSrc = model.preview;

    const previewImg = new Image();
    previewImg.src = imgSrc;
    previewImg.alt = model.name;
    previewImg.style.width = '100%';
    previewImg.style.height = '200px';
    previewImg.style.objectFit = 'cover';

    const previewDiv = document.createElement('div');
    previewDiv.className = 'model-preview';
    previewDiv.appendChild(previewImg);
    previewDiv.addEventListener('click', () => {
      const link = document.createElement('a');
      link.href = model.url;
      link.download = model.name;
      link.click();
    });

    const info = document.createElement('div');
    info.className = 'model-info';
    info.innerHTML = `<strong>${model.name}</strong><br>分类: ${model.category}`;

    card.appendChild(previewDiv);
    card.appendChild(info);

    grid.appendChild(card);
  });
}

// 翻页功能
document.getElementById('prevBtn').addEventListener('click', () => {
  if (currentPage > 1) {
    currentPage--;
    renderModels();
  }
});

document.getElementById('nextBtn').addEventListener('click', () => {
  const filtered = allModels.filter(m => currentCategory === 'all' || m.category === currentCategory);
  const totalPages = Math.ceil(filtered.length / modelsPerPage);
  if (currentPage < totalPages) {
    currentPage++;
    renderModels();
  }
});
```

