    <script>
        // API Key - Replace with your own OpenWeatherMap API key
        const API_KEY = 'YOUR_API_KEY_HERE';

        // DOM Elements
        const cityInput = document.getElementById('city-input');
        const searchBtn = document.getElementById('search-btn');
        const weatherCard = document.getElementById('weather-card');
        const loading = document.getElementById('loading');
        const errorMessage = document.getElementById('error-message');
        const forecastContainer = document.querySelector('.forecast-container');
        const forecastCards = document.getElementById('forecast-cards');

        // DOM Elements for weather data
        const cityName = document.getElementById('city-name');
        const currentDate = document.getElementById('current-date');
        const temperature = document.getElementById('temperature');
        const weatherDescription = document.getElementById('weather-description');
        const icon = document.getElementById('icon');
        const feelsLike = document.getElementById('feels-like');
        const minMaxTemp = document.getElementById('min-max-temp');
        const humidity = document.getElementById('humidity');
        const windSpeed = document.getElementById('wind-speed');
        const pressure = document.getElementById('pressure');

        // Event Listeners
        searchBtn.addEventListener('click', getWeather);
        cityInput.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                getWeather();
            }
        });

        // Function to get weather data
        async function getWeather() {
            const city = cityInput.value.trim();

            if (!city) {
                showError('Please enter a city name');
                return;
            }

            // Show loading state
            loading.style.display = 'block';
            weatherCard.style.display = 'none';
            errorMessage.style.display = 'none';
            forecastContainer.style.display = 'none';

            try {
                // Fetch current weather
                const currentWeatherResponse = await fetch(
                    `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${API_KEY}&units=metric`
                );

                if (!currentWeatherResponse.ok) {
                    throw new Error('City not found');
                }

                const currentWeatherData = await currentWeatherResponse.json();

                // Fetch 5-day forecast
                const forecastResponse = await fetch(
                    `https://api.openweathermap.org/data/2.5/forecast?q=${city}&appid=${API_KEY}&units=metric`
                );

                if (!forecastResponse.ok) {
                    throw new Error('Forecast data unavailable');
                }

                const forecastData = await forecastResponse.json();

                // Process and display data
                displayWeather(currentWeatherData, forecastData);

            } catch (error) {
                if (error.message === 'City not found') {
                    showError('City not found. Please check the spelling and try again.');
                } else {
                    showError('Error fetching weather data. Please try again later.');
                }
                console.error('Error:', error);
            } finally {
                loading.style.display = 'none';
            }
        }

        // Function to display weather data
        function displayWeather(currentData, forecastData) {
            // Update city name and date
            cityName.textContent = currentData.name + ', ' + currentData.sys.country;

            const now = new Date();
            const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
            currentDate.textContent = now.toLocaleDateString(undefined, options);

            // Update main temperature
            temperature.textContent = Math.round(currentData.main.temp) + '°C';

            // Update weather description
            weatherDescription.textContent = currentData.weather[0].description;

            // Update icon
            const iconCode = currentData.weather[0].icon;
            icon.src = `https://openweathermap.org/img/wn/${iconCode}@2x.png`;

            // Update additional info
            feelsLike.textContent = Math.round(currentData.main.feels_like) + '°C';
            minMaxTemp.textContent = 
                Math.round(currentData.main.temp_min) + ' / ' + 
                Math.round(currentData.main.temp_max) + '°C';
            humidity.textContent = currentData.main.humidity + '%';
            windSpeed.textContent = currentData.wind.speed + ' m/s';
            pressure.textContent = currentData.main.pressure + ' hPa';

            // Show weather card
            weatherCard.style.display = 'block';

            // Display forecast
            displayForecast(forecastData);
        }

        // Function to display forecast data
        function displayForecast(forecastData) {
            // Clear previous forecast cards
            forecastCards.innerHTML = '';

            // Get unique forecast dates (only one forecast per day)
            const dailyForecasts = [];
            const dates = new Set();

            forecastData.list.forEach(item => {
                const date = new Date(item.dt * 1000).toISOString().split('T')[0];

                // Only take one forecast per day (preferably at noon)
                if (!dates.has(date)) {
                    dates.add(date);
                    dailyForecasts.push(item);
                }
            });

            // Create forecast cards for the next 5 days
            dailyForecasts.slice(0, 5).forEach(item => {
                const date = new Date(item.dt * 1000);
                const options = { weekday: 'short' };
                const dayName = date.toLocaleDateString(undefined, options);

                const card = document.createElement('div');
                card.className = 'forecast-card';

                card.innerHTML = `
                    <div class="forecast-date">${dayName}</div>
                    <img class="forecast-icon" src="https://openweathermap.org/img/wn/${item.weather[0].icon}@2x.png" alt="${item.weather[0].description}">
                    <div class="forecast-temp">${Math.round(item.main.temp)}°C</div>
                `;

                forecastCards.appendChild(card);
            });

            // Show forecast container
            forecastContainer.style.display = 'block';
        }

        // Function to show error message
        function showError(message) {
            errorMessage.textContent = message;
            errorMessage.style.display = 'block';
        }

        // Initialize the app
        window.addEventListener('load', () => {
            // Set default city to London on load
            cityInput.placeholder = 'Enter a city name (e.g., London)';

            // Set a brief delay to show a welcome message
            setTimeout(() => {
                const defaultCity = 'London';
                cityInput.value = defaultCity;
                getWeather();
            }, 500);
        });
    </script>
</body>
