    const container = document.getElementById('gameArea');
    const button = document.getElementById('button');
    const scoreDisplay = document.getElementById('score');

    const gameSize = 600;
    const buttonSize = 50;
    const buttonHalf = buttonSize / 2;
    const escapeThreshold = 80; // 鼠标与按钮距离小于80像素时触发逃走

    let score = 0;
    let isEscaping = false; // 是否正在逃走
    let buttonX = gameSize / 2;
    let buttonY = gameSize / 2;

    // 设置初始按钮位置（中心）
    function resetButton() {
      buttonX = gameSize / 2;
      buttonY = gameSize / 2;
      button.style.left = buttonX + 'px';
      button.style.top = buttonY + 'px';
      isEscaping = false;
    }

    // 生成一个安全的新位置（不与鼠标位置太近，且在边界内）
    function generateSafePosition(mouseX, mouseY) {
      let attempts = 0;
      const maxAttempts = 100;

      while (attempts < maxAttempts) {
        const x = Math.random() * (gameSize - buttonSize) + buttonHalf;
        const y = Math.random() * (gameSize - buttonSize) + buttonHalf;

        // 检查是否离鼠标太近（避免重叠或过于靠近）
        const dx = x - mouseX;
        const dy = y - mouseY;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance > escapeThreshold) {
          return { x, y };
        }

        attempts++;
      }

      // 安全兜底（如果一直失败，直接放到角落）
      return { x: buttonHalf + 10, y: buttonHalf + 10 };
    }

    // 鼠标移动事件 —— 检测是否快碰到按钮
    container.addEventListener('mousemove', (e) => {
      const rect = container.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      if (isEscaping) return; // 不处理逃走过程的移动

      const dx = buttonX - mouseX;
      const dy = buttonY - mouseY;
      const distance = Math.sqrt(dx * dx + dy * dy);

      // 如果鼠标太靠近按钮（触发逃走）
      if (distance < escapeThreshold) {
        const newPos = generateSafePosition(mouseX, mouseY);
        buttonX = newPos.x;
        buttonY = newPos.y;
        button.style.left = buttonX + 'px';
        button.style.top = buttonY + 'px';
        isEscaping = true; // 标记逃走完成，等待点击
      }
    });

    // 点击按钮事件
    button.addEventListener('click', () => {
      if (isEscaping) {
        // 成功点击，加分并复位
        score++;
        scoreDisplay.textContent = score;
        resetButton();
      }
    });

    // 初始化
    resetButton();
  </script>
</body>
</html>
```

