import { getSortedPostsData } from '@/lib/blogUtils';
import PostCard from '@/components/PostCard';
import SearchBar from '@/components/SearchBar';
import { useState } from 'react';
import { getPostBySlug } from '@/lib/blogUtils';

export default function BlogPage() {
  const allPosts = getSortedPostsData();
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredPosts, setFilteredPosts] = useState(allPosts);

  const handleSearch = (term: string) => {
    setSearchTerm(term);
    if (term === '') {
      setFilteredPosts(allPosts);
    } else {
      const filtered = allPosts.filter(post => 
        post.title.toLowerCase().includes(term.toLowerCase()) ||
        post.excerpt.toLowerCase().includes(term.toLowerCase()) ||
        post.tags.some(tag => tag.toLowerCase().includes(term.toLowerCase()))
      );
      setFilteredPosts(filtered);
    }
  };

  return (
    <div className="max-w-6xl mx-auto">
      <h1 className="text-3xl font-bold text-center mb-8 pt-6">Blog Posts</h1>

      <div className="mb-8">
        <SearchBar onSearch={handleSearch} />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredPosts.map(post => (
          <PostCard key={post.id} post={post} />
        ))}
      </div>

      {filteredPosts.length === 0 && (
        <div className="text-center mt-12 text-gray-500">
          <p>No posts found for "{searchTerm}".</p>
        </div>
      )}
    </div>
  );
}
