        // Add event listener for input changes (to recalculate while typing)
        [costInput, markupPercentInput, profitGoalInput].forEach(input => {
            input.addEventListener('input', function() {
                // Only calculate if all fields have values
                if (this.value && 
                    costInput.value && 
                    markupPercentInput.value && 
                    profitGoalInput.value) {
                    calculate();
                }
            });
        });

        // Initialize with default values
        calculate();
    </script>
</body>
</html>
