function deleteQuestion(questionUrl) {
    if (!questionUrl) {
        alert("URL invalide.");
        return;
    }

    fetch(questionUrl, {
        method: "DELETE",
        headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json'
        }
    })
    .then(res => {
        if (res.ok) {
            alert("Question supprimée !");
            refreshQuestionnaireList(); // ou rafraîchir juste les questions
        } else {
            alert("Erreur de suppression.");
            console.log(res);
        }
    })
    .catch(err => {
        alert("Erreur réseau : " + err.message);
        console.error(err);
    });
}
