## 🧩 需要配合后台脚本（background.js）实现自动读取文件

> 将下面的代码加入你的 `background.js`（或 `service-worker.js`）中：

```js
// background.js

let currentFileIndex = 1;
const JSON_FOLDER_ID = 'json-folder'; // 你可以用一个固定ID来代表文件夹，或通过用户选择文件夹后保留

// 监听来自 content script 的消息
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
    if (request.action === "autoImportNextJson") {
        // 临时存储当前索引（建议持久化）
        const storageKey = 'autoImportNextFileIndex';
        chrome.storage.local.get([storageKey], (result) => {
            currentFileIndex = result[storageKey] || 1;

            const fileName = `${currentFileIndex}.json`;

            // 用 chrome.fileSystem 打开文件夹（必须是用户授权过的）
            chrome.fileSystem.chooseEntry({ type: 'openDirectory' }, (directoryEntry) => {
                if (chrome.runtime.lastError) {
                    console.error('File system access denied:', chrome.runtime.lastError);
                    sendResponse({ status: 'error', message: 'File system access denied' });
                    return;
                }

                // 保存目录信息以便下次复用
                chrome.storage.local.set({ jsonFolderEntry: directoryEntry.toURL() });

                // 读取文件
                directoryEntry.getDirectory(fileName, { create: false }, (fileEntry) => {
                    if (chrome.runtime.lastError) {
                        // 文件不存在，尝试下一个编号
                        const nextIndex = currentFileIndex + 1;
                        if (nextIndex > 100) {
                            // 安全上限，防止无限循环
                            sendResponse({ status: 'completed', message: 'No more files found', fileName: null });
                        } else {
                            // 更新索引并重试
                            chrome.storage.local.set({ [storageKey]: nextIndex }, () => {
                                currentFileIndex = nextIndex;
                                sendResponse({ status: 'next', fileName: `${nextIndex}.json` });
                            });
                        }
                        return;
                    }

                    // 读取文件内容
                    fileEntry.file((file) => {
                        const reader = new FileReader();
                        reader.onload = (e) => {
                            const content = e.target.result;
                            let cookies;

                            try {
                                cookies = JSON.parse(content);
                                if (!Array.isArray(cookies)) {
                                    throw new Error('Not an array');
                                }
                            } catch (err) {
                                sendResponse({ status: 'error', message: `Invalid JSON in ${fileName}: ${err.message}` });
                                return;
                            }

                            // 保存到当前 tab 的 cookie store
                            const currentTabUrl = getCurrentTabUrl(); // 你需实现这个函数
                            const storeId = cookieHandler.currentTab.cookieStoreId;

                            let importSuccessCount = 0;
                            let importErrors = [];

                            cookies.forEach((cookie) => {
                                cookie.storeId = storeId;
                                if (cookie.sameSite && cookie.sameSite === 'unspecified') {
                                    cookie.sameSite = null;
                                }

                                try {
                                    cookieHandler.saveCookie(cookie, currentTabUrl, (error, savedCookie) => {
                                        if (error) {
                                            importErrors.push(error);
                                        } else {
                                            importSuccessCount++;
                                        }
                                    });
                                } catch (e) {
                                    importErrors.push(e.message);
                                }
                            });

                            const total = cookies.length;
                            const msg = `Imported ${importSuccessCount}/${total} cookies from ${fileName}`;
                            sendResponse({ status: 'success', fileName, message: msg, success: importSuccessCount, errors: importErrors });

                            // 更新当前索引为下一个
                            const nextIndex = currentFileIndex + 1;
                            chrome.storage.local.set({ [storageKey]: nextIndex });
                        };

                        reader.onerror = () => {
                            sendResponse({ status: 'error', message: `Failed to read file ${fileName}` });
                        };

                        reader.readAsText(file);
                    });
                }, (err) => {
                    if (err.name === 'NotFoundError') {
                        // 文件不存在，尝试下一个
                        const nextIndex = currentFileIndex + 1;
                        if (nextIndex > 100) {
                            sendResponse({ status: 'completed', message: 'All files processed', fileName: null });
                        } else {
                            chrome.storage.local.set({ [storageKey]: nextIndex }, () => {
                                currentFileIndex = nextIndex;
                                sendResponse({ status: 'next', fileName: `${nextIndex}.json` });
                            });
                        }
                    } else {
                        sendResponse({ status: 'error', message: `Error accessing file: ${err.message}` });
                    }
                });
            });
        });

        // 返回 true 表示异步响应
        return true;
    }
});
```

