## 15. `public/script.js`

```javascript
document.addEventListener('DOMContentLoaded', () => {
  const loginBtn = document.getElementById('loginBtn');
  const logoutBtn = document.getElementById('logoutBtn');
  const userDisplay = document.getElementById('userDisplay');
  const foodGrid = document.getElementById('foodGrid');

  // Check if user is logged in
  const checkAuth = async () => {
    try {
      const res = await fetch('/api/auth/user', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (res.ok) {
        const user = await res.json();
        showUser(user);
        loadFoods();
      } else {
        clearAuth();
      }
    } catch (err) {
      console.error('Auth check failed:', err);
      clearAuth();
    }
  };

  const showUser = (user) => {
    userDisplay.innerHTML = `
      <img src="${user.image}" alt="${user.name}" width="40" height="40" style="border-radius: 50%; margin-right: 0.5rem;">
      ${user.name}
    `;
    loginBtn.style.display = 'none';
    logoutBtn.style.display = 'inline-block';
  };

  const clearAuth = () => {
    userDisplay.innerHTML = '';
    loginBtn.style.display = 'inline-block';
    logoutBtn.style.display = 'none';
    localStorage.removeItem('token');
  };

  const loginWithGoogle = () => {
    window.location.href = '/api/auth/google';
  };

  const logout = async () => {
    try {
      // Clear local storage
      localStorage.removeItem('token');
      // Redirect to home
      window.location.href = '/';
    } catch (err) {
      console.error('Logout failed:', err);
    }
  };

  const loadFoods = async () => {
    try {
      const res = await fetch('/api/food/foods');
      const foods = await res.json();

      foodGrid.innerHTML = '';

      foods.forEach(food => {
        const foodCard = document.createElement('div');
        foodCard.className = 'food-card';
        foodCard.innerHTML = `
          <img src="${food.image}" alt="${food.name}" class="food-img">
          <div class="food-info">
            <h3>${food.name}</h3>
            <p>${food.description}</p>
            <div class="price">$${food.price.toFixed(2)}</div>
            <button class="btn-order" data-id="${food._id}">Order Now</button>
          </div>
        `;
        foodGrid.appendChild(foodCard);
      });

      // Add event listeners to order buttons
      document.querySelectorAll('.btn-order').forEach(btn => {
        btn.addEventListener('click', (e) => {
          const foodId = e.target.getAttribute('data-id');
          alert(`You ordered: Food ID ${foodId}`);
          // In real app, would add to cart and order
        });
      });

    } catch (err) {
      console.error('Failed to load foods:', err);
      foodGrid.innerHTML = '<p>Failed to load food items. Please try again later.</p>';
    }
  };

  // Event listeners
  loginBtn.addEventListener('click', loginWithGoogle);
  logoutBtn.addEventListener('click', logout);

  // Check authentication on load
  checkAuth();
});
```

