# Snake Game in HTML, CSS, and JavaScript

Here's a basic Snake game implemented with HTML, CSS, and JavaScript. This is a complete, self-contained version you can run in any modern browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Snake Game</title>
    <style>
        body {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            background-color: #f0f0f0;
            font-family: Arial, sans-serif;
        }

        #game-container {
            position: relative;
            width: 400px;
            height: 400px;
            border: 2px solid #333;
            background-color: #111;
        }

        #game-canvas {
            display: block;
            background-color: #000;
        }

        #score-display {
            margin-top: 20px;
            font-size: 24px;
            color: #333;
        }

        #start-button {
            margin-top: 10px;
            padding: 10px 20px;
            font-size: 18px;
            background-color: #4CAF50;
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
        }

        #start-button:hover {
            background-color: #45a049;
        }

        #game-over {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background-color: rgba(0, 0, 0, 0.8);
            color: white;
            padding: 20px;
            border-radius: 10px;
            text-align: center;
            display: none;
        }
    </style>
</head>
<body>
    <h1>Snake Game</h1>
    <div id="game-container">
        <canvas id="game-canvas" width="400" height="400"></canvas>
        <div id="game-over">
            <h2>Game Over!</h2>
            <p>Your score: <span id="final-score">0</span></p>
            <button id="restart-button">Play Again</button>
        </div>
    </div>
    <div id="score-display">Score: 0</div>
    <button id="start-button">Start Game</button>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            // Get elements
            const canvas = document.getElementById('game-canvas');
            const ctx = canvas.getContext('2d');
            const startButton = document.getElementById('start-button');
            const restartButton = document.getElementById('restart-button');
            const scoreDisplay = document.getElementById('score-display');
            const gameOverDiv = document.getElementById('game-over');
            const finalScoreSpan = document.getElementById('final-score');

            // Game constants
            const GRID_SIZE = 20;
            const GRID_WIDTH = canvas.width / GRID_SIZE;
            const GRID_HEIGHT = canvas.height / GRID_SIZE;

            // Game variables
            let snake, food, score, gameInterval, direction, nextDirection, gameRunning;

            // Initialize game
            function initGame() {
                // Snake starts in the middle of the canvas
                snake = [
                    {x: Math.floor(GRID_WIDTH / 2), y: Math.floor(GRID_HEIGHT / 2)}
                ];

                // Generate first food
                generateFood();

                // Reset score
                score = 0;
                scoreDisplay.textContent = `Score: ${score}`;

                // Reset direction
                direction = 'right';
                nextDirection = 'right';

                // Game is not running yet
                gameRunning = false;

                // Hide game over screen
                gameOverDiv.style.display = 'none';

                // Draw initial state
                draw();
            }

            // Generate food at random position
            function generateFood() {
                // Generate random position
                let x, y;
                do {
                    x = Math.floor(Math.random() * GRID_WIDTH);
                    y = Math.floor(Math.random() * GRID_HEIGHT);
                } while (snake.some(segment => segment.x === x && segment.y === y));

                food = {x, y};
            }

            // Draw everything on the canvas
            function draw() {
                // Clear canvas
                ctx.fillStyle = 'black';
                ctx.fillRect(0, 0, canvas.width, canvas.height);

                // Draw snake
                snake.forEach((segment, index) => {
                    // Head is a different color
                    if (index === 0) {
                        ctx.fillStyle = '#00ff00';
                    } else {
                        ctx.fillStyle = '#00cc00';
                    }
                    ctx.fillRect(segment.x * GRID_SIZE, segment.y * GRID_SIZE, GRID_SIZE, GRID_SIZE);

                    // Add a border to each segment
                    ctx.strokeStyle = '#003300';
                    ctx.lineWidth = 1;
                    ctx.strokeRect(segment.x * GRID_SIZE, segment.y * GRID_SIZE, GRID_SIZE, GRID_SIZE);
                });

                // Draw food
                ctx.fillStyle = 'red';
                ctx.fillRect(food.x * GRID_SIZE, food.y * GRID_SIZE, GRID_SIZE, GRID_SIZE);

                // Add a border to food
                ctx.strokeStyle = '#800000';
                ctx.lineWidth = 1;
                ctx.strokeRect(food.x * GRID_SIZE, food.y * GRID_SIZE, GRID_SIZE, GRID_SIZE);
            }

            // Update game state
            function update() {
                // Update direction
                direction = nextDirection;

                // Get current head position
                const head = {...snake[0]};

                // Move head based on direction
                switch (direction) {
                    case 'up':
                        head.y--;
                        break;
                    case 'down':
                        head.y++;
                        break;
                    case 'left':
                        head.x--;
                        break;
                    case 'right':
                        head.x++;
                        break;
                }

                // Check for collisions
                // Wall collision
                if (head.x < 0 || head.x >= GRID_WIDTH || head.y < 0 || head.y >= GRID_HEIGHT) {
                    gameOver();
                    return;
                }

                // Self collision (check if snake hits itself)
                if (snake.some(segment => segment.x === head.x && segment.y === head.y)) {
                    gameOver();
                    return;
                }

                // Add new head
                snake.unshift(head);

                // Check if snake ate food
                if (head.x === food.x && head.y === food.y) {
                    // Increase score
                    score++;
                    scoreDisplay.textContent = `Score: ${score}`;

                    // Generate new food
                    generateFood();
                } else {
                    // Remove tail
                    snake.pop();
                }

                // Redraw
                draw();
            }

            // Game over function
            function gameOver() {
                clearInterval(gameInterval);
                gameRunning = false;
                finalScoreSpan.textContent = score;
                gameOverDiv.style.display = 'block';
            }

            // Start game function
            function startGame() {
                if (gameRunning) return;

                startButton.disabled = true;
                gameRunning = true;

                // Reset game interval if it exists
                if (gameInterval) {
                    clearInterval(gameInterval);
                }

                // Start game loop
                gameInterval = setInterval(update, 150);
            }

            // Event listeners
            startButton.addEventListener('click', startGame);

            restartButton.addEventListener('click', () => {
                initGame();
                startGame();
            });

            // Keyboard controls
            document.addEventListener('keydown', (e) => {
                // Prevent default behavior for arrow keys
                if ([37, 38, 39, 40, 32].includes(e.keyCode)) {
                    e.preventDefault();
                }

                switch (e.keyCode) {
                    case 37: // Left arrow
                        if (direction !== 'right') {
