// Inside your <script> tag

// Step 1: Your API key (Replace with your actual key!)
const apiKey = "abc123def456ghi789"; // 🔒 Replace this with YOUR API key

// Step 2: The city we want weather for
const city = "London";

// Step 3: The API URL (includes city and your key)
const apiUrl = `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}&units=metric`;

// Step 4: The function to fetch & display weather data
async function getWeather() {
  const cityEl = document.getElementById("city");
  const tempEl = document.getElementById("temp");
  const descEl = document.getElementById("desc");
  const iconEl = document.getElementById("icon");

  // Show "Loading..." while we wait
  cityEl.textContent = "Loading...";
  tempEl.textContent = "--°C";
  descEl.textContent = "--";
  iconEl.src = "";

  try {
    // Use fetch() to get data from the API
    const response = await fetch(apiUrl);

    // Check if the response is OK (status code 200-299)
    if (!response.ok) {
      throw new Error(`Error: ${response.status}`);
    }

    // Parse the JSON data
    const data = await response.json();

    // Now, update the webpage with real data
    cityEl.textContent = data.name;
    tempEl.textContent = `${data.main.temp}°C`;
    descEl.textContent = data.weather[0].description;

    // Set the weather icon
    const iconCode = data.weather[0].icon;
    iconEl.src = `https://openweathermap.org/img/wn/${iconCode}@2x.png`;

    // Optional: Add a success message
    console.log("Weather data loaded successfully!");
  } catch (error) {
    // If something goes wrong (network error, invalid city, etc.)
    cityEl.textContent = "Oops! Could not load weather.";
    cityEl.className = "error";
    console.error("Error fetching weather:", error);
  }
}

// Step 5: Run the function when the page loads
window.onload = getWeather;
```

