    const startBtn = document.getElementById('startBtn');

    let score = 0;
    let timeLeft = 30;
    let timer;
    let gameActive = false;

    // وضع الدائرة في مكان عشوائي
    function randomPosition() {
      const gameRect = game.getBoundingClientRect();
      const targetRect = target.getBoundingClientRect();

      // التأكد من أن الدائرة لا تخرج من الشاشة
      const maxX = gameRect.width - targetRect.width;
      const maxY = gameRect.height - targetRect.height;

      const randomX = Math.floor(Math.random() * maxX);
      const randomY = Math.floor(Math.random() * maxY);

      target.style.left = randomX + 'px';
      target.style.top = randomY + 'px';
    }

    // بداية اللعبة
    function startGame() {
      if (gameActive) return;
      gameActive = true;
      score = 0;
      timeLeft = 30;

      scoreDisplay.textContent = `النتيجة: ${score}`;
      timeDisplay.textContent = `الوقت: ${timeLeft} ثانية`;

      startBtn.disabled = true;
      startBtn.textContent = "جاري اللعبة...";

      // عرض الهدف أولًا
      randomPosition();

      // تفعيل الحدث عند النقر
      target.addEventListener('click', hitTarget);

      // بدء التوقيت
      timer = setInterval(() => {
        timeLeft--;
        timeDisplay.textContent = `الوقت: ${timeLeft} ثانية`;

        if (timeLeft <= 0) {
          endGame();
        }
      }, 1000);
    }

    // ارتكاب النقر على الدائرة
    function hitTarget() {
      score++;
      scoreDisplay.textContent = `النتيجة: ${score}`;
      randomPosition(); // نقل الهدف إلى مكان جديد
    }

    // إنهاء اللعبة
    function endGame() {
      gameActive = false;
      clearInterval(timer);
      target.removeEventListener('click', hitTarget);
      startBtn.disabled = false;
      startBtn.textContent = "إعادة اللعبة";

      // تنبيه
      alert(`اللعبة انتهت! نتيجتك: ${score}`);
    }

    // زر البدء
    startBtn.addEventListener('click', startGame);
  </script>
</body>
</html>
