document.addEventListener("DOMContentLoaded", () => {
  const searchInput = document.getElementById("searchInput");
  const searchButton = document.getElementById("searchButton");
  const resultsDiv = document.getElementById("results");

  // Função para simular busca (exemplo de dados)
  const simulateSearch = (query) => {
    const lowerQuery = query.toLowerCase().trim();

    if (!lowerQuery) {
      resultsDiv.innerHTML = "<p>Insira um termo para buscar.</p>";
      return;
    }

    // Simulando resultados (pode ser substituído por API)
    const mockResults = [
      "Resultado 1: Informações sobre " + query,
      "Resultado 2: Tópicos relacionados a " + query,
      "Resultado 3: Dicas para trabalhar com " + query,
      "Resultado 4: Artigos sobre " + query + " no mundo moderno"
    ];

    // Filtrar apenas os que contêm a query
    const filteredResults = mockResults.filter(item =>
      item.toLowerCase().includes(lowerQuery)
    );

    if (filteredResults.length === 0) {
      resultsDiv.innerHTML = `<p>Nenhum resultado encontrado para "${query}".</p>`;
    } else {
      resultsDiv.innerHTML = filteredResults
        .map(result => `<p>${result}</p>`)
        .join('');
    }
  };

  // Evento de clique no botão
  searchButton.addEventListener("click", () => {
    const query = searchInput.value;
    simulateSearch(query);
  });

  // Evento de tecla Enter no input
  searchInput.addEventListener("keypress", (e) => {
    if (e.key === "Enter") {
      const query = searchInput.value;
      simulateSearch(query);
    }
  });

  // Limpa resultados ao digitar (opcional)
  searchInput.addEventListener("input", () => {
    if (searchInput.value.trim() === "") {
      resultsDiv.innerHTML = "";
    }
  });
});
```

