```js
import { fromEvent, of } from 'rxjs';
import { switchMap, map, catchError } from 'rxjs/operators';
import { ajax } from 'rxjs/ajax';

// Получаем DOM-элементы
const showBtn = document.getElementById('showBtn');
const deleteBtn = document.getElementById('deleteBtn');
const dataContainer = document.getElementById('dataContainer');

// Создаём Observable на основе нажатия кнопки "Показать данные"
const showData$ = fromEvent(showBtn, 'click').pipe(
  switchMap(() => {
    // Загружаем JSON с сервера
    return ajax.getJSON('./data.json').pipe(
      map(data => {
        // Сохраняем данные в localStorage (опционально, для персистентности)
        localStorage.setItem('appData', JSON.stringify(data));
        return data;
      }),
      catchError(err => {
        console.error('Ошибка при загрузке данных:', err);
        alert('Не удалось загрузить данные.');
        return of([]); // возвращаем пустой массив в случае ошибки
      })
    );
  })
);

// Создаём Observable для кнопки "Удалить"
const deleteRow$ = fromEvent(deleteBtn, 'click').pipe(
  map(() => {
    // Находим все строки с данными
    const rows = dataContainer.querySelectorAll('.data-row');
    if (rows.length > 0) {
      // Удаляем последнюю строку
      rows[rows.length - 1].remove();
    } else {
      alert('Нечего удалять!');
    }
  })
);

// Подписываемся на оба потока
showData$.subscribe(data => {
  // Очищаем контейнер
  dataContainer.innerHTML = '';

  // Выводим данные
  data.forEach(item => {
    const row = document.createElement('div');
    row.className = 'data-row';
    row.innerHTML = `<strong>ID:</strong> ${item.id} | <strong>Имя:</strong> ${item.name} | <strong>Город:</strong> ${item.city}`;
    dataContainer.appendChild(row);
  });

  console.log('Данные загружены:', data);
});

deleteRow$.subscribe();

// Важно: в версиях RxJS 7.8+ `ajax.getJSON` доступна через `rxjs/ajax`
```

