const WebSocket = require('ws');
const http = require('http');
const path = require('path');

// Create HTTP server (for any static files if needed later)
const server = http.createServer();

// Initialize WebSocket server on the HTTP server
const wss = new WebSocket.Server({ server });

// Keep track of connected clients
const clients = new Map();

// Utility: broadcast message to all clients
function broadcast(message, isBinary = false) {
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      if (isBinary) {
        client.send(message, { binary: true });
      } else {
        client.send(message);
      }
    }
  });
}

// Handle new connection
wss.on('connection', (ws, req) => {
  const clientId = Date.now() + Math.random().toString(36).substr(2, 5);
  clients.set(clientId, ws);

  console.log(`New connection: ${clientId}`);

  // Send welcome
  ws.send(JSON.stringify({
    type: 'system',
    message: 'Connected to chat server',
    timestamp: new Date().toLocaleString()
  }));

  // Handle incoming messages
  ws.on('message', (data, isBinary) => {
    try {
      if (isBinary) {
        // It’s a file
        const buffer = Buffer.from(data);

        // Parse filename from header (simple: assume metadata in first 256 bytes as JSON)
        const headerLength = Math.min(256, buffer.length);
        const header = buffer.subarray(0, headerLength).toString('utf8');

        let metadata;
        try {
          metadata = JSON.parse(header);
        } catch (e) {
          console.warn('Invalid file header:', e);
          return;
        }

        const { filename, fileType } = metadata;

        // Broadcast the file (with metadata)
        const fileData = buffer.subarray(headerLength);
        const base64Data = fileData.toString('base64');

        broadcast(JSON.stringify({
          type: 'file',
          from: clientId,
          filename,
          fileType,
          data: base64Data,
          timestamp: new Date().toLocaleString()
        }));

        console.log(`Received file: ${filename} (${fileType}) from ${clientId}`);
      } else {
        // It's text
        const str = data.toString();

        // Parse text as JSON if needed
        let parsed;
        try {
          parsed = JSON.parse(str);
          if (parsed.type === 'ping') {
            ws.send(JSON.stringify({ type: 'pong', timestamp: new Date().toISOString() }));
            return;
          }
        } catch (e) {
          // Not JSON, treat as text
        }

        // Broadcast
        const message = `[${new Date().toLocaleString()}] ${str}`;
        broadcast(message);
        console.log(message);
      }
    } catch (err) {
      console.error('Error processing message:', err);
      ws.send(JSON.stringify({ type: 'error', message: 'Failed to process message' }));
    }
  });

  // Handle errors
  ws.on('error', (err) => {
    console.error('WebSocket error:', err);
  });

  // Handle close
  ws.on('close', () => {
    clients.delete(clientId);
    console.log(`Client disconnected: ${clientId}`);
  });
});

// Start server
const PORT = 3000;
server.listen(PORT, '172.16.10.34', () => {
  console.log(`WebSocket server running on ws://172.16.10.34:${PORT}`);
});
```

