  <title>WebSocket Chat (Modern & Secure)</title>
  <script src="https://cdn.jsdelivr.net/npm/axios/dist/axios.min.js"></script>
  <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
  <style>
    body {
      font-family: Arial, sans-serif;
      background-color: #d3d3d3;
      padding: 20px;
    }

    #register, #main, #file {
      margin: 10px auto;
      width: 300px;
      text-align: center;
    }

    #main {
      display: none;
      border: 1px solid #ccc;
      padding: 15px;
      border-radius: 8px;
      background-color: #fff;
    }

    textarea, input[type="text"], button {
      margin: 5px;
      padding: 8px;
    }

    #responseText {
      width: 100%;
      height: 200px;
      border: 1px solid #aaa;
      border-radius: 4px;
      font-family: monospace;
    }

    .file-preview {
      margin: 10px 0;
    }

    .file-preview img {
      max-width: 200px;
