      border-radius: 4px;
    }
  </style>
</head>
<body>

  <!-- Registration Form -->
  <div id="register">
    <input id="name" type="text" placeholder="请输入你的名字" />
    <button id="login" style="height: 30px" onclick="connect()">连接服务器</button>
  </div>

  <!-- Chat Main UI -->
  <div id="main">
    <form onsubmit="return false;">
      <p>
        <span id="nameData">当前用户：</span>
        <button id="close" style="height: 25px; display:none" onclick="disconnect()">断开连接</button>
      </p>
      <textarea id="responseText" readonly></textarea>
      <br>
      <input type="text" id="messageInput" placeholder="输入消息..." style="width: 300px" />
      <button type="button" onclick="sendMessage()">发送消息</button>
      <button type="button" onclick="clearChat()">清空聊天记录</button>
    </form>
    <br>

    <!-- File Upload -->
    <div id="file">
      <input type="file" id="fileInput" />
      <button type="button" onclick="sendFile()">发送文件</button>
    </div>
  </div>

  <script>
    let socket;
    let name;
    let ip = "未知地区";

    // Get public IP
    async function getPublicIp() {
      try {
        const res = await axios.get('https://api.ipify.org?format=json');
        ip = res.data.ip;
        console.log('Your public IP:', ip);
      } catch (err) {
        console.warn('Could not get IP:', err);
      }
    }

    // Connect to server
    function connect() {
      name = $('#name').val().trim();
      if (!name) return alert("请输入名字！");

      $('#name').prop('readonly', true);
      $('#login').hide();
      $('#main').show();

      // Get IP before connecting
      getPublicIp().then(() => {
        // Initialize WebSocket
        socket = new WebSocket("ws://38.46.30.148:3000");

        socket.onopen = () => {
          $('#responseText').val('✅ 连接成功！\n');
        };

        socket.onmessage = (event) => {
          const data = event.data;
          let msg;

          try {
            const parsed = JSON.parse(data);
            if (parsed.type === 'system') {
              msg = parsed.message;
            } else if (parsed.type === 'file') {
              const { filename, fileType, data: base64Data, timestamp } = parsed;
              msg = `[文件] ${filename} (${fileType}) at ${timestamp}`;
              const img = new Image();
              img.src = `data:${fileType};base64,${base64Data}`;
              img.style.maxWidth = '200px';
              img.style.border = '1px solid #ddd';
              img.style.margin = '5px';
              document.body.appendChild(img);
              // Optional: store in UI
              $('#responseText').val($('#responseText').val() + '\n' + msg);
            } else {
              msg = data;
            }
          } catch (e) {
            if (typeof data === 'string') {
              msg = data;
            } else {
              msg = String(data);
            }
          }

          $('#responseText').val($('#responseText').val() + '\n' + msg);
        };

        socket.onclose = () => {
          $('#responseText').val($('#responseText').val() + '\n⛔ 连接已关闭\n');
        };

        socket.onerror = (err) => {
          console.error('WebSocket Error:', err);
          $('#responseText').val($('#responseText').val() + '\n❌ WebSocket 错误\n');
        };
      });
    }

    // Send text message
    function sendMessage() {
      const msg = $('#messageInput').val().trim();
      if (!msg) return;

      const text = `from ${ip} 的 ${name}：${msg}`;
      socket.send(text);
      $('#messageInput').val('');
    }

    // Clear chat history
    function clearChat() {
      $('#responseText').val('');
    }

    // Send file
    function sendFile() {
      const fileInput = $('#fileInput')[0];
      const file = fileInput.files[0];
      if (!file) return alert("请选择文件");

      const reader = new FileReader();
      reader.onload = function (e) {
        const arrayBuffer = e.target.result;

        // Create header with metadata
        const metadata = JSON.stringify({
          filename: file.name,
          fileType: file.type || 'application/octet-stream'
        });

        // Append metadata + actual file data
        const header = new TextEncoder().encode(metadata);
        const combined = new Uint8Array(header.length + arrayBuffer.byteLength);
        combined.set(header, 0);
        combined.set(new Uint8Array(arrayBuffer), header.length);

        // Send whole blob as binary
        if (socket.readyState === WebSocket.OPEN) {
          socket.send(combined);
        } else {
          alert("连接未开启！");
        }
      };

      reader.readAsArrayBuffer(file);
    }

    // Disconnect
    function disconnect() {
      if (socket) {
        socket.close();
      }
      $('#main').hide();
      $('#name').prop('readonly', false);
      $('#login').show();
      $('#close').hide();
      $('#nameData').text('当前用户：');
      $('#fileInput').val('');
    }

    // Add Enter key support
    $('#messageInput').on('keypress', function (e) {
      if (e.which === 13 && !e.shiftKey) {
        e.preventDefault();
        sendMessage();
      }
    });
  </script>

</body>
</html>
```

