         console.error('Database error:', err);
         return res.status(500).send('Registration failed');
       }
       res.send('success');
     });
   });
   ```

2. **Hash passwords (e.g., with bcrypt)** before storing them!
   - Never store plain-text passwords.

   Example:
   ```js
   const bcrypt = require('bcrypt');
   const saltRounds = 10;

