document.addEventListener("DOMContentLoaded", () => {
  const form = document.getElementById("quizForm");
  const resultsDiv = document.getElementById("results");
  const quizOutput = document.getElementById("quizOutput");
  const charCount = document.getElementById("charCount");
  const regenerateBtn = document.getElementById("regenerate");

  // Character counter
  const contextTextarea = document.getElementById("context");
  contextTextarea.addEventListener("input", () => {
    const count = contextTextarea.value.length;
    charCount.textContent = `${count}/500`;
    if (count > 500) {
      charCount.style.color = "red";
    } else {
      charCount.style.color = "#999";
    }
  });

  // Handle form submission
  form.addEventListener("submit", async (e) => {
    e.preventDefault();

    const formData = new FormData(form);
    const data = Object.fromEntries(formData.entries());

    try {
      // Show loading
      quizOutput.textContent = "Generating quiz... Please wait.";
      resultsDiv.style.display = "block";

      const response = await fetch("/generate-quiz", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.message || "Error generating quiz");
      }

      // Display quiz
      quizOutput.innerHTML = formatQuiz(result.data);
    } catch (err) {
      quizOutput.innerHTML = `<p style="color: red;">Error: ${err.message}</p>`;
    }
  });

  // Regenerate quiz
  regenerateBtn.addEventListener("click", () => {
    form.reset();
    charCount.textContent = "0/500";
    quizOutput.innerHTML = "";
  });

  function formatQuiz(quizText) {
    return `<pre style="white-space: pre-wrap; font-family: monospace; background: #f8f9fa; padding: 15px; border-radius: 6px; border: 1px solid #ccc; font-size: 15px;">${quizText}</pre>`;
  }
});
