const express = require("express");
const cors = require("cors");
const dotenv = require("dotenv");
const OpenAI = require("openai");

dotenv.config();

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(express.json({ limit: "10mb" })); // Allow large payloads
app.use(express.static("public"));

// Initialize OpenAI
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
});

// Validate input
function isValidInput(data) {
  const { board, questionType, difficulty, numQuestions, context } = data;

  if (!board || !questionType || !difficulty || !numQuestions || !context) {
    return { valid: false, error: "All fields are required." };
  }

  const num = parseInt(numQuestions);
  if (isNaN(num) || num < 1 || num > 50) {
    return { valid: false, error: "Number of questions must be between 1 and 50." };
  }

  if (context.length > 500) {
    return { valid: false, error: "Context must be 500 characters or less." };
  }

  return { valid: true };
}

// POST /generate-quiz
app.post("/generate-quiz", async (req, res) => {
  const { board, questionType, difficulty, numQuestions, context } = req.body;

  // Validate input
  const validation = isValidInput(req.body);
  if (!validation.valid) {
    return res.status(400).json({ error: validation.error });
  }

  const num = parseInt(numQuestions);

  // Build prompt
  const prompt = `
You are a radiology education expert. Generate ${num} ${difficultiesToWord(difficulty)} ${questionTypeToWord(questionType)} questions based on the ${board} board exam format. Focus on the following clinical context: "${context}".

Format each question as:
[Question #] Your question here?
A) Option A
B) Option B
C) Option C
D) Option D
Answer: [Correct answer letter]

Provide only the questions without any explanations or extra text.
  `;

  try {
    const response = await openai.chat.completions.create({
      model: "gpt-3.5-turbo",
      messages: [
        {
          role: "system",
          content: "You are a radiology educator generating high-yield board-style questions.",
        },
        {
          role: "user",
          content: prompt,
        },
      ],
      max_tokens: 2000,
      temperature: 0.7,
    });

    const generatedText = response.choices[0].message.content.trim();

    // Optional: Add metadata or clean output
    const finalOutput = {
      timestamp: new Date().toISOString(),
      board,
      questionType,
      difficulty,
      numQuestions,
      context: context.substring(0, 100) + (context.length > 100 ? "..." : ""),
      data: generatedText,
    };

    res.json(finalOutput);
  } catch (error) {
    console.error("OpenAI API Error:", error);
    res.status(500).json({
      error: "Failed to generate quiz. Please check your OpenAI API key.",
      details: error.message,
    });
  }
});

// Helper: Convert difficulty enum to word
function difficultiesToWord(difficulty) {
  const map = {
    beginner: "beginner-level",
    intermediate: "intermediate-level",
    advanced: "advanced-level",
    expert: "expert-level",
  };
  return map[difficulty] || "intermediate-level";
}

// Helper: Convert question type to word
function questionTypeToWord(type) {
  const map = {
    mcq: "multiple choice",
    truefalse: "true/false",
    matching: "matching",
    shortanswer: "short answer",
  };
  return map[type] || "multiple choice";
}

// Root route
app.get("/", (req, res) => {
  res.sendFile(__dirname + "/public/index.html");
});

// Start server
app.listen(PORT, () => {
  console.log(`✨ Radiology Quiz Platform is running on http://localhost:${PORT}`);
  console.log(`🔐 OpenAI API Key loaded: ${process.env.OPENAI_API_KEY ? '✓' : '✗'}`);
});

module.exports = app;
```

