## ✅ 1. Corriger `remplirQuestions` → afficher les questions d’un questionnaire

```js
function remplirQuestions(data) {
    // data est le JSON retourné : { "questionnaire": { ... } }
    const questionnaire = data.questionnaire;
    $('#questions').empty();
    const ul = $('<ul>');

    console.log("Questions du questionnaire:", questionnaire.questions);

    // On itère sur les questions dans questionnaire.questions
    for (const question of questionnaire.questions) {
        const li = $('<li>');
        const title = $('<h4>').text(question.title);
        const type = $('<p>').text('Type : ' + question.questionType);

        // Afficher les propositions si multiple
        let props = '';
        if (question.questionType === "multiple") {
            props = `<p>Propositions : ${question.proposition1} ou ${question.proposition2}</p>`;
            props += `<p>Réponse : ${question.reponse === 1 ? question.proposition1 : question.proposition2}</p>`;
        } else if (question.questionType === "simple") {
            props = `<p>Réponse : ${question.reponse}</p>`;
        }

        // Ajouter action "Modifier" + "Supprimer"
        const editBtn = $('<button>').text("Modifier").on("click", () => {
            fillFormQuestionnaire(question);
        });

        const deleteBtn = $('<button>').text("Supprimer").on("click", () => {
            if (confirm("Confirmer la suppression ?")) {
                deleteQuestion(question.url);
            }
        });

        li.append(title).append(type).append($(props)).append(editBtn).append(deleteBtn);
        ul.append(li);
    }

    $('#questions').append(ul);
}
```

> ✅ On affiche les questions avec `Modifier` / `Supprimer` sur chaque.

