## ✅ 5. `SaveNewQuestion` : Créer une question

```js
function SaveNewQuestion() {
    const isMultiple = $("#isMultiple").is(":checked");
    const title = $("#title").val();
    const questionnaireId = $("#questionnaire_id").val();
    const url = $("#url").val();

    const jsonData = {
        title,
        questionType: isMultiple ? "multiple" : "simple",
        questionnaire_id: +questionnaireId
    };

    if (isMultiple) {
        jsonData.proposition1 = $("#textChoix1").val();
        jsonData.proposition2 = $("#textChoix2").val();
        jsonData.reponse = $("#choix1").is(":checked") ? 1 : 2;
    } else {
        jsonData.reponse = $("#reponse").val();
    }

    fetch("http://localhost:5000/quiz/api/v1.0/questions", {
        method: "POST",
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(jsonData)
    })
    .then(res => {
        if (!res.ok) throw new Error("Échec création");
        console.log("Question créée !");
        refreshQuestions(questionnaireId);
        formQuestionnaire(true, false, questionnaireId); // Réinitialise le formulaire
    })
    .catch(err => {
        console.error("Erreur :", err);
        alert("Échec de création de la question");
    });
}
