const fs = require("fs");
const path = require("path");

const loadRoutes = async () => {
  const directory = path.resolve(ROUTES_DIR);
  if (!fs.existsSync(directory)) {
    logger.warn(`Routes directory not found: ${directory}. Skipping.`);
    return;
  }

  const files = fs.readdirSync(directory);
  const router = PromiseRouter();

  for (const file of files) {
    const filePath = path.join(directory, file);
    const stat = fs.statSync(filePath);

    if (stat.isDirectory()) continue;
    if (!file.endsWith(".js") && !file.endsWith(".cjs")) continue;

    const moduleName = path.basename(file, path.extname(file));
    const controllerModule = require(filePath);
    const controller = typeof controllerModule === "function" ? controllerModule(app) : controllerModule;

    // Add route based on file name (e.g., users.js -> /users)
    const routePrefix = `/${moduleName}`;
    router.use(routePrefix, controller);
  }

  app.use(router);
};
```

