// src/server.js
const express = require("express");
const cors = require("cors");
const helmet = require("helmet");
const rateLimit = require("express-rate-limit");
const methodOverride = require("method-override");
const createLogger = require("./core/Logger");
const LockManager = require("node-locksmith");
const MongoDBConnectionManager = require("./core/MongodbService");
const PromiseRouter = require("express-promise-router");

module.exports = async function createApp({ config }) {
  const app = express();
  const logger = createLogger(config.appName || "generic-app");

  app.logger = logger;

  // === MIDDLEWARE ===
  app.use(cors());
  app.use(helmet());
  app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));
  app.use(methodOverride("X-HTTP-Method-Override"));
  app.use(express.json());
  app.use(express.urlencoded({ extended: true }));

  // === HEALTHCHECK ===
  app.get(["/hc", "/healthcheck"], (req, res) => {
    res.status(200).send("OK");
  });

  // === REQUEST LOGGING ===
  const logRequest = (req, res, next) => {
    const clientIp = req.headers["x-forwarded-for"] || req.connection.remoteAddress;
    logger.info({
      msg: "Request received",
      method: req.method,
      url: req.url,
      clientIp,
      query: req.query,
      body: req.method !== "GET" && Object.keys(req.body || {}).length > 0 ? req.body : undefined,
    });
    next();
  };
  app.use(logRequest);

  // === APP CONFIG ===
  const port = config.port || 3000;

  // === INITIALIZATION ===
  const lockManager = new LockManager({ lockFileName: `${config.appName}.lock` });

  try {
    await lockManager.checkLock();
    await lockManager.createLock(Infinity, 3);

    const dbManager = new MongoDBConnectionManager(config.dbUrl, logger);
    await dbManager.connectToDatabase();

    app.models = require("./models/index");

    // Load routes dynamically
    await loadRoutes({ app, routesDir: config.routesDir || "./routes" });

    // Set up shutdown handlers
    process.on("unhandledRejection", (error) => {
      logger.error("Unhandled Rejection:", error);
    });

    process.on("SIGTERM", () => {
      logger.info("Received SIGTERM. Shutting down gracefully.");
      process.exit(0);
    });

    const server = require("http").createServer(app);
    server.listen(port, () => {
      logger.info(`HTTP server running on port ${port}`);
    });

    return { app, server };

  } catch (error) {
    logger.error("Failed to initialize app:", error);
    process.exit(1);
  }
};
```

> ✅ Now you can reuse `createApp()` in **any project** with minimal config.

