const express = require('express');
const axios = require('axios');
const dotenv = require('dotenv');
const path = require('path');
const { URLSearchParams } = require('url');

dotenv.config();

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(express.static(path.join(__dirname, 'views')));
app.set('view engine', 'ejs');

// Route utama
app.get('/', async (req, res) => {
  const query = req.query.q || 'lofi music';
  const pageToken = req.query.pageToken || '';
  const maxResults = 10;

  try {
    const response = await axios.get('https://www.googleapis.com/youtube/v3/search', {
      params: {
        part: 'snippet',
        q: query,
        type: 'video',
        maxResults,
        pageToken,
        key: process.env.YOUTUBE_API_KEY
      }
    });

    const videos = response.data.items.map(item => ({
      id: item.id.videoId,
      title: item.snippet.title,
      description: item.snippet.description,
      thumbnail: item.snippet.thumbnails.default.url,
      publishedAt: item.snippet.publishedAt
    }));

    const nextPageToken = response.data.nextPageToken || null;
    const prevPageToken = pageToken ? pageToken : null;

    res.render('index', {
      videos,
      query,
      nextPageToken,
      prevPageToken,
      maxResults,
      totalResults: response.data.pageInfo.totalResults
    });
  } catch (error) {
    console.error('Error fetching YouTube data:', error.response?.data || error.message);
    res.status(500).send('Error fetching videos from YouTube.');
  }
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

