            border-radius: 4px;
        }
        button {
            background-color: #007BFF;
            color: white;
            padding: 10px 20px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        button:hover {
            background-color: #0056b3;
        }
        .output {
            margin-top: 20px;
            padding: 10px;
            background-color: #e9e9e9;
            border-radius: 4px;
            white-space: pre-wrap;
        }
    </style>
</head>
<body>
    <div class="form-container">
        <h2>Вывод чисел от n до m</h2>
        <form method="post">
            <label for="n">Введите число n:</label>
            <input type="number" id="n" name="n" required>

            <label for="m">Введите число m:</label>
            <input type="number" id="m" name="m" required>

            <button type="submit">Показать числа</button>
        </form>

        <?php
        // Проверяем, была ли отправлена форма
        if ($_POST) {
            // Получаем значения
            $n = intval($_POST['n']);
            $m = intval($_POST['m']);

            // Проверяем, чтобы n не было больше m (по умолчанию выводим в порядке возрастания)
            $start = $n;
            $end = $m;

            // Путь к файлу
            $filename = 'numbers.txt';

            // Открываем файл для записи (перезапись)
            $file = fopen($filename, 'w');

            if ($file) {
                // Пишем числа в файл
                for ($i = $start; $i <= $end; $i++) {
                    fwrite($file, $i . "\n");
                }

                fclose($file);

                echo "<div class='output'>";
                echo "Числа от $n до $m записаны в файл: <strong>$filename</strong><br>";
                echo "Содержимое файла:<br>";
                echo nl2br(file_get_contents($filename));
                echo "</div>";
            } else {
                echo "<div class='output' style='color: red;'>";
                echo "Ошибка: не удалось открыть файл для записи.";
                echo "</div>";
            }
        }
        ?>
    </div>
</body>
</html>
```

---

### 🔍 Как это работает:

- Пользователь вводит два целых числа: `n` и `m`.
- При отправке формы скрипт обрабатывает данные.
- Цикл `for` перебирает числа от `n` до `m` включительно.
- Каждое число записывается в файл `numbers.txt` с новой строки.
- После записи содержимое файла выводится на страницу.

---

### ⚠️ Важные замечания:

1. **Файл должен быть доступен для записи** — убедитесь, что сервер может записывать файлы в папку, где лежит скрипт (часто нужно настроить права `chmod 666 numbers.txt` или `777` для папки).
2. **Если `n > m`**, текущий скрипт не работает (цикл `for` не выполнится). Чтобы это исправить, можно добавить проверку:

```php
if ($n > $m) {
    echo "Ошибка: n должно быть меньше или равно m.";
} else {
    for ($i = $n; $i <= $m; $i++) {
        fwrite($file, $i . "\n");
    }
}
```

