$filepath = __DIR__ . '/' . $filename; // Creates file in the same directory

// Check if form is submitted
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    // Get the custom text from the form
    $customText = $_POST['text'] ?? '';

    // Validate input (optional)
    if (empty($customText)) {
        die("Error: Text cannot be empty.");
    }

    // Write the text to the file
    $success = file_put_contents($filepath, $customText);

    if ($success !== false) {
        echo "<p style='color: green;'>✅ File saved successfully as <strong>$filename</strong>!</p>";
