### 🔧 Como usar com um servidor real?

Você precisaria de um backend (ex: Node.js com `ytdl-core`) para fazer o download do vídeo e converter para MP3.

#### Exemplo com Node.js (usando `ytdl-core`):
```bash
npm install ytdl-core ffmpeg-static
```

```js
// server.js
const express = require('express');
const ytdl = require('ytdl-core');
const path = require('path');
const fs = require('fs');
const app = express();

app.use(express.json());

app.post('/api/convert', (req, res) => {
  const { url } = req.body;
  const videoId = url.match(/(?:youtube\.com\/.*[?&]v=|youtu\.be\/)([a-zA-Z0-9_-]+)/)[1];
  const filename = `${videoId}.mp3`;

  const ytUrl = `https://www.youtube.com/watch?v=${videoId}`;

  const stream = ytdl(ytUrl, { quality: 'highestaudio', filter: 'audioonly' });
  const outputPath = path.join(__dirname, 'downloads', filename);

  // Criar pasta se não existir
  if (!fs.existsSync('downloads')) fs.mkdirSync('downloads');

  const writeStream = fs.createWriteStream(outputPath);

  stream.pipe(writeStream);

  writeStream.on('finish', () => {
    res.json({ url: `/downloads/${filename}` });
  });

  writeStream.on('error', (err) => {
    res.status(500).json({ error: 'Erro ao baixar o áudio' });
  });
});

app.use('/downloads', express.static(path.join(__dirname, 'downloads')));

app.listen(3000, () => {
  console.log('Servidor rodando em http://localhost:3000');
});
```

