<?php

class CheckboxQuestion extends Question
{
    public function afficheQuestion(): void
    {
        echo "<div class='question'>\n";
        echo "<p><strong>" . htmlspecialchars($this->label) . "</strong></p>\n";
        foreach ($this->choices as $choice) {
            echo "<label>\n";
            echo "<input type='checkbox' name='" . htmlspecialchars($this->uuid) . "[]' value='" . htmlspecialchars($choice) . "'> ";
            echo htmlspecialchars($choice) . "<br>\n";
            echo "</label>\n";
        }
        echo "</div>\n";
    }

    public function checkReponse($userAnswer): bool
    {
        if (!is_array($userAnswer)) {
            return false;
        }

        $userChoices = array_map('trim', $userAnswer);
        $correctChoices = array_map('trim', (array)$this->correct);

        sort($userChoices);
        sort($correctChoices);

        return $userChoices === $correctChoices;
    }
}
