<?php

// Pfad zur Vue.js-Build-Datei (dist/index.html)
$vueAppEntry = 'app/dist/index.html';

// Basis-Pfad für API-Anfragen
$apiPrefix = '/api';

// Pfad zum Projekt-Root (basierend auf dem Skript-Verzeichnis)
define('ROOT_DIR', __DIR__);

// Hole den URI-Pfad aus der Anfrage
$requestUri = parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH);

