// 1. API-Anfragen: Wenn Pfad mit /api beginnt
if (strpos($requestUri, $apiPrefix) === 0) {
    // Pfad zur API-Datei zusammenbauen
    $apiPath = substr($requestUri, strlen($apiPrefix));
    $filePath = ROOT_DIR . '/api' . $apiPath;

    // Überprüfe, ob die Datei existiert
    if (file_exists($filePath)) {
        // Lade und führe die API-Datei aus
        require $filePath;
        exit;
    } else {
        // 404 für nicht existierende API-Endpunkte
        http_response_code(404);
        echo json_encode(['error' => 'API-Endpunkt nicht gefunden']);
        exit;
    }
