        'css'  => 'text/css',
        'js'   => 'application/javascript',
        'json' => 'application/json',
        'png'  => 'image/png',
        'jpg'  => 'image/jpeg',
        'jpeg' => 'image/jpeg',
        'gif'  => 'image/gif',
        'svg'  => 'image/svg+xml',
        'woff' => 'font/woff',
        'woff2'=> 'font/woff2',
        'ttf'  => 'font/ttf',
    ];

    $contentType = $mimeTypes[$extension] ?? 'application/octet-stream';
    header('Content-Type: ' . $contentType);

    // Liefere die Datei
    readfile($filePath);
    exit;
}

// 3. Fallback: Für alle nicht statisch existierenden Pfade (SPA-Routing)
// Diese Anfragen werden an index.html weitergeleitet (sog. "client-side routing")

// Lade die Vue.js-App (eine einzige HTML-Datei für die gesamte Anwendung)
if (file_exists($vueAppEntry)) {
