<?php
/**
 * Autoloader pour charger automatiquement les classes
 */
class Autoloader
{
    public static function register()
    {
        spl_autoload_register([__CLASS__, 'autoload']);
    }

    /**
     * Charge la classe selon son nom complet (FQCN)
     * @param string $fqcn Nom complet de la classe (ex: Form\Type\RadioQuestion)
     */
    public static function autoload($fqcn)
    {
        // Convertir les backslashes en forward slashes
        $path = str_replace('\\', '/', $fqcn);
        $file = __DIR__ . '/' . $path . '.php';

        if (file_exists($file)) {
            require $file;
        } else {
            // Optional: pour déboguer
            error_log("Fichier non trouvé : $file");
        }
    }
}

// Enregistrer l'autoloader au démarrage
