class CheckQuestion extends Question
{
    public function afficheQuestion(): void
    {
        echo "<div class='question'>";
        echo "<p><strong>{$this->label}</strong></p>";
        foreach ($this->choices as $choice) {
            echo "<label>";
            echo "<input type='checkbox' name='{$this->uuid}[]' value='$choice'> $choice";
            echo "</label><br>";
        }
        echo "</div>";
