        // On compare comme collection (ordre non important)
        $userAnswer = array_map('trim', $userAnswer);
        $correct = array_map('trim', is_array($this->correct) ? $this->correct : [$this->correct]);

        sort($userAnswer);
        sort($correct);

        return $userAnswer === $correct;
    }
}
