use Form\Type\RadioQuestion;
use Form\Type\CheckQuestion;
use Form\Type\TextQuestion;
use Form\Type\SelectQuestion;

class Quiz
{
    private array $questions = [];
    private int $score = 0;

    public function addQuestion(Question $question): self
    {
        $this->questions[] = $question;
        return $this;
    }

    public function getQuestions(): array
    {
        return $this->questions;
    }

    public function afficheQuiz(): void
    {
        echo '<form method="post">';
        foreach ($this->questions as $question) {
            $question->afficheQuestion();
            echo '<hr>';
        }
        echo '<button type="submit" name="submit">Valider</button>';
        echo '</form>';
    }

    public function checkReponse(array $userAnswers): int
    {
        $this->score = 0;

        foreach ($this->questions as $question) {
            $questionUuid = $question->getUuid();
            if (isset($userAnswers[$questionUuid])) {
                if ($question->checkReponse($userAnswers[$questionUuid])) {
                    $this->score++;
                }
            }
        }

        return $this->score;
    }
}
