require_once 'config.php';

// Check if the request is AJAX
if (!$_SERVER['HTTP_X_REQUESTED_WITH'] || strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) !== 'xmlhttprequest') {
    http_response_code(400);
    echo json_encode(['success' => false, 'message' => 'Invalid request']);
    exit;
}

// Check if file was uploaded
if (!isset($_FILES['video_file']) || $_FILES['video_file']['error'] !== UPLOAD_ERR_OK) {
    http_response_code(400);
    echo json_encode(['success' => false, 'message' => 'File upload failed']);
    exit;
}

$file = $_FILES['video_file'];
$fileName = $file['name'];
$fileSize = $file['size'];
$fileTmpPath = $file['tmp_name'];

// Validate file size
if ($fileSize > MAX_FILE_SIZE * 1024 * 1024) {
    http_response_code(400);
    echo json_encode(['success' => false, 'message' => 'File size exceeds the maximum limit of ' . MAX_FILE_SIZE . 'MB']);
    exit;
}

// Get file extension and validate
$ext = strtolower(pathinfo($fileName, PATHINFO_EXTENSION));
if (!in_array($ext, ALLOWED_EXTENSIONS)) {
    http_response_code(400);
    echo json_encode(['success' => false, 'message' => 'Invalid file format. Please upload a supported video file']);
    exit;
}

// Generate unique filename for the uploaded file
$uniqueFileName = uniqid() . '_' . time() . '_' . $fileName;
$uploadPath = UPLOAD_DIR . $uniqueFileName;

// Move uploaded file to upload directory
if (!move_uploaded_file($fileTmpPath, $uploadPath)) {
    http_response_code(500);
    echo json_encode(['success' => false, 'message' => 'Failed to move uploaded file']);
    exit;
}

// Generate output filename
$outputFileName = pathinfo($fileName, PATHINFO_FILENAME) . '.mp4';
$outputFilePath = DOWNLOAD_DIR . $outputFileName;

// Create FFmpeg command to convert to MP4
$ffmpegCommand = '"' . FFMPEG_PATH . '" -i "' . escapeshellarg($uploadPath) . '" -c:v libx264 -crf 23 -preset medium -c:a aac -b:a 128k "' . 
                 escapeshellarg($outputFilePath) . '" 2>&1';

// Execute FFmpeg command
$ffmpegOutput = [];
$ffmpegReturnCode = 0;
exec($ffmpegCommand, $ffmpegOutput, $ffmpegReturnCode);

// Clean up uploaded file
unlink($uploadPath);

// Check if conversion was successful
if ($ffmpegReturnCode !== 0) {
    // Conversion failed
    http_response_code(500);
    $errorMessage = 'Conversion failed: ' . implode(' ', $ffmpegOutput);

    // Try to send the error message to the client
    echo json_encode([
        'success' => false,
        'message' => $errorMessage
    ]);
    exit;
}

// Conversion successful
echo json_encode([
    'success' => true,
    'filename' => $outputFileName
]);
exit;
?>
