        <input type="text" name="name" id="name" value="<?= htmlspecialchars($_POST['name'] ?? '') ?>">
        <?php if (isset($errors['name'])): ?>
            <span class="error"><?= $errors['name'] ?></span>
        <?php endif; ?>
    </div>

    <div class="form-group">
        <label for="age">Age:</label>
        <input type="number" name="age" id="age" value="<?= htmlspecialchars($_POST['age'] ?? '') ?>">
        <?php if (isset($errors['age'])): ?>
            <span class="error"><?= $errors['age'] ?></span>
        <?php endif; ?>
    </div>

    <h3>Enter Subject Marks (Max 100)</h3>
    <?php
    $subjects = ['Math', 'English', 'Science', 'History', 'Art'];
    $marks = $_POST['marks'] ?? [];
    ?>
    <?php foreach ($subjects as $subject): ?>
        <div class="form-group">
            <label><?= $subject ?>:</label>
            <input type="number" name="marks[]" value="<?= htmlspecialchars($marks[array_search($subject, $subjects)] ?? '') ?>" 
                   min="0" max="100" step="1">
        </div>
    <?php endforeach; ?>

    <button type="submit" name="submit">Calculate Grades</button>
</form>

<?php
// Initialize errors array
$errors = [];

// Check if form was submitted
if (isset($_POST['submit'])) {
    $name = trim($_POST['name'] ?? '');
    $age = $_POST['age'] ?? null;
    $marks = $_POST['marks'] ?? [];

    // Validate name
    if (empty($name)) {
        $errors['name'] = "Name is required.";
    } elseif (strlen($name) < 2) {
        $errors['name'] = "Name must be at least 2 characters.";
    }

    // Validate age
    if (empty($age) || !is_numeric($age) || $age < 5 || $age > 120) {
        $errors['age'] = "Age must be a valid number between 5 and 120.";
    }

    // Validate marks (must be 5 subjects)
    if (count($marks) !== 5) {
        $errors['marks'] = "Please enter marks for all 5 subjects.";
    } else {
        foreach ($marks as $mark) {
            if (!is_numeric($mark) || $mark < 0 || $mark > 100) {
                $errors['marks'] = "All marks must be between 0 and 100.";
                break;
            }
        }
    }

    // If no errors, process data
    if (empty($errors)) {
        $total = 0;
        $passCount = 0;

        // Use For loop to sum scores and count passes
        for ($i = 0; $i < count($marks); $i++) {
            $total += $marks[$i];
            if ($marks[$i] >= 50) {
                $passCount++;
            }
        }

        $average = $total / 5;

        // Use conditional operator to assign grade
        $grade = $average >= 90 ? 'A' :
                 $average >= 80 ? 'B' :
                 $average >= 70 ? 'C' :
                 $average >= 60 ? 'D' : 'F';

        // Use While loop to display subject-wise results
        $i = 0;
        $resultsList = "";
        while ($i < 5) {
            $subject = $subjects[$i];
            $mark = $marks[$i];
            $status = $mark >= 50 ? 'Pass' : 'Fail';
            $resultsList .= "<li><strong>$subject:</strong> $mark ($status)</li>";
            $i++;
        }
        ?>
        <div class="result">
            <h3>📋 Results for <?= htmlspecialchars($name) ?></h3>
            <p><strong>Age:</strong> <?= htmlspecialchars($age) ?></p>
            <p><strong>Average:</strong> <?= number_format($average, 2) ?></p>
            <p><strong>Grade:</strong> <?= $grade ?></p>
            <p><strong>Passed Subjects:</strong> <?= $passCount ?>/5</p>
            <h4>Subject-wise Results:</h4>
            <ul><?= $resultsList ?></ul>
        </div>
        <?php
    }
}
?>

</body>
</html>
```

