## ✅ 4. `upload.php` — обработка загрузки

```php
<?php
require_once 'config.php';

header('Content-Type: application/json');

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    echo json_encode(['error' => 'Доступ запрещён']);
    exit;
}

if (!isset($_FILES['file'])) {
    echo json_encode(['error' => 'Файл не выбран']);
    exit;
}

$file = $_FILES['file'];
$expireDays = (int)$_POST['expireDays'] ?? 7;

// Проверка размера
if ($file['size'] > MAX_FILE_SIZE) {
    echo json_encode(['error' => 'Файл слишком большой. Максимум ' . (MAX_FILE_SIZE / 1024 / 1024) . ' МБ']);
    exit;
}

// Проверка расширения
$ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
if (!in_array($ext, ALLOWED_EXTENSIONS)) {
    echo json_encode(['error' => 'Расширение файла не разрешено']);
    exit;
}

// Генерация уникального имени
$filename = uniqid() . '.' . $ext;
$filepath = UPLOAD_DIR . $filename;

// Перемещение файла
if (!move_uploaded_file($file['tmp_name'], $filepath)) {
    echo json_encode(['error' => 'Ошибка при загрузке файла']);
    exit;
}

// Сохраняем метаданные в JSON
$meta = [
    'name' => $file['name'],
    'filename' => $filename,
    'size' => $file['size'],
    'date' => date('Y-m-d H:i:s'),
    'expiryDate' => $expireDays > 0 ? date('Y-m-d H:i:s', strtotime("+{$expireDays} days")) : null
];

$metaFile = UPLOAD_DIR . 'meta_' . $filename . '.json';
file_put_contents($metaFile, json_encode($meta, JSON_UNESCAPED_UNICODE));

echo json_encode([
    'success' => true,
    'message' => 'Файл успешно загружен!',
    'url' => "download.php?file=" . urlencode($filename),
    'expireIn' => $expireDays . ' дней',
]);
?>
