## ✅ 9. `admin/save_settings.php` — сохранение настроек

```php
<?php
require_once '../config.php';
header('Content-Type: application/json');

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    echo json_encode(['error' => 'Доступ запрещён']);
    exit;
}

$data = json_decode(file_get_contents('php://input'), true);

if (!$data) {
    $data = $_POST;
}

$maxSizeMB = (int)$data['maxSize'] ?? 10;
$extensions = $data['extensions'] ?? [];

if (!is_numeric($maxSizeMB) || $maxSizeMB < 1) {
    echo json_encode(['error' => 'Неверный размер']);
    exit;
}

if (!is_array($extensions) || empty($extensions)) {
    echo json_encode(['error' => 'Не указаны расширения']);
    exit;
}

// Обновляем переменные (временно — лучше использовать файл настроек)
define('MAX_FILE_SIZE', $maxSizeMB * 1024 * 1024);
define('ALLOWED_EXTENSIONS', $extensions);

// Запись в файл (для сохранения между перезагрузками)
$settings = [
    'maxSize' => $maxSizeMB,
    'extensions' => $extensions
];

file_put_contents('../config_settings.json', json_encode($settings, JSON_UNESCAPED_UNICODE));

echo json_encode(['success' => true, 'message' => 'Настройки сохранены']);
?>
