public class PdfInIframe : MonoBehaviour
{
    public string pdfFileName = "manual.pdf";

    void Start()
    {
        string pdfUrl = "StreamingAssets/" + pdfFileName;

        // Вызов JavaScript-функции, которая вставит iframe
        string jsCode = $"showPdf('{pdfUrl}');";
        // Важно, чтобы в index.html была функция showPdf()
        // И она должна быть встроена в страницу!
        // Это делается через плагин или манифест
        Debug.Log("Вызов JS: " + jsCode);
