    // تخزين المنتجات في متغير (يمكن استبداله بـ localStorage أو خادم لاحقًا)
    let products = JSON.parse(localStorage.getItem("products")) || [];

    // دالة لعرض المنتجات
    function renderProducts() {
      productsContainer.innerHTML = "";
      if (products.length === 0) {
        productsContainer.innerHTML = "<p>لا توجد منتجات بعد.</p>";
        return;
      }

      products.forEach((product, index) => {
        const productDiv = document.createElement("div");
        productDiv.className = "product";
        productDiv.innerHTML = `
          <div>
            <h3>${product.name}</h3>
            <span class="price">السعر: ${product.price} ر.س</span>
          </div>
          <button class="delete" data-index="${index}">حذف</button>
        `;
        productsContainer.appendChild(productDiv);
      });

      // إضافة حدث الحذف لجميع الأزرار
      document.querySelectorAll(".delete").forEach(btn => {
        btn.addEventListener("click", function () {
          const index = this.dataset.index;
          products.splice(index, 1);
          localStorage.setItem("products", JSON.stringify(products));
          renderProducts();
        });
      });
    }

    // إضافة منتج جديد
    form.addEventListener("submit", function (e) {
      e.preventDefault();

      const name = productNameInput.value.trim();
      const price = parseFloat(productPriceInput.value);

      if (name === "" || isNaN(price)) {
        alert("يرجى إدخال اسم المنتج وسعر صحيح.");
        return;
      }

      // إضافة المنتج إلى المصفوفة
      products.push({ name, price });

      // حفظ المنتجات في localStorage
      localStorage.setItem("products", JSON.stringify(products));

      // إرجاع النموذج لحالة فارغة
      form.reset();

      // إعادة عرض المنتجات
      renderProducts();
    });

    // تحميل المنتجات عند فتح الصفحة
    renderProducts();
  </script>
</body>
</html>
