## 4️⃣ 前端逻辑（Ajax）—— `public/script.js`

```js
document.addEventListener('DOMContentLoaded', function () {
  const userList = document.getElementById('userList');
  const refreshBtn = document.getElementById('refreshBtn');

  // 通用的 Ajax 函数（支持 GET / POST）
  function ajax(method, url, data = null, successCallback, errorCallback) {
    const xhr = new XMLHttpRequest();

    xhr.open(method, url, true);

    // 设置请求头（JSON 格式）
    xhr.setRequestHeader('Content-Type', 'application/json');

    xhr.onreadystatechange = function () {
      if (xhr.readyState === 4) {
        if (xhr.status >= 200 && xhr.status < 300) {
          try {
            const response = JSON.parse(xhr.responseText);
            successCallback(response);
          } catch (e) {
            errorCallback('解析响应失败');
          }
        } else {
          errorCallback(`请求失败：${xhr.status}`);
        }
      }
    };

    xhr.onerror = function () {
      errorCallback('网络错误');
    };

    xhr.send(data ? JSON.stringify(data) : null);
  }

  // 渲染用户列表
  function renderUsers(users) {
    userList.innerHTML = ''; // 清空

    if (users.length === 0) {
      const li = document.createElement('li');
      li.textContent = '暂无用户数据';
      userList.appendChild(li);
      return;
    }

    users.forEach(user => {
      const li = document.createElement('li');
      li.innerHTML = `
        <strong>ID: ${user.id}</strong> - 
        姓名: ${user.name} - 
        邮箱: ${user.email}
      `;
      userList.appendChild(li);
    });
  }

  // 加载初始用户数据
  function loadUsers() {
    userList.innerHTML = '<li class="loading">正在加载用户...</li>';
    ajax(
      'GET',
      '/api/users',
      null,
      function (data) {
        renderUsers(data);
      },
      function (error) {
        const li = document.createElement('li');
        li.textContent = '加载失败: ' + error;
        li.style.color = 'red';
        userList.appendChild(li);
      }
    );
  }

  // 刷新按钮点击事件
  refreshBtn.addEventListener('click', function () {
    // 显示加载状态
    userList.innerHTML = '<li class="loading">刷新中...</li>';

    // 发送 POST 请求刷新数据
    ajax(
      'POST',
      '/api/users/refresh',
      null,
      function (data) {
        alert('用户数据已刷新！');
        renderUsers(data.users); // 使用新数据渲染
      },
      function (error) {
        alert('刷新失败: ' + error);
      }
    );
  });

  // 页面加载完成后加载初始数据
  loadUsers();
});
```

