## 🔗 2. `api/matomo-api.php` – Comunicazione con Matomo

```php
<?php
// api/matomo-api.php

require_once '../config.php';

class MatomoAPI {
    private $url;
    private $token;

    public function __construct() {
        $this->url = MATOMO_URL;
        $this->token = MATOMO_TOKEN;
    }

    /**
     * Ottiene tutti i siti in Matomo
     */
    public function getSites() {
        $params = [
            'module' => 'API',
            'method' => 'SitesManager.getSitesIdAndName',
            'format' => 'json',
            'token_auth' => $this->token,
        ];

        $url = $this->url . '/index.php?' . http_build_query($params);
        $response = $this->fetch($url);

        if (!$response) return [];

        $data = json_decode($response, true);
        return $data ?? [];
    }

    /**
     * Estrae dati statistici da Matomo con API
     */
    public function getReport($siteId, $dateFrom, $dateTo, $reportType = 'VisitsSummary.getVisits') {
        $params = [
            'module' => 'API',
            'method' => $reportType,
            'idSite' => $siteId,
            'period' => 'range',
            'date' => $dateFrom . ',' . $dateTo,
            'format' => 'json',
            'token_auth' => $this->token,
        ];

        $url = $this->url . '/index.php?' . http_build_query($params);
        $response = $this->fetch($url);

        if (!$response) return null;

        $data = json_decode($response, true);
        return $data ?? null;
    }

    /**
     * Funzione generica per chiamare l'API Matomo
     */
    private function fetch($url) {
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
        curl_setopt($ch, CURLOPT_TIMEOUT, 30);
        curl_setopt($ch, CURLOPT_USERAGENT, 'Matomo Report Downloader/1.0');

        $response = curl_exec($ch);
        $err = curl_error($ch);
        curl_close($ch);

        if ($err) {
            error_log("Curl error: " . $err);
            return null;
        }

        return $response;
    }
}
```

